/*C++ program to insert element in Binary Tree*/

#include <iostream>
#include <queue>
using namespace std;

/* A binary tree node has data, pointer to left child
and a pointer to right child */

struct Node {
    int data;
    Node* left;
    Node* right;
};

/* Function to create a new node */

Node* CreateNode(int data)
{
    Node* newNode = new Node();
    if (!newNode) {
        cout << "Memory error\n";
        return NULL;
    }
    newNode->data = data;
    newNode->left = newNode->right = NULL;
    return newNode;
}

/* Inorder traversal of a binary tree */

void inorder(Node* temp)
{
    if (temp == NULL)
        return;
    inorder(temp->left);
    cout << temp->data << ' ';
    inorder(temp->right);
}

/* Function to insert element in binary tree */

Node* InsertNode(Node* root, int data)
{
    if (root == NULL) {
        root = CreateNode(data);
        return root;
    }

/*  do level order traversal until we find an empty
    place, i.e. either left child or right child of some
    node is pointing to NULL.*/

    queue<Node*> q;
    q.push(root);
    while (!q.empty()) {
        Node* temp = q.front();
        q.pop();
        if (temp->left != NULL)
            q.push(temp->left);
        else {
            temp->left = CreateNode(data);
            return root;
        }
        if (temp->right != NULL)
            q.push(temp->right);
        else {
            temp->right = CreateNode(data);
            return root;
        }
    }
}

/*Driver code*/

int main()
{
    Node* root = CreateNode(10);
    root->left = CreateNode(11);
    root->left->left = CreateNode(7);
    root->right = CreateNode(9);
    root->right->left = CreateNode(15);
    root->right->right = CreateNode(8);
    cout << "Inorder traversal before insertion: ";
    inorder(root);
    cout << endl;
    int key = 12;
    root = InsertNode(root, key);
    cout << "Inorder traversal after insertion: ";
    inorder(root);
    cout << endl;
    return 0;
}

/*C++ program to delete element in binary tree*/

#include <bits/stdc++.h>
using namespace std;

/* A binary tree node has key, pointer to left
child and a pointer to right child */

struct Node {
    int key;
    struct Node *left, *right;
};

/* function to create a new node of tree and
return pointer */

struct Node* newNode(int key)
{
    struct Node* temp = new Node;
    temp->key = key;
    temp->left = temp->right = NULL;
    return temp;
};

/* Inorder traversal of a binary tree*/

void inorder(struct Node* temp)
{
    if (!temp)
        return;
    inorder(temp->left);
    cout << temp->key << " ";
    inorder(temp->right);
}

/* function to delete the given deepest node
(d_node) in binary tree */

void deletDeepest(struct Node* root,
                  struct Node* d_node)
{
    queue<struct Node*> q;
    q.push(root);

/*    Do level order traversal until last node*/

    struct Node* temp;
    while (!q.empty()) {
        temp = q.front();
        q.pop();
        if (temp == d_node) {
            temp = NULL;
            delete (d_node);
            return;
        }
        if (temp->right) {
            if (temp->right == d_node) {
                temp->right = NULL;
                delete (d_node);
                return;
            }
            else
                q.push(temp->right);
        }
        if (temp->left) {
            if (temp->left == d_node) {
                temp->left = NULL;
                delete (d_node);
                return;
            }
            else
                q.push(temp->left);
        }
    }
}

/* function to delete element in binary tree */

Node* deletion(struct Node* root, int key)
{
    if (root == NULL)
        return NULL;
    if (root->left == NULL && root->right == NULL) {
        if (root->key == key)
            return NULL;
        else
            return root;
    }
    queue<struct Node*> q;
    q.push(root);
    struct Node* temp;
    struct Node* key_node = NULL;

/*    Do level order traversal to find deepest
    node(temp) and node to be deleted (key_node)*/

    while (!q.empty()) {
        temp = q.front();
        q.pop();
        if (temp->key == key)
            key_node = temp;
        if (temp->left)
            q.push(temp->left);
        if (temp->right)
            q.push(temp->right);
    }
    if (key_node != NULL) {
        int x = temp->key;
        deletDeepest(root, temp);
        key_node->key = x;
    }
    return root;
}

/*Driver code*/

int main()
{
    struct Node* root = newNode(10);
    root->left = newNode(11);
    root->left->left = newNode(7);
    root->left->right = newNode(12);
    root->right = newNode(9);
    root->right->left = newNode(15);
    root->right->right = newNode(8);
    cout << "Inorder traversal before deletion : ";
    inorder(root);
    int key = 11;
    root = deletion(root, key);
    cout << endl;
    cout << "Inorder traversal after deletion : ";
    inorder(root);
    return 0;
}

/*C++ program to check if a tree is continuous or not*/

#include<bits/stdc++.h>
using namespace std;

/* A binary tree node has data, pointer to left child
   and a pointer to right child */

struct Node
{
    int data;
    struct Node* left, * right;
};

/* Helper function that allocates a new node with the
   given data and NULL left and right pointers. */

struct Node* newNode(int data)
{
    struct Node* node = new Node;
    node->data = data;
    node->left = node->right = NULL;
    return(node);
}

/*Function to check tree is continuous or not*/

bool treeContinuous(struct Node *ptr)
{

/*    if next node is empty then return true*/

    if (ptr == NULL)
        return true;

/*    if current node is leaf node then return true
    because it is end of root to leaf path*/

    if (ptr->left == NULL && ptr->right == NULL)
        return true;

/*    If left subtree is empty, then only check right*/

    if (ptr->left == NULL)
       return (abs(ptr->data - ptr->right->data) == 1) &&
              treeContinuous(ptr->right);

/*    If right subtree is empty, then only check left*/

    if (ptr->right == NULL)
       return (abs(ptr->data - ptr->left->data) == 1) &&
              treeContinuous(ptr->left);

/*    If both left and right subtrees are not empty, check
    everything*/

    return  abs(ptr->data - ptr->left->data)==1 &&
            abs(ptr->data - ptr->right->data)==1 &&
            treeContinuous(ptr->left) &&
            treeContinuous(ptr->right);
}

/* Driver program to test mirror() */

int main()
{
    struct Node *root = newNode(3);
    root->left        = newNode(2);
    root->right       = newNode(4);
    root->left->left  = newNode(1);
    root->left->right = newNode(3);
    root->right->right = newNode(5);
    treeContinuous(root)?  cout << "Yes" : cout << "No";
    return 0;
}

/*CPP Code to check if the tree is continuous or not*/

#include <bits/stdc++.h>
using namespace std;

/*Node structure*/

struct node {
    int val;
    node* left;
    node* right;
    node()
        : val(0)
        , left(nullptr)
        , right(nullptr)
    {
    }
    node(int x)
        : val(x)
        , left(nullptr)
        , right(nullptr)
    {
    }
    node(int x, node* left, node* right)
        : val(x)
        , left(left)
        , right(right)
    {
    }
};

/*Function to check if the tree is continuous or not*/

bool continuous(struct node* root)
{

/*    If root is Null then tree isn't Continuous*/

    if (root == NULL)
        return false;
    int flag = 1;
    queue<struct node*> Q;
    Q.push(root);
    node* temp;

/*    BFS Traversal*/

    while (!Q.empty()) {
        temp = Q.front();
        Q.pop();

/*        Move to left child*/

        if (temp->left) {

/*            if difference between parent and child is
            equal to 1 then do continue otherwise make
            flag = 0 and break*/

            if (abs(temp->left->val - temp->val) == 1)
                Q.push(temp->left);
            else {
                flag = 0;
                break;
            }
        }

/*        Move to right child*/

        if (temp->right) {

/*            if difference between parent and child is
            equal to 1 then do continue otherwise make
            flag = 0 and break*/

            if (abs(temp->right->val - temp->val) == 1)
                Q.push(temp->right);
            else {
                flag = 0;
                break;
            }
        }
    }
    if (flag)
        return true;
    else
        return false;
}

/*Driver Code*/

int main()
{

/*    Constructing the Tree*/

    struct node* root = new node(3);
    root->left = new node(2);
    root->right = new node(4);
    root->left->left = new node(1);
    root->left->right = new node(3);
    root->right->right = new node(5);

/*    Function Call*/

    if (continuous(root))
        cout << "True\n";
    else
        cout << "False\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
#define bool int
#define true 1
#define false 0

/* A binary tree node has data, pointer to left child
and a pointer to right child */

class node {
public:
    int data;
    node* left;
    node* right;
};

/* A utility function that checks
if trees with roots as n1 and n2
are mirror of each other */

bool IsFoldableUtil(node* n1, node* n2);

/* Returns true if the given tree can be folded */

bool IsFoldable(node* root)
{
    if (root == NULL) {
        return true;
    }
    return IsFoldableUtil(root->left, root->right);
}

/* A utility function that checks
if trees with roots as n1 and n2
are mirror of each other */

bool IsFoldableUtil(node* n1, node* n2)
{

/* If both left and right subtrees are NULL,
    then return true */

    if (n1 == NULL && n2 == NULL) {
        return true;
    }

/* If one of the trees is NULL and other is not,
    then return false */

    if (n1 == NULL || n2 == NULL) {
        return false;
    }

/* Otherwise check if left and right subtrees are
    mirrors of their counterparts */

    return IsFoldableUtil(n1->left, n2->right)
           && IsFoldableUtil(n1->right, n2->left);
}

/* Helper function that allocates a new node with the
given data and NULL left and right pointers. */

node* newNode(int data)
{
    node* Node = new node();
    Node->data = data;
    Node->left = NULL;
    Node->right = NULL;
    return (Node);
}

/* Driver code */

int main(void)
{

/* The constructed binary tree is
        1
        / \
        2 3
        \ /
        4 5
    */

    node* root = newNode(1);
    root->left = newNode(2);
    root->right = newNode(3);
    root->left->right = newNode(4);
    root->right->left = newNode(5);
    if (IsFoldable(root) == true) {
        cout << "Tree is foldable";
    }
    else {
        cout << "Tree is not foldable";
    }
    return 0;
}

/*C++ program for expression tree*/

#include<bits/stdc++.h>
using namespace std;

/*An expression tree node*/

struct et
{
    char value;
    et* left, *right;
};

/*A utility function to check if 'c'
is an operator*/

bool isOperator(char c)
{
    if (c == '+' || c == '-' ||
            c == '*' || c == '/' ||
            c == '^')
        return true;
    return false;
}

/*Utility function to do inorder traversal*/

void inorder(et *t)
{
    if(t)
    {
        inorder(t->left);
        printf("%c ", t->value);
        inorder(t->right);
    }
}

/*A utility function to create a new node*/

et* newNode(char v)
{
    et *temp = new et;
    temp->left = temp->right = NULL;
    temp->value = v;
    return temp;
};

/*Returns root of constructed tree for given
postfix expression*/

et* constructTree(char postfix[])
{
    stack<et *> st;
    et *t, *t1, *t2;

/*    Traverse through every character of
    input expression*/

    for (int i=0; i<strlen(postfix); i++)
    {

/*        If operand, simply push into stack*/

        if (!isOperator(postfix[i]))
        {
            t = newNode(postfix[i]);
            st.push(t);
        }

/*operator*/

else 
        {
            t = newNode(postfix[i]);

/*            Pop two top nodes
Store top*/

t1 = st.top(); 
st.pop();      
t2 = st.top();
st.pop();

/*              make them children*/

            t->right = t1;
            t->left = t2;

/*            Add this subexpression to stack*/

            st.push(t);
        }
    }

/*      only element will be root of expression
    tree*/

    t = st.top();
    st.pop();
    return t;
}

/*Driver program to test above*/

int main()
{
    char postfix[] = "ab+ef*g*-";
    et* r = constructTree(postfix);
    printf("infix expression is \n");
    inorder(r);
    return 0;
}

/*C++ program to evaluate an expression tree */

#include <bits/stdc++.h> 
using namespace std;

/*Class to represent the nodes of syntax tree */

class node 
{ 
public: 
    string info; 
    node *left = NULL, *right = NULL; 
    node(string x) 
    { 
        info = x; 
    } 
};

/*Utility function to return the integer value 
of a given string */

int toInt(string s) 
{ 
    int num = 0;

/*      Check if the integral value is 
      negative or not
      If it is not negative, generate the number 
      normally*/

      if(s[0]!='-')
        for (int i=0; i<s.length(); i++) 
            num = num*10 + (int(s[i])-48);

/*    If it is negative, calculate the +ve number
    first ignoring the sign and invert the 
    sign at the end*/

      else
        for (int i=1; i<s.length(); i++) 
        {
            num = num*10 + (int(s[i])-48); 
            num = num*-1;
        }
    return num; 
}

/*This function receives a node of the syntax tree 
and recursively evaluates it */

int eval(node* root) 
{

/*    empty tree */

    if (!root) 
        return 0;

/*    leaf node i.e, an integer */

    if (!root->left && !root->right) 
        return toInt(root->info);

/*    Evaluate left subtree */

    int l_val = eval(root->left);

/*    Evaluate right subtree */

    int r_val = eval(root->right);

/*    Check which operator to apply */

    if (root->info=="+") 
        return l_val+r_val; 
    if (root->info=="-") 
        return l_val-r_val; 
    if (root->info=="*") 
        return l_val*r_val; 
    return l_val/r_val; 
}

/*    create a syntax tree */
int main() 
{
    node *root = new node("+"); 
    root->left = new node("*"); 
    root->left->left = new node("5"); 
    root->left->right = new node("-4"); 
    root->right = new node("-"); 
    root->right->left = new node("100"); 
    root->right->right = new node("20"); 
    cout << eval(root) << endl; 
    delete(root); 
    root = new node("+"); 
    root->left = new node("*"); 
    root->left->left = new node("5"); 
    root->left->right = new node("4"); 
    root->right = new node("-"); 
    root->right->left = new node("100"); 
    root->right->right = new node("/"); 
    root->right->right->left = new node("20"); 
    root->right->right->right = new node("2"); 
    cout << eval(root); 
    return 0; 
}

/*C++ program to check if a given
Binary Tree is symmetric or not*/

#include <bits/stdc++.h>
using namespace std;

/*A Binary Tree Node*/

struct Node
{
    int key;
    struct Node *left, *right;
};

/*Utility function to create new Node*/

Node* newNode(int key)
{
    Node* temp = new Node;
    temp->key = key;
    temp->left = temp->right = NULL;
    return (temp);
}

/*Returns true if trees
with roots as root1 and root2 are mirror*/

bool isMirror(struct Node* root1, struct Node* root2)
{

/*    If both trees are emptu,
    then they are mirror images*/

    if (root1 == NULL && root2 == NULL)
        return true;

/*    For two trees to be mirror
    images, the following
    three conditions must be true
    1 - Their root node's
    key must be same 2 - left
    subtree of left tree and right subtree
    of right tree have to be mirror images
    3 - right subtree of left tree and left subtree
    of right tree have to be mirror images*/

    if (root1 && root2 && root1->key == root2->key)
        return isMirror(root1->left, root2->right)
               && isMirror(root1->right, root2->left);

/*    if none of above conditions is true then root1
    and root2 are not mirror images*/

    return false;
}

/*Returns true if a tree is
symmetric i.e. mirror image of itself*/

bool isSymmetric(struct Node* root)
{

/*    Check if tree is mirror of itself*/

    return isMirror(root, root);
}

/*Driver code*/

int main()
{

/*    Let us construct the Tree shown in the above figure*/

    Node* root = newNode(1);
    root->left = newNode(2);
    root->right = newNode(2);
    root->left->left = newNode(3);
    root->left->right = newNode(4);
    root->right->left = newNode(4);
    root->right->right = newNode(3);
    if(isSymmetric(root))
      cout<<"Symmetric";
    else
      cout<<"Not symmetric";
    return 0;
}

/*C++ program for different tree traversals*/

#include <iostream>
using namespace std;

/* A binary tree node has data, pointer to left child
and a pointer to right child */

struct Node {
    int data;
    struct Node *left, *right;
    Node(int data)
    {
        this->data = data;
        left = right = NULL;
    }
};

/* Given a binary tree, print its nodes according to the
"bottom-up" postorder traversal. */

void printPostorder(struct Node* node)
{
    if (node == NULL)
        return;

/*    first recur on left subtree*/

    printPostorder(node->left);

/*    then recur on right subtree*/

    printPostorder(node->right);

/*    now deal with the node*/

    cout << node->data << " ";
}

/* Given a binary tree, print its nodes in inorder*/

void printInorder(struct Node* node)
{
    if (node == NULL)
        return;

/* first recur on left child */

    printInorder(node->left);

/* then print the data of node */

    cout << node->data << " ";

/* now recur on right child */

    printInorder(node->right);
}

/* Given a binary tree, print its nodes in preorder*/

void printPreorder(struct Node* node)
{
    if (node == NULL)
        return;

/* first print data of node */

    cout << node->data << " ";

/* then recur on left sutree */

    printPreorder(node->left);

/* now recur on right subtree */

    printPreorder(node->right);
}

/* Driver program to test above functions*/

int main()
{
    struct Node* root = new Node(1);
    root->left = new Node(2);
    root->right = new Node(3);
    root->left->left = new Node(4);
    root->left->right = new Node(5);
    cout << "\nPreorder traversal of binary tree is \n";
    printPreorder(root);
    cout << "\nInorder traversal of binary tree is \n";
    printInorder(root);
    cout << "\nPostorder traversal of binary tree is \n";
    printPostorder(root);
    return 0;
}

/*C++ program to print inorder traversal
using stack.*/

#include<bits/stdc++.h>
using namespace std;

/* A binary tree Node has data, pointer to left child
   and a pointer to right child */

struct Node
{
    int data;
    struct Node* left;
    struct Node* right;
    Node (int data)
    {
        this->data = data;
        left = right = NULL;
    }
};

/* Iterative function for inorder tree
   traversal */

void inOrder(struct Node *root)
{
    stack<Node *> s;
    Node *curr = root;

/*        traverse the tree*/

    while (curr != NULL || s.empty() == false)
    {

/* Reach the left most Node of the
           curr Node */

        while (curr !=  NULL)
        {

/* place pointer to a tree node on
               the stack before traversing
              the node's left subtree */

            s.push(curr);
            curr = curr->left;
        }

/* Current must be NULL at this point */

        curr = s.top();
        s.pop();
        cout << curr->data << " ";

/* we have visited the node and its
           left subtree.  Now, it's right
           subtree's turn */

        curr = curr->right;
    } 
}

/* Driver program to test above functions*/

int main()
{

/* Constructed binary tree is
              1
            /   \
          2      3
        /  \
      4     5
    */

    struct Node *root = new Node(1);
    root->left        = new Node(2);
    root->right       = new Node(3);
    root->left->left  = new Node(4);
    root->left->right = new Node(5);
    inOrder(root);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

/* A binary tree tNode has data, a pointer to left child
   and a pointer to right child */

struct tNode {
    int data;
    struct tNode* left;
    struct tNode* right;
};

/* Function to traverse the binary tree without recursion
   and without stack */

void MorrisTraversal(struct tNode* root)
{
    struct tNode *current, *pre;
    if (root == NULL)
        return;
    current = root;
    while (current != NULL) {
        if (current->left == NULL) {
            printf("%d ", current->data);
            current = current->right;
        }
        else {

/* Find the inorder predecessor of current */

            pre = current->left;
            while (pre->right != NULL
                   && pre->right != current)
                pre = pre->right;

/* Make current as the right child of its
               inorder predecessor */

            if (pre->right == NULL) {
                pre->right = current;
                current = current->left;
            }

/* Revert the changes made in the 'if' part to
               restore the original tree i.e., fix the right
               child of predecessor */

            else {
                pre->right = NULL;
                printf("%d ", current->data);
                current = current->right;
            } 
        } 
    } 
}

/* Helper function that allocates a new tNode with the
   given data and NULL left and right pointers. */

struct tNode* newtNode(int data)
{
    struct tNode* node = new tNode;
    node->data = data;
    node->left = NULL;
    node->right = NULL;
    return (node);
}

/* Driver program to test above functions*/

int main()
{

/* Constructed binary tree is
            1
          /   \
         2     3
       /   \
      4     5
  */

    struct tNode* root = newtNode(1);
    root->left = newtNode(2);
    root->right = newtNode(3);
    root->left->left = newtNode(4);
    root->left->right = newtNode(5);
    MorrisTraversal(root);
    return 0;
}

/*C++ program to find binary tree with given inorder
traversal*/

#include <bits/stdc++.h>
using namespace std;

/*Node structure*/

struct Node
{
    int key;
    struct Node *left, *right;
};

/*A utility function to create a new tree Node*/

struct Node *newNode(int item)
{
    struct Node *temp = new Node;
    temp->key = item;
    temp->left = temp->right = NULL;
    return temp;
}

/*A utility function to do preorder traversal of BST*/

void preorder(Node *root)
{
    if (root != NULL)
    {
        printf("%d ", root->key);
        preorder(root->left);
        preorder(root->right);
    }
}

/*Function for constructing all possible trees with
given inorder traversal stored in an array from
arr[start] to arr[end]. This function returns a
vector of trees.*/

vector<Node *> getTrees(int arr[], int start, int end)
{

/*    List to store all possible trees*/

    vector<Node *> trees;

/* if start > end then subtree will be empty so
    returning NULL in the list */

    if (start > end)
    {
        trees.push_back(NULL);
        return trees;
    }

/* Iterating through all values from start to end
        for constructing left and right subtree
        recursively */

    for (int i = start; i <= end; i++)
    {

/* Constructing left subtree */

        vector<Node *> ltrees = getTrees(arr, start, i-1);

/* Constructing right subtree */

        vector<Node *> rtrees = getTrees(arr, i+1, end);

/* Now looping through all left and right subtrees
        and connecting them to ith root below */

        for (int j = 0; j < ltrees.size(); j++)
        {
            for (int k = 0; k < rtrees.size(); k++)
            {

/*                Making arr[i] as root*/

                Node * node = newNode(arr[i]);

/*                Connecting left subtree*/

                node->left = ltrees[j];

/*                Connecting right subtree*/

                node->right = rtrees[k];

/*                Adding this tree to list*/

                trees.push_back(node);
            }
        }
    }
    return trees;
}

/*Driver Program to test above functions*/

int main()
{
    int in[] = {4, 5, 7};
    int n = sizeof(in) / sizeof(in[0]);
    vector<Node *> trees = getTrees(in, 0, n-1);
    cout << "Preorder traversals of different "
         << "possible Binary Trees are \n";
    for (int i = 0; i < trees.size(); i++)
    {
        preorder(trees[i]);
        printf("\n");
    }
    return 0;
}

/*C++ program to populate inorder
traversal of all nodes*/

#include<bits/stdc++.h>
using namespace std;

/*A binary tree node*/

class node
{
    public:
    int data;
    node *left;
    node *right;
    node *next;
};

/* Set next of p and all descendants of p
by traversing them in reverse Inorder */

void populateNext(node* p)
{

/*    The first visited node will be the
    rightmost node next of the rightmost
    node will be NULL*/

    static node *next = NULL;
    if (p)
    {

/*        First set the next pointer
        in right subtree*/

        populateNext(p->right);

/*        Set the next as previously visited
        node in reverse Inorder*/

        p->next = next;

/*        Change the prev for subsequent node*/

        next = p;

/*        Finally, set the next pointer in
        left subtree*/

        populateNext(p->left);
    }
}

/* Helper function that allocates a new
node with the given data and NULL left
and right pointers. */

node* newnode(int data)
{
    node* Node = new node();
    Node->data = data;
    Node->left = NULL;
    Node->right = NULL;
    Node->next = NULL;
    return(Node);
}

/* Constructed binary tree is
            10
            / \
        8 12
        /
    3
    */
int main()
{
    node *root = newnode(10);
    root->left = newnode(8);
    root->right = newnode(12);
    root->left->left = newnode(3);

/*    Populates nextRight pointer in all nodes*/

    populateNext(root);

/*    Let us see the populated values*/

    node *ptr = root->left->left;
    while(ptr)
    {

/*        -1 is printed if there is no successor*/

        cout << "Next of " << ptr->data << " is "
             << (ptr->next? ptr->next->data: -1)
             << endl;
        ptr = ptr->next;
    }
    return 0;
}

/*C++ program to populate inorder
 traversal of all nodes*/

#include<bits/stdc++.h>
using namespace std;

class node
{
    public:
    int data;
    node *left;
    node *right;
    node *next;
};

/*An implementation that doesn't use static variable
A wrapper over populateNextRecur*/

void populateNext(node *root)
{

/*    The first visited node will be the rightmost node
    next of the rightmost node will be NULL*/

    node *next = NULL;
    populateNextRecur(root, &next);
}

/* Set next of all descendents of p by
traversing them in reverse Inorder */

void populateNextRecur(node* p, node **next_ref)
{
    if (p)
    {

/*        First set the next pointer in right subtree*/

        populateNextRecur(p->right, next_ref);

/*        Set the next as previously visited
        node in reverse Inorder*/

        p->next = *next_ref;

/*        Change the prev for subsequent node*/

        *next_ref = p;

/*        Finally, set the next pointer in right subtree*/

        populateNextRecur(p->left, next_ref);
    }
}

/*CPP program to find inorder successor of a node*/

#include<bits/stdc++.h>
using namespace std;

/*A Binary Tree Node*/

struct Node
{
    int data;
    struct Node *left, *right;
};

/*Temporary node for case 2*/

Node* temp = new Node;

/*Utility function to create a new tree node*/

Node* newNode(int data)
{
    Node *temp = new Node;
    temp->data = data;
    temp->left = temp->right = NULL;
    return temp;
}

/*function to find left most node in a tree*/

Node* leftMostNode(Node* node)
{
    while (node != NULL && node->left != NULL)
        node = node->left;
    return node;
}

/*function to find right most node in a tree*/

Node* rightMostNode(Node* node)
{
    while (node != NULL && node->right != NULL)
        node = node->right;
    return node;
}

/*recursive function to find the Inorder Scuccessor
when the right child of node x is NULL*/

Node* findInorderRecursive(Node* root, Node* x )
{
    if (!root)
        return NULL;
    if (root==x || (temp = findInorderRecursive(root->left,x)) ||
                   (temp = findInorderRecursive(root->right,x)))
    {
        if (temp)
        {
            if (root->left == temp)
            {
                cout << "Inorder Successor of " << x->data;
                cout << " is "<< root->data << "\n";
                return NULL;
            }
        }
        return root;
    }
    return NULL;
}

/*function to find inorder successor of 
a node*/

void inorderSuccesor(Node* root, Node* x)
{

/*    Case1: If right child is not NULL*/

    if (x->right != NULL)
    {
        Node* inorderSucc = leftMostNode(x->right);
        cout<<"Inorder Successor of "<<x->data<<" is ";
        cout<<inorderSucc->data<<"\n";
    }

/*    Case2: If right child is NULL*/

    if (x->right == NULL)
    {    
        int f = 0;
        Node* rightMost = rightMostNode(root);

/*        case3: If x is the right most node*/

        if (rightMost == x)
            cout << "No inorder successor! Right most node.\n";
        else
            findInorderRecursive(root, x);
    }
}

