    root->right->right = newNode(6);

/*    Case 1 */

    inorderSuccesor(root, root->right);

/*    case 2*/

    inorderSuccesor(root, root->left->left);

/*    case 3*/

    inorderSuccesor(root, root->right->right);
    return 0;
