/*    Case 1 */

    Node* next = NULL;
    inorderSuccessor(root, root->right, next);

/*    case 2 */

    next = NULL;
    inorderSuccessor(root, root->left->left, next);

/*    case 3 */

    next = NULL;
    inorderSuccessor(root, root->right->right, next);
    return 0;
}

/*C++ program to find n-th node of
Postorder Traversal of Binary Tree*/

#include <bits/stdc++.h>
using namespace std;

/*node of tree*/

struct Node {
    int data;
    Node *left, *right;
};

/*function to create a new node*/

struct Node* createNode(int item)
{
    Node* temp = new Node;
    temp->data = item;
    temp->left = NULL;
    temp->right = NULL;
    return temp;
}

/*function to find the N-th node in the postorder
traversal of a given binary tree*/

void NthPostordernode(struct Node* root, int N)
{
    static int flag = 0;
    if (root == NULL)
        return;
    if (flag <= N) {

/*        left recursion*/

        NthPostordernode(root->left, N);

/*        right recursion*/

        NthPostordernode(root->right, N);
        flag++;

/*        prints the n-th node of preorder traversal*/

        if (flag == N)
            cout << root->data;
    }
}

