{
    struct Node* root = createNode(25);
    root->left = createNode(20);
    root->right = createNode(30);
    root->left->left = createNode(18);
    root->left->right = createNode(22);
    root->right->left = createNode(24);
    root->right->right = createNode(32);
    int N = 6;

/*    prints n-th node found*/

    NthPostordernode(root, N);
    return 0;
}

/* C++ program to print levels 
line by line */

#include <bits/stdc++.h>
using namespace std;

/*A Binary Tree Node*/

struct node
{
    struct node *left;
    int data;
    struct node *right;
};

/*Function to do level order
traversal line by line*/

void levelOrder(node *root)
{
    if (root == NULL) return;

/*    Create an empty queue for
    level order traversal*/

    queue<node *> q;

/*    to store front element of 
    queue.*/

    node *curr;

/*    Pushing root node into the queue.*/

    q.push(root);

/*    Pushing delimiter into the queue.*/

    q.push(NULL);

/*        condition to check 
        occurrence of next 
        level.*/
    while (q.size() > 1)
    {
        curr = q.front();
        q.pop();

/*      condition to check the
      occurence of next level*/

        if (curr == NULL)
        {
           q.push(NULL);
           cout << "\n";
        }
        else {

/*            pushing left child of 
            current node.*/

            if(curr->left)
            q.push(curr->left);

/*            pushing right child of
            current node.*/

            if(curr->right)
            q.push(curr->right);
            cout << curr->data << " ";
        }
    }
}

/*Utility function to create a
new tree node*/

node* newNode(int data)
{
    node *temp = new node;
    temp->data = data;
    temp->left = NULL;
    temp->right = NULL;
    return temp;
}

