/* C++ program for special order traversal */

#include <bits/stdc++.h>
using namespace std;

/* A binary tree node has data, pointer to left child
and a pointer to right child */

struct Node
{
    int data;
    Node *left, *right;
};

/* Helper function that allocates a new node with the
given data and NULL left and right pointers. */

Node* newNode(int data)
{
    Node* node = new Node;
    node->data = data;
    node->right = node->left = NULL;
    return node;
}

/*Function body*/

void printSpecificLevelOrderUtil(Node* root, stack<Node*> &s)
{
    if (root == NULL)
        return;

/*    Create a queue and enqueue left and right
    children of root*/

    queue<Node*> q;
    q.push(root->left);
    q.push(root->right);

/*    We process two nodes at a time, so we
    need two variables to store two front
    items of queue*/

    Node *first = NULL, *second = NULL;

/*    traversal loop*/

    while (!q.empty())
    {

/*        Pop two items from queue*/

        first = q.front();
        q.pop();
        second = q.front();
        q.pop();

/*        Push first and second node's chilren
        in reverse order*/

        s.push(second->left);
        s.push(first->right);
        s.push(second->right);
        s.push(first->left);

/*        If first and second have grandchildren,
        enqueue them in specific order*/

        if (first->left->left != NULL)
        {
            q.push(first->right);
            q.push(second->left);
            q.push(first->left);
            q.push(second->right);
        }
    }
}

/* Given a perfect binary tree, print its nodes in
specific level order */

void printSpecificLevelOrder(Node* root)
{

/*    create a stack and push root*/

    stack<Node*> s;

/*    Push level 1 and level 2 nodes in stack*/

    s.push(root);

/*    Since it is perfect Binary Tree, right is
    not checked*/

    if (root->left != NULL)
    {
        s.push(root->right);
        s.push(root->left);
    }

/*    Do anything more if there are nodes at next
    level in given perfect Binary Tree*/

    if (root->left->left != NULL)
        printSpecificLevelOrderUtil(root, s);

/*    Finally pop all Nodes from stack and prints
    them.*/

    while (!s.empty())
    {
        cout << s.top()->data << " ";
        s.pop();
    }
}

/* Driver program to test above functions*/

int main()
{
    Node* root = newNode(1);
    root->left = newNode(2);
    root->right = newNode(3);
    cout << "Specific Level Order traversal of binary "
         "tree is \n";
    printSpecificLevelOrder(root);
    return 0;
}

/* C++ program for special order traversal */

#include<bits/stdc++.h>
using namespace std;

/* A binary tree node has data, pointer to left child
and a pointer to right child */

class Node
{
    public:
        int data;
        Node* left;
        Node* right;

/* Helper function that allocates a new node with the
        given data and NULL left and right pointers. */

        Node(int value)
        {
            data = value;
            left = NULL;
            right = NULL;
        }
};

/* Given a perfect binary tree, print its nodes in
specific level order */

void specific_level_order_traversal(Node* root)
{

/*    for level order traversal*/

    queue <Node*> q;

/*    stack to print reverse*/

    stack < vector <int> > s;
    q.push(root);
    int sz;
    while(!q.empty())
    {

/*vector to store the level*/

vector <int> v;

/*considering size of the level*/

sz = q.size();    
        for(int i=0;i<sz;++i)
        {
            Node* temp = q.front();
            q.pop();

/*            push data of the node of a particular level to vector*/

            v.push_back(temp->data);
            if(temp->left!=NULL)
            q.push(temp->left);
            if(temp->right!=NULL)
                q.push(temp->right);
        }

/*        push vector containing a level in stack*/

        s.push(v);
    }

/*    print the stack*/

    while(!s.empty())
    {

/*        Finally pop all Nodes from stack and prints
        them.*/

        vector <int> v = s.top();
        s.pop();
        for(int i=0,j=v.size()-1;i<j;++i)
            {
                cout<<v[i]<<" "<<v[j]<<" ";
                j--;
            }
    }

/*    finally print root;*/

    cout<<root->data;
}

