}

/*C++ program to implement iterative preorder traversal*/

#include <bits/stdc++.h>
using namespace std;

/* A binary tree node has data, left child and right child */

struct node {
    int data;
    struct node* left;
    struct node* right;
};

/* Helper function that allocates a new node with the given data and
   NULL left and right  pointers.*/

struct node* newNode(int data)
{
    struct node* node = new struct node;
    node->data = data;
    node->left = NULL;
    node->right = NULL;
    return (node);
}

/*An iterative process to print preorder traversal of Binary tree*/

void iterativePreorder(node* root)
{

/*    Base Case*/

    if (root == NULL)
        return;

/*    Create an empty stack and push root to it*/

    stack<node*> nodeStack;
    nodeStack.push(root);

/* Pop all items one by one. Do following for every popped item
       a) print it
       b) push its right child
       c) push its left child
    Note that right child is pushed first so that left is processed first */

    while (nodeStack.empty() == false) {

/*        Pop the top item from stack and print it*/

        struct node* node = nodeStack.top();
        printf("%d ", node->data);
        nodeStack.pop();

/*        Push right and left children of the popped node to stack*/

        if (node->right)
            nodeStack.push(node->right);
        if (node->left)
            nodeStack.push(node->left);
    }
}

/*Driver program to test above functions*/

int main()
{
    struct node* root = newNode(10);
    root->left = newNode(8);
    root->right = newNode(2);
    root->left->left = newNode(3);
    root->left->right = newNode(5);
    root->right->left = newNode(2);
    iterativePreorder(root);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

/*Tree Node*/

struct Node {
    int data;
    Node *left, *right;
    Node(int data)
    {
        this->data = data;
        this->left = this->right = NULL;
    }
};

/*Iterative function to do Preorder traversal of the tree*/

void preorderIterative(Node* root)
{
    if (root == NULL)
        return;
    stack<Node*> st;

/*    start from root node (set current node to root node)*/

    Node* curr = root;

/*    run till stack is not empty or current is
    not NULL*/

    while (!st.empty() || curr != NULL) {

/*        Print left children while exist
        and keep pushing right into the
        stack.*/

        while (curr != NULL) {
            cout << curr->data << " ";
            if (curr->right)
                st.push(curr->right);
            curr = curr->left;
        }

/*        We reach when curr is NULL, so We
        take out a right child from stack*/

        if (st.empty() == false) {
            curr = st.top();
            st.pop();
        }
    }
}

/*Driver Code*/

int main()
{
    Node* root = new Node(10);
    root->left = new Node(20);
    root->right = new Node(30);
    root->left->left = new Node(40);
    root->left->left->left = new Node(70);
    root->left->right = new Node(50);
    root->right->left = new Node(60);
    root->left->left->right = new Node(80);
    preorderIterative(root);
    return 0;
}

/*CPP program or postorder traversal*/

#include <bits/stdc++.h>
using namespace std;

/* A binary tree node has data, pointer to left child
and a pointer to right child */

struct Node {
    int data;
    struct Node *left, *right;
};

/* Helper function that allocates a new node with the
given data and NULL left and right pointers. */

void postorder(struct Node* head)
{
    struct Node* temp = head;
    unordered_set<Node*> visited;
    while (temp && visited.find(temp) == visited.end()) {

/*        Visited left subtree*/

        if (temp->left &&
         visited.find(temp->left) == visited.end())
            temp = temp->left;

/*        Visited right subtree*/

        else if (temp->right &&
        visited.find(temp->right) == visited.end())
            temp = temp->right;

/*        Print node*/

        else {
            printf("%d ", temp->data);
            visited.insert(temp);
            temp = head;
        }
    }
}
struct Node* newNode(int data)
{
    struct Node* node = new Node;
    node->data = data;
    node->left = NULL;
    node->right = NULL;
    return (node);
}

