    root->left->left = newNode(1);
    root->left->right = newNode(6);
    root->right->right = newNode(14);
    root->right->right->left = newNode(13);
    root->left->right->left = newNode(4);
    root->left->right->right = newNode(7);
    diagonalPrint(root);
    return 0;
}

/* C++ program to construct string from binary tree*/

#include <bits/stdc++.h>
using namespace std;

/* A binary tree node has data, pointer to left
   child and a pointer to right child */

struct Node {
    int data;
    Node *left, *right;
};

/* Helper function that allocates a new node */

Node* newNode(int data)
{
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = data;
    node->left = node->right = NULL;
    return (node);
}

/*Iterative function to print diagonal view*/

void diagonalPrint(Node* root)
{

/*    base case*/

    if (root == NULL)
        return;

/*    inbuilt queue of Treenode*/

    queue<Node*> q;

/*    push root*/

    q.push(root);

/*    push delimiter*/

    q.push(NULL);
    while (!q.empty()) {
        Node* temp = q.front();
        q.pop();

/*        if current is delimiter then insert another
        for next diagonal and cout nextline*/

        if (temp == NULL) {

/*            if queue is empty return*/

            if (q.empty())
                return;

/*            output nextline*/

            cout << endl;

/*            push delimiter again*/

            q.push(NULL);
        }
        else {
            while (temp) {
                cout << temp->data << " ";

/*                if left child is present
                push into queue*/

                if (temp->left)
                    q.push(temp->left);

/*                current equals to right child*/

                temp = temp->right;
            }
        }
    }
}

/*Driver Code*/

int main()
{
    Node* root = newNode(8);
    root->left = newNode(3);
    root->right = newNode(10);
    root->left->left = newNode(1);
    root->left->right = newNode(6);
    root->right->right = newNode(14);
    root->right->right->left = newNode(13);
    root->left->right->left = newNode(4);
    root->left->right->right = newNode(7);
    diagonalPrint(root);
}

/* C program for boundary traversal 
of a binary tree */

#include <stdio.h>
#include <stdlib.h>

/* A binary tree node has data, pointer to left child
and a pointer to right child */

struct node {
    int data;
    struct node *left, *right;
};

/*A simple function to print leaf nodes of a binary tree*/

void printLeaves(struct node* root)
{
    if (root == NULL)
        return;
    printLeaves(root->left);

/*    Print it if it is a leaf node*/

    if (!(root->left) && !(root->right))
        printf("%d ", root->data);
    printLeaves(root->right);
}

/*A function to print all left boundary nodes, except a leaf node.
Print the nodes in TOP DOWN manner*/

void printBoundaryLeft(struct node* root)
{
    if (root == NULL)
        return;
    if (root->left) {

/*        to ensure top down order, print the node
        before calling itself for left subtree*/

        printf("%d ", root->data);
        printBoundaryLeft(root->left);
    }
    else if (root->right) {
        printf("%d ", root->data);
        printBoundaryLeft(root->right);
    }

/*    do nothing if it is a leaf node, this way we avoid
    duplicates in output*/

}

/*A function to print all right boundary nodes, except a leaf node
Print the nodes in BOTTOM UP manner*/

void printBoundaryRight(struct node* root)
{
    if (root == NULL)
        return;
    if (root->right) {

/*        to ensure bottom up order, first call for right
        subtree, then print this node*/

        printBoundaryRight(root->right);
        printf("%d ", root->data);
    }
    else if (root->left) {
        printBoundaryRight(root->left);
        printf("%d ", root->data);
    }

/*    do nothing if it is a leaf node, this way we avoid
    duplicates in output*/

}

/*A function to do boundary traversal of a given binary tree*/

void printBoundary(struct node* root)
{
    if (root == NULL)
        return;
    printf("%d ", root->data);

/*    Print the left boundary in top-down manner.*/

    printBoundaryLeft(root->left);

/*    Print all leaf nodes*/

    printLeaves(root->left);
    printLeaves(root->right);

/*    Print the right boundary in bottom-up manner*/

    printBoundaryRight(root->right);
}

/*A utility function to create a node*/

struct node* newNode(int data)
{
    struct node* temp = (struct node*)malloc(sizeof(struct node));
    temp->data = data;
    temp->left = temp->right = NULL;
    return temp;
}

