        40 
        / \ 
        10 30 
        /     \ 
        5     28 */

    int inorder[] = {5, 10, 40, 30, 28}; 
    int len = sizeof(inorder)/sizeof(inorder[0]); 
    node *root = buildTree(inorder, 0, len - 1);

/* Let us test the built tree by printing Insorder traversal */

