/*C++ program to construct a Binary Tree from parent array*/

#include<bits/stdc++.h>
using namespace std;

/*A tree node*/

struct Node
{
    int key;
    struct Node *left, *right;
};

/*Utility function to create new Node*/

Node *newNode(int key)
{
    Node *temp = new Node;
    temp->key  = key;
    temp->left  = temp->right = NULL;
    return (temp);
}

/*Creates a node with key as 'i'.  If i is root, then it changes
root.  If parent of i is not created, then it creates parent first*/

void createNode(int parent[], int i, Node *created[], Node **root)
{

/*    If this node is already created*/

    if (created[i] != NULL)
        return;

/*    Create a new node and set created[i]*/

    created[i] = newNode(i);

/*    If 'i' is root, change root pointer and return*/

    if (parent[i] == -1)
    {
        *root = created[i];
        return;
    }

/*    If parent is not created, then create parent first*/

    if (created[parent[i]] == NULL)
        createNode(parent, parent[i], created, root);

/*    Find parent pointer*/

    Node *p = created[parent[i]];

/*    If this is first child of parent*/

    if (p->left == NULL)
        p->left = created[i];

/*If second child*/

else 
        p->right = created[i];
}

/*Creates tree from parent[0..n-1] and returns root of the created tree*/

Node *createTree(int parent[], int n)
{

/*    Create an array created[] to keep track
    of created nodes, initialize all entries
    as NULL*/

    Node *created[n];
    for (int i=0; i<n; i++)
        created[i] = NULL;
    Node *root = NULL;
    for (int i=0; i<n; i++)
        createNode(parent, i, created, &root);
    return root;
}

/*For adding new line in a program*/

inline void newLine(){
    cout << "\n";
}

/*Utility function to do inorder traversal*/

void inorder(Node *root)
{
    if (root != NULL)
    {
        inorder(root->left);
        cout << root->key << " ";
        inorder(root->right);
    }
}

/*Driver method*/

int main()
{
    int parent[] =  {-1, 0, 0, 1, 1, 3, 5};
    int n = sizeof parent / sizeof parent[0];
    Node *root = createTree(parent, n);
    cout << "Inorder Traversal of constructed tree\n";
    inorder(root);
    newLine();
}

/* C++ program to construct tree using inorder and
   postorder traversals */

#include <bits/stdc++.h>
using namespace std;

/* A binary tree node has data, pointer to left
   child and a pointer to right child */

struct Node {
    int data;
    Node *left, *right;
};

/*Utility function to create a new node*/

Node* newNode(int data);
int search(int arr[], int strt, int end, int value);

/* Recursive function to construct binary of size n
   from  Inorder traversal in[] and Postorder traversal
   post[].  Initial values of inStrt and inEnd should
   be 0 and n -1.  The function doesn't do any error
   checking for cases where inorder and postorder
   do not form a tree */

Node* buildUtil(int in[], int post[], int inStrt,
                int inEnd, int* pIndex)
{

/*    Base case*/

    if (inStrt > inEnd)
        return NULL;

/* Pick current node from Postorder traversal using
       postIndex and decrement postIndex */

    Node* node = newNode(post[*pIndex]);
    (*pIndex)--;

/* If this node has no children then return */

    if (inStrt == inEnd)
        return node;

/* Else find the index of this node in Inorder
       traversal */

    int iIndex = search(in, inStrt, inEnd, node->data);

/* Using index in Inorder traversal, construct left and
       right subtress */

    node->right = buildUtil(in, post, iIndex + 1, inEnd, pIndex);
    node->left = buildUtil(in, post, inStrt, iIndex - 1, pIndex);
    return node;
}

/*This function mainly initializes index of root
and calls buildUtil()*/

Node* buildTree(int in[], int post[], int n)
{
    int pIndex = n - 1;
    return buildUtil(in, post, 0, n - 1, &pIndex);
}

/* Function to find index of value in arr[start...end]
   The function assumes that value is postsent in in[] */

int search(int arr[], int strt, int end, int value)
{
    int i;
    for (i = strt; i <= end; i++) {
        if (arr[i] == value)
            break;
    }
    return i;
}

/* Helper function that allocates a new node */

Node* newNode(int data)
{
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = data;
    node->left = node->right = NULL;
    return (node);
}

/* This funtcion is here just to test  */

void preOrder(Node* node)
{
    if (node == NULL)
        return;
    printf("%d ", node->data);
    preOrder(node->left);
    preOrder(node->right);
}

/*Driver code*/

int main()
{
    int in[] = { 4, 8, 2, 5, 1, 6, 3, 7 };
    int post[] = { 8, 4, 5, 2, 6, 7, 3, 1 };
    int n = sizeof(in) / sizeof(in[0]);
    Node* root = buildTree(in, post, n);
    cout << "Preorder of the constructed tree : \n";
    preOrder(root);
    return 0;
}

/* C++ program to construct tree using inorder and
postorder traversals */

#include <bits/stdc++.h>
using namespace std;

/* A binary tree node has data, pointer to left
child and a pointer to right child */

struct Node {
    int data;
    Node *left, *right;
};

/*Utility function to create a new node*/

Node* newNode(int data);

/* Recursive function to construct binary of size n
from Inorder traversal in[] and Postorder traversal
post[]. Initial values of inStrt and inEnd should
be 0 and n -1. The function doesn't do any error
checking for cases where inorder and postorder
do not form a tree */

Node* buildUtil(int in[], int post[], int inStrt,
    int inEnd, int* pIndex, unordered_map<int, int>& mp)
{

/*    Base case*/

    if (inStrt > inEnd)
        return NULL;

/* Pick current node from Postorder traversal 
    using postIndex and decrement postIndex */

    int curr = post[*pIndex];
    Node* node = newNode(curr);
    (*pIndex)--;

/* If this node has no children then return */

    if (inStrt == inEnd)
        return node;

/* Else find the index of this node in Inorder
    traversal */

    int iIndex = mp[curr];

/* Using index in Inorder traversal, construct
    left and right subtress */

    node->right = buildUtil(in, post, iIndex + 1,
                            inEnd, pIndex, mp);
    node->left = buildUtil(in, post, inStrt,
                           iIndex - 1, pIndex, mp);
    return node;
}

/*This function mainly creates an unordered_map, then
calls buildTreeUtil()*/

struct Node* buildTree(int in[], int post[], int len)
{

/*    Store indexes of all items so that we
    we can quickly find later*/

    unordered_map<int, int> mp;
    for (int i = 0; i < len; i++)
        mp[in[i]] = i;

/*Index in postorder*/

int index = len - 1; 
    return buildUtil(in, post, 0, len - 1,
                     &index, mp);
}

/* Helper function that allocates a new node */

Node* newNode(int data)
{
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = data;
    node->left = node->right = NULL;
    return (node);
}

