void preOrder(Node* node)
{
    if (node == NULL)
        return;
    printf("%d ", node->data);
    preOrder(node->left);
    preOrder(node->right);
}

/*Driver code*/

int main()
{
    int in[] = { 4, 8, 2, 5, 1, 6, 3, 7 };
    int post[] = { 8, 4, 5, 2, 6, 7, 3, 1 };
    int n = sizeof(in) / sizeof(in[0]);
    Node* root = buildTree(in, post, n);
    cout << "Preorder of the constructed tree : \n";
    preOrder(root);
    return 0;
}

/*C++ program for above approach*/

#include <bits/stdc++.h>
using namespace std;

/* Node class */

struct Node
{
  int data;
  Node *left, *right;

/*        Constructor*/

Node(int x)
  {
    data = x;
    left = right = NULL;
  }
};

/*Tree building function*/

Node *buildTree(int in[], int post[], int n)
{

/*  Create Stack of type Node**/

  stack<Node*> st;

/*  Create Set of type Node**/

  set<Node*> s;

/*  Initialise postIndex with n - 1*/

  int postIndex = n - 1;

/*  Initialise root with NULL*/

  Node* root = NULL;
  for (int p = n - 1, i = n - 1; p>=0; ) 
  {

/*    Initialise node with NULL*/

    Node* node = NULL;

/*    Run do-while loop*/

    do
    {

/*      Initialise node with
      new Node(post[p]);*/

      node = new Node(post[p]);

/*      Check is root is
      equal to NULL*/

      if (root == NULL)
      {
        root = node;
      }

/*      If size of set
      is greater than 0*/

      if (st.size() > 0) 
      {

/*        If st.top() is present in the
        set s*/

        if (s.find(st.top()) != s.end())
        {
          s.erase(st.top());
          st.top()->left = node;
          st.pop();
        }
        else
        {
          st.top()->right = node;
        }
      }
      st.push(node);
    } while (post[p--] != in[i] && p >=0);
    node = NULL;

/*    If the stack is not empty and
    st.top()->data is equal to in[i]*/

    while (st.size() > 0 && i>=0 && 
           st.top()->data == in[i]) 
    {
      node = st.top();

/*      Pop elements from stack*/

      st.pop();
      i--;
    }

/*    if node not equal to NULL*/

    if (node != NULL) 
    {
      s.insert(node);
      st.push(node);
    }
  }

/*  Return root*/

  return root;
}

/* for print preOrder Traversal */

void preOrder(Node* node)
{
  if (node == NULL)
    return;
  printf("%d ", node->data);
  preOrder(node->left);
  preOrder(node->right);
}

/*Driver Code*/

int main()
{
  int in[] = { 4, 8, 2, 5, 1, 6, 3, 7 };
  int post[] = { 8, 4, 5, 2, 6, 7, 3, 1 };
  int n = sizeof(in) / sizeof(in[0]);

/*  Function Call*/

  Node* root = buildTree(in, post, n);
  cout << "Preorder of the constructed
                                tree : \n";

/*  Function Call for preOrder*/

  preOrder(root);
  return 0;
}

/*C++ program to create a tree with left child
right sibling representation.*/

#include<bits/stdc++.h>
using namespace std;
struct Node
{
    int data;
    struct Node *next;
    struct Node *child;
};

/*Creating new Node*/

Node* newNode(int data)
{
    Node *newNode = new Node;
    newNode->next = newNode->child = NULL;
    newNode->data = data;
    return newNode;
}

/*Adds a sibling to a list with starting with n*/

Node *addSibling(Node *n, int data)
{
    if (n == NULL)
        return NULL;
    while (n->next)
        n = n->next;
    return (n->next = newNode(data));
}

/*Add child Node to a Node*/

Node *addChild(Node * n, int data)
{
    if (n == NULL)
        return NULL;

/*    Check if child list is not empty.*/

    if (n->child)
        return addSibling(n->child, data);
    else
        return (n->child = newNode(data));
}

/*Traverses tree in depth first order*/

void traverseTree(Node * root)
{
    if (root == NULL)
        return;
    while (root)
    {
        cout << " " << root->data;
        if (root->child)
            traverseTree(root->child);
        root = root->next;
    }
}

/*Driver code*/

int main()
{
    Node *root = newNode(10);
    Node *n1  = addChild(root, 2);
    Node *n2  = addChild(root, 3);
    Node *n3  = addChild(root, 4);
    Node *n4  = addChild(n3, 6);
    Node *n5  = addChild(root, 5);
    Node *n6  = addChild(n5, 7);
    Node *n7  = addChild(n5, 8);
    Node *n8  = addChild(n5, 9);
    traverseTree(root);
    return 0;
}

/*C++ program to create a tree with left child
right sibling representation.*/

#include <bits/stdc++.h>
using namespace std;
struct Node {
    int data;
    struct Node* next;
    struct Node* child;
};

/*Creating new Node*/

Node* newNode(int data)
{
    Node* newNode = new Node;
    newNode->next = newNode->child = NULL;
    newNode->data = data;
    return newNode;
}

/*Adds a sibling to a list with starting with n*/

Node* addSibling(Node* n, int data)
{
    if (n == NULL)
        return NULL;
    while (n->next)
        n = n->next;
    return (n->next = newNode(data));
}

/*Add child Node to a Node*/

Node* addChild(Node* n, int data)
{
    if (n == NULL)
        return NULL;

/*    Check if child list is not empty.*/

    if (n->child)
        return addSibling(n->child, data);
    else
        return (n->child = newNode(data));
}

/*Traverses tree in level order*/

void traverseTree(Node* root)
{

/*    Corner cases*/

    if (root == NULL)
        return;
    cout << root->data << " ";
    if (root->child == NULL)
        return;

/*    Create a queue and enque root*/

    queue<Node*> q;
    Node* curr = root->child;
    q.push(curr);
    while (!q.empty()) {

/*        Take out an item from the queue*/

        curr = q.front();
        q.pop();

/*        Print next level of taken out item and enque
        next level's children*/

        while (curr != NULL) {
            cout << curr->data << " ";
            if (curr->child != NULL) {
                q.push(curr->child);
            }
            curr = curr->next;
        }
    }
}

/*Driver code*/

int main()
{
    Node* root = newNode(10);
    Node* n1 = addChild(root, 2);
    Node* n2 = addChild(root, 3);
    Node* n3 = addChild(root, 4);
    Node* n4 = addChild(n3, 6);
    Node* n5 = addChild(root, 5);
    Node* n6 = addChild(n5, 7);
    Node* n7 = addChild(n5, 8);
    Node* n8 = addChild(n5, 9);
    traverseTree(root);
    return 0;
}

/*C++ program to build full k-ary tree from
its preorder traversal and to print the
postorder traversal of the tree.*/

#include <bits/stdc++.h>
using namespace std;

/*Structure of a node of an n-ary tree*/

struct Node {
    int key;
    vector<Node*> child;
};

/*Utility function to create a new tree 
node with k children*/

Node* newNode(int value)
{
    Node* nNode = new Node;
    nNode->key = value;
    return nNode;
}

/*Function to build full k-ary tree*/

Node* BuildKaryTree(int A[], int n, int k, int h, int& ind)
{

/*    For null tree*/

    if (n <= 0)
        return NULL;
    Node* nNode = newNode(A[ind]);
    if (nNode == NULL) {
        cout << "Memory error" << endl;
        return NULL;
    }

/*    For adding k children to a node*/

    for (int i = 0; i < k; i++) {

/*        Check if ind is in range of array
        Check if height of the tree is greater than 1*/

        if (ind < n - 1 && h > 1) {
            ind++;

/*            Recursively add each child*/

            nNode->child.push_back(BuildKaryTree(A, n, k, h - 1, ind));
        } else {
            nNode->child.push_back(NULL);
        }
    }
    return nNode;
}

/*Function to find the height of the tree*/

Node* BuildKaryTree(int* A, int n, int k, int ind)
{
    int height = (int)ceil(log((double)n * (k - 1) + 1) 
                 / log((double)k));
    return BuildKaryTree(A, n, k, height, ind);
}

/*Function to print postorder traversal of the tree*/

void postord(Node* root, int k)
{
    if (root == NULL)
        return;
    for (int i = 0; i < k; i++)
        postord(root->child[i], k);
    cout << root->key << " ";
}

/*Driver program to implement full k-ary tree*/

int main()
{
    int ind = 0;
    int k = 3, n = 10;
    int preorder[] = { 1, 2, 5, 6, 7, 3, 8, 9, 10, 4 };
    Node* root = BuildKaryTree(preorder, n, k, ind);
    cout << "Postorder traversal of constructed"
             " full k-ary tree is: ";
    postord(root, k);
    cout << endl;
    return 0;
}

/* C++ program to construct a binary tree from
   the given string */

#include <bits/stdc++.h>
using namespace std;

/* A binary tree node has data, pointer to left
   child and a pointer to right child */

struct Node {
    int data;
    Node *left, *right;
};

/* Helper function that allocates a new node */

Node* newNode(int data)
{
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = data;
    node->left = node->right = NULL;
    return (node);
}

/* This function is here just to test  */

void preOrder(Node* node)
{
    if (node == NULL)
        return;
    printf("%d ", node->data);
    preOrder(node->left);
    preOrder(node->right);
}

/*function to return the index of close parenthesis*/

int findIndex(string str, int si, int ei)
{
    if (si > ei)
        return -1;

/*    Inbuilt stack*/

    stack<char> s;
    for (int i = si; i <= ei; i++) {

/*        if open parenthesis, push it*/

        if (str[i] == '(')
            s.push(str[i]);

/*        if close parenthesis*/

        else if (str[i] == ')') {
            if (s.top() == '(') {
                s.pop();

/*                if stack is empty, this is
                the required index*/

                if (s.empty())
                    return i;
            }
        }
    }

/*    if not found return -1*/

    return -1;
}

/*function to construct tree from string*/

Node* treeFromString(string str, int si, int ei)
{

/*    Base case*/

    if (si > ei)
        return NULL;

/*    new root*/

    Node* root = newNode(str[si] - '0');
    int index = -1;

/*    if next char is '(' find the index of
    its complement ')'*/

    if (si + 1 <= ei && str[si + 1] == '(')
        index = findIndex(str, si + 1, ei);

/*    if index found*/

    if (index != -1) {

/*        call for left subtree*/

        root->left = treeFromString(str, si + 2, index - 1);

/*        call for right subtree*/

        root->right
            = treeFromString(str, index + 2, ei - 1);
    }
    return root;
}

/*Driver Code*/

int main()
{
    string str = "4(2(3)(1))(6(5))";
    Node* root = treeFromString(str, 0, str.length() - 1);
    preOrder(root);
}

/*Program for linked implementation of complete binary tree*/

#include <bits/stdc++.h>
using namespace std;

/*For Queue Size*/

#define SIZE 50

/*A tree node*/

class node
{
    public:
    int data;
    node *right,*left;
};

/*A queue node*/

class Queue
{
    public:
    int front, rear;
    int size;
    node**array;
};

/*A utility function to create a new tree node*/

node* newNode(int data)
{
    node* temp = new node();
    temp->data = data;
    temp->left = temp->right = NULL;
    return temp;
}

/*A utility function to create a new Queue*/

Queue* createQueue(int size)
{
    Queue* queue = new Queue();
    queue->front = queue->rear = -1;
    queue->size = size;
    queue->array = new node*[queue->size * sizeof( node* )];
    int i;
    for (i = 0; i < size; ++i)
        queue->array[i] = NULL;
    return queue;
}

/*Standard Queue Functions*/

int isEmpty(Queue* queue)
{
    return queue->front == -1;
}
int isFull(Queue* queue)
{ return queue->rear == queue->size - 1; }
int hasOnlyOneItem(Queue* queue)
{ return queue->front == queue->rear; }
void Enqueue(node *root, Queue* queue)
{
    if (isFull(queue))
        return;
    queue->array[++queue->rear] = root;
    if (isEmpty(queue))
        ++queue->front;
}
node* Dequeue(Queue* queue)
{
    if (isEmpty(queue))
        return NULL;
    node* temp = queue->array[queue->front];
    if (hasOnlyOneItem(queue))
        queue->front = queue->rear = -1;
    else
        ++queue->front;
    return temp;
}
node* getFront(Queue* queue)
{ return queue->array[queue->front]; }

/*A utility function to check if a tree node
has both left and right children*/

int hasBothChild(node* temp)
{
    return temp && temp->left && temp->right;
}

/*Function to insert a new node in complete binary tree*/

void insert(node **root, int data, Queue* queue)
{

/*    Create a new node for given data*/

    node *temp = newNode(data);

/*    If the tree is empty, initialize the root with new node.*/

    if (!*root)
        *root = temp;
    else
    {

/*        get the front node of the queue.*/

        node* front = getFront(queue);

/*        If the left child of this front node doesn t exist, set the
        left child as the new node*/

        if (!front->left)
            front->left = temp;

/*        If the right child of this front node doesn t exist, set the
        right child as the new node*/

        else if (!front->right)
            front->right = temp;

/*        If the front node has both the left child and right child,
        Dequeue() it.*/

        if (hasBothChild(front))
            Dequeue(queue);
    }

/*    Enqueue() the new node for later insertions*/

    Enqueue(temp, queue);
}

/*Standard level order traversal to test above function*/

void levelOrder(node* root)
{
    Queue* queue = createQueue(SIZE);
    Enqueue(root, queue);
    while (!isEmpty(queue))
    {
        node* temp = Dequeue(queue);
        cout<<temp->data<<" ";
        if (temp->left)
            Enqueue(temp->left, queue);
        if (temp->right)
            Enqueue(temp->right, queue);
    }
}

/*Driver program to test above functions*/

int main()
{
    node* root = NULL;
    Queue* queue = createQueue(SIZE);
    int i;
    for(i = 1; i <= 12; ++i)
        insert(&root, i, queue);
    levelOrder(root);
    return 0;
}

/*A C++ program for in-place
conversion of Binary Tree to DLL*/

#include <bits/stdc++.h>
using namespace std;

/* A binary tree node has data,
and left and right pointers */

class node {
public:
    int data;
    node* left;
    node* right;
};

/* This is the core function to convert
Tree to list. This function follows
steps 1 and 2 of the above algorithm */

node* bintree2listUtil(node* root)
{

/*    Base case*/

    if (root == NULL)
        return root;

/*    Convert the left subtree and link to root*/

    if (root->left != NULL) {

/*        Convert the left subtree*/

        node* left = bintree2listUtil(root->left);

/*        Find inorder predecessor. After this loop, left
        will point to the inorder predecessor*/

        for (; left->right != NULL; left = left->right)
            ;

/*        Make root as next of the predecessor*/

        left->right = root;

/*        Make predecssor as previous of root*/

        root->left = left;
    }

/*    Convert the right subtree and link to root*/

    if (root->right != NULL) {

/*        Convert the right subtree*/

        node* right = bintree2listUtil(root->right);

/*        Find inorder successor. After this loop, right
        will point to the inorder successor*/

        for (; right->left != NULL; right = right->left)
            ;

/*        Make root as previous of successor*/

        right->left = root;

/*        Make successor as next of root*/

        root->right = right;
    }
    return root;
}

/*The main function that first calls
bintree2listUtil(), then follows step 3
of the above algorithm*/

node* bintree2list(node* root)
{

/*    Base case*/

    if (root == NULL)
        return root;

/*    Convert to DLL using bintree2listUtil()*/

    root = bintree2listUtil(root);

/*    bintree2listUtil() returns root node of the converted
    DLL. We need pointer to the leftmost node which is
    head of the constructed DLL, so move to the leftmost
    node*/

    while (root->left != NULL)
        root = root->left;
    return (root);
}

/* Helper function that allocates a new node with the
given data and NULL left and right pointers. */

node* newNode(int data)
{
    node* new_node = new node();
    new_node->data = data;
    new_node->left = new_node->right = NULL;
    return (new_node);
}

/* Function to print nodes in a given doubly linked list */

void printList(node* node)
{
    while (node != NULL) {
        cout << node->data << " ";
        node = node->right;
    }
}

/* Driver code*/

int main()
{

/*    Let us create the tree shown in above diagram*/

    node* root = newNode(10);
    root->left = newNode(12);
    root->right = newNode(15);
    root->left->left = newNode(25);
    root->left->right = newNode(30);
    root->right->left = newNode(36);

/*    Convert to DLL*/

    node* head = bintree2list(root);

/*    Print the converted list*/

    printList(head);
    return 0;
}

/*A simple inorder traversal based
program to convert a Binary Tree to DLL*/

#include <bits/stdc++.h>
using namespace std;

/*A tree node*/

class node
{
    public:
    int data;
    node *left, *right;
};

/*A utility function to create
a new tree node*/

node *newNode(int data)
{
    node *Node = new node();
    Node->data = data;
    Node->left = Node->right = NULL;
    return(Node);
}

/*Standard Inorder traversal of tree*/

void inorder(node *root)
{
    if (root != NULL)
    {
        inorder(root->left);
        cout << "\t" << root->data;
        inorder(root->right);
    }
}

/*Changes left pointers to work as
previous pointers in converted DLL
The function simply does inorder
traversal of Binary Tree and updates
left pointer using previously visited node*/

void fixPrevPtr(node *root)
{
    static node *pre = NULL;
    if (root != NULL)
    {
        fixPrevPtr(root->left);
        root->left = pre;
        pre = root;
        fixPrevPtr(root->right);
    }
}

/*Changes right pointers to work
as next pointers in converted DLL*/

node *fixNextPtr(node *root)
{
    node *prev = NULL;

/*    Find the right most node
    in BT or last node in DLL*/

    while (root && root->right != NULL)
        root = root->right;

/*    Start from the rightmost node,
    traverse back using left pointers.
    While traversing, change right pointer of nodes.*/

    while (root && root->left != NULL)
    {
        prev = root;
        root = root->left;
        root->right = prev;
    }

/*    The leftmost node is head
    of linked list, return it*/

    return (root);
}

/*The main function that converts
BST to DLL and returns head of DLL*/

node *BTToDLL(node *root)
{

/*    Set the previous pointer*/

    fixPrevPtr(root);

/*    Set the next pointer and return head of DLL*/

    return fixNextPtr(root);
}

/*Traverses the DLL from left tor right*/

void printList(node *root)
{
    while (root != NULL)
    {
        cout<<"\t"<<root->data;
        root = root->right;
    }
}

/*Driver code*/

int main(void)
{

/*    Let us create the tree
    shown in above diagram*/

    node *root = newNode(10);
    root->left = newNode(12);
    root->right = newNode(15);
    root->left->left = newNode(25);
    root->left->right = newNode(30);
    root->right->left = newNode(36);
    cout<<"\n\t\tInorder Tree Traversal\n\n";
    inorder(root);
    node *head = BTToDLL(root);
    cout << "\n\n\t\tDLL Traversal\n\n";
    printList(head);
    return 0;
}

/*A C++ program for in-place conversion of Binary Tree to DLL*/

#include <iostream>
using namespace std;

/* A binary tree node has data, and left and right pointers */

struct node
{
    int data;
    node* left;
    node* right;
};

/*A simple recursive function to convert a given Binary tree to Doubly
Linked List
root --> Root of Binary Tree
head --> Pointer to head node of created doubly linked list*/

void BinaryTree2DoubleLinkedList(node *root, node **head)
{

/*    Base case*/

    if (root == NULL) return;

/*    Initialize previously visited node as NULL. This is
    static so that the same value is accessible in all recursive
    calls*/

    static node* prev = NULL;

/*    Recursively convert left subtree*/

    BinaryTree2DoubleLinkedList(root->left, head);

/*    Now convert this node*/

    if (prev == NULL)
        *head = root;
    else
    {
        root->left = prev;
        prev->right = root;
    }
    prev = root;

/*    Finally convert right subtree*/

    BinaryTree2DoubleLinkedList(root->right, head);
}

/* Helper function that allocates a new node with the
   given data and NULL left and right pointers. */

node* newNode(int data)
{
    node* new_node = new node;
    new_node->data = data;
    new_node->left = new_node->right = NULL;
    return (new_node);
}

/* Function to print nodes in a given doubly linked list */

void printList(node *node)
{
    while (node!=NULL)
    {
        cout << node->data << " ";
        node = node->right;
    }
}

/* Driver program to test above functions*/

int main()
{

/*    Let us create the tree shown in above diagram*/

    node *root        = newNode(10);
    root->left        = newNode(12);
    root->right       = newNode(15);
    root->left->left  = newNode(25);
    root->left->right = newNode(30);
    root->right->left = newNode(36);

/*    Convert to DLL*/

    node *head = NULL;
    BinaryTree2DoubleLinkedList(root, &head);

/*    Print the converted list*/

    printList(head);
    return 0;
}

/* C++ Program to convert an aribitary
binary tree to a tree that hold
children sum property */

#include<bits/stdc++.h> 
using namespace std;
class node 
{ 
    public:
    int data; 
    node* left; 
    node* right;

/* Constructor that allocates a new node 
    with the given data and NULL left and right 
    pointers. */

    node(int data)
    {
        this->data = data; 
        this->left = NULL; 
        this->right = NULL;
    }
};

/* This function is used 
to increment left subtree */

void increment(node* node, int diff);

/* This function changes a tree 
to hold children sum property */

void convertTree(node* node) 
{ 
    int left_data = 0, right_data = 0, diff;

/* If tree is empty or it's a leaf  
        node then return true */

    if (node == NULL || (node->left == NULL &&
                        node->right == NULL)) 
        return; 
    else
    {

/* convert left and right subtrees */

        convertTree(node->left); 
        convertTree(node->right);

/* If left child is not present then 0 is used 
        as data of left child */

        if (node->left != NULL) 
        left_data = node->left->data;

/* If right child is not present then 0 is used 
        as data of right child */

        if (node->right != NULL) 
        right_data = node->right->data;

/* get the diff of node's data and children sum */

        diff = left_data + right_data - node->data;

/* If node's children sum is 
        greater than the node's data */

        if (diff > 0) 
        node->data = node->data + diff;

/* THIS IS TRICKY --> If node's data
        is greater than children sum, 
        then increment subtree by diff */

        if (diff < 0)

/*-diff is used to make diff positive */

increment(node, -diff); 
    } 
}

/* This function is used 
to increment subtree by diff */

void increment(node* node, int diff) 
{

/* IF left child is not 
    NULL then increment it */

    if(node->left != NULL) 
    { 
        node->left->data = node->left->data + diff;

/*        Recursively call to fix 
        the descendants of node->left */

        increment(node->left, diff); 
    }

/*Else increment right child */

else if (node->right != NULL) 
    { 
        node->right->data = node->right->data + diff;

/*        Recursively call to fix 
        the descendants of node->right */

        increment(node->right, diff); 
    } 
}

/* Given a binary tree, 
printInorder() prints out its 
inorder traversal*/

void printInorder(node* node) 
{ 
    if (node == NULL) 
        return;

/* first recur on left child */

    printInorder(node->left);

/* then print the data of node */

    cout<<node->data<<" ";

/* now recur on right child */

    printInorder(node->right); 
}

/* Driver code */

int main() 
{ 
    node *root = new node(50); 
    root->left = new node(7); 
    root->right = new node(2); 
    root->left->left = new node(3); 
    root->left->right = new node(5); 
    root->right->left = new node(1); 
    root->right->right = new node(30); 
    cout << "\nInorder traversal before conversion: " << endl; 
    printInorder(root);
    convertTree(root); 
    cout << "\nInorder traversal after conversion: " << endl; 
    printInorder(root); 
    return 0; 
}

/* C++ program to convert left-right to down-right
   representation of binary tree */

#include <bits/stdc++.h>
using namespace std;

/*A Binary Tree Node*/

struct node
{
    int key;
    struct node *left, *right;
};

/*An Iterative level order traversal based function to
convert left-right to down-right representation.*/

void convert(node *root)
{

/*    Base Case*/

    if (root == NULL)  return;

/*    Recursively convert left an right subtrees*/

    convert(root->left);
    convert(root->right);

/*    If left child is NULL, make right child as left
    as it is the first child.*/

    if (root->left == NULL)
       root->left = root->right;

/*    If left child is NOT NULL, then make right child
    as right of left child*/

    else
       root->left->right = root->right;

/*    Set root's right as NULL*/

    root->right = NULL;
}

/*A utility function to traverse a tree stored in
down-right form.*/

void downRightTraversal(node *root)
{
    if (root != NULL)
    {
        cout << root->key << " ";
        downRightTraversal(root->right);
        downRightTraversal(root->left);
    }
}

/*Utility function to create a new tree node*/

node* newNode(int key)
{
    node *temp = new node;
    temp->key = key;
    temp->left = temp->right = NULL;
    return temp;
}

