    root->left     = new node(2); 
    root->right = new node(3); 
    root->left->left = new node(4); 
    root->left->right = new node(5); 
    root->right->right = new node(6); 
    updatetree(root); 
    cout << "Inorder traversal of the modified tree is: \n"; 
    inorder(root); 
    return 0; 
}

/*C++ program to convert a binary tree
to its mirror*/

#include<bits/stdc++.h>
using namespace std;

/* A binary tree node has data, pointer 
to left child and a pointer to right child */

struct Node 
{
    int data;
    struct Node* left;
    struct Node* right;
};

/* Helper function that allocates a new node with 
the given data and NULL left and right pointers. */

struct Node* newNode(int data)
{
    struct Node* node = (struct Node*)
                         malloc(sizeof(struct Node));
    node->data = data;
    node->left = NULL;
    node->right = NULL;
    return(node);
}

/* Change a tree so that the roles of the left and 
    right pointers are swapped at every node.
So the tree...
    4
    / \
    2 5
    / \
1 3
is changed to...
    4
    / \
    5 2
        / \
    3 1
*/

void mirror(struct Node* node) 
{
    if (node == NULL) 
        return; 
    else
    {
        struct Node* temp;

/* do the subtrees */

        mirror(node->left);
        mirror(node->right);

/* swap the pointers in this node */

        temp     = node->left;
        node->left = node->right;
        node->right = temp;
    }
}

/* Helper function to print 
Inorder traversal.*/

void inOrder(struct Node* node) 
{
    if (node == NULL) 
        return;
    inOrder(node->left);
    cout << node->data << " ";
    inOrder(node->right);
}

/*Driver Code*/

int main()
{
    struct Node *root = newNode(1);
    root->left = newNode(2);
    root->right = newNode(3);
    root->left->left = newNode(4);
    root->left->right = newNode(5);

/* Print inorder traversal of the input tree */

    cout << "Inorder traversal of the constructed"
         << " tree is" << endl;
    inOrder(root);

/* Convert tree to its mirror */

    mirror(root);

/* Print inorder traversal of the mirror tree */

    cout << "\nInorder traversal of the mirror tree"
         << " is \n"; 
    inOrder(root);
    return 0; 
}

/*Iterative CPP program to convert a Binary
Tree to its mirror*/

#include<bits/stdc++.h>
using namespace std;

/* A binary tree node has data, pointer to
   left child and a pointer to right child */

struct Node
{
    int data;
    struct Node* left;
    struct Node* right;
};

/* Helper function that allocates a new node
   with the given data and NULL left and right
   pointers. */

struct Node* newNode(int data)
{
    struct Node* node = new Node;
    node->data = data;
    node->left = node->right = NULL;
    return(node);
}

/* Change a tree so that the roles of the  left and
    right pointers are swapped at every node.
 So the tree...
       4
      / \
     2   5
    / \
   1   3
 is changed to...
       4
      / \
     5   2
        / \
       3   1
*/

void mirror(Node* root)
{
    if (root == NULL)
        return;
    queue<Node*> q;
    q.push(root);

/*    Do BFS. While doing BFS, keep swapping
    left and right children*/

    while (!q.empty())
    {

/*        pop top node from queue*/

        Node* curr = q.front();
        q.pop();

/*        swap left child with right child*/

        swap(curr->left, curr->right);

/*        push left and right children*/

        if (curr->left)
            q.push(curr->left);
        if (curr->right)
            q.push(curr->right);
    }
}

/* Helper function to print Inorder traversal.*/

void inOrder(struct Node* node)
{
    if (node == NULL)
        return;
    inOrder(node->left);
    cout << node->data << " ";
    inOrder(node->right);
}

/* Driver program to test mirror() */

int main()
{
    struct Node *root = newNode(1);
    root->left        = newNode(2);
    root->right       = newNode(3);
    root->left->left  = newNode(4);
    root->left->right = newNode(5);

/* Print inorder traversal of the input tree */

    cout << "\n Inorder traversal of the"
            " constructed tree is \n";
    inOrder(root);

/* Convert tree to its mirror */

    mirror(root);

/* Print inorder traversal of the mirror tree */

    cout << "\n Inorder traversal of the "
           "mirror tree is \n";
    inOrder(root);
    return 0;
}

/* c++ program to convert Binary Tree into Doubly
   Linked List where the nodes are represented
   spirally. */

#include <bits/stdc++.h>
using namespace std;

/*A Binary Tree Node*/

struct Node
{
    int data;
    struct Node *left, *right;
};

/* Given a reference to the head of a list and a node,
inserts the node on the front of the list. */

void push(Node** head_ref, Node* node)
{

/*    Make right of given node as head and left as
    NULL*/

    node->right = (*head_ref);
    node->left = NULL;

/*    change left of head node to given node*/

    if ((*head_ref) !=  NULL)
        (*head_ref)->left = node ;

/*    move the head to point to the given node*/

    (*head_ref) = node;
}

/*Function to prints contents of DLL*/

void printList(Node *node)
{
    while (node != NULL)
    {
        cout << node->data << " ";
        node = node->right;
    }
}

/* Function to print corner node at each level */

void spiralLevelOrder(Node *root)
{

/*    Base Case*/

    if (root == NULL)
        return;

/*    Create an empty deque for doing spiral
    level order traversal and enqueue root*/

    deque<Node*> q;
    q.push_front(root);

/*    create a stack to store Binary Tree nodes
    to insert into DLL later*/

    stack<Node*> stk;
    int level = 0;
    while (!q.empty())
    {

/*        nodeCount indicates number of Nodes
        at current level.*/

        int nodeCount = q.size();

/*        Dequeue all Nodes of current level and
        Enqueue all Nodes of next level
odd level*/

if (level&1)    
        {
            while (nodeCount > 0)
            {

/*                dequeue node from front & push it to
                stack*/

                Node *node = q.front();
                q.pop_front();
                stk.push(node);

/*                insert its left and right children
                in the back of the deque*/

                if (node->left != NULL)
                    q.push_back(node->left);
                if (node->right != NULL)
                    q.push_back(node->right);
                nodeCount--;
            }
        }

/*even level*/

else      
        {
            while (nodeCount > 0)
            {

/*                dequeue node from the back & push it
                to stack*/

                Node *node = q.back();
                q.pop_back();
                stk.push(node);

/*                inserts its right and left children
                in the front of the deque*/

                if (node->right != NULL)
                    q.push_front(node->right);
                if (node->left != NULL)
                    q.push_front(node->left);
                nodeCount--;
            }
        }
        level++;
    }

/*    head pointer for DLL*/

    Node* head = NULL;

/*    pop all nodes from stack and
    push them in the beginning of the list*/

    while (!stk.empty())
    {
        push(&head, stk.top());
        stk.pop();
    }
    cout << "Created DLL is:\n";
    printList(head);
}

/*Utility function to create a new tree Node*/

Node* newNode(int data)
{
    Node *temp = new Node;
    temp->data = data;
    temp->left = temp->right = NULL;
    return temp;
}

