/*C++ code to convert a given binary tree
to a tree that holds logical AND property.*/

#include<bits/stdc++.h>
using namespace std;

/*Structure of binary tree*/

struct Node
{
    int data;
    struct Node* left;
    struct Node* right;
};

/*function to create a new node*/

struct Node* newNode(int key)
{
    struct Node* node = new Node;
    node->data= key;
    node->left = node->right = NULL;
    return node;
}

/*Convert the given tree to a tree where
each node is logical AND of its children
The main idea is to do Postorder traversal*/

void convertTree(Node *root)
{
    if (root == NULL)
        return;

/* first recur on left child */

    convertTree(root->left);

/* then recur on right child */

    convertTree(root->right);
    if (root->left != NULL && root->right != NULL)
        root->data = (root->left->data) &
                     (root->right->data);
}
void printInorder(Node* root)
{
    if (root == NULL)
        return;

/* first recur on left child */

    printInorder(root->left);

/* then print the data of node */

    printf("%d ", root->data);

/* now recur on right child */

    printInorder(root->right);
}

/*main function*/

int main()
{

/* Create following Binary Tree
             1
           /   \
          1     0
         / \   / \
        0   1 1   1
             */

    Node *root=newNode(0);
    root->left=newNode(1);
    root->right=newNode(0);
    root->left->left=newNode(0);
    root->left->right=newNode(1);
    root->right->left=newNode(1);
    root->right->right=newNode(1);
    printf("\n Inorder traversal before conversion ");
    printInorder(root);
    convertTree(root);
    printf("\n Inorder traversal after conversion ");
    printInorder(root);
    return 0;
}

/*  C/C++ program to flip a binary tree */

#include <bits/stdc++.h>
using namespace std;

/* A binary tree node structure */

struct Node
{
    int data;
    Node *left, *right;
};

/* Utility function to create a new Binary
   Tree Node */

struct Node* newNode(int data)
{
    struct Node *temp = new struct Node;
    temp->data = data;
    temp->left = temp->right = NULL;
    return temp;
}

/*method to flip the binary tree*/

Node* flipBinaryTree(Node* root)
{
    if (root == NULL)
        return root;
    if (root->left == NULL && root->right == NULL)
        return root;

/*      recursively call the same method*/

    Node* flippedRoot = flipBinaryTree(root->left);

/*      rearranging main root Node after returning
    from recursive call*/

    root->left->left = root->right;
    root->left->right = root;
    root->left = root->right = NULL;
    return flippedRoot;
}

/*Iterative method to do level order traversal
line by line*/

void printLevelOrder(Node *root)
{

/*    Base Case*/

    if (root == NULL)  return;

/*    Create an empty queue for level order traversal*/

    queue<Node *> q;

/*    Enqueue Root and initialize height*/

    q.push(root);
    while (1)
    {

/*        nodeCount (queue size) indicates number
        of nodes at current lelvel.*/

        int nodeCount = q.size();
        if (nodeCount == 0)
            break;

/*        Dequeue all nodes of current level and
        Enqueue all nodes of next level*/

        while (nodeCount > 0)
        {
            Node *node = q.front();
            cout << node->data << " ";
            q.pop();
            if (node->left != NULL)
                q.push(node->left);
            if (node->right != NULL)
                q.push(node->right);
            nodeCount--;
        }
        cout << endl;
    }
}

/*  Driver code*/

int main()
{
    Node* root = newNode(1);
    root->left = newNode(2);
    root->right = newNode(3);
    root->right->left = newNode(4);
    root->right->right = newNode(5);
    cout << "Level order traversal of given tree\n";
    printLevelOrder(root);
    root = flipBinaryTree(root);
    cout << "\nLevel order traversal of the flipped"
            " tree\n";
    printLevelOrder(root);
    return 0;
}

/*  C/C++ program to flip a binary tree*/

#include <bits/stdc++.h>
using namespace std;

/*A binary tree node structure*/

struct Node
{
    int data;
    Node *left, *right;
};

/*Utility function to create a new Binary
Tree Node*/

struct Node* newNode(int data)
{
    struct Node *temp = new struct Node;
    temp->data = data;
    temp->left = temp->right = NULL;
    return temp;
}

/*method to flip the binary tree*/

Node* flipBinaryTree(Node* root)
{

/*    Initialization of pointers*/

    Node *curr = root;
    Node *next = NULL;
    Node *temp = NULL;
    Node *prev = NULL;

/*    Iterate through all left nodes*/

    while(curr)
    {
        next = curr->left;

/*        Swapping nodes now, need temp to keep the previous right child
        Making prev's right as curr's left child*/

        curr->left = temp;

/*        Storing curr's right child*/

        temp = curr->right;

/*        Making prev as curr's right child*/

        curr->right = prev;        
        prev = curr;
        curr = next;
    }
    return prev;
}

/*Iterative method to do level order traversal
line by line*/

void printLevelOrder(Node *root)
{

/*    Base Case*/

    if (root == NULL) return;

/*    Create an empty queue for level order traversal*/

    queue<Node *> q;

/*    Enqueue Root and initialize height*/

    q.push(root);
    while (1)
    {

/*        nodeCount (queue size) indicates number
        of nodes at current lelvel.*/

        int nodeCount = q.size();
        if (nodeCount == 0)
            break;

/*        Dequeue all nodes of current level and
        Enqueue all nodes of next level*/

        while (nodeCount > 0)
        {
            Node *node = q.front();
            cout << node->data << " ";
            q.pop();
            if (node->left != NULL)
                q.push(node->left);
            if (node->right != NULL)
                q.push(node->right);
            nodeCount--;
        }
        cout << endl;
    }
}

/*Driver code*/

int main()
{
    Node* root = newNode(1);
    root->left = newNode(2);
    root->right = newNode(3);
    root->right->left = newNode(4);
    root->right->right = newNode(5);
    cout << "Level order traversal of given tree\n";
    printLevelOrder(root);
    root = flipBinaryTree(root);
    cout << "\nLevel order traversal of the flipped"
            " tree\n";
    printLevelOrder(root);
    return 0;
}

/* Program to check children sum property */

#include <bits/stdc++.h>
using namespace std;

/* A binary tree node has data, left 
child and right child */

struct node
{
    int data;
    struct node* left;
    struct node* right;
};

/* returns 1 if children sum property holds 
for the given node and both of its children*/

int isSumProperty(struct node* node)
{

/* left_data is left child data and
       right_data is for right child data*/

    int left_data = 0, right_data = 0;

/* If node is NULL or it's a leaf node 
    then return true */

    if(node == NULL ||
        (node->left == NULL && 
         node->right == NULL))
        return 1;
    else
    {

/* If left child is not present then 0 
        is used as data of left child */

        if(node->left != NULL)
        left_data = node->left->data;

/* If right child is not present then 0 
        is used as data of right child */

        if(node->right != NULL)
        right_data = node->right->data;

/* if the node and both of its children 
        satisfy the property return 1 else 0*/

        if((node->data == left_data + right_data)&&
            isSumProperty(node->left) &&
            isSumProperty(node->right))
        return 1;
        else
        return 0;
    }
}

/*
Helper function that allocates a new node
with the given data and NULL left and right
pointers.
*/

struct node* newNode(int data)
{
    struct node* node =
        (struct node*)malloc(sizeof(struct node));
    node->data = data;
    node->left = NULL;
    node->right = NULL;
    return(node);
}

/*Driver Code*/

int main()
{
    struct node *root = newNode(10);
    root->left     = newNode(8);
    root->right = newNode(2);
    root->left->left = newNode(3);
    root->left->right = newNode(5);
    root->right->right = newNode(2);
    if(isSumProperty(root))
        cout << "The given tree satisfies "
            << "the children sum property ";
    else
        cout << "The given tree does not satisfy "
            << "the children sum property ";
    getchar();
    return 0;
}

/*C++ program to find sum of Covered and Uncovered node of
binary tree*/

#include <bits/stdc++.h>
using namespace std;

/* A binary tree node has key, pointer to left
   child and a pointer to right child */

struct Node
{
    int key;
    struct Node* left, *right;
};

/* To create a newNode of tree and return pointer */

struct Node* newNode(int key)
{
    Node* temp = new Node;
    temp->key = key;
    temp->left = temp->right = NULL;
    return (temp);
}

/* Utility function to calculate sum of all node of tree */

int sum(Node* t)
{
    if (t == NULL)
        return 0;
    return t->key + sum(t->left) + sum(t->right);
}

/* Recursive function to calculate sum of left boundary
   elements  */

int uncoveredSumLeft(Node* t)
{

/*  If leaf node, then just return its key value   */

    if (t->left == NULL && t->right == NULL)
        return t->key;

/*  If left is available then go left otherwise go right  */

    if (t->left != NULL)
        return t->key + uncoveredSumLeft(t->left);
    else
        return t->key + uncoveredSumLeft(t->right);
}

/* Recursive function to calculate sum of right boundary
   elements  */

int uncoveredSumRight(Node* t)
{

/*  If leaf node, then just return its key value   */

    if (t->left == NULL && t->right == NULL)
        return t->key;

/*  If right is available then go right otherwise go left  */

    if (t->right != NULL)
        return t->key + uncoveredSumRight(t->right);
    else
        return t->key + uncoveredSumRight(t->left);
}

/*Returns sum of uncovered elements*/

int uncoverSum(Node* t)
{

/* Initializing with 0 in case we don't have
       left or right boundary  */

    int lb = 0, rb = 0;
    if (t->left != NULL)
        lb = uncoveredSumLeft(t->left);
    if (t->right != NULL)
        rb = uncoveredSumRight(t->right);

/* returning sum of root node, left boundary
       and right boundary*/

    return t->key + lb + rb;
}

/*Returns true if sum of covered and uncovered elements
is same.*/

bool isSumSame(Node *root)
{

/*    Sum of uncovered elements*/

    int sumUC = uncoverSum(root);

/*    Sum of all elements*/

    int sumT = sum(root);

/*    Check if sum of covered and uncovered is same*/

    return (sumUC == (sumT - sumUC));
}

/* Helper function to print inorder traversal of
   binary tree   */

void inorder(Node* root)
{
    if (root)
    {
        inorder(root->left);
        printf("%d ", root->key);
        inorder(root->right);
    }
}

/*Driver program to test above functions*/

int main()
{

/*    Making above given diagram's binary tree*/

    Node* root = newNode(8);
    root->left = newNode(3);
    root->left->left = newNode(1);
    root->left->right = newNode(6);
    root->left->right->left = newNode(4);
    root->left->right->right = newNode(7);
    root->right = newNode(10);
    root->right->right = newNode(14);
    root->right->right->left = newNode(13);
    if (isSumSame(root))
        printf("Sum of covered and uncovered is same\n");
    else
        printf("Sum of covered and uncovered is not same\n");
}

/*C++ program to check if all leaves
are at same level*/

#include <bits/stdc++.h>
using namespace std;

/*A binary tree node*/

struct Node
{
    int data;
    struct Node *left, *right;
};

/*A utility function to allocate
a new tree node*/

struct Node* newNode(int data)
{
    struct Node* node = (struct Node*) malloc(sizeof(struct Node));
    node->data = data;
    node->left = node->right = NULL;
    return node;
}

/* Recursive function which checks whether
all leaves are at same level */

bool checkUtil(struct Node *root,
            int level, int *leafLevel)
{

/*    Base case*/

    if (root == NULL) return true;

/*    If a leaf node is encountered*/

    if (root->left == NULL &&
        root->right == NULL)
    {

/*        When a leaf node is found
        first time*/

        if (*leafLevel == 0)
        {

/*Set first found leaf's level*/

*leafLevel = level; 
            return true;
        }

/*        If this is not first leaf node, compare
        its level with first leaf's level*/

        return (level == *leafLevel);
    }

/*    If this node is not leaf, recursively
    check left and right subtrees*/

    return checkUtil(root->left, level + 1, leafLevel) &&
            checkUtil(root->right, level + 1, leafLevel);
}

/* The main function to check
if all leafs are at same level.
It mainly uses checkUtil() */

bool check(struct Node *root)
{
    int level = 0, leafLevel = 0;
    return checkUtil(root, level, &leafLevel);
}

/*Driver Code*/

int main()
{

/*    Let us create tree shown in third example*/

    struct Node *root = newNode(12);
    root->left = newNode(5);
    root->left->left = newNode(3);
    root->left->right = newNode(9);
    root->left->left->left = newNode(1);
    root->left->right->left = newNode(1);
    if (check(root))
        cout << "Leaves are at same level\n";
    else
        cout << "Leaves are not at same level\n";
    getchar();
    return 0;
}

/*C++ program to check if all leaf nodes are at
same level of binary tree*/

#include <bits/stdc++.h>
using namespace std;

/*tree node*/

struct Node {
    int data;
    Node *left, *right;
};

/*returns a new tree Node*/

Node* newNode(int data)
{
    Node* temp = new Node();
    temp->data = data;
    temp->left = temp->right = NULL;
    return temp;
}

/*return true if all leaf nodes are
at same level, else false*/

int checkLevelLeafNode(Node* root)
{
    if (!root)
        return 1;

/*    create a queue for level order traversal*/

    queue<Node*> q;
    q.push(root);
    int result = INT_MAX;
     int level = 0;

/*    traverse until the queue is empty*/

    while (!q.empty()) {
        int size = q.size();
        level += 1;

/*        traverse for complete level*/

        while(size > 0){
            Node* temp = q.front();
            q.pop();

/*            check for left child*/

            if (temp->left) {
                q.push(temp->left);

/*                if its leaf node*/

                if(!temp->left->right && !temp->left->left){

/*                    if it's first leaf node, then update result*/

                    if (result == INT_MAX)
                        result = level;

/*                    if it's not first leaf node, then compare
                    the level with level of previous leaf node*/

                    else if (result != level)
                        return 0;                   
                }
            }

/*             check for right child*/

            if (temp->right){
                q.push(temp->right);

/*                if it's leaf node*/

                if (!temp->right->left && !temp->right->right)

/*                    if it's first leaf node till now,
                    then update the result*/

                    if (result == INT_MAX)
                        result = level;

/*                    if it is not the first leaf node,
                    then compare the level with level
                    of previous leaf node*/

                    else if(result != level)
                        return 0;
               }
               size -= 1;
        }   
    }
    return 1;
}

/*driver program*/

int main()
{

/*    construct a tree*/

    Node* root = newNode(1);
    root->left = newNode(2);
    root->right = newNode(3);
    root->left->right = newNode(4);
    root->right->left = newNode(5);
    root->right->right = newNode(6);
    int result = checkLevelLeafNode(root);
    if (result)
        cout << "All leaf nodes are at same level\n";
    else
        cout << "Leaf nodes not at same level\n";
    return 0;
}

/*C++ program to check if there exist an edge whose
removal creates two trees of same size*/

#include<bits/stdc++.h>
using namespace std;
struct Node
{
    int data;
    struct Node* left, *right;
};

/*utility function to create a new node*/

struct Node* newNode(int x)
{
    struct Node* temp = new Node;
    temp->data = x;
    temp->left = temp->right = NULL;
    return temp;
};

/*To calculate size of tree with given root*/

int count(Node* root)
{
    if (root==NULL)
        return 0;
    return count(root->left) + count(root->right) + 1;
}

/*This function returns true if there is an edge
whose removal can divide the tree in two halves
n is size of tree*/

bool checkRec(Node* root, int n)
{

/*    Base cases*/

    if (root ==NULL)
       return false;

/*    Check for root*/

    if (count(root) == n-count(root))
        return true;

/*    Check for rest of the nodes*/

    return checkRec(root->left, n) ||
           checkRec(root->right, n);
}

/*This function mainly uses checkRec()*/

bool check(Node *root)
{

/*    Count total nodes in given tree*/

    int n = count(root);

/*    Now recursively check all nodes*/

    return checkRec(root, n);
}

/*Driver code*/

int main()
{
    struct Node* root = newNode(5);
    root->left = newNode(1);
    root->right = newNode(6);
    root->left->left = newNode(3);
    root->right->left = newNode(7);
    root->right->right = newNode(4);
    check(root)?  printf("YES") : printf("NO");
    return 0;
}

/*C++ program to check if there exist an edge whose
removal creates two trees of same size*/

#include<bits/stdc++.h>
using namespace std;
struct Node
{
    int data;
    struct Node* left, *right;
};

/*utility function to create a new node*/

struct Node* newNode(int x)
{
    struct Node* temp = new Node;
    temp->data = x;
    temp->left = temp->right = NULL;
    return temp;
};

/*To calculate size of tree with given root*/

int count(Node* root)
{
    if (root==NULL)
        return 0;
    return count(root->left) + count(root->right) + 1;
}

/*This function returns size of tree rooted with given
root. It also set "res" as true if there is an edge
whose removal divides tree in two halves.
n is size of tree*/

int checkRec(Node* root, int n, bool &res)
{

/*    Base case*/

    if (root == NULL)
       return 0;

/*    Compute sizes of left and right children*/

    int c = checkRec(root->left, n, res) + 1 +
            checkRec(root->right, n, res);

/*    If required property is true for current node
    set "res" as true*/

    if (c == n-c)
        res = true;

/*    Return size*/

    return c;
}

/*This function mainly uses checkRec()*/

bool check(Node *root)
{

/*    Count total nodes in given tree*/

    int n = count(root);

/*    Initialize result and recursively check all nodes*/

    bool res = false;
    checkRec(root, n,  res);
    return res;
}

/*Driver code*/

int main()
{
    struct Node* root = newNode(5);
    root->left = newNode(1);
    root->right = newNode(6);
    root->left->left = newNode(3);
    root->right->left = newNode(7);
    root->right->right = newNode(4);
    check(root)?  printf("YES") : printf("NO");
    return 0;
}

/* C++ program to check if all three given
   traversals are of the same tree */

#include <bits/stdc++.h>
using namespace std;

/*A Binary Tree Node*/

struct Node
{
    int data;
    struct Node *left, *right;
};

/*Utility function to create a new tree node*/

Node* newNode(int data)
{
    Node *temp = new Node;
    temp->data = data;
    temp->left = temp->right = NULL;
    return temp;
}

/* Function to find index of value in arr[start...end]
   The function assumes that value is present in in[] */

int search(int arr[], int strt, int end, int value)
{
    for (int i = strt; i <= end; i++)
    {
        if(arr[i] == value)
            return i;
    }
}

/* Recursive function to construct binary tree
   of size len from Inorder traversal in[] and
   Preorder traversal pre[].  Initial values
   of inStrt and inEnd should be 0 and len -1. 
   The function doesn't do any error checking for
   cases where inorder and preorder do not form a
   tree */

Node* buildTree(int in[], int pre[], int inStrt,
                                      int inEnd)
{
    static int preIndex = 0;
    if(inStrt > inEnd)
        return NULL;

/* Pick current node from Preorder traversal
       using preIndex and increment preIndex */

    Node *tNode = newNode(pre[preIndex++]);

/* If this node has no children then return */

    if (inStrt == inEnd)
        return tNode;

/* Else find the index of this node in
       Inorder traversal */

    int inIndex = search(in, inStrt, inEnd, tNode->data);

/* Using index in Inorder traversal,
       construct left and right subtress */

    tNode->left = buildTree(in, pre, inStrt, inIndex-1);
    tNode->right = buildTree(in, pre, inIndex+1, inEnd);
    return tNode;
}

/* function to compare Postorder traversal
   on constructed tree and given Postorder */

int checkPostorder(Node* node, int postOrder[], int index)
{
    if (node == NULL)
        return index;

/* first recur on left child */

    index = checkPostorder(node->left,postOrder,index);

/* now recur on right child */

    index = checkPostorder(node->right,postOrder,index);

/* Compare if data at current index in
       both Postorder traversals are same */

    if (node->data == postOrder[index])
        index++;
    else
        return -1;
    return index;
}

/*Driver program to test above functions*/

int main()
{
    int inOrder[] = {4, 2, 5, 1, 3};
    int preOrder[] = {1, 2, 4, 5, 3};
    int postOrder[] = {4, 5, 2, 3, 1};
    int len = sizeof(inOrder)/sizeof(inOrder[0]);

/*    build tree from given
    Inorder and Preorder traversals*/

    Node *root = buildTree(inOrder, preOrder, 0, len - 1);

/*    compare postorder traversal on constructed
    tree with given Postorder traversal*/

    int index = checkPostorder(root,postOrder,0);

/*    If both postorder traversals are same*/

    if (index == len)
        cout << "Yes";
    else
        cout << "No";
    return 0;
}

/*C++ code to check if leaf traversals
of two Binary Trees are same or not.*/

#include <bits/stdc++.h>
using namespace std;

/*Binary Tree Node*/

struct Node {
    int data;
    Node* left;
    Node* right;
};

/*Returns new Node with data as
input to below function.*/

Node* newNode(int d)
{
    Node* temp = new Node;
    temp->data = d;
    temp->left = NULL;
    temp->right = NULL;
    return temp;
}

/*checks if a given node is leaf or not.*/

bool isLeaf(Node* root)
{
    if (root == NULL)
        return false;
    if (!root->left && !root->right)
        return true;
    return false;
}

/*iterative function.
returns true if leaf traversals
are same, else false.*/

bool isSame(Node* root1, Node* root2)
{

/*        Create empty stacks.  These stacks are going
        to be used for iterative traversals.*/

    stack<Node*> s1;
    stack<Node*> s2;
    s1.push(root1);
    s2.push(root2);

/*    loop until either of stacks are non-empty.*/

    while (!s1.empty() || !s2.empty()) 
    {

/*        this means one of the stacks has
        extra leaves, hence return false.*/

        if (s1.empty() || s2.empty())
            return false;
        Node* temp1 = s1.top();
        s1.pop();
        while (temp1 != NULL && !isLeaf(temp1))
        {

/*                Push right and left children of temp1.
                Note that right child is inserted
                before left*/

            if (temp1->right)
                s1.push(temp1->right);
            if (temp1->left)
                s1.push(temp1->left);
            temp1 = s1.top();
            s1.pop();
        }

/*            same for tree2*/

        Node* temp2 = s2.top();
        s2.pop();
        while (temp2 != NULL && !isLeaf(temp2)) 
        {
            if (temp2->right)
                s2.push(temp2->right);
            if (temp2->left)
                s2.push(temp2->left);
            temp2 = s2.top();
            s2.pop();
        }

/*            If one is null and other is not, then
            return false*/



        if (!temp1 && temp2)
            return false;
        if (temp1 && !temp2)
            return false;

/*            If both are not null and data is not
            same return false*/

        if (temp1 && temp2) {
            return temp1->data == temp2->data;
        }
    }

/*    all leaves are matched*/

    return true;
}

/*Driver Code*/

int main()
{

/*        Let us create trees in above example 1*/

    Node* root1 = newNode(1);
    root1->left = newNode(2);
    root1->right = newNode(3);
    root1->left->left = newNode(4);
    root1->right->left = newNode(6);
    root1->right->right = newNode(7);
    Node* root2 = newNode(0);
    root2->left = newNode(1);
    root2->right = newNode(5);
    root2->left->right = newNode(4);
    root2->right->left = newNode(6);
    root2->right->right = newNode(7);
    if (isSame(root1, root2))
        cout << "Same";
    else
        cout << "Not Same";
    return 0;
}

/*C++ program to check whether a given
Binary Tree is Perfect or not*/

#include<bits/stdc++.h>

/*  Tree node structure */

struct Node
{
    int key;
    struct Node *left, *right;
};

/*Returns depth of leftmost leaf.*/

int findADepth(Node *node)
{
   int d = 0;
   while (node != NULL)
   {
      d++;
      node = node->left;
   }
   return d;
}

/* This function tests if a binary tree is perfect
   or not. It basically checks for two things :
   1) All leaves are at same level
   2) All internal nodes have two children */

bool isPerfectRec(struct Node* root, int d, int level = 0)
{

/*    An empty tree is perfect*/

    if (root == NULL)
        return true;

/*    If leaf node, then its depth must be same as
    depth of all other leaves.*/

    if (root->left == NULL && root->right == NULL)
        return (d == level+1);

/*    If internal node and one child is empty*/

    if (root->left == NULL || root->right == NULL)
        return false;

/*    Left and right subtrees must be perfect.*/

    return isPerfectRec(root->left, d, level+1) &&
           isPerfectRec(root->right, d, level+1);
}

/*Wrapper over isPerfectRec()*/

bool isPerfect(Node *root)
{
   int d = findADepth(root);
   return isPerfectRec(root, d);
}

/* Helper function that allocates a new node with the
   given key and NULL left and right pointer. */

struct Node *newNode(int k)
{
    struct Node *node = new Node;
    node->key = k;
    node->right = node->left = NULL;
    return node;
}

/*Driver Program*/

int main()
{
    struct Node* root = NULL;
    root = newNode(10);
    root->left = newNode(20);
    root->right = newNode(30);
    root->left->left = newNode(40);
    root->left->right = newNode(50);
    root->right->left = newNode(60);
    root->right->right = newNode(70);
    if (isPerfect(root))
        printf("Yes\n");
    else
        printf("No\n");
    return(0);
}

/*C++ program to check whether a given Binary Tree is full or not*/

#include <bits/stdc++.h>
using namespace std;

/*  Tree node structure */

struct Node
{
    int key;
    struct Node *left, *right;
};

/* Helper function that allocates a new node with the
   given key and NULL left and right pointer. */

struct Node *newNode(char k)
{
    struct Node *node = new  Node;
    node->key = k;
    node->right = node->left = NULL;
    return node;
}

/* This function tests if a binary tree is a full binary tree. */

bool isFullTree (struct Node* root)
{

/*    If empty tree*/

    if (root == NULL)
        return true;

/*    If leaf node*/

    if (root->left == NULL && root->right == NULL)
        return true;

/*    If both left and right are not NULL, and left & right subtrees
    are full*/

    if ((root->left) && (root->right))
        return (isFullTree(root->left) && isFullTree(root->right));

/*    We reach here when none of the above if conditions work*/

    return false;
}

/*Driver Program*/

int main()
{
    struct Node* root = NULL;
    root = newNode(10);
    root->left = newNode(20);
    root->right = newNode(30);
    root->left->right = newNode(40);
    root->left->left = newNode(50);
    root->right->left = newNode(60);
    root->right->right = newNode(70);
    root->left->left->left = newNode(80);
    root->left->left->right = newNode(90);
    root->left->right->left = newNode(80);
    root->left->right->right = newNode(90);
    root->right->left->left = newNode(80);
    root->right->left->right = newNode(90);
    root->right->right->left = newNode(80);
    root->right->right->right = newNode(90);
    if (isFullTree(root))
        cout << "The Binary Tree is full\n";
    else
        cout << "The Binary Tree is not full\n";
    return(0);
}

/*C++ implementation to check whether a binary 
tree is a full binary tree or not*/

#include <bits/stdc++.h>
using namespace std;

/*structure of a node of binary tree*/

struct Node {
    int data;
    Node *left, *right;
};

/*function to get a new node*/

Node* getNode(int data)
{

/*    allocate space*/

    Node* newNode = (Node*)malloc(sizeof(Node));

/*    put in the data*/

    newNode->data = data;
    newNode->left = newNode->right = NULL;
    return newNode;
}

/*function to check whether a binary tree
is a full binary tree or not*/

bool isFullBinaryTree(Node* root)
{

/*    if tree is empty*/

    if (!root)
        return true;

/*    queue used for level order traversal*/

    queue<Node*> q;

/*    push 'root' to 'q'*/

    q.push(root);

/*    traverse all the nodes of the binary tree
    level by level until queue is empty*/

    while (!q.empty()) {

/*        get the pointer to 'node' at front
        of queue*/

        Node* node = q.front();
        q.pop();

/*        if it is a leaf node then continue*/

        if (node->left == NULL && node->right == NULL)
            continue;

/*        if either of the child is not null and the
        other one is null, then binary tree is not
        a full binary tee*/

        if (node->left == NULL || node->right == NULL)
            return false;

/*        push left and right childs of 'node'
        on to the queue 'q'*/

        q.push(node->left);
        q.push(node->right);
    }

/*    binary tree is a full binary tee*/

    return true;
}

/*Driver program to test above*/

int main()
{
    Node* root = getNode(1);
    root->left = getNode(2);
    root->right = getNode(3);
    root->left->left = getNode(4);
    root->left->right = getNode(5);
    if (isFullBinaryTree(root))
        cout << "Yes";
    else
        cout << "No";
    return 0;
}

/* Program to check if a given Binary Tree is balanced like a Red-Black Tree */

#include <bits/stdc++.h>
using namespace std;
struct Node
{
    int key;
    Node *left, *right;
};

/* utility that allocates a new Node with the given key  */

Node* newNode(int key)
{
    Node* node = new Node;
    node->key = key;
    node->left = node->right = NULL;
    return (node);
}

/*Returns returns tree if the Binary tree is balanced like a Red-Black
tree. This function also sets value in maxh and minh (passed by
reference). maxh and minh are set as maximum and minimum heights of root.*/

bool isBalancedUtil(Node *root, int &maxh, int &minh)
{

/*    Base case*/

    if (root == NULL)
    {
        maxh = minh = 0;
        return true;
    }

/*To store max and min heights of left subtree*/

int lmxh, lmnh;

/*To store max and min heights of right subtree*/

int rmxh, rmnh;

/*    Check if left subtree is balanced, also set lmxh and lmnh*/

    if (isBalancedUtil(root->left, lmxh, lmnh) == false)
        return false;

/*    Check if right subtree is balanced, also set rmxh and rmnh*/

    if (isBalancedUtil(root->right, rmxh, rmnh) == false)
        return false;

/*    Set the max and min heights of this node for the parent call*/

    maxh = max(lmxh, rmxh) + 1;
    minh = min(lmnh, rmnh) + 1;

/*    See if this node is balanced*/

    if (maxh <= 2*minh)
        return true;
    return false;
}

/*A wrapper over isBalancedUtil()*/

bool isBalanced(Node *root)
{
    int maxh, minh;
    return isBalancedUtil(root, maxh, minh);
}

/* Driver program to test above functions*/

int main()
{
    Node * root = newNode(10);
    root->left = newNode(5);
    root->right = newNode(100);
    root->right->left = newNode(50);
    root->right->right = newNode(150);
    root->right->left->left = newNode(40);
    isBalanced(root)? cout << "Balanced" : cout << "Not Balanced";
    return 0;
}

/*C++ Program to check duplicates
in Binary Tree*/

#include <bits/stdc++.h>
using namespace std;

/*A binary tree Node has data,
pointer to left child
and a pointer to right child*/

struct Node {
    int data;
    struct Node* left;
    struct Node* right;
};

/*Helper function that allocates
a new Node with the given data
and NULL left and right pointers.*/

struct Node* newNode(int data)
{
    struct Node* node = new Node;
    node->data = data;
    node->left = node->right = NULL;
    return (node);
}
bool checkDupUtil(Node* root, unordered_set<int> &s)
{

/*    If tree is empty, there are no
    duplicates. */

    if (root == NULL)
       return false;

/*    If current node's data is already present.*/

    if (s.find(root->data) != s.end())
       return true;

/*    Insert current node*/

    s.insert(root->data);

/*    Recursively check in left and right
    subtrees.*/

    return checkDupUtil(root->left, s) || 
           checkDupUtil(root->right, s);
}

/*To check if tree has duplicates*/

bool checkDup(struct Node* root)
{
    unordered_set<int> s;
    return checkDupUtil(root, s);
}

/*Driver program to test above functions*/

int main()
{
    struct Node* root = newNode(1);
    root->left = newNode(2);
    root->right = newNode(2);
    root->left->left = newNode(3);
    if (checkDup(root))
        printf("Yes");
    else
        printf("No");
    return 0;
}

/*C++ program to find if there is a duplicate
sub-tree of size 2 or more.*/

#include<bits/stdc++.h>
using namespace std;
const char MARKER = '$';

/*Structure for a binary tree node*/

struct Node
{
    char key;
    Node *left, *right;
};

/*A utility function to create a new node*/

Node* newNode(char key)
{
    Node* node = new Node;
    node->key = key;
    node->left = node->right = NULL;
    return node;
}
unordered_set<string> subtrees;

/*This function returns empty string if tree
contains a duplicate subtree of size 2 or more.*/

string dupSubUtil(Node *root)
{
    string s = "";

/*    If current node is NULL, return marker*/

    if (root == NULL)
        return s + MARKER;

/*    If left subtree has a duplicate subtree.*/

    string lStr = dupSubUtil(root->left);
    if (lStr.compare(s) == 0)
    return s;

/*    Do same for right subtree*/

    string rStr = dupSubUtil(root->right);
    if (rStr.compare(s) == 0)
    return s;

/*    Serialize current subtree*/

    s = s + root->key + lStr + rStr;

/*    If current subtree already exists in hash
    table. [Note that size of a serialized tree
    with single node is 3 as it has two marker
    nodes.*/

    if (s.length() > 3 &&
        subtrees.find(s) != subtrees.end())
    return "";
    subtrees.insert(s);
    return s;
}

/*Driver program to test above functions*/

int main()
{
    Node *root = newNode('A');
    root->left = newNode('B');
    root->right = newNode('C');
    root->left->left = newNode('D');
    root->left->right = newNode('E');
    root->right->right = newNode('B');
    root->right->right->right = newNode('E');
    root->right->right->left= newNode('D');
    string str = dupSubUtil(root);
    (str.compare("") == 0) ? cout << " Yes ":
                            cout << " No " ;
    return 0;
}

/*C++ program to check if two trees are mirror
of each other*/

#include<bits/stdc++.h>
using namespace std;

/* A binary tree node has data, pointer to
   left child and a pointer to right child */

struct Node
{
    int data;
    Node* left, *right;
};

/* Given two trees, return true if they are
   mirror of each other */

int areMirror(Node* a, Node* b)
{

/* Base case : Both empty */

    if (a==NULL && b==NULL)
        return true;

/*    If only one is empty*/

    if (a==NULL || b == NULL)
        return false;

/* Both non-empty, compare them recursively
     Note that in recursive calls, we pass left
     of one tree and right of other tree */

    return  a->data == b->data &&
            areMirror(a->left, b->right) &&
            areMirror(a->right, b->left);
}

/* Helper function that allocates a new node */

Node* newNode(int data)
{
    Node* node = new Node;
    node->data  = data;
    node->left  =  node->right  = NULL;
    return(node);
}

/* Driver program to test areMirror() */

int main()
{
    Node *a = newNode(1);
    Node *b = newNode(1);
    a->left = newNode(2);
    a->right = newNode(3);
    a->left->left  = newNode(4);
    a->left->right = newNode(5);
    b->left = newNode(3);
    b->right = newNode(2);
    b->right->left = newNode(5);
    b->right->right = newNode(4);
    areMirror(a, b)? cout << "Yes" : cout << "No";
    return 0;
}

/*C++ implementation to check whether the two 
binary tress are mirrors of each other or not*/

#include <bits/stdc++.h>
using namespace std;

/*structure of a node in binary tree*/

struct Node
{
    int data;
    struct Node *left, *right;
};

/*Utility function to create and return 
a new node for a binary tree*/

struct Node* newNode(int data)
{
    struct Node *temp = new Node();
    temp->data = data;
    temp->left = temp->right = NULL;
    return temp;
}

/*function to check whether the two binary trees
are mirrors of each other or not*/

string areMirrors(Node *root1, Node *root2)
{
    stack<Node*> st1, st2;
    while (1)
    {

/*        iterative inorder traversal of 1st tree and
        reverse inoder traversal of 2nd tree*/

        while (root1 && root2)
        {

/*            if the corresponding nodes in the two traversal
            have different data values, then they are not
            mirrors of each other.*/

            if (root1->data != root2->data)
                return "No";
            st1.push(root1);
            st2.push(root2);
            root1 = root1->left;
            root2 = root2->right;    
        }

/*        if at any point one root becomes null and
        the other root is not null, then they are 
        not mirrors. This condition verifies that
        structures of tree are mirrors of each other.*/

        if (!(root1 == NULL && root2 == NULL))
            return "No";
        if (!st1.empty() && !st2.empty())
        {
            root1 = st1.top();
            root2 = st2.top();
            st1.pop(); 
            st2.pop();

/* we have visited the node and its left subtree.
               Now, it's right subtree's turn */

            root1 = root1->right;

/* we have visited the node and its right subtree.
               Now, it's left subtree's turn */

            root2 = root2->left;
        }

/*        both the trees have been completely traversed*/

        else
            break;
    }

/*    tress are mirrors of each other*/

    return "Yes";
}

/*Driver program to test above*/

int main()
{

/*    1st binary tree formation*/

    Node *root1 = newNode(1);

/*         1          */

    root1->left = newNode(3);

/*       /   \        */

    root1->right = newNode(2);

/*      3     2       */

    root1->right->left = newNode(5);

/*          /   \     */

    root1->right->right = newNode(4);

/*    2nd binary tree formation    */

    Node *root2 = newNode(1);

/*         1          */

    root2->left = newNode(2);

/*       /   \        */

    root2->right = newNode(3);

/*      2     3       */

    root2->left->left = newNode(4);

/*    /   \           */

    root2->left->right = newNode(5);

/*   4    5           */

    cout << areMirrors(root1, root2);
    return 0;
}

/*C++ program to see if two trees are identical*/

#include <bits/stdc++.h>
using namespace std;

/* A binary tree node has data, pointer to left child 
and a pointer to right child */

class node 
{ 
    public:
    int data; 
    node* left; 
    node* right; 
};

/* Helper function that allocates a new node with the 
given data and NULL left and right pointers. */

node* newNode(int data) 
{ 
    node* Node = new node();
    Node->data = data; 
    Node->left = NULL; 
    Node->right = NULL; 
    return(Node); 
}

/* Given two trees, return true if they are 
structurally identical */

int identicalTrees(node* a, node* b) 
{

/*1. both empty */

    if (a == NULL && b == NULL) 
        return 1;

/* 2. both non-empty -> compare them */

    if (a != NULL && b != NULL) 
    { 
        return
        ( 
            a->data == b->data && 
            identicalTrees(a->left, b->left) && 
            identicalTrees(a->right, b->right) 
        ); 
    }

/* 3. one empty, one not -> false */

    return 0; 
}

/* Driver code*/

int main() 
{ 
    node *root1 = newNode(1); 
    node *root2 = newNode(1); 
    root1->left = newNode(2); 
    root1->right = newNode(3); 
    root1->left->left = newNode(4); 
    root1->left->right = newNode(5); 
    root2->left = newNode(2); 
    root2->right = newNode(3); 
    root2->left->left = newNode(4); 
    root2->left->right = newNode(5); 
    if(identicalTrees(root1, root2)) 
        cout << "Both tree are identical."; 
    else
        cout << "Trees are not identical."; 
return 0; 
}

/* Iterative C++ program to check if two */

#include <bits/stdc++.h>
using namespace std;

/*A Binary Tree Node*/

struct Node
{
    int data;
    struct Node *left, *right;
};

/*Iterative method to find height of Binary Tree*/

bool areIdentical(Node *root1, Node *root2)
{

/*    Return true if both trees are empty*/

    if (root1==NULL  && root2==NULL) return true;

/*    Return false if one is empty and other is not*/

    if (root1 == NULL) return false;
    if (root2 == NULL) return false;

/*    Create an empty queues for simultaneous traversals */

    queue<Node *> q1, q2;

/*    Enqueue Roots of trees in respective queues*/

    q1.push(root1);
    q2.push(root2);
    while (!q1.empty() && !q2.empty())
    {

/*        Get front nodes and compare them*/

        Node *n1 = q1.front();
        Node *n2 = q2.front();
        if (n1->data != n2->data)
           return false;

/*        Remove front nodes from queues*/

        q1.pop(), q2.pop();

/* Enqueue left children of both nodes */

        if (n1->left && n2->left)
        {
            q1.push(n1->left);
            q2.push(n2->left);
        }

/*        If one left child is empty and other is not*/

        else if (n1->left || n2->left)
            return false;

/*        Right child code (Similar to left child code)*/

        if (n1->right && n2->right)
        {
            q1.push(n1->right);
            q2.push(n2->right);
        }
        else if (n1->right || n2->right)
            return false;
    }
    return true;
}

/*Utility function to create a new tree node*/

Node* newNode(int data)
{
    Node *temp = new Node;
    temp->data = data;
    temp->left = temp->right = NULL;
    return temp;
}

