/*C++ program to see if there is a root to leaf path
with given sequence.*/

#include<bits/stdc++.h>
using namespace std;

/* A binary tree node has data, pointer to left child
and a pointer to right child */

struct Node
{
    int data;
    struct Node* left, *right;
};

/* utility that allocates a new node with the
given data and NULL left and right pointers. */

struct Node* newnode(int data)
{
    struct Node* node = new Node;
    node->data = data;
    node->left = node->right = NULL;
    return (node);
}

/*Util function*/

bool existPathUtil(struct Node *root, int arr[], int n, int index)
{

/*    If root is NULL or reached end of the array*/

    if(root == NULL or index==n) 
            return false;

/*    If current node is leaf*/

    if (root->left == NULL && root->right == NULL)
    {
        if((root->data == arr[index]) && (index == n-1)) 
            return true; 
       return false;
    }

/*    If current node is equal to arr[index] this means
    that till this level path has been matched and
    remaining path can be either in left subtree or
    right subtree.*/

    return ((index < n) && (root->data == arr[index]) &&
                (existPathUtil(root->left, arr, n, index+1) ||
                existPathUtil(root->right, arr, n, index+1) ));
}

/*Function to check given sequence of root to leaf path exist
in tree or not.
index represents current element in sequence of rooth to
leaf path*/

bool existPath(struct Node *root, int arr[], int n, int index)
{
    if(!root)
        return (n==0);
    return existPathUtil(root, arr, n, 0);
}

/*Driver function to run the case*/

int main()
{

/*    arr[] --> sequence of root to leaf path*/

    int arr[] = {5, 8, 6, 7};
    int n = sizeof(arr)/sizeof(arr[0]);
    struct Node *root = newnode(5);
    root->left = newnode(3);
    root->right = newnode(8);
    root->left->left = newnode(2);
    root->left->right = newnode(4);
    root->left->left->left = newnode(1);
    root->right->left = newnode(6);
    root->right->left->right = newnode(7);
    existPath(root, arr, n, 0)? cout << "Path Exists" :
                                cout << "Path does not Exist";
    return 0;
}

/*C++ program to print cousins of a node*/

#include <bits/stdc++.h>
using namespace std;

/*A Binary Tree Node*/

struct Node
{
    int data;
    Node *left, *right;
};

/*A utility function to create a new 
Binary Tree Node*/

Node *newNode(int item)
{
    Node *temp = new Node;
    temp->data = item;
    temp->left = temp->right = NULL;
    return temp;
}

/* It returns level of the node if it is
present in tree, otherwise returns 0.*/

int getLevel(Node *root, Node *node, int level)
{

/*    base cases*/

    if (root == NULL)
        return 0;
    if (root == node)
        return level;

/*    If node is present in left subtree*/

    int downlevel = getLevel(root->left,
                             node, level + 1);
    if (downlevel != 0)
        return downlevel;

/*    If node is not present in left subtree*/

    return getLevel(root->right, node, level + 1);
}

/* Print nodes at a given level such that 
sibling of node is not printed if it exists */

void printGivenLevel(Node* root, Node *node, int level)
{

/*    Base cases*/

    if (root == NULL || level < 2)
        return;

/*    If current node is parent of a node 
    with given level*/

    if (level == 2)
    {
        if (root->left == node || root->right == node)
            return;
        if (root->left)
            cout << root->left->data << " ";
        if (root->right)
            cout << root->right->data;
    }

/*    Recur for left and right subtrees*/

    else if (level > 2)
    {
        printGivenLevel(root->left, node, level - 1);
        printGivenLevel(root->right, node, level - 1);
    }
}

/*This function prints cousins of a given node*/

void printCousins(Node *root, Node *node)
{

/*    Get level of given node*/

    int level = getLevel(root, node, 1);

/*    Print nodes of given level.*/

    printGivenLevel(root, node, level);
}

/*Driver Code*/

int main()
{
    Node *root = newNode(1);
    root->left = newNode(2);
    root->right = newNode(3);
    root->left->left = newNode(4);
    root->left->right = newNode(5);
    root->left->right->right = newNode(15);
    root->right->left = newNode(6);
    root->right->right = newNode(7);
    root->right->left->right = newNode(8);
    printCousins(root, root->left->right);
    return 0;
}

/* C++ program to print all of its
root-to-leaf paths for a tree*/

#include <bits/stdc++.h>
using namespace std;

/* A binary tree node has data, pointer to left child 
and a pointer to right child */

class node 
{ 
    public:
    int data; 
    node* left; 
    node* right; 
};

/*Function prototypes*/

void printArray(int [], int); 
void printPathsRecur(node*, int [], int); 
node* newNode(int ); 
void printPaths(node*);

/* Given a binary tree, print out 
all of its root-to-leaf paths, 
one per line. Uses a recursive helper
to do the work.*/

void printPaths(node* node) 
{ 
    int path[1000]; 
    printPathsRecur(node, path, 0); 
}

/* Recursive helper function -- given 
a node, and an array containing the 
path from the root node up to but not 
including this node, print out all the 
root-leaf paths. */

void printPathsRecur(node* node, int path[], int pathLen) 
{ 
    if (node == NULL) return;

/* append this node to the path array */

    path[pathLen] = node->data; 
    pathLen++;

/* it's a leaf, so print the path that led to here */

    if (node->left == NULL && node->right == NULL) 
    { 
        printArray(path, pathLen); 
    } 
    else
    {

/* otherwise try both subtrees */

        printPathsRecur(node->left, path, pathLen); 
        printPathsRecur(node->right, path, pathLen); 
    } 
}

/* Helper function that allocates a new node with the 
given data and NULL left and right pointers. */

node* newNode(int data) 
{ 
    node* Node = new node();
    Node->data = data; 
    Node->left = NULL; 
    Node->right = NULL; 
    return(Node); 
}

/* Utility that prints out an array on a line */

void printArray(int ints[], int len) 
{ 
    int i; 
    for (i = 0; i < len; i++)
    { 
        cout << ints[i] << " "; 
    } 
    cout << endl; 
}

