/*A C++ program to find sum of all left leaves*/

#include <bits/stdc++.h>
using namespace std;

/* A binary tree Node has key, pointer to left and right
   children */

struct Node
{
    int key;
    struct Node* left, *right;
};

/* Helper function that allocates a new node with the
   given data and NULL left and right pointer. */

Node *newNode(char k)
{
    Node *node = new Node;
    node->key = k;
    node->right = node->left = NULL;
    return node;
}

/*A utility function to check if a given node is leaf or not*/

bool isLeaf(Node *node)
{
   if (node == NULL)
       return false;
   if (node->left == NULL && node->right == NULL)
       return true;
   return false;
}

/*This function returns sum of all left leaves in a given
binary tree*/

int leftLeavesSum(Node *root)
{

/*    Initialize result*/

    int res = 0;

/*    Update result if root is not NULL*/

    if (root != NULL)
    {

/*       If left of root is NULL, then add key of
       left child*/

       if (isLeaf(root->left))
            res += root->left->key;

/*Else recur for left child of root*/

else 
            res += leftLeavesSum(root->left);

/*       Recur for right child of root and update res*/

       res += leftLeavesSum(root->right);
    }

/*    return result*/

    return res;
}

