    root->right->right->left = new Node(50);
    root->left->left = new Node(5);
    root->left->right = new Node(12);
    root->left->right->right = new Node(12);
    cout << "Sum of left leaves is "
      << sumOfLeftLeaves(root) << endl;
    return 0;
}

/*C++ program to find sum of all left leaves*/

#include <bits/stdc++.h>
using namespace std;

/*A binary tree node*/

class Node {
public:
    int key;
    Node *left, *right;

/*    constructor to create a new Node*/

    Node(int key_)
    {
        key = key_;
        left = NULL;
        right = NULL;
    }
};

/*Return the sum of left leaf nodes*/

int sumOfLeftLeaves(Node* root)
{
    if (root == NULL)
        return 0;

/*    A queue of pairs to do bfs traversal
    and keep track if the node is a left
    or right child if boolean value
    is true then it is a left child.*/

    queue<pair<Node*, bool> > q;
    q.push({ root, 0 });
    int sum = 0;

/*    do bfs traversal*/

    while (!q.empty()) {
        Node* temp = q.front().first;
        bool is_left_child =
                   q.front().second;
        q.pop();

/*        if temp is a leaf node and
        left child of its parent*/

        if (!temp->left && !temp->right &&
                            is_left_child)
            sum = sum + temp->key;

/*        if it is not leaf then
        push its children nodes
        into queue*/

        if (temp->left) {

/*            boolean value is true
            here because it is left
            child of its parent*/

            q.push({ temp->left, 1 });
        }
        if (temp->right) {

/*            boolean value is false
            here because it is
            right child of its parent*/

            q.push({ temp->right, 0 });
        }
    }
    return sum;
}

