/*      2   5      */

    root->left->left = getNode(7);

/*     / \ / \     */

    root->left->right = getNode(1);

/*    7  1 2  3    */

    root->right->left = getNode(2);

/*     6           */

    root->right->right = getNode(3); 
    root->left->right->left = getNode(6);
    cout << "Sum = "
         << sumOfLongRootToLeafPathUtil(root);
    return 0;
}

