    root->left = getNode(-10);
    root->right = getNode(3);
    root->left->left = getNode(9);
    root->left->right = getNode(8);
    root->right->left = getNode(-4);
    root->right->right = getNode(7);
    int x = 7;
    cout << "Count = "
         << countSubtreesWithSumXUtil(root, x);
    return 0;
}

