/*Code to find the sum of the nodes
which are present at the maximum depth.*/

#include <bits/stdc++.h>
using namespace std;
int sum = 0, max_level = INT_MIN;
struct Node
{
    int d;
    Node *l;
    Node *r;
};

/*Function to return a new node*/

Node* createNode(int d)
{
    Node *node;
    node = new Node;
    node->d = d;
    node->l = NULL;
    node->r = NULL;
    return node;
}

/*Function to find the sum of the node
which are present at the maximum depth.
While traversing the nodes compare the level
of the node with max_level
(Maximum level till the current node).
If the current level exceeds the maximum level,
update the max_level as current level.
If the max level and current level are same,
add the root data to current sum.*/

void sumOfNodesAtMaxDepth(Node *ro,int level)
{
    if(ro == NULL)
    return;
    if(level > max_level)
    {
        sum = ro -> d;
        max_level = level;
    }
    else if(level == max_level)
    {
        sum = sum + ro -> d;
    }
    sumOfNodesAtMaxDepth(ro -> l, level + 1);
    sumOfNodesAtMaxDepth(ro -> r, level + 1);
}

/*Driver Code*/

int main()
{
    Node *root;
    root = createNode(1);
    root->l = createNode(2);
    root->r = createNode(3);
    root->l->l = createNode(4);
    root->l->r = createNode(5);
    root->r->l = createNode(6);
    root->r->r = createNode(7);
    sumOfNodesAtMaxDepth(root, 0);
    cout << sum;
    return 0;
}

/*C++ code for sum of nodes
at maximum depth*/

#include <bits/stdc++.h>
using namespace std;

/*    Constructor*/
struct Node
{
    int data;
    Node* left, *right;
    Node(int data)
    {
        this->data = data;
        this->left = NULL;
        this->right = NULL;
    }
};

/*    function to find the sum of nodes at
    maximum depth arguments are node and
    max, where max is to match the depth
    of node at every call to node, if
    max will be equal to 1, means
    we are at deepest node.*/

    int sumMaxLevelRec(Node* node, int max)
    {

/*        base case*/

        if (node == NULL)
            return 0;

/*        max == 1 to track the node
        at deepest level*/

        if (max == 1)
            return node->data;

/*        recursive call to left and right nodes*/

        return sumMaxLevelRec(node->left, max - 1) +
            sumMaxLevelRec(node->right, max - 1);
    }

/*    maxDepth function to find the
    max depth of the tree*/

    int maxDepth(Node* node)
    {

/*        base case*/

        if (node == NULL)
            return 0;

/*        either leftDepth of rightDepth is
        greater add 1 to include height
        of node at which call is*/

        return 1 + max(maxDepth(node->left),
                        maxDepth(node->right));    
    }

/*        call to function to calculate
        max depth*/
    int sumMaxLevel(Node* root)
    {
        int MaxDepth = maxDepth(root);
        return sumMaxLevelRec(root, MaxDepth);
    }

/*    Driver code*/

    int main()
    {

/*     1
            / \
            2 3
            / \ / \
            4 5 6 7     */

/*        Constructing tree*/

        Node* root = new Node(1);
        root->left = new Node(2);
        root->right = new Node(3);
        root->left->left = new Node(4);
        root->left->right = new Node(5);
        root->right->left = new Node(6);
        root->right->right = new Node(7);

/*        call to calculate required sum*/

        cout<<(sumMaxLevel(root))<<endl;
    }

/*CPP program to find 
difference between 
sums of odd level 
and even level nodes 
of binary tree*/

#include <bits/stdc++.h>
using namespace std;

/*tree node*/

struct Node 
{
    int data;
    Node *left, *right;
};

/*returns a new
tree Node*/

Node* newNode(int data)
{
    Node* temp = new Node();
    temp->data = data;
    temp->left = temp->right = NULL;
    return temp;
}

/*return difference of
sums of odd level 
and even level*/

int evenOddLevelDifference(Node* root)
{
    if (!root)
        return 0;

/*    create a queue for
    level order traversal*/

    queue<Node*> q;
    q.push(root);
    int level = 0;
    int evenSum = 0, oddSum = 0;

/*    traverse until the
    queue is empty*/

    while (!q.empty()) 
    {
        int size = q.size();
        level += 1;

/*        traverse for 
        complete level*/

        while(size > 0)
        {
            Node* temp = q.front();
            q.pop();

/*            check if level no.
            is even or odd and
            accordingly update
            the evenSum or oddSum*/

            if(level % 2 == 0)
                evenSum += temp->data;
            else
                oddSum += temp->data;

/*            check for left child*/

            if (temp->left) 
            {
                q.push(temp->left);
            }

/*            check for right child*/

            if (temp->right)
            {
                q.push(temp->right);
            }
            size -= 1;
        } 
    }
    return (oddSum - evenSum);
}

/*driver program*/

int main()
{

/*    construct a tree*/

    Node* root = newNode(5);
    root->left = newNode(2);
    root->right = newNode(6);
    root->left->left = newNode(1);
    root->left->right = newNode(4);
    root->left->right->left = newNode(3);
    root->right->right = newNode(8);
    root->right->right->right = newNode(9);
    root->right->right->left = newNode(7);
    int result = evenOddLevelDifference(root);
    cout << "diffence between sums is :: ";
    cout << result << endl;
    return 0;
}

/*A recursive program to find difference 
between sum of nodes at odd level
and sum at even level */

#include <bits/stdc++.h>
using namespace std;

/*Binary Tree node */

class node 
{ 
    public:
    int data; 
    node* left, *right; 
};

/*A utility function to allocate 
a new tree node with given data */

node* newNode(int data) 
{ 
    node* Node = new node();
    Node->data = data; 
    Node->left = Node->right = NULL; 
    return (Node); 
}

/*The main function that return
difference between odd and even 
level nodes */

int getLevelDiff(node *root) 
{

/*Base case */

if (root == NULL) 
        return 0;

/*Difference for root is root's data - difference for 
left subtree - difference for right subtree */

return root->data - getLevelDiff(root->left) - 
                    getLevelDiff(root->right); 
}

