/*    construct binary tree*/

    Node *root = newNode(1);
    root->left = newNode(2);
    root->left->left = newNode(4);
    root->left->right = newNode(5);
    root->right = newNode(3);
    root->right->right = newNode(7);
    root->right->left = newNode(6);
    root->right->left->right = newNode(8);

/*    variable to store sum of leaf nodes*/

    int sum = 0;
    leafSum(root, sum);
    cout << sum << endl;
    return 0;
}

/*C++ implementation to find the sum of
leaf nodes at minimum level*/

#include <bits/stdc++.h>
using namespace std;

/*structure of a node of binary tree*/

struct Node {
    int data;
    Node *left, *right;
};

/*function to get a new node*/

Node* getNode(int data)
{

/*    allocate space*/

    Node* newNode = (Node*)malloc(sizeof(Node));

/*    put in the data*/

    newNode->data = data;
    newNode->left = newNode->right = NULL;
    return newNode;
}

/*function to find the sum of
leaf nodes at minimum level*/

int sumOfLeafNodesAtMinLevel(Node* root)
{

/*    if tree is empty*/

    if (!root)
        return 0;

/*    if there is only one node*/

    if (!root->left && !root->right)
        return root->data;

/*    queue used for level order traversal*/

    queue<Node*> q;
    int sum = 0; 
    bool f = 0;

/*    push root node in the queue 'q'*/

    q.push(root);
    while (f == 0) {

/*        count number of nodes in the
        current level*/

        int nc = q.size();

/*        traverse the current level nodes*/

        while (nc--) {

/*            get front element from 'q'*/

            Node* top = q.front();
            q.pop();

/*            if it is a leaf node*/

            if (!top->left && !top->right) {

/*                accumulate data to 'sum'*/

                sum += top->data;

/*                set flag 'f' to 1, to signify 
                minimum level for leaf nodes 
                has been encountered*/

                f = 1;
            }
            else {

/*                if top's left and right child 
                exists, then push them to 'q'*/

                if (top->left)
                    q.push(top->left);
                if (top->right)
                    q.push(top->right);
            }
        }
    }

/*    required sum*/

    return sum;
}

/*Driver program to test above*/

int main()
{

/*    binary tree creation*/

    Node* root = getNode(1);
    root->left = getNode(2);
    root->right = getNode(3);
    root->left->left = getNode(4);
    root->left->right = getNode(5);
    root->right->left = getNode(6);
    root->right->right = getNode(7);
    root->left->right->left = getNode(8);
    root->right->left->right = getNode(9);
    cout << "Sum = "
         << sumOfLeafNodesAtMinLevel(root);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
#define bool int

/* A binary tree node has data, pointer to left child
and a pointer to right child */

class node
{
    public:
    int data;
    node* left;
    node* right;
};

/*
Given a tree and a sum, return true if there is a path from the root
down to a leaf, such that adding up all the values along the path
equals the given sum.
Strategy: subtract the node value from the sum when recurring down,
and check to see if the sum is 0 when you run out of tree.
*/

bool hasPathSum(node* Node, int sum)
{
        if (Node == NULL)
    {
        return (sum == 0);
    }
    else
    {
        bool ans = 0;
        int subSum = sum - Node->data;
        if ( subSum == 0 && Node->left == NULL && Node->right == NULL )
        return 1;
        if(Node->left)
            ans = ans || hasPathSum(Node->left, subSum);
        if(Node->right)
            ans = ans || hasPathSum(Node->right, subSum);
        return ans;
    }
}

/* Helper function that allocates a new node with the
given data and NULL left and right pointers. */

node* newnode(int data)
{
    node* Node = new node();
    Node->data = data;
    Node->left = NULL;
    Node->right = NULL;
    return(Node);
}

/*Driver Code*/

