           4
         /   \
        1     7
       /     /  \
      3     2    6   */

    Node *root2 = newNode(4);
    root2->left = newNode(1);
    root2->right = newNode(7);
    root2->left->left = newNode(3);
    root2->right->left = newNode(2);
    root2->right->right = newNode(6);
    Node *root3 = MergeTrees(root1, root2);
    printf("The Merged Binary Tree is:\n");
    inorder(root3);
    return 0;
}

/*C++ program to Merge Two Binary Trees*/

#include <bits/stdc++.h>
using namespace std;

/* A binary tree node has data, pointer to left child
and a pointer to right child */

struct Node
{
    int data;
    struct Node *left, *right;
};

/*Structure to store node pair onto stack*/

struct snode
{
    Node *l, *r;
};

/* Helper function that allocates a new node with the
given data and NULL left and right pointers. */

Node *newNode(int data)
{
    Node *new_node = new Node;
    new_node->data = data;
    new_node->left = new_node->right = NULL;
    return new_node;
}

/* Given a binary tree, print its nodes in inorder*/

void inorder(Node * node)
{
    if (! node)
        return;

/* first recur on left child */

    inorder(node->left);

/* then print the data of node */

    printf("%d ", node->data);

/* now recur on right child */

    inorder(node->right);
}

/* Function to merge given two binary trees*/

Node* MergeTrees(Node* t1, Node* t2)
{
    if (! t1)
        return t2;
    if (! t2)
        return t1;
    stack<snode> s;
    snode temp;
    temp.l = t1;
    temp.r = t2;
    s.push(temp);
    snode n;
    while (! s.empty())
    {
        n = s.top();
        s.pop();
        if (n.l == NULL|| n.r == NULL)
            continue;
        n.l->data += n.r->data;
        if (n.l->left == NULL)
            n.l->left = n.r->left;
        else
        {
            snode t;
            t.l = n.l->left;
            t.r = n.r->left;
            s.push(t);
        }
        if (n.l->right == NULL)
            n.l->right = n.r->right;
        else
        {
            snode t;
            t.l = n.l->right;
            t.r = n.r->right;
            s.push(t);
        }
    }
    return t1;
}

/*Driver code*/

int main()
{

/* Let us construct the first Binary Tree
            1
          /   \
         2     3
        / \     \
       4   5     6
    */

    Node *root1 = newNode(1);
    root1->left = newNode(2);
    root1->right = newNode(3);
    root1->left->left = newNode(4);
    root1->left->right = newNode(5);
    root1->right->right = newNode(6);

/* Let us construct the second Binary Tree
           4
         /   \
        1     7
       /     /  \
      3     2    6   */

    Node *root2 = newNode(4);
    root2->left = newNode(1);
    root2->right = newNode(7);
    root2->left->left = newNode(3);
    root2->right->left = newNode(2);
    root2->right->right = newNode(6);
    Node *root3 = MergeTrees(root1, root2);
    printf("The Merged Binary Tree is:\n");
    inorder(root3);
    return 0;
}

/* C++ Program to find LCA of n1 and n2 using one traversal of Binary Tree */

#include <iostream>
using namespace std;

/*A Binary Tree Node*/

struct Node
{
    struct Node *left, *right;
    int key;
};

/*Utility function to create a new tree Node*/

Node* newNode(int key)
{
    Node *temp = new Node;
    temp->key = key;
    temp->left = temp->right = NULL;
    return temp;
}

/*This function returns pointer to LCA of two given values n1 and n2.
This function assumes that n1 and n2 are present in Binary Tree*/

struct Node *findLCA(struct Node* root, int n1, int n2)
{

/*    Base case*/

    if (root == NULL) return NULL;

/*    If either n1 or n2 matches with root's key, report
    the presence by returning root (Note that if a key is
    ancestor of other, then the ancestor key becomes LCA*/

    if (root->key == n1 || root->key == n2)
        return root;

/*    Look for keys in left and right subtrees*/

    Node *left_lca  = findLCA(root->left, n1, n2);
    Node *right_lca = findLCA(root->right, n1, n2);

/*    If both of the above calls return Non-NULL, then one key
    is present in once subtree and other is present in other,
    So this node is the LCA*/

    if (left_lca && right_lca)  return root;

/*    Otherwise check if left subtree or right subtree is LCA*/

    return (left_lca != NULL)? left_lca: right_lca;
}

/*Driver program to test above functions*/

int main()
{
    Node * root = newNode(1);
    root->left = newNode(2);
    root->right = newNode(3);
    root->left->left = newNode(4);
    root->left->right = newNode(5);
    root->right->left = newNode(6);
    root->right->right = newNode(7);
    cout << "LCA(4, 5) = " << findLCA(root, 4, 5)->key;
    cout << "nLCA(4, 6) = " << findLCA(root, 4, 6)->key;
    cout << "nLCA(3, 4) = " << findLCA(root, 3, 4)->key;
    cout << "nLCA(2, 4) = " << findLCA(root, 2, 4)->key;
    return 0;
}

/* C++ program to find LCA of n1 and n2 using one traversal of Binary Tree.
   It handles all cases even when n1 or n2 is not there in Binary Tree */

#include <iostream>
using namespace std;

/*A Binary Tree Node*/

struct Node
{
    struct Node *left, *right;
    int key;
};

/*Utility function to create a new tree Node*/

Node* newNode(int key)
{
    Node *temp = new Node;
    temp->key = key;
    temp->left = temp->right = NULL;
    return temp;
}

/*This function returns pointer to LCA of two given values n1 and n2.
v1 is set as true by this function if n1 is found
v2 is set as true by this function if n2 is found*/

struct Node *findLCAUtil(struct Node* root, int n1, int n2, bool &v1, bool &v2)
{

/*    Base case*/

    if (root == NULL) return NULL;

/*    If either n1 or n2 matches with root's key, report the presence
    by setting v1 or v2 as true and return root (Note that if a key
    is ancestor of other, then the ancestor key becomes LCA)*/

    if (root->key == n1)
    {
        v1 = true;
        return root;
    }
    if (root->key == n2)
    {
        v2 = true;
        return root;
    }

/*    Look for keys in left and right subtrees*/

    Node *left_lca  = findLCAUtil(root->left, n1, n2, v1, v2);
    Node *right_lca = findLCAUtil(root->right, n1, n2, v1, v2);

/*    If both of the above calls return Non-NULL, then one key
    is present in once subtree and other is present in other,
    So this node is the LCA*/

    if (left_lca && right_lca)  return root;

/*    Otherwise check if left subtree or right subtree is LCA*/

    return (left_lca != NULL)? left_lca: right_lca;
}

/*Returns true if key k is present in tree rooted with root*/

bool find(Node *root, int k)
{

    if (root == NULL)
        return false;
    if (root->key == k || find(root->left, k) ||  find(root->right, k))
        return true;
    return false;
}

/*This function returns LCA of n1 and n2 only if both n1 and n2 are present
in tree, otherwise returns NULL;*/

Node *findLCA(Node *root, int n1, int n2)
{

/*    Initialize n1 and n2 as not visited*/

    bool v1 = false, v2 = false;

/*    Find lca of n1 and n2 using the technique discussed above*/

    Node *lca = findLCAUtil(root, n1, n2, v1, v2);

/*    Return LCA only if both n1 and n2 are present in tree*/

    if (v1 && v2 || v1 && find(lca, n2) || v2 && find(lca, n1))
        return lca;

/*    Else return NULL*/

    return NULL;
}

/*Driver program to test above functions*/

int main()
{

    Node * root = newNode(1);
    root->left = newNode(2);
    root->right = newNode(3);
    root->left->left = newNode(4);
    root->left->right = newNode(5);
    root->right->left = newNode(6);
    root->right->right = newNode(7);
    Node *lca =  findLCA(root, 4, 5);
    if (lca != NULL)
       cout << "LCA(4, 5) = " << lca->key;
    else
       cout << "Keys are not present ";
    lca =  findLCA(root, 4, 10);
    if (lca != NULL)
       cout << "nLCA(4, 10) = " << lca->key;
    else
       cout << "nKeys are not present ";
    return 0;
}

/*C++ program to find lowest common ancestor using parent pointer*/

#include <bits/stdc++.h>
using namespace std;

/*A Tree Node*/

struct Node
{
    Node *left, *right, *parent;
    int key;
};

/*A utility function to create a new BST node*/

Node *newNode(int item)
{
    Node *temp = new Node;
    temp->key = item;
    temp->parent = temp->left = temp->right = NULL;
    return temp;
}

/* A utility function to insert a new node with
given key in Binary Search Tree */

Node *insert(Node *node, int key)
{

/* If the tree is empty, return a new node */

    if (node == NULL) return newNode(key);

/* Otherwise, recur down the tree */

    if (key < node->key)
    {
        node->left = insert(node->left, key);
        node->left->parent = node;
    }
    else if (key > node->key)
    {
        node->right = insert(node->right, key);
        node->right->parent = node;
    }

/* return the (unchanged) node pointer */

    return node;
}

/*A utility function to find depth of a node
(distance of it from root)*/

int depth(Node *node)
{
    int d = -1;
    while (node)
    {
        ++d;
        node = node->parent;
    }
    return d;
}

/*To find LCA of nodes n1 and n2 in Binary Tree*/

Node *LCA(Node *n1, Node *n2)
{

/*    Find depths of two nodes and differences*/

    int d1 = depth(n1), d2 = depth(n2);
    int diff = d1 - d2;

/*    If n2 is deeper, swap n1 and n2*/

    if (diff < 0)
    {
        Node * temp = n1;
        n1 = n2;
        n2 = temp;
        diff = -diff;
    }

/*    Move n1 up until it reaches the same level as n2*/

    while (diff--)
        n1 = n1->parent;

/*    Now n1 and n2 are at same levels*/

    while (n1 && n2)
    {
        if (n1 == n2)
            return n1;
        n1 = n1->parent;
        n2 = n2->parent;
    }
    return NULL;
}

/*Driver method to test above functions*/

int main(void)
{
    Node * root = NULL;
    root = insert(root, 20);
    root = insert(root, 8);
    root = insert(root, 22);
    root = insert(root, 4);
    root = insert(root, 12);
    root = insert(root, 10);
    root = insert(root, 14);
    Node *n1 = root->left->right->left;
    Node *n2 = root->right;
    Node *lca = LCA(n1, n2);
    printf("LCA of %d and %d is %d \n", n1->key, n2->key, lca->key);
    return 0;
}

/*C++ Program to find common nodes for given two nodes*/

#include <bits/stdc++.h>
using namespace std;

/*A Binary Tree Node*/

struct Node {
    struct Node* left, *right;
    int key;
};

/*Utility function to create a new tree Node*/

Node* newNode(int key)
{
    Node* temp = new Node;
    temp->key = key;
    temp->left = temp->right = NULL;
    return temp;
}

/*Utility function to find the LCA of two given values
n1 and n2.*/

struct Node* findLCA(struct Node* root, int n1, int n2)
{

/*    Base case*/

    if (root == NULL)
        return NULL;

/*    If either n1 or n2 matches with root's key,
    report the presence by returning root (Note
    that if a key is ancestor of other, then the
    ancestor key becomes LCA*/

    if (root->key == n1 || root->key == n2)
        return root;

/*    Look for keys in left and right subtrees*/

    Node* left_lca = findLCA(root->left, n1, n2);
    Node* right_lca = findLCA(root->right, n1, n2);

/*    If both of the above calls return Non-NULL, then
    one key  is present in once subtree and other is
    present in other, So this node is the LCA*/

    if (left_lca && right_lca)
        return root;

/*    Otherwise check if left subtree or right
    subtree is LCA*/

    return (left_lca != NULL) ? left_lca : right_lca;
}

/*Utility Function to print all ancestors of LCA*/

bool printAncestors(struct Node* root, int target)
{

/* base cases */

    if (root == NULL)
        return false;
    if (root->key == target) {
        cout << root->key << " ";
        return true;
    }

/* If target is present in either left or right
      subtree of this node, then print this node */

    if (printAncestors(root->left, target) ||
        printAncestors(root->right, target)) {
        cout << root->key << " ";
        return true;
    }

/* Else return false */

    return false;
}

/*Function to find nodes common to given two nodes*/

bool findCommonNodes(struct Node* root, int first,
                                       int second)
{
    struct Node* LCA = findLCA(root, first, second);
    if (LCA == NULL)
        return false;
    printAncestors(root, LCA->key);
}

