/* C++ program to calculate Kth ancestor of given node */

#include <bits/stdc++.h>
using namespace std;

/*A Binary Tree Node*/

struct Node
{
    int data;
    struct Node *left, *right;
};

/*temporary node to keep track of Node returned
from previous recursive call during backtrack*/

Node* temp = NULL;

/*recursive function to calculate Kth ancestor*/

Node* kthAncestorDFS(Node *root, int node , int &k)
{

/*    Base case*/

    if (!root)
        return NULL;
    if (root->data == node||
       (temp =  kthAncestorDFS(root->left,node,k)) ||
       (temp =  kthAncestorDFS(root->right,node,k)))
    {   
        if (k > 0)        
            k--;
        else if (k == 0)
        {

/*            print the kth ancestor*/

            cout<<"Kth ancestor is: "<<root->data;

/*            return NULL to stop further backtracking*/

            return NULL;
        }

/*        return current node to previous call*/

        return root;
    }
}

/*Utility function to create a new tree node*/

Node* newNode(int data)
{
    Node *temp = new Node;
    temp->data = data;
    temp->left = temp->right = NULL;
    return temp;
}

