    root->left->right = newNode(12);
    root->right->left = newNode(16);
    root->right->right = newNode(25);

/*    delete entire binary tree*/

    deleteTree(&root);
    return 0;
}

/*C++ program to print size of tree in iterative*/

#include<iostream>
#include<queue>
using namespace std;

/*Node Structure*/

struct Node 
{
    int data;
    Node *left, *right;
};

/*A utility function to
create a new Binary Tree Node*/

Node *newNode(int data)
{
    Node *temp = new Node;
    temp->data = data;
    temp->left = NULL;
    temp->right = NULL;
    return temp;
}

/*return size of tree*/

int sizeoftree(Node *root)
{

/*    if tree is empty it will
    return 0*/

    if(root == NULL)
        return 0;

/*    Using level order Traversal.*/

    queue<Node *> q;
    int count = 1;
    q.push(root);
    while(!q.empty())
    {
        Node *temp = q.front();

/*            when the queue is empty:
            the poll() method returns null.*/

        if(temp->left)
        {

/*            Increment count*/
            count++;

/*            Enqueue left child */
            q.push(temp->left);
        }
        if(temp->right)
        {

/*            Increment count*/

            count++;

/*            Enqueue right child */

            q.push(temp->right);
        }
        q.pop();
    }
    return count;
}

