    root->left->right = newNode(5);
    root->left->right->left = newNode(6);
    cout << "Height of tree is " << heightOfTree(root);
    return 0;
}

/* CPP program to check if
a tree is height-balanced or not */

#include <bits/stdc++.h>
using namespace std;

/* A binary tree node has data,
pointer to left child and
a pointer to right child */

class node {
public:
    int data;
    node* left;
    node* right;
};

/* Returns the height of a binary tree */

int height(node* node);

/* Returns true if binary tree
with root as root is height-balanced */

bool isBalanced(node* root)
{

/* for height of left subtree */

    int lh;

/* for height of right subtree */

    int rh;

/* If tree is empty then return true */

    if (root == NULL)
        return 1;

/* Get the height of left and right sub trees */

    lh = height(root->left);
    rh = height(root->right);
    if (abs(lh - rh) <= 1 && isBalanced(root->left) && isBalanced(root->right))
        return 1;

/* If we reach here then
    tree is not height-balanced */

    return 0;
}

/* returns maximum of two integers */

int max(int a, int b)
{
    return (a >= b) ? a : b;
}

/* The function Compute the "height"
of a tree. Height is the number of
nodes along the longest path from
the root node down to the farthest leaf node.*/

int height(node* node)
{

/* base case tree is empty */

    if (node == NULL)
        return 0;

/* If tree is not empty then
    height = 1 + max of left
        height and right heights */

    return 1 + max(height(node->left),
                   height(node->right));
}

/* Helper function that allocates
a new node with the given data
and NULL left and right pointers. */

node* newNode(int data)
{
    node* Node = new node();
    Node->data = data;
    Node->left = NULL;
    Node->right = NULL;
    return (Node);
}

