}

/*CPP program to find
depth of the deepest
odd level leaf node
of binary tree*/

#include <bits/stdc++.h>
using namespace std;

/*tree node*/

struct Node 
{
    int data;
    Node *left, *right;
};

/*returns a new
tree Node*/

Node* newNode(int data)
{
    Node* temp = new Node();
    temp->data = data;
    temp->left = temp->right = NULL;
    return temp;
}

/*return max odd number
depth of leaf node*/

int maxOddLevelDepth(Node* root)
{
    if (!root)
        return 0;

/*    create a queue
    for level order 
    traversal*/

    queue<Node*> q;
    q.push(root);
    int result = INT_MAX;
    int level = 0;

/*    traverse until the
    queue is empty*/

    while (!q.empty()) 
    {
        int size = q.size();
        level += 1;

/*        traverse for
        complete level*/

        while(size > 0)
        {
            Node* temp = q.front();
            q.pop();

/*            check if the node is
            leaf node and level 
            is odd if level is
            odd, then update result*/

            if(!temp->left && !temp->right 
                      && (level % 2 != 0))
            {
                result = level;
            }

/*            check for left child*/

            if (temp->left) 
            {
                q.push(temp->left);
            }

/*            check for right child*/

            if (temp->right)
            {
                q.push(temp->right);
            }
            size -= 1;
        } 
    }
    return result;
}

/*driver program*/

