/*CPP program to find deepest left leaf
node of binary tree*/

#include <bits/stdc++.h>
using namespace std;

/*tree node*/

struct Node {
    int data;
    Node *left, *right;
};

/*returns a new tree Node*/

Node* newNode(int data)
{
    Node* temp = new Node();
    temp->data = data;
    temp->left = temp->right = NULL;
    return temp;
}

/*return the deepest left leaf node
of binary tree*/

Node* getDeepestLeftLeafNode(Node* root)
{
    if (!root)
        return NULL;

/*    create a queue for level order traversal*/

    queue<Node*> q;
    q.push(root);
    Node* result = NULL;

/*    traverse until the queue is empty*/

    while (!q.empty()) {
        Node* temp = q.front();
        q.pop();

/*        Since we go level by level, the last 
        stored left leaf node is deepest one,*/

        if (temp->left) {
            q.push(temp->left);
            if (!temp->left->left && !temp->left->right)
                result = temp->left;
        }
        if (temp->right)
            q.push(temp->right);
    }
    return result;
}

