    root->left    = newNode(7);
    root->right   = newNode(5);
    root->left->right = newNode(6);
    root->left->right->left = newNode(1);
    root->left->right->right = newNode(11);
    root->right->right = newNode(9);
    root->right->right->left = newNode(4);
    cout << getfullCount(root);
    return 0;
}

/*Connect nodes at same level using level order
traversal.*/

#include <bits/stdc++.h>
using namespace std;

/*    Node structure*/

struct Node {
    int data;
    struct Node* left, *right, *nextRight;
};

/*Sets nextRight of all nodes of a tree*/

void connect(struct Node* root)
{
    queue<Node*> q;
    q.push(root);

/*    null marker to represent end of current level*/

    q.push(NULL);

/*    Do Level order of tree using NULL markers*/

    while (!q.empty()) {
        Node *p = q.front();
        q.pop();
        if (p != NULL) {

/*            next element in queue represents next 
            node at current Level */

            p->nextRight = q.front();

/*            push left and right children of current
            node*/

            if (p->left)
                q.push(p->left); 
            if (p->right)
                q.push(p->right);
        }

/*        if queue is not empty, push NULL to mark 
        nodes at this level are visited*/

        else if (!q.empty()) 
            q.push(NULL); 
    }
}

/* Helper function that allocates a new node with the
   given data and NULL left and right pointers. */

struct Node* newnode(int data)
{
    struct Node* node = (struct Node*)
                         malloc(sizeof(struct Node));
    node->data = data;
    node->left = node->right = node->nextRight = NULL;
    return (node);
}

/* Driver program to test above functions*/

int main()
{

/* Constructed binary tree is
              10
            /   \
          8      2
        /         \
      3            90
    */

    struct Node* root = newnode(10);
    root->left = newnode(8);
    root->right = newnode(2);
    root->left->left = newnode(3);
    root->right->right = newnode(90);

/*    Populates nextRight pointer in all nodes*/

    connect(root);

/*    Let us check the values of nextRight pointers*/

    printf("Following are populated nextRight pointers in \n"
     "the tree (-1 is printed if there is no nextRight) \n");
    printf("nextRight of %d is %d \n", root->data,
     root->nextRight ? root->nextRight->data : -1);
    printf("nextRight of %d is %d \n", root->left->data,
     root->left->nextRight ? root->left->nextRight->data : -1);
    printf("nextRight of %d is %d \n", root->right->data,
     root->right->nextRight ? root->right->nextRight->data : -1);
    printf("nextRight of %d is %d \n", root->left->left->data,
     root->left->left->nextRight ? root->left->left->nextRight->data : -1);
    printf("nextRight of %d is %d \n", root->right->right->data,
     root->right->right->nextRight ? root->right->right->nextRight->data : -1);
    return 0;
}

/*Iterative CPP program to connect
nodes at same level using
constant extra space */

#include<bits/stdc++.h> 
#include<bits/stdc++.h>
using namespace std;

/* Constructor that allocates a new node with the 
    given data and NULL left and right pointers. */
class node 
{ 
    public:
    int data; 
    node* left; 
    node* right; 
    node *nextRight; 
    node(int data)
    {
        this->data = data;
        this->left = NULL;
        this->right = NULL;
        this->nextRight = NULL;
    }
};

/* This function returns the leftmost
child of nodes at the same level as p. 
This function is used to getNExt right
of p's right child  If right child of
is NULL then this can also be used for
the left child */

node *getNextRight(node *p) 
{ 
    node *temp = p->nextRight;

/* Traverse nodes at p's level
    and find and return the first 
    node's first child */

    while (temp != NULL) 
    { 
        if (temp->left != NULL) 
            return temp->left; 
        if (temp->right != NULL) 
            return temp->right; 
        temp = temp->nextRight; 
    }

/*    If all the nodes at p's level 
    are leaf nodes then return NULL */

    return NULL; 
}

/* Sets nextRight of all nodes
of a tree with root as p */

void connectRecur(node* p) 
{ 
    node *temp; 
    if (!p) 
    return;

/*    Set nextRight for root */

    p->nextRight = NULL;

/*    set nextRight of all levels one by one */

    while (p != NULL) 
    { 
        node *q = p;

/* Connect all childrem nodes of p and
        children nodes of all other nodes at
        same level as p */

        while (q != NULL) 
        {

/*            Set the nextRight pointer
            for p's left child */

            if (q->left) 
            {

/*                If q has right child, then 
                right child is nextRight of 
                p and we also need to set
                nextRight of right child */

                if (q->right) 
                    q->left->nextRight = q->right; 
                else
                    q->left->nextRight = getNextRight(q); 
            } 
            if (q->right) 
                q->right->nextRight = getNextRight(q);

/*            Set nextRight for other 
            nodes in pre order fashion */

            q = q->nextRight; 
        }

/*        start from the first 
        node of next level */

        if (p->left) 
            p = p->left; 
        else if (p->right) 
            p = p->right; 
        else
            p = getNextRight(p); 
    } 
}

/* Driver code*/

int main() 
{

/* Constructed binary tree is 
            10 
            / \ 
        8 2 
        /     \ 
    3     90 
    */

    node *root = new node(10); 
    root->left = new node(8); 
    root->right = new node(2); 
    root->left->left = new node(3); 
    root->right->right     = new node(90);

/*    Populates nextRight pointer in all nodes */

    connectRecur(root);

/*    Let us check the values of nextRight pointers */

    cout << "Following are populated nextRight pointers in the tree"
        " (-1 is printed if there is no nextRight) \n"; 
    cout << "nextRight of " << root->data << " is "
        << (root->nextRight? root->nextRight->data: -1) <<endl; 
    cout << "nextRight of " << root->left->data << " is "
        << (root->left->nextRight? root->left->nextRight->data: -1) << endl;
    cout << "nextRight of " << root->right->data << " is "
        << (root->right->nextRight? root->right->nextRight->data: -1) << endl;
    cout << "nextRight of " << root->left->left->data<< " is "
        << (root->left->left->nextRight? root->left->left->nextRight->data: -1) << endl;
    cout << "nextRight of " << root->right->right->data << " is "
        << (root->right->right->nextRight? root->right->right->nextRight->data: -1) << endl;
    return 0; 
}

/*CPP program to connect nodes
at same level using extended
pre-order traversal*/

#include <bits/stdc++.h>
#include <iostream>
using namespace std;

/* Constructor that allocates a new node with the 
    given data and NULL left and right pointers. */
class node {
public:
    int data;
    node* left;
    node* right;
    node* nextRight;
    node(int data)
    {
        this->data = data;
        this->left = NULL;
        this->right = NULL;
        this->nextRight = NULL;
    }
};
void connectRecur(node* p);

/*Sets the nextRight of
root and calls connectRecur()
for other nodes*/

void connect(node* p)
{

/*    Set the nextRight for root*/

    p->nextRight = NULL;

/*    Set the next right for rest of the nodes
    (other than root)*/

    connectRecur(p);
}

/* Set next right of all descendents of p. 
Assumption: p is a compete binary tree */

void connectRecur(node* p)
{

/*    Base case*/

    if (!p)
        return;

/*    Set the nextRight pointer for p's left child*/

    if (p->left)
        p->left->nextRight = p->right;

/*    Set the nextRight pointer
    for p's right child p->nextRight
    will be NULL if p is the right
    most child at its level*/

    if (p->right)
        p->right->nextRight = (p->nextRight) ? p->nextRight->left : NULL;

/*    Set nextRight for other
    nodes in pre order fashion*/

    connectRecur(p->left);
    connectRecur(p->right);
}

/* Driver code*/

int main()
{

/* Constructed binary tree is 
                10 
            / \ 
            8 2 
        / 
        3 
    */

    node* root = new node(10);
    root->left = new node(8);
    root->right = new node(2);
    root->left->left = new node(3);

/*    Populates nextRight pointer in all nodes*/

    connect(root);

/*    Let us check the values
    of nextRight pointers*/

    cout << "Following are populated nextRight pointers in the tree"
            " (-1 is printed if there is no nextRight)\n";
    cout << "nextRight of " << root->data << " is "
         << (root->nextRight ? root->nextRight->data : -1) << endl;
    cout << "nextRight of " << root->left->data << " is "
         << (root->left->nextRight ? root->left->nextRight->data : -1) << endl;
    cout << "nextRight of " << root->right->data << " is "
         << (root->right->nextRight ? root->right->nextRight->data : -1) << endl;
    cout << "nextRight of " << root->left->left->data << " is "
         << (root->left->left->nextRight ? root->left->left->nextRight->data : -1) << endl;
    return 0;
}

/*C++ implementation to find the level
having maximum number of Nodes*/

#include <bits/stdc++.h>
using namespace std;

/* A binary tree Node has data, pointer
   to left child and a pointer to right
   child */

struct Node
{
    int data;
    struct Node* left;
    struct Node* right;
};

/* Helper function that allocates a new node with the
   given data and NULL left and right pointers. */

struct Node* newNode(int data)
{
    struct Node* node = new Node;
    node->data = data;
    node->left = NULL;
    node->right = NULL;
    return(node);
}

/*function to find the level
having maximum number of Nodes*/

int maxNodeLevel(Node *root)
{
    if (root == NULL)
        return -1;
    queue<Node *> q;
    q.push(root);

/*    Current level*/

    int level = 0;

/*    Maximum Nodes at same level*/

    int max = INT_MIN;

/*    Level having maximum Nodes*/

    int level_no = 0;
    while (1)
    {

/*        Count Nodes in a level*/

        int NodeCount = q.size();
        if (NodeCount == 0)
            break;

/*        If it is maximum till now
        Update level_no to current level*/

        if (NodeCount > max)
        {
            max = NodeCount;
            level_no = level;
        }

/*        Pop complete current level*/

        while (NodeCount > 0)
        {
            Node *Node = q.front();
            q.pop();
            if (Node->left != NULL)
                q.push(Node->left);
            if (Node->right != NULL)
                q.push(Node->right);
            NodeCount--;
        }

/*        Increment for next level*/

        level++;
    }
    return level_no;
}

/*Driver program to test above*/

int main()
{

/*    binary tree formation*/

    struct Node *root = newNode(2);

/*        2      */

    root->left        = newNode(1);

/*      /   \    */

    root->right       = newNode(3);

/*     1     3      */

    root->left->left  = newNode(4);

/*   /   \    \  */

    root->left->right = newNode(6);

/*  4     6    8 */

    root->right->right  = newNode(8);

/*       /       */

    root->left->right->left = newNode(5);

/*      5        */

    printf("Level having maximum number of Nodes : %d",
            maxNodeLevel(root));
    return 0;
}

/*C++ implementation to print largest
value in each level of Binary Tree*/

#include <bits/stdc++.h>
using namespace std;

/*structure of a node of binary tree*/

struct Node {
    int data;
    Node *left, *right;
};

/*function to get a new node*/

Node* newNode(int data)
{

/*    allocate space*/

    Node* temp = new Node;

/*    put in the data*/

    temp->data = data;
    temp->left = temp->right = NULL;
    return temp;
}

/*function to print largest value
in each level of Binary Tree*/

void largestValueInEachLevel(Node* root)
{

/*    if tree is empty*/

    if (!root)
        return;
    queue<Node*> q;
    int nc, max;

/*    push root to the queue 'q'*/

    q.push(root);
    while (1) {

/*        node count for the current level*/

        nc = q.size();

/*        if true then all the nodes of
        the tree have been traversed*/

        if (nc == 0)
            break;

/*        maximum element for the current
        level*/

        max = INT_MIN;
        while (nc--) {

/*            get the front element from 'q'*/

            Node* front = q.front();

/*            remove front element from 'q'*/

            q.pop();

/*            if true, then update 'max'*/

            if (max < front->data)
                max = front->data;

/*            if left child exists*/

            if (front->left)
                q.push(front->left);

/*            if right child exists*/

            if (front->right)
                q.push(front->right);
        }

/*        print maximum element of
        current level*/

        cout << max << " ";
    }
}

/*Driver code*/

int main()
{

/* Construct a Binary Tree
        4
       / \
      9   2
     / \   \
    3   5   7 */

    Node* root = NULL;
    root = newNode(4);
    root->left = newNode(9);
    root->right = newNode(2);
    root->left->left = newNode(3);
    root->left->right = newNode(5);
    root->right->right = newNode(7);

/*    Function call*/

    largestValueInEachLevel(root);
    return 0;
}

/*CPP program to print smallest element
in each level of binary tree.*/

#include <bits/stdc++.h>
#define INT_MAX 10e6
using namespace std;

/*A Binary Tree Node*/

struct Node {
    int data;
    struct Node *left, *right;
};

/*return height of tree*/

int heightoftree(Node* root)
{
    if (root == NULL)
        return 0;
    int left = heightoftree(root->left);
    int right = heightoftree(root->right);
    return ((left > right ? left : right) + 1);
}

/*Inorder Traversal
Search minimum element in each level and
store it into vector array.*/

void printPerLevelMinimum(Node* root,
                  vector<int>& res, int level)
{
    if (root != NULL) {
        printPerLevelMinimum(root->left,
                              res, level + 1);
        if (root->data < res[level])
            res[level] = root->data;
        printPerLevelMinimum(root->right,
                              res, level + 1);
    }
}
void perLevelMinimumUtility(Node* root)
{

/*    height of tree for the size of
    vector array*/

    int n = heightoftree(root), i;

/*    vector for store all minimum of
    every level*/

    vector<int> res(n, INT_MAX);

/*    save every level minimum using
    inorder traversal*/

    printPerLevelMinimum(root, res, 0);

/*    print every level minimum*/

    cout << "Every level minimum is\n";
    for (i = 0; i < n; i++) {
        cout << "level " << i <<" min is = "
                            << res[i] << "\n";
    }
}

