/*CPP program to print minimum element
in each level of binary tree.*/

#include <iostream>
#include <queue>
#include <vector>
#define INT_MAX 10e6
using namespace std;

/*A Binary Tree Node*/

struct Node {
    int data;
    struct Node *left, *right;
};

/*return height of tree*/

int heightoftree(Node* root)
{
    if (root == NULL)
        return 0;
    int left = heightoftree(root->left);
    int right = heightoftree(root->right);
    return ((left > right ? left : right) + 1);
}

/*Iterative method to find every level
minimum element of Binary Tree*/

void printPerLevelMinimum(Node* root)
{

/*    Base Case*/

    if (root == NULL)
        return ;

/*    Create an empty queue for
    level order traversal*/

    queue<Node*> q;

/*    push the root for Change the level*/

    q.push(root);

/*    for go level by level*/

    q.push(NULL);
    int min = INT_MAX;

/*    for check the level*/

    int level = 0;
    while (q.empty() == false) {

/*        Get top of queue*/

        Node* node = q.front();
        q.pop();

/*        if node == NULL (Means this is
        boundary between two levels)*/

        if (node == NULL) {
            cout << "level " << level <<
             " min is = " << min << "\n";

/*            here queue is empty represent
            no element in the actual
            queue*/

            if (q.empty())
                break;
            q.push(NULL);

/*            increment level*/

            level++;

/*            Reset min for next level
            minimum value*/

            min = INT_MAX;
            continue;
        }

/*        get Minimum in every level*/

        if (min > node->data)
            min = node->data;

/* Enqueue left child */

        if (node->left != NULL) {
            q.push(node->left);
        }

/*Enqueue right child */

        if (node->right != NULL) {
            q.push(node->right);
        }
    }
}

/*Utility function to create a
new tree node*/

Node* newNode(int data)
{
    Node* temp = new Node;
    temp->data = data;
    temp->left = temp->right = NULL;
    return temp;
}

