/*      7
        /  \
       6    5
      / \  / \
     4  3 2   1         */

    cout << "Every Level minimum is"
        << "\n";
    printPerLevelMinimum(root);
    return 0;
}

/*C++ program to Get Level of a
node in a Binary Tree*/

#include<bits/stdc++.h>
using namespace std;

/* A tree node structure */

struct node
{
    int data;
    struct node *left;
    struct node *right;
};

/* Helper function for getLevel().
It returns level of the data if data is
present in tree, otherwise returns 0.*/

int getLevelUtil(struct node *node,
                 int data, int level)
{
    if (node == NULL)
        return 0;
    if (node -> data == data)
        return level;
    int downlevel = getLevelUtil(node -> left,
                                 data, level + 1);
    if (downlevel != 0)
        return downlevel;
    downlevel = getLevelUtil(node->right,
                             data, level + 1);
    return downlevel;
}

/* Returns level of given data value */

int getLevel(struct node *node, int data)
{
    return getLevelUtil(node, data, 1);
}

/* Utility function to create a
new Binary Tree node */

struct node* newNode(int data)
{
    struct node *temp = new struct node;
    temp -> data = data;
    temp -> left = NULL;
    temp -> right = NULL;
    return temp;
}

