    struct Node *root = newNode(2);

/*          2         */

    root->left        = newNode(1);

/*      /     \       */

    root->right       = newNode(3);

/*     1        3        */

    root->left->left  = newNode(4);

/*   /   \     /  \    */

    root->left->right = newNode(10);

/*  4    10   8     5  */

    root->right->left  = newNode(8);

/*       /             */

    root->right->right = newNode(5);

/*     6               */

    root->left->right->left = newNode(6);
    printf("Count = %d", countSubtrees(root));
    return 0;
}

/*C++ program to find distance of a given
node from root.*/

#include <bits/stdc++.h>
using namespace std;

/*A Binary Tree Node*/

struct Node
{
    int data;
    Node *left, *right;
};

/*A utility function to create a new Binary
Tree Node*/

Node *newNode(int item)
{
    Node *temp = new Node;
    temp->data = item;
    temp->left = temp->right = NULL;
    return temp;
}

/*Returns -1 if x doesn't exist in tree. Else
returns distance of x from root*/

int findDistance(Node *root, int x)
{

/*    Base case*/

    if (root == NULL)
      return -1;

/*    Initialize distance*/

    int dist = -1;

/*    Check if x is present at root or in left
    subtree or right subtree.*/

    if ((root->data == x) ||
        (dist = findDistance(root->left, x)) >= 0 ||
        (dist = findDistance(root->right, x)) >= 0)
        return dist + 1;
    return dist;
}

/*Driver Program to test above functions*/

int main()
{
    Node *root = newNode(5);
    root->left = newNode(10);
    root->right = newNode(15);
    root->left->left = newNode(20);
    root->left->right = newNode(25);
    root->left->right->right = newNode(45);
    root->right->left = newNode(30);
    root->right->right = newNode(35);
    cout << findDistance(root, 45);
    return 0;
}

/*C program to print right sibling of a node*/

#include <bits/stdc++.h>

/*A Binary Tree Node*/

struct Node {
    int data;
    Node *left, *right, *parent;
};

/*A utility function to create a new Binary
Tree Node*/

Node* newNode(int item, Node* parent)
{
    Node* temp = new Node;
    temp->data = item;
    temp->left = temp->right = NULL;
    temp->parent = parent;
    return temp;
}

/*Method to find right sibling*/

Node* findRightSibling(Node* node, int level)
{
    if (node == NULL || node->parent == NULL)
        return NULL;

/*    GET Parent pointer whose right child is not
    a parent or itself of this node. There might
    be case when parent has no right child, but,
    current node is left child of the parent
    (second condition is for that).*/

    while (node->parent->right == node
           || (node->parent->right == NULL
               && node->parent->left == node)) {
        if (node->parent == NULL
            || node->parent->parent == NULL)
            return NULL;
        node = node->parent;
        level--;
    }

/*    Move to the required child, where right sibling
    can be present*/

    node = node->parent->right;
    if (node == NULL)
        return NULL;

/*    find right sibling in the given subtree(from current
    node), when level will be 0*/

    while (level < 0) {

/*        Iterate through subtree*/

        if (node->left != NULL)
            node = node->left;
        else if (node->right != NULL)
            node = node->right;
        else

/*            if no child are there, we cannot have right
            sibling in this path*/

            break;
        level++;
    }
    if (level == 0)
        return node;

/*    This is the case when we reach 9 node in the tree,
    where we need to again recursively find the right
    sibling*/

    return findRightSibling(node, level);
}

/*Driver Program to test above functions*/

int main()
{
    Node* root = newNode(1, NULL);
    root->left = newNode(2, root);
    root->right = newNode(3, root);
    root->left->left = newNode(4, root->left);
    root->left->right = newNode(6, root->left);
    root->left->left->left = newNode(7, root->left->left);
    root->left->left->left->left = newNode(10, root->left->left->left);
    root->left->right->right = newNode(9, root->left->right);
    root->right->right = newNode(5, root->right);
    root->right->right->right = newNode(8, root->right->right);
    root->right->right->right->right = newNode(12, root->right->right->right);

/*    passing 10*/

    Node* res = findRightSibling(root->left->left->left->left, 0);
    if (res == NULL)
        printf("No right sibling");
    else
        printf("%d", res->data);
    return 0;
}

/* C++ program to find next right of a given key
   using preorder traversal */

#include <bits/stdc++.h>
using namespace std;

/*A Binary Tree Node*/

struct Node {
    struct Node *left, *right;
    int key;
};

/*Utility function to create a new tree node*/

Node* newNode(int key)
{
    Node* temp = new Node;
    temp->key = key;
    temp->left = temp->right = NULL;
    return temp;
}

/*Function to find next node for given node
in same level in a binary tree by using
pre-order traversal*/

Node* nextRightNode(Node* root, int k, int level,
                               int& value_level)
{

/*    return null if tree is empty*/

    if (root == NULL)
        return NULL;

/*    if desired node is found, set value_level
    to current level*/

    if (root->key == k) {
        value_level = level;
        return NULL;
    }

/*    if value_level is already set, then current
    node is the next right node*/

    else if (value_level) {
        if (level == value_level)
            return root;
    }

/*    recurse for left subtree by increasing level by 1*/

    Node* leftNode = nextRightNode(root->left, k,
                        level + 1,  value_level);

/*    if node is found in left subtree, return it*/

    if (leftNode)
        return leftNode;

/*    recurse for right subtree by increasing level by 1*/

    return nextRightNode(root->right, k, level + 1,
                                       value_level);
}

/*Function to find next node of given node in the
  same level in given binary tree*/

Node* nextRightNodeUtil(Node* root, int k)
{
    int value_level = 0;
    return nextRightNode(root, k, 1, value_level);
}

/*A utility function to test above functions*/

void test(Node* root, int k)
{
    Node* nr = nextRightNodeUtil(root, k);
    if (nr != NULL)
        cout << "Next Right of " << k << " is "
             << nr->key << endl;
    else
        cout << "No next right node found for "
             << k << endl;
}

/*Driver program to test above functions*/

int main()
{

/*    Let us create binary tree given in the
    above example*/

    Node* root = newNode(10);
    root->left = newNode(2);
    root->right = newNode(6);
    root->right->right = newNode(5);
    root->left->left = newNode(8);
    root->left->right = newNode(4);
    test(root, 10);
    test(root, 2);
    test(root, 6);
    test(root, 5);
    test(root, 8);
    test(root, 4);
    return 0;
}

/*CPP program to find largest three elements in
a binary tree.*/

#include <bits/stdc++.h>
using namespace std;
struct Node {
  int data;
  struct Node *left;
  struct Node *right;
};

/* Helper function that allocates a new Node with the
   given data and NULL left and right pointers. */

struct Node *newNode(int data) {
  struct Node *node = new Node;
  node->data = data;
  node->left = NULL;
  node->right = NULL;
  return (node);
}

/*function to find three largest element*/

void threelargest(Node *root, int &first, int &second,
                                          int &third) {
  if (root == NULL)
    return;

/*  if data is greater than first large number
  update the top three list*/

  if (root->data > first) {
    third = second;
    second = first;
    first = root->data;
  }

/*  if data is greater than second large number
  and not equal to first update the bottom
  two list*/

  else if (root->data > second && root->data != first) {
    third = second;
    second = root->data;
  }

/*  if data is greater than third large number
  and not equal to first & second update the
  third highest list*/

  else if (root->data > third &&
           root->data != first &&
           root->data != second)
    third = root->data;
  threelargest(root->left, first, second, third);
  threelargest(root->right, first, second, third);
}

/*driver function*/

int main() {
  struct Node *root = newNode(1);
  root->left = newNode(2);
  root->right = newNode(3);
  root->left->left = newNode(4);
  root->left->right = newNode(5);
  root->right->left = newNode(4);
  root->right->right = newNode(5);
  int first = 0, second = 0, third = 0;
  threelargest(root, first, second, third);
  cout << "three largest elements are "
       << first << " " << second << " "
       << third;
  return 0;
}

/*C++ program to find maximum and
minimum in a Binary Tree*/

#include <bits/stdc++.h>
#include <iostream>
using namespace std;

/*A tree node*/

class Node {
public:
    int data;
    Node *left, *right;

/* Constructor that allocates a new
    node with the given data and NULL
    left and right pointers. */

    Node(int data)
    {
        this->data = data;
        this->left = NULL;
        this->right = NULL;
    }
};

/*Returns maximum value in a given
Binary Tree*/

int findMax(Node* root)
{

/*    Base case*/

    if (root == NULL)
        return INT_MIN;

/*    Return maximum of 3 values:
    1) Root's data 2) Max in Left Subtree
    3) Max in right subtree*/

    int res = root->data;
    int lres = findMax(root->left);
    int rres = findMax(root->right);
    if (lres > res)
        res = lres;
    if (rres > res)
        res = rres;
    return res;
}

/*Driver Code*/

int main()
{
    Node* NewRoot = NULL;
    Node* root = new Node(2);
    root->left = new Node(7);
    root->right = new Node(5);
    root->left->right = new Node(6);
    root->left->right->left = new Node(1);
    root->left->right->right = new Node(11);
    root->right->right = new Node(9);
    root->right->right->left = new Node(4);

/*    Function call*/

    cout << "Maximum element is " << findMax(root) << endl;
    return 0;
}

/*C++ program to extract leaves of
a Binary Tree in a Doubly Linked List*/

#include <bits/stdc++.h>
using namespace std;

/*Structure for tree and linked list*/

class Node
{
    public:
    int data;
    Node *left, *right;
};

/*Main function which extracts all
leaves from given Binary Tree.
The function returns new root of
Binary Tree (Note that root may change
if Binary Tree has only one node).
The function also sets *head_ref as
head of doubly linked list. left pointer
of tree is used as prev in DLL
and right pointer is used as next*/

Node* extractLeafList(Node *root, Node **head_ref)
{
if (root == NULL) return NULL;
if (root->left == NULL && root->right == NULL)
{
    root->right = *head_ref;
    if (*head_ref != NULL) (*head_ref)->left = root;
    *head_ref = root;
return NULL; 
}
root->right = extractLeafList(root->right, head_ref);
root->left = extractLeafList(root->left, head_ref);
return root;
}

/*Utility function for allocating node for Binary Tree.*/

Node* newNode(int data)
{
    Node* node = new Node();
    node->data = data;
    node->left = node->right = NULL;
    return node;
}

/*Utility function for printing tree in In-Order.*/

void print(Node *root)
{
    if (root != NULL)
    {
        print(root->left);
        cout<<root->data<<" ";
        print(root->right);
    }
}

/*Utility function for printing double linked list.*/

void printList(Node *head)
{
    while (head)
    {
        cout<<head->data<<" ";
        head = head->right;
    }
}

/*Driver code*/

int main()
{
    Node *head = NULL;
    Node *root = newNode(1);
    root->left = newNode(2);
    root->right = newNode(3);
    root->left->left = newNode(4);
    root->left->right = newNode(5);
    root->right->right = newNode(6);
    root->left->left->left = newNode(7);
    root->left->left->right = newNode(8);
    root->right->right->left = newNode(9);
    root->right->right->right = newNode(10);
    cout << "Inorder Trvaersal of given Tree is:\n";
    print(root);
    root = extractLeafList(root, &head);
    cout << "\nExtracted Double Linked list is:\n";
    printList(head);
    cout << "\nInorder traversal of modified tree is:\n";
    print(root);
    return 0;
}

/*A C++ program to demonstrate adjacency list
representation of graphs using sets*/

#include <bits/stdc++.h>
using namespace std;

struct Graph {
    int V;
    set<int, greater<int> >* adjList;
};

Graph* createGraph(int V)
{
    Graph* graph = new Graph;
    graph->V = V;
    graph->adjList = new set<int, greater<int> >[V];
    return graph;
}

/*Adds an edge to an undirected graph*/

void addEdge(Graph* graph, int src, int dest)
{

/*    Add an edge from src to dest.  A new
    element is inserted to the adjacent
    list of src.*/

    graph->adjList[src].insert(dest);

/*    Since graph is undirected, add an edge
    from dest to src also*/

    graph->adjList[dest].insert(src);
}

/*A utility function to print the adjacency
list representation of graph*/

void printGraph(Graph* graph)
{
    for (int i = 0; i < graph->V; ++i) {
        set<int, greater<int> > lst = graph->adjList[i];
        cout << endl << "Adjacency list of vertex "
             << i << endl;
        for (auto itr = lst.begin(); itr != lst.end(); ++itr)
            cout << *itr << " ";
        cout << endl;
    }
}

/*Searches for a given edge in the graph*/

void searchEdge(Graph* graph, int src, int dest)
{
    auto itr = graph->adjList[src].find(dest);
    if (itr == graph->adjList[src].end())
        cout << endl << "Edge from " << src
             << " to " << dest << " not found."
             << endl;
    else
        cout << endl << "Edge from " << src
             << " to " << dest << " found."
             << endl;
}

/*Driver code*/

int main()
{

/*    Create the graph given in the above figure*/

    int V = 5;
    struct Graph* graph = createGraph(V);
    addEdge(graph, 0, 1);
    addEdge(graph, 0, 4);
    addEdge(graph, 1, 2);
    addEdge(graph, 1, 3);
    addEdge(graph, 1, 4);
    addEdge(graph, 2, 3);
    addEdge(graph, 3, 4);

/*    Print the adjacency list representation of
    the above graph*/

    printGraph(graph);

/*    Search the given edge in the graph*/

    searchEdge(graph, 2, 1);
    searchEdge(graph, 0, 3);
    return 0;
}

/*C++ program to find K-Cores of a graph*/

#include<bits/stdc++.h>
using namespace std;

/*This class represents a undirected graph using adjacency
list representation*/

class Graph
{

/*No. of vertices*/

int V;

/*    Pointer to an array containing adjacency lists*/

    list<int> *adj;
public:
Graph::Graph(int V)
{
    this->V = V;
    adj = new list<int>[V];
}

/*Constructor*/

    void addEdge(int u, int v);
    bool DFSUtil(int, vector<bool> &, vector<int> &, int k);

    void printKCores(int k);
};

/*        function to add an edge to graph*/

void Graph::addEdge(int u, int v)
{
    adj[u].push_back(v);
    adj[v].push_back(u);
}

/*A recursive function to print DFS starting from v.
It returns true if degree of v after processing is less
than k else false
It also updates degree of adjacent if degree of v
is less than k. And if degree of a processed adjacent
becomes less than k, then it reduces of degree of v also,*/

void Graph::DFSUtil(int v, vector<bool> &visited,
                    vector<int> &vDegree, int k)
{

/*    Mark the current node as visited and print it*/

    visited[v] = true;

/*    Recur for all the vertices adjacent to this vertex*/

    list<int>::iterator i;
    for (i = adj[v].begin(); i != adj[v].end(); ++i)
    {

/*        degree of v is less than k, then degree of adjacent
        must be reduced*/

        if (vDegree[v] < k)
            vDegree[*i]--;

/*        If adjacent is not processed, process it*/

        if (!visited[*i])
        {

/*            If degree of adjacent after processing becomes
            less than k, then reduce degree of v also.*/

            DFSUtil(*i, visited, vDegree, k)
        }
    }

/*    Return true if degree of v is less than k*/

    return (vDegree[v] < k);
}

/*Prints k cores of an undirected graph*/

void Graph::printKCores(int k)
{

/*    INITIALIZATION
    Mark all the vertices as not visited and not
    processed.*/

    vector<bool> visited(V, false);
    vector<bool> processed(V, false);
    int mindeg = INT_MAX;
    int startvertex;

/*    Store degrees of all vertices*/

    vector<int> vDegree(V);
    for (int i=0; i<V; i++)
    {
        vDegree[i] = adj[i].size();
        if (vDegree[i] < mindeg)
        {
            mindeg = vDegree[i];
            startvertex=i;
        }
    }
    DFSUtil(startvertex, visited, vDegree, k);

/*    If Graph is disconnected.*/

    for (int i=0; i<V; i++)
        if (visited[i] == false)
            DFSUtil(i, visited, vDegree, k);

/*    PRINTING K CORES*/

    cout << "K-Cores : \n";
    for (int v=0; v<V; v++)
    {

/*        Only considering those vertices which have degree
        >= K after BFS*/

        if (vDegree[v] >= k)
        {
            cout << "\n[" << v << "]";

/*            Traverse adjacency list of v and print only
            those adjacent which have vDegree >= k after
            BFS.*/

            list<int>::iterator itr;
            for (itr = adj[v].begin(); itr != adj[v].end(); ++itr)
                if (vDegree[*itr] >= k)
                    cout << " -> " << *itr;
        }
    }
}

