}

/*C++ program to check if linked list is circular*/

#include<bits/stdc++.h>
using namespace std;

/* Link list Node */

struct Node
{
    int data;
    struct Node* next;
};

/* This function returns true if given linked
   list is circular, else false. */

bool isCircular(struct Node *head)
{

/*    An empty linked list is circular*/

    if (head == NULL)
       return true;

/*    Next of head*/

    struct Node *node = head->next;

/*    This loop would stop in both cases (1) If
    Circular (2) Not circular*/

    while (node != NULL && node != head)
       node = node->next;

/*    If loop stopped because of circular
    condition*/

    return (node == head);
}

/*Utility function to create a new node.*/

Node *newNode(int data)
{
    struct Node *temp = new Node;
    temp->data = data;
    temp->next = NULL;
    return temp;
}

/* Driver program to test above function*/

int main()
{

/* Start with the empty list */

    struct Node* head = newNode(1);
    head->next = newNode(2);
    head->next->next = newNode(3);
    head->next->next->next = newNode(4);
    isCircular(head)? cout << "Yes\n" :
                      cout << "No\n" ;

/*    Making linked list circular*/

    head->next->next->next->next = head;
    isCircular(head)? cout << "Yes\n" :
                      cout << "No\n" ;
    return 0;
}

/*A C++ program to swap Kth node
from beginning with kth node from end*/

#include <bits/stdc++.h>
using namespace std;

/*A Linked List node*/

struct Node {
    int data;
    struct Node* next;
};

/* Utility function to insert
   a node at the beginning */

void push(struct Node** head_ref, int new_data)
{
    struct Node* new_node
        = (struct Node*)malloc(
            sizeof(struct Node));
    new_node->data = new_data;
    new_node->next = (*head_ref);
    (*head_ref) = new_node;
}

/* Utility function for displaying linked list */

void printList(struct Node* node)
{
    while (node != NULL) {
        cout << node->data << " ";
        node = node->next;
    }
    cout << endl;
}

/* Utility function for calculating
   length of linked list */

int countNodes(struct Node* s)
{
    int count = 0;
    while (s != NULL) {
        count++;
        s = s->next;
    }
    return count;
}

/* Function for swapping kth nodes
   from both ends of linked list */

void swapKth(struct Node** head_ref, int k)
{

/*    Count nodes in linked list*/

    int n = countNodes(*head_ref);

/*    Check if k is valid*/

    if (n < k)
        return;

/*    If x (kth node from start) and
    y(kth node from end) are same*/

    if (2 * k - 1 == n)
        return;

/*    Find the kth node from the beginning of
    the linked list. We also find
    previous of kth node because we
    need to update next pointer of
    the previous.*/

    Node* x = *head_ref;
    Node* x_prev = NULL;
    for (int i = 1; i < k; i++) {
        x_prev = x;
        x = x->next;
    }

/*    Similarly, find the kth node from
    end and its previous. kth node
    from end is (n-k+1)th node from beginning*/

    Node* y = *head_ref;
    Node* y_prev = NULL;
    for (int i = 1; i < n - k + 1; i++) {
        y_prev = y;
        y = y->next;
    }

/*    If x_prev exists, then new next of
    it will be y. Consider the case
    when y->next is x, in this case,
    x_prev and y are same. So the statement
    "x_prev->next = y" creates a self loop.
    This self loop will be broken
    when we change y->next.*/

    if (x_prev)
        x_prev->next = y;

/*    Same thing applies to y_prev*/

    if (y_prev)
        y_prev->next = x;

/*    Swap next pointers of x and y.
    These statements also break self
    loop if x->next is y or y->next is x*/

    Node* temp = x->next;
    x->next = y->next;
    y->next = temp;

/*    Change head pointers when k is 1 or n*/

    if (k == 1)
        *head_ref = y;
    if (k == n)
        *head_ref = x;
}

/*Driver program to test above functions*/

int main()
{
    struct Node* head = NULL;
    for (int i = 8; i >= 1; i--)
        push(&head, i);
    cout << "Original Linked List: ";
    printList(head);
    for (int k = 1; k < 9; k++) {
        swapKth(&head, k);
        cout << "\nModified List for k = " << k << endl;
        printList(head);
    }
    return 0;
}

/*C++ program to find a pair with given sum x.*/

#include<bits/stdc++.h>
using namespace std;

/*structure of node of doubly linked list*/

struct Node
{
    int data;
    struct Node *next, *prev;
};

/*Function to find pair whose sum equal to given value x.*/

void pairSum(struct Node *head, int x)
{

/*    Set two pointers, first to the beginning of DLL
    and second to the end of DLL.*/

    struct Node *first = head;
    struct Node *second = head;
    while (second->next != NULL)
        second = second->next;

/*    To track if we find a pair or not*/

    bool found = false;

/*    The loop terminates when two pointers
    cross each other (second->next
    == first), or they become same (first == second)*/

    while (first != second && second->next != first)
    {

/*        pair found*/

        if ((first->data + second->data) == x)
        {
            found = true;
            cout << "(" << first->data<< ", "
                << second->data << ")" << endl;

/*            move first in forward direction*/

            first = first->next;

/*            move second in backward direction*/

            second = second->prev;
        }
        else
        {
            if ((first->data + second->data) < x)
                first = first->next;
            else
                second = second->prev;
        }
    }

/*    if pair is not present*/

    if (found == false)
        cout << "No pair found";
}

/*A utility function to insert a new node at the
beginning of doubly linked list*/

void insert(struct Node **head, int data)
{
    struct Node *temp = new Node;
    temp->data = data;
    temp->next = temp->prev = NULL;
    if (!(*head))
        (*head) = temp;
    else
    {
        temp->next = *head;
        (*head)->prev = temp;
        (*head) = temp;
    }
}

/*Driver program*/

int main()
{
    struct Node *head = NULL;
    insert(&head, 9);
    insert(&head, 8);
    insert(&head, 6);
    insert(&head, 5);
    insert(&head, 4);
    insert(&head, 2);
    insert(&head, 1);
    int x = 7;
    pairSum(head, x);
    return 0;
}

/*C++ implementation to count triplets in a sorted doubly linked list
whose sum is equal to a given value 'x'*/

#include <bits/stdc++.h>
using namespace std;

/*structure of node of doubly linked list*/

struct Node {
    int data;
    struct Node* next, *prev;
};

/*function to count pairs whose sum equal to given 'value'*/

int countPairs(struct Node* first, struct Node* second, int value)
{
    int count = 0;

/*    The loop terminates when either of two pointers
    become NULL, or they cross each other (second->next
    == first), or they become same (first == second)*/

    while (first != NULL && second != NULL &&
           first != second && second->next != first) {

/*        pair found*/

        if ((first->data + second->data) == value) {

/*            increment count*/

            count++;

/*            move first in forward direction*/

            first = first->next;

/*            move second in backward direction*/

            second = second->prev;
        }

/*        if sum is greater than 'value'
        move second in backward direction*/

        else if ((first->data + second->data) > value)
            second = second->prev;

/*        else move first in forward direction*/

        else
            first = first->next;
    }

/*    required count of pairs*/

    return count;
}

/*function to count triplets in a sorted doubly linked list
whose sum is equal to a given value 'x'*/

int countTriplets(struct Node* head, int x)
{

/*    if list is empty*/

    if (head == NULL)
        return 0;
    struct Node* current, *first, *last;
    int count = 0;

/*    get pointer to the last node of
    the doubly linked list*/

    last = head;
    while (last->next != NULL)
        last = last->next;

/*    traversing the doubly linked list*/

    for (current = head; current != NULL; current = current->next) {

/*        for each current node*/

        first = current->next;

/*        count pairs with sum(x - current->data) in the range
        first to last and add it to the 'count' of triplets*/

        count += countPairs(first, last, x - current->data);
    }

/*    required count of triplets*/

    return count;
}

/*A utility function to insert a new node at the
beginning of doubly linked list*/

void insert(struct Node** head, int data)
{

/*    allocate node*/

    struct Node* temp = new Node();

/*    put in the data*/

    temp->data = data;
    temp->next = temp->prev = NULL;
    if ((*head) == NULL)
        (*head) = temp;
    else {
        temp->next = *head;
        (*head)->prev = temp;
        (*head) = temp;
    }
}

/*Driver program to test above*/

int main()
{

/*    start with an empty doubly linked list*/

    struct Node* head = NULL;

/*    insert values in sorted order*/

    insert(&head, 9);
    insert(&head, 8);
    insert(&head, 6);
    insert(&head, 5);
    insert(&head, 4);
    insert(&head, 2);
    insert(&head, 1);
    int x = 17;
    cout << "Count = "
         << countTriplets(head, x);
    return 0;
}

/*C++ implementation to remove duplicates from an
unsorted doubly linked list*/

#include <bits/stdc++.h>
using namespace std;

/*a node of the doubly linked list*/

struct Node {
    int data;
    struct Node* next;
    struct Node* prev;
};

/*Function to delete a node in a Doubly Linked List.
head_ref --> pointer to head node pointer.
del  -->  pointer to node to be deleted.*/

void deleteNode(struct Node** head_ref, struct Node* del)
{

/*    base case*/

    if (*head_ref == NULL || del == NULL)
        return;

/*    If node to be deleted is head node*/

    if (*head_ref == del)
        *head_ref = del->next;

/*    Change next only if node to be deleted
    is NOT the last node*/

    if (del->next != NULL)
        del->next->prev = del->prev;

/*    Change prev only if node to be deleted
    is NOT the first node*/

    if (del->prev != NULL)
        del->prev->next = del->next;
    free(del);
}

/*function to remove duplicates from
an unsorted doubly linked list*/

void removeDuplicates(struct Node** head_ref)
{

/*    if DLL is empty or if it contains only
    a single node*/

    if ((*head_ref) == NULL ||
        (*head_ref)->next == NULL)
        return;
    struct Node* ptr1, *ptr2;

/*    pick elements one by one*/

    for (ptr1 = *head_ref; ptr1 != NULL; ptr1 = ptr1->next) {
        ptr2 = ptr1->next;

/*        Compare the picked element with the
        rest of the elements*/

        while (ptr2 != NULL) {

/*            if duplicate, then delete it*/

            if (ptr1->data == ptr2->data) {

/*                store pointer to the node next to 'ptr2'*/

                struct Node* next = ptr2->next;

/*                delete node pointed to by 'ptr2'*/

                deleteNode(head_ref, ptr2);

/*                update 'ptr2'*/

                ptr2 = next;
            }

/*            else simply move to the next node*/

            else
                ptr2 = ptr2->next;
        }
    }
}

/*Function to insert a node at the beginning
of the Doubly Linked List*/

void push(struct Node** head_ref, int new_data)
{

/*    allocate node*/

    struct Node* new_node =
        (struct Node*)malloc(sizeof(struct Node));

/*    put in the data*/

    new_node->data = new_data;

/*    since we are adding at the beginning,
    prev is always NULL*/

    new_node->prev = NULL;

/*    link the old list off the new node*/

    new_node->next = (*head_ref);

/*    change prev of head node to new node*/

    if ((*head_ref) != NULL)
        (*head_ref)->prev = new_node;

/*    move the head to point to the new node*/

    (*head_ref) = new_node;
}

/*Function to print nodes in a given doubly
linked list*/

void printList(struct Node* head)
{

/*    if list is empty*/

    if (head == NULL)
        cout << "Doubly Linked list empty";
    while (head != NULL) {
        cout << head->data << " ";
        head = head->next;
    }
}

