/* C++ program to insetail nodes in doubly
linked list such that list remains in
ascending order on printing from left
to right */

#include <bits/stdc++.h>
using namespace std;

/*A linked list node*/

class Node
{
    public:
    Node *prev;
    int info;
    Node *next;
};

/*Function to insetail new node*/

void nodeInsetail(Node **head,
                Node **tail,
                int key)
{
    Node *p = new Node();
    p->info = key;
    p->next = NULL;

/*    If first node to be insetailed in doubly
    linked list*/

    if ((*head) == NULL)
    {
        (*head) = p;
        (*tail) = p;
        (*head)->prev = NULL;
        return;
    }

/*    If node to be insetailed has value less
    than first node*/

    if ((p->info) < ((*head)->info))
    {
        p->prev = NULL;
        (*head)->prev = p;
        p->next = (*head);
        (*head) = p;
        return;
    }

/*    If node to be insetailed has value more
    than last node*/

    if ((p->info) > ((*tail)->info))
    {
        p->prev = (*tail);
        (*tail)->next = p;
        (*tail) = p;
        return;
    }

/*    Find the node before which we need to
    insert p.*/

    Node *temp = (*head)->next;
    while ((temp->info) < (p->info))
        temp = temp->next;

/*    Insert new node before temp*/

    (temp->prev)->next = p;
    p->prev = temp->prev;
    temp->prev = p;
    p->next = temp;
}

/*Function to print nodes in from left to right*/

void printList(Node *temp)
{
    while (temp != NULL)
    {
        cout << temp->info << " ";
        temp = temp->next;
    }
}

/*Driver program to test above functions*/

int main()
{
    Node *left = NULL, *right = NULL;
    nodeInsetail(&left, &right, 30);
    nodeInsetail(&left, &right, 50);
    nodeInsetail(&left, &right, 90);
    nodeInsetail(&left, &right, 10);
    nodeInsetail(&left, &right, 40);
    nodeInsetail(&left, &right, 110);
    nodeInsetail(&left, &right, 60);
    nodeInsetail(&left, &right, 95);
    nodeInsetail(&left, &right, 23);
    cout<<"Doubly linked list on printing"
        " from left to right\n";
    printList(left);
    return 0;
}

/*C++ program to illustrate inserting a Node in
a Cicular Doubly Linked list in begging, end
and middle*/

#include <bits/stdc++.h>
using namespace std;

/*Structure of a Node*/

struct Node
{
    int data;
    struct Node *next;
    struct Node *prev;
};

/*Function to insert at the end*/

void insertEnd(struct Node** start, int value)
{

/*    If the list is empty, create a single node
    circular and doubly list*/

    if (*start == NULL)
    {
        struct Node* new_node = new Node;
        new_node->data = value;
        new_node->next = new_node->prev = new_node;
        *start = new_node;
        return;
    }

/*    If list is not empty*/

/* Find last node */

    Node *last = (*start)->prev;

/*    Create Node dynamically*/

    struct Node* new_node = new Node;
    new_node->data = value;

/*    Start is going to be next of new_node*/

    new_node->next = *start;

/*    Make new node previous of start*/

    (*start)->prev = new_node;

/*    Make last preivous of new node*/

    new_node->prev = last;

/*    Make new node next of old last*/

    last->next = new_node;
}

/*Function to insert Node at the beginning
of the List,*/

void insertBegin(struct Node** start, int value)
{

/*    Pointer points to last Node*/

    struct Node *last = (*start)->prev;
    struct Node* new_node = new Node;

/*Inserting the data*/

new_node->data = value;

/*    setting up previous and next of new node*/

    new_node->next = *start;
    new_node->prev = last;

/*    Update next and previous pointers of start
    and last.*/

    last->next = (*start)->prev = new_node;

/*    Update start pointer*/

    *start = new_node;
}

/*Function to insert node with value as value1.
The new node is inserted after the node with
with value2*/

void insertAfter(struct Node** start, int value1,
                                      int value2)
{
    struct Node* new_node = new Node;

/*Inserting the data*/

new_node->data = value1;

/*    Find node having value2 and next node of it*/

    struct Node *temp = *start;
    while (temp->data != value2)
        temp = temp->next;
    struct Node *next = temp->next;

/*    insert new_node between temp and next.*/

    temp->next = new_node;
    new_node->prev = temp;
    new_node->next = next;
    next->prev = new_node;
}
void display(struct Node* start)
{
    struct Node *temp = start;
    printf("\nTraversal in forward direction \n");
    while (temp->next != start)
    {
        printf("%d ", temp->data);
        temp = temp->next;
    }
    printf("%d ", temp->data);
    printf("\nTraversal in reverse direction \n");
    Node *last = start->prev;
    temp = last;
    while (temp->prev != last)
    {
        printf("%d ", temp->data);
        temp = temp->prev;
    }
    printf("%d ", temp->data);
}

/* Driver program to test above functions*/

int main()
{

/* Start with the empty list */

    struct Node* start = NULL;

/*    Insert 5. So linked list becomes 5->NULL*/

    insertEnd(&start, 5);

/*    Insert 4 at the beginning. So linked
    list becomes 4->5*/

    insertBegin(&start, 4);

/*    Insert 7 at the end. So linked list
    becomes 4->5->7*/

    insertEnd(&start, 7);

/*    Insert 8 at the end. So linked list
    becomes 4->5->7->8*/

    insertEnd(&start, 8);

/*    Insert 6, after 5. So linked list
    becomes 4->5->6->7->8*/

    insertAfter(&start, 6, 5);
    printf("Created circular doubly linked list is: ");
    display(start);
    return 0;
}

/*C program to print reverse of list*/

#include <stdio.h>
#include <stdlib.h>

/* Link list node */

struct Node {
    int data;
    struct Node* next;
};

/* Function to reverse the linked list */

void printReverse(struct Node** head_ref, int n)
{
    int j = 0;
    struct Node* current = *head_ref;
    while (current != NULL) {

/*        For each node, print proper number
        of spaces before printing it*/

        for (int i = 0; i < 2 * (n - j); i++)
            printf(" ");

/*        use of carriage return to move back
        and print.*/

        printf("%d\r", current->data);
        current = current->next;
        j++;
    }
}

/* Function to push a node */

void push(struct Node** head_ref, int new_data)
{
    struct Node* new_node = 
          (struct Node*)malloc(sizeof(struct Node));
    new_node->data = new_data;
    new_node->next = (*head_ref);
    (*head_ref) = new_node;
}

/* Function to print linked list and find its
   length */

int printList(struct Node* head)
{

/*    i for finding length of list*/

    int i = 0;
    struct Node* temp = head;
    while (temp != NULL) {
        printf("%d  ", temp->data);
        temp = temp->next;
        i++;
    }
    return i;
}

