/*C++ program to find sqrt(n)'th node 
of a linked list */

#include <bits/stdc++.h>
using namespace std;

/*Linked list node */

class Node 
{ 
    public:
    int data; 
    Node* next; 
};

/*Function to get the sqrt(n)th 
node of a linked list */

int printsqrtn(Node* head) 
{ 
    Node* sqrtn = NULL; 
    int i = 1, j = 1;

/*    Traverse the list */

    while (head!=NULL) 
    {

/*        check if j = sqrt(i) */

        if (i == j*j) 
        {

/*            for first node */

            if (sqrtn == NULL) 
                sqrtn = head; 
            else
                sqrtn = sqrtn->next;

/*            increment j if j = sqrt(i) */

            j++; 
        } 
        i++; 
        head=head->next; 
    }

/*    return node's data */

    return sqrtn->data; 
} 
void print(Node* head) 
{ 
    while (head != NULL) 
    { 
        cout << head->data << " "; 
        head = head->next; 
    } 
    cout<<endl; 
}

