        printf("%d\n", answer->data);
    else
        printf("null\n");
    return 0;
}

/* C++ program to arrange consonants and
   vowels nodes in a linked list */

#include<bits/stdc++.h>
using namespace std;

/* A linked list node */

struct Node
{
    char data;
    struct Node *next;
};

/* Function to add new node to the List */

Node *newNode(char key)
{
    Node *temp = new Node;
    temp->data = key;
    temp->next = NULL;
    return temp;
}

/*utility function to print linked list*/

void printlist(Node *head)
{
    if (! head)
    {
        cout << "Empty List\n";
        return;
    }
    while (head != NULL)
    {
        cout << head->data << " ";
        if (head->next)
           cout << "-> ";
        head = head->next;
    }
    cout << endl;
}

/*utility function for checking vowel*/

bool isVowel(char x)
{
    return (x == 'a' || x == 'e' || x == 'i' ||
            x == 'o' || x == 'u');
}

/* function to arrange consonants and
   vowels nodes */

Node *arrange(Node *head)
{
    Node *newHead = head;

/*    for keep track of vowel*/

    Node *latestVowel;
    Node *curr = head;

/*    list is empty*/

    if (head == NULL)
        return NULL;

/*    We need to discover the first vowel
    in the list. It is going to be the
    returned head, and also the initial
    latestVowel.*/

    if (isVowel(head->data))

/*        first element is a vowel. It will
        also be the new head and the initial
        latestVowel;*/

        latestVowel = head;
    else
    {

/*        First element is not a vowel. Iterate
        through the list until we find a vowel.
        Note that curr points to the element
        *before* the element with the vowel.*/

        while (curr->next != NULL &&
               !isVowel(curr->next->data))
            curr = curr->next;

/*        This is an edge case where there are
        only consonants in the list.*/

        if (curr->next == NULL)
            return head;

/*        Set the initial latestVowel and the
        new head to the vowel item that we found.
        Relink the chain of consonants after
        that vowel item:
        old_head_consonant->consonant1->consonant2->
        vowel->rest_of_list becomes
        vowel->old_head_consonant->consonant1->
        consonant2->rest_of_list*/

        latestVowel = newHead = curr->next;
        curr->next = curr->next->next;
        latestVowel->next = head;
    }

/*    Now traverse the list. Curr is always the item
    *before* the one we are checking, so that we
    can use it to re-link.*/

    while (curr != NULL && curr->next != NULL)
    {
        if (isVowel(curr->next->data))
        {

/*            The next discovered item is a vowel*/

            if (curr == latestVowel)
            {

/*                If it comes directly after the
                previous vowel, we don't need to
                move items around, just mark the
                new latestVowel and advance curr.*/

                latestVowel = curr = curr->next;
            }
            else
            {

/*                But if it comes after an intervening
                chain of consonants, we need to chain
                the newly discovered vowel right after
                the old vowel. Curr is not changed as
                after the re-linking it will have a
                new next, that has not been checked yet,
                and we always keep curr at one before
                the next to check.*/

                Node *temp = latestVowel->next;

/*                Chain in new vowel*/

                latestVowel->next = curr->next;

/*                Advance latestVowel*/

                latestVowel = latestVowel->next;

/*                Remove found vowel from previous place*/

                curr->next = curr->next->next;

/*                Re-link chain of consonants after latestVowel*/

                latestVowel->next = temp;
            }
        }
        else
        {

/*            No vowel in the next element, advance curr.*/

            curr = curr->next;
        }
    }
    return newHead;
}

/*Driver code*/

int main()
{
    Node *head = newNode('a');
    head->next = newNode('b');
    head->next->next = newNode('c');
    head->next->next->next = newNode('e');
    head->next->next->next->next = newNode('d');
    head->next->next->next->next->next = newNode('o');
    head->next->next->next->next->next->next = newNode('x');
    head->next->next->next->next->next->next->next = newNode('i');
    printf("Linked list before :\n");
    printlist(head);
    head = arrange(head);
    printf("Linked list after :\n");
    printlist(head);
    return 0;
}

/*C++ implementation to modify the contents of
the linked list*/

#include <bits/stdc++.h>
using namespace std;
void printList(struct Node*);

/* Linked list node */

struct Node
{
    int data;
    struct Node* next;
};

/* Function to insert a node at the beginning of
   the linked list */

void push(struct Node **head_ref, int new_data)
{

/* allocate node */

  struct Node* new_node =
            (struct Node*) malloc(sizeof(struct Node));

/* put in the data  */

  new_node->data = new_data;

/* link the old list at the end of the new node */

  new_node->next = *head_ref;

/* move the head to point to the new node */

  *head_ref = new_node;
}

/* Split the nodes of the given list
   into front and back halves,
   and return the two lists
   using the reference parameters.
   Uses the fast/slow pointer strategy. */

void frontAndBackSplit(struct Node *head,
               struct Node **front_ref, struct Node **back_ref)
{
    Node *slow, *fast;
    slow = head;
    fast = head->next;

/* Advance 'fast' two nodes, and
       advance 'slow' one node */

    while (fast != NULL)
    {
        fast = fast->next;
        if (fast != NULL)
        {
            slow = slow->next;
            fast = fast->next;
        }
    }

/* 'slow' is before the midpoint in the list,
        so split it in two at that point. */

    *front_ref = head;
    *back_ref = slow->next;
    slow->next = NULL;
}

/* Function to reverse the linked list */

void reverseList(struct Node **head_ref)
{
    struct Node *current, *prev, *next;
    current = *head_ref;
    prev = NULL;
    while (current != NULL)
    {
        next = current->next;
        current->next = prev;
        prev = current;
        current = next;
    }   
    *head_ref = prev;
}

/*perfrom the required subtraction operation on
the 1st half of the linked list*/

void modifyTheContentsOf1stHalf(struct Node *front,
                                struct Node *back)
{

/*    traversing both the lists simultaneously*/

    while (back != NULL)
    {

/*        subtraction operation and node data
        modification*/

        front->data = front->data - back->data;
        front = front->next;
        back = back->next;
    }
}

/*function to concatenate the 2nd(back) list at the end of
the 1st(front) list and returns the head of the new list*/

struct Node* concatFrontAndBackList(struct Node *front,
                                    struct Node *back)
{
    struct Node *head = front;
    while (front->next != NULL)
        front = front->next;   
    front->next    = back;
    return head;
}

/*function to modify the contents of the linked list*/

struct Node* modifyTheList(struct Node *head)
{

/*    if list is empty or contains only single node*/

    if (!head || head->next == NULL)
        return head;
    struct Node *front, *back;

/*    split the list into two halves
    front and back lists*/

    frontAndBackSplit(head, &front, &back);

/*    reverse the 2nd(back) list*/

    reverseList(&back);

/*    modify the contents of 1st half   */

    modifyTheContentsOf1stHalf(front, back);

/*    agains reverse the 2nd(back) list*/

    reverseList(&back);

/*    concatenating the 2nd list back to the
    end of the 1st list*/

    head = concatFrontAndBackList(front, back);

/*    pointer to the modified list*/

    return head;
}

/*function to print the linked list*/

void printList(struct Node *head)
{
    if (!head)
        return;
    while (head->next != NULL)
    {
        cout << head->data << " -> ";
        head = head->next;
    }
    cout << head->data << endl;
}

/*Driver program to test above*/

int main()
{
    struct Node *head = NULL;

/*    creating the linked list*/

    push(&head, 10);
    push(&head, 7);
    push(&head, 12);
    push(&head, 8);
    push(&head, 9);
    push(&head, 2);

/*    modify the linked list*/

    head = modifyTheList(head);

/*    print the modified linked list*/

    cout << "Modified List:" << endl;
    printList(head);
    return 0;
}

/*C++ implementation to modify the
contents of the linked list*/

#include <bits/stdc++.h>
using namespace std;
void printList(struct Node*);

/*Linked list node*/

struct Node
{
    int data;
    struct Node* next;
};

/*Function to insert a node at the
beginning of the linked list*/

void push(struct Node **head_ref, int new_data)
{

/*allocate node*/

struct Node* new_node =
            (struct Node*) malloc(sizeof(struct Node));

/*put in the data*/

new_node->data = new_data;

/*link the old list at the end of the new node*/

new_node->next = *head_ref;

/*move the head to point to the new node*/

*head_ref = new_node;
}

/*function to print the linked list*/

void printList(struct Node *head)
{
    if (!head)
        return;
    while (head->next != NULL)
    {
        cout << head->data << " -> ";
        head = head->next;
    }
    cout << head->data << endl;
}

/*Function to middle node of list.*/

Node* find_mid(Node *head)
{
    Node *temp = head, *slow = head, *fast = head ;
    while(fast && fast->next)
    {

/*    Advance 'fast' two nodes, and
    advance 'slow' one node*/

    slow = slow->next ;
    fast = fast->next->next ;
    }

/*    If number of nodes are odd then update slow
    by slow->next;*/

    if(fast)
    slow = slow->next ;
return slow ;
}

/*function to modify the contents of the linked list.*/

void modifyTheList(struct Node *head, struct Node *slow)
{

/*Create Stack.*/

stack <int> s;
Node *temp = head ;
while(slow)
{
    s.push( slow->data ) ;
    slow = slow->next ;
}

/*Traverse the list by using temp until stack is empty.*/

while( !s.empty() )
{
    temp->data = temp->data - s.top() ;
    temp = temp->next ;
    s.pop() ;
}
}

/*Driver program to test above*/

int main()
{
    struct Node *head = NULL, *mid ;

/*    creating the linked list*/

    push(&head, 10);
    push(&head, 7);
    push(&head, 12);
    push(&head, 8);
    push(&head, 9);
    push(&head, 2);

/*    Call Function to Find the starting point of second half of list.*/

    mid = find_mid(head) ;

/*    Call function to modify the contents of the linked list.*/

    modifyTheList( head, mid);

/*    print the modified linked list*/

    cout << "Modified List:" << endl;
    printList(head);
    return 0;
}

/*C++ implementation to construct a BST
from its level order traversal*/

#include <bits/stdc++.h>
using namespace std;

/*node of a BST*/

struct Node
{
    int data;
    Node *left, *right;
};

/*function to get a new node*/

Node* getNode(int data)
{

/*    Allocate memory*/

    Node *newNode =
        (Node*)malloc(sizeof(Node));

/*    put in the data    */

    newNode->data = data;
    newNode->left = newNode->right = NULL;    
    return newNode;
}

/*function to construct a BST from
its level order traversal*/

Node *LevelOrder(Node *root , int data) 
{
     if(root==NULL){    
        root = getNode(data);
        return root;
     }
     if(data <= root->data)
     root->left = LevelOrder(root->left, data);
     else
     root->right = LevelOrder(root->right, data);
     return root;     
}
Node* constructBst(int arr[], int n)
{
    if(n==0)return NULL;
    Node *root =NULL;
    for(int i=0;i<n;i++)
    root = LevelOrder(root , arr[i]);
    return root;
}

/*function to print the inorder traversal*/

void inorderTraversal(Node* root)
{
    if (!root)
        return;
    inorderTraversal(root->left);
    cout << root->data << " ";
    inorderTraversal(root->right);    
}

/*Driver program to test above*/

int main()
{
    int arr[] = {7, 4, 12, 3, 6, 8, 1, 5, 10};
    int n = sizeof(arr) / sizeof(arr[0]);
    Node *root = constructBst(arr, n);
    cout << "Inorder Traversal: ";
    inorderTraversal(root);
    return 0;    
}

/*C++ program to Check given array
can represent BST or not*/

#include <bits/stdc++.h>
using namespace std;

/*structure for Binary Node*/

struct Node {
    int key;
    struct Node *right, *left;
};
Node* newNode(int num)
{
    Node* temp = new Node;
    temp->key = num;
    temp->left = NULL;
    temp->right = NULL;
    return temp;
}

/*To create a Tree with n levels. We always
insert new node to left if it is less than
previous value.*/

Node* createNLevelTree(int arr[], int n)
{
    Node* root = newNode(arr[0]);
    Node* temp = root;
    for (int i = 1; i < n; i++) {
        if (temp->key > arr[i]) {
            temp->left = newNode(arr[i]);
            temp = temp->left;
        }
        else {
            temp->right = newNode(arr[i]);
            temp = temp->right;
        }
    }
    return root;
}

/*Please refer below post for details of this
function.
www.geeksforgeeks.org/a-program-to-check-if-a-binary-tree-is-bst-or-not/
https:*/

bool isBST(Node* root, int min, int max)
{
    if (root == NULL)
        return true;
    if (root->key < min || root->key > max)
        return false;

/*    Allow only distinct values*/

    return (isBST(root->left, min,
                  (root->key) - 1)
            && isBST(root->right,
                     (root->key) + 1, max));
}

/*Returns tree if given array of size n can
represent a BST of n levels.*/

bool canRepresentNLevelBST(int arr[], int n)
{
    Node* root = createNLevelTree(arr, n);
    return isBST(root, INT_MIN, INT_MAX);
}

/*Driver code*/

int main()
{
    int arr[] = { 512, 330, 78, 11, 8 };
    int n = sizeof(arr) / sizeof(arr[0]);
    if (canRepresentNLevelBST(arr, n))
        cout << "Yes";
    else
        cout << "No";
    return 0;
}

/*C++ program to convert a left unbalanced BST to
a balanced BST*/

#include <bits/stdc++.h>
using namespace std;

/* A binary tree node has data, pointer to left child
   and a pointer to right child */
struct Node
{
    int data;
    Node* left,  *right;
};

/* This function traverse the skewed binary tree and
   stores its nodes pointers in vector nodes[] */

void storeBSTNodes(Node* root, vector<Node*> &nodes)
{

/*    Base case*/

    if (root==NULL)
        return;

/*    Store nodes in Inorder (which is sorted
    order for BST)*/

    storeBSTNodes(root->left, nodes);
    nodes.push_back(root);
    storeBSTNodes(root->right, nodes);
}

/* Recursive function to construct binary tree */

Node* buildTreeUtil(vector<Node*> &nodes, int start,
                   int end)
{

/*    base case*/

    if (start > end)
        return NULL;

/* Get the middle element and make it root */

    int mid = (start + end)/2;
    Node *root = nodes[mid];

/* Using index in Inorder traversal, construct
       left and right subtress */

    root->left  = buildTreeUtil(nodes, start, mid-1);
    root->right = buildTreeUtil(nodes, mid+1, end);
    return root;
}

/*This functions converts an unbalanced BST to
a balanced BST*/

Node* buildTree(Node* root)
{

/*    Store nodes of given BST in sorted order*/

    vector<Node *> nodes;
    storeBSTNodes(root, nodes);

/*    Constucts BST from nodes[]*/

    int n = nodes.size();
    return buildTreeUtil(nodes, 0, n-1);
}

/*Utility function to create a new node*/
Node* newNode(int data)
{
    Node* node = new Node;
    node->data = data;
    node->left = node->right = NULL;
    return (node);
}

/* Function to do preorder traversal of tree */

void preOrder(Node* node)
{
    if (node == NULL)
        return;
    printf("%d ", node->data);
    preOrder(node->left);
    preOrder(node->right);
}

/*Driver program*/

int main()
{

/* Constructed skewed binary tree is
                10
               /
              8
             /
            7
           /
          6
         /
        5   */

    Node* root = newNode(10);
    root->left = newNode(8);
    root->left->left = newNode(7);
    root->left->left->left = newNode(6);
    root->left->left->left->left = newNode(5);
    root = buildTree(root);
    printf("Preorder traversal of balanced "
            "BST is : \n");
    preOrder(root);
    return 0;
}

/*C++ program to find minimum value node in binary search Tree. */

#include <bits/stdc++.h> 
using namespace std;

/* A binary tree node has data, pointer to left child 
and a pointer to right child */

struct node 
{ 
    int data; 
    struct node* left; 
    struct node* right; 
};

/* Helper function that allocates a new node 
with the given data and NULL left and right 
pointers. */

struct node* newNode(int data) 
{ 
struct node* node = (struct node*) 
                    malloc(sizeof(struct node)); 
node->data = data; 
node->left = NULL; 
node->right = NULL; 
return(node); 
}

/* Give a binary search tree and a number, 
inserts a new node with the given number in 
the correct place in the tree. Returns the new 
root pointer which the caller should then use 
(the standard trick to avoid using reference 
parameters). */

struct node* insert(struct node* node, int data) 
{

/* 1. If the tree is empty, return a new, 
    single node */

if (node == NULL) 
    return(newNode(data)); 
else
{

/* 2. Otherwise, recur down the tree */

    if (data <= node->data) 
        node->left = insert(node->left, data); 
    else
        node->right = insert(node->right, data);

/* return the (unchanged) node pointer */

    return node; 
} 
}

/* Given a non-empty binary search tree, 
return the minimum data value found in that 
tree. Note that the entire tree does not need 
to be searched. */

int minValue(struct node* node) 
{ 
struct node* current = node;

/* loop down to find the leftmost leaf */

while (current->left != NULL) 
{ 
    current = current->left; 
} 
return(current->data); 
}

/* Driver Code*/

int main() 
{ 
struct node* root = NULL; 
root = insert(root, 4); 
insert(root, 2); 
insert(root, 1); 
insert(root, 3); 
insert(root, 6); 
insert(root, 5); 
cout << "\n Minimum value in BST is " << minValue(root); 
getchar(); 
return 0; 
}

/*C++ implementation to check if the given array 
can represent Level Order Traversal of Binary 
Search Tree*/

#include <bits/stdc++.h>
using namespace std;

/*to store details of a node like
node's data, 'min' and 'max' to obtain the
range of values where node's left and 
right child's should lie*/

struct NodeDetails
{
    int data;
    int min, max;
};

/*function to check if the given array 
can represent Level Order Traversal 
of Binary Search Tree*/

bool levelOrderIsOfBST(int arr[], int n)
{

/*    if tree is empty*/

    if (n == 0)
        return true;

/*    queue to store NodeDetails*/

    queue<NodeDetails> q;

/*    index variable to access array elements*/

    int i=0;

/*    node details for the 
    root of the BST*/

    NodeDetails newNode;
    newNode.data = arr[i++];
    newNode.min = INT_MIN;
    newNode.max = INT_MAX;
    q.push(newNode);

/*    until there are no more elements 
    in arr[] or queue is not empty*/

    while (i != n && !q.empty())        
    {

/*        extracting NodeDetails of a
        node from the queue*/

        NodeDetails temp = q.front();
        q.pop();

/*        check whether there are more elements 
        in the arr[] and arr[i] can be left child 
        of 'temp.data' or not */

        if (i < n && (arr[i] < temp.data && 
                     arr[i] > temp.min))
        {

/*            Create NodeDetails for newNode 
and add it to the queue*/

            newNode.data = arr[i++];
            newNode.min = temp.min;
            newNode.max = temp.data;
            q.push(newNode);                
        }

/*        check whether there are more elements 
        in the arr[] and arr[i] can be right child 
        of 'temp.data' or not */

        if (i < n && (arr[i] > temp.data && 
                      arr[i] < temp.max))
        {

/*            Create NodeDetails for newNode 
and add it to the queue*/

            newNode.data = arr[i++];
            newNode.min = temp.data;
            newNode.max = temp.max;
            q.push(newNode);            
        }        
    }

/*    given array represents level
    order traversal of BST*/

    if (i == n)
        return true;

/*    given array do not represent 
    level order traversal of BST    */

    return false;        
}

/*Driver program to test above*/

int main()
{
    int arr[] = {7, 4, 12, 3, 6, 8, 1, 5, 10};    
    int n = sizeof(arr) / sizeof(arr[0]);    
    if (levelOrderIsOfBST(arr, n))
        cout << "Yes";
    else
        cout << "No";        
    return 0;    
}

/*A recursive CPP program to find
LCA of two nodes n1 and n2. */

#include <bits/stdc++.h>
using namespace std;
class node 
{ 
    public:
    int data; 
    node* left, *right; 
};

/* Function to find LCA of n1 and n2. 
The function assumes that both 
n1 and n2 are present in BST */

node *lca(node* root, int n1, int n2) 
{ 
    if (root == NULL) return NULL;

/*    If both n1 and n2 are smaller
    than root, then LCA lies in left */

    if (root->data > n1 && root->data > n2) 
        return lca(root->left, n1, n2);

/*    If both n1 and n2 are greater than 
    root, then LCA lies in right */

    if (root->data < n1 && root->data < n2) 
        return lca(root->right, n1, n2); 
    return root; 
}

/* Helper function that allocates 
a new node with the given data.*/

node* newNode(int data) 
{ 
    node* Node = new node();
    Node->data = data; 
    Node->left = Node->right = NULL; 
    return(Node); 
}

