    root->left->left = new Node(1);
    root->left->right = new Node(4);
    if (isBST(root))
        cout << "Is BST";
    else
        cout << "Not a BST";
    return 0;
}

/*A simple inorder traversal based C++ program
to find k-th smallest element in a BST.*/

#include <iostream>
using namespace std;

/*A BST node*/

struct Node {
    int data;
    Node *left, *right;
    Node(int x)
    {
        data = x;
        left = right = NULL;
    }
};

/*Recursive function to insert an key into BST*/

Node* insert(Node* root, int x)
{
    if (root == NULL)
        return new Node(x);
    if (x < root->data)
        root->left = insert(root->left, x);
    else if (x > root->data)
        root->right = insert(root->right, x);
    return root;
}

/*Function to find k'th largest element in BST
Here count denotes the number of nodes processed so far*/

Node* kthSmallest(Node* root, int& k)
{

/*    base case*/

    if (root == NULL)
        return NULL;

/*    search in left subtree*/

    Node* left = kthSmallest(root->left, k);

/*    if k'th smallest is found in left subtree, return it*/

    if (left != NULL)
        return left;

/*    if current element is k'th smallest, return it*/

    k--;
    if (k == 0)
        return root;

/*    else search in right subtree*/

    return kthSmallest(root->right, k);
}

/*Function to find k'th largest element in BST*/

void printKthSmallest(Node* root, int k)
{

/*    maintain index to count number of nodes processed so far*/

    int count = 0;
    Node* res = kthSmallest(root, k);
    if (res == NULL)
        cout << "There are less than k nodes in the BST";
    else
        cout << "K-th Smallest Element is " << res->data;
}

/*main function*/

int main()
{
    Node* root = NULL;
    int keys[] = { 20, 8, 22, 4, 12, 10, 14 };
    for (int x : keys)
        root = insert(root, x);
    int k = 3;
    printKthSmallest(root, k);
    return 0;
}

/*A simple inorder traversal based C++ program
to find k-th smallest element in a BST.*/

#include <iostream>
using namespace std;

/*A BST node*/

struct Node {
    int data;
    Node *left, *right;
    int lCount;
    Node(int x)
    {
        data = x;
        left = right = NULL;
        lCount = 0;
    }
};

/*Recursive function to insert an key into BST*/

Node* insert(Node* root, int x)
{
    if (root == NULL)
        return new Node(x);

/*    If a node is inserted in left subtree, then
    lCount of this node is increased. For simplicity,
    we are assuming that all keys (tried to be
    inserted) are distinct.*/

    if (x < root->data) {
        root->left = insert(root->left, x);
        root->lCount++;
    }
    else if (x > root->data)
        root->right = insert(root->right, x);
    return root;
}

/*Function to find k'th largest element in BST
Here count denotes the number of nodes processed so far*/

Node* kthSmallest(Node* root, int k)
{

/*    base case*/

    if (root == NULL)
        return NULL;
    int count = root->lCount + 1;
    if (count == k)
        return root;
    if (count > k)
        return kthSmallest(root->left, k);

/*    else search in right subtree*/

    return kthSmallest(root->right, k - count);
}

/*main function*/

int main()
{
    Node* root = NULL;
    int keys[] = { 20, 8, 22, 4, 12, 10, 14 };
    for (int x : keys)
        root = insert(root, x);
    int k = 4;
    Node* res = kthSmallest(root, k);
    if (res == NULL)
        cout << "There are less than k nodes in the BST";
    else
        cout << "K-th Smallest Element is " << res->data;
    return 0;
}

/*CPP code for finding K-th largest Node using O(1)
extra memory and reverse Morris traversal.*/

#include <bits/stdc++.h>
using namespace std;

/*Node structure*/

struct Node {
    int data;
    struct Node *left, *right;
};

/*helper function to create a new Node*/

Node* newNode(int data)
{
    Node* temp = new Node;
    temp->data = data;
    temp->right = temp->left = NULL;
    return temp;
}
Node* KthLargestUsingMorrisTraversal(Node* root, int k)
{
    Node* curr = root;
    Node* Klargest = NULL;

/*    count variable to keep count of visited Nodes*/

    int count = 0;
    while (curr != NULL) {

/*        if right child is NULL*/

        if (curr->right == NULL) {

/*            first increment count and check if count = k*/

            if (++count == k)
                Klargest = curr;

/*            otherwise move to the left child*/

            curr = curr->left;
        }
        else {

/*            find inorder successor of current Node*/

            Node* succ = curr->right;
            while (succ->left != NULL && succ->left != curr)
                succ = succ->left;
            if (succ->left == NULL) {

/*                set left child of successor to the
                current Node*/

                succ->left = curr;

/*                move current to its right*/

                curr = curr->right;
            }

/*            restoring the tree back to original binary
              search tree removing threaded links*/

            else {
                succ->left = NULL;
                if (++count == k)
                    Klargest = curr;

/*                move current to its left child*/

                curr = curr->left;
            }
        }
    }
    return Klargest;
}
int main()
{

