/*CPP code for inorder successor
and predecessor of tree*/

#include<iostream>
#include<stdlib.h>
using namespace std;
struct Node
{
    int data;
    Node* left,*right;
};

/*Function to return data*/

Node* getnode(int info)
{
    Node* p = (Node*)malloc(sizeof(Node));
    p->data = info;
    p->right = NULL;
    p->left = NULL;
    return p;
}

/*
since inorder traversal results in
ascending order visit to node , we
can store the values of the largest
no which is smaller than a (predecessor)
and smallest no which is large than
a (successor) using inorder traversal
*/

void find_p_s(Node* root,int a,
              Node** p, Node** q)
{

/*    If root is null return*/

    if(!root)
        return ;

/*    traverse the left subtree   */

    find_p_s(root->left, a, p, q);

/*    root data is greater than a*/

    if(root&&root->data > a)
    {

/*        q stores the node whose data is greater
        than a and is smaller than the previously
        stored data in *q which is successor*/

        if((!*q) || (*q) && (*q)->data > root->data)
                *q = root;
    }

/*    if the root data is smaller than
    store it in p which is predecessor*/

    else if(root && root->data < a)
    {
        *p = root;
    }

/*    traverse the right subtree*/

    find_p_s(root->right, a, p, q);
}

/*Driver code*/

int main()
{
    Node* root1 = getnode(50);
    root1->left = getnode(20);
    root1->right = getnode(60);
    root1->left->left = getnode(10);
    root1->left->right = getnode(30);
    root1->right->left = getnode(55);
    root1->right->right = getnode(70);
    Node* p = NULL, *q = NULL;
    find_p_s(root1, 55, &p, &q);
    if(p)
        cout << p->data;
    if(q)
        cout << " " << q->data;
    return 0;
}

/*C++ program to find predecessor
and successor in a BST*/

#include <bits/stdc++.h>
using namespace std;

/*BST Node*/

struct Node {
    int key;
    struct Node *left, *right;
};

/*Function that finds predecessor and successor of key in BST.*/

void findPreSuc(Node* root, Node*& pre, Node*& suc, int key)
{
    if (root == NULL)
        return;

/*    Search for given key in BST.*/

    while (root != NULL) {

/*        If root is given key.*/

        if (root->key == key) {

/*            the minimum value in right subtree
            is predecessor.*/

            if (root->right) {
                suc = root->right;
                while (suc->left)
                    suc = suc->left;
            }

/*            the maximum value in left subtree
            is successor.*/

            if (root->left) {
                pre = root->left;
                while (pre->right)
                    pre = pre->right;
            }
            return;
        }

/*        If key is greater than root, then
        key lies in right subtree. Root
        could be predecessor if left
        subtree of key is null.*/

        else if (root->key < key) {
            pre = root;
            root = root->right;
        }

/*        If key is smaller than root, then
        key lies in left subtree. Root
        could be successor if right
        subtree of key is null.*/

        else {
            suc = root;
            root = root->left;
        }
    }
}

/*A utility function to create a new BST node*/

Node* newNode(int item)
{
    Node* temp = new Node;
    temp->key = item;
    temp->left = temp->right = NULL;
    return temp;
}

/*A utility function to insert
a new node with given key in BST*/

Node* insert(Node* node, int key)
{
    if (node == NULL)
        return newNode(key);
    if (key < node->key)
        node->left = insert(node->left, key);
    else
        node->right = insert(node->right, key);
    return node;
}

/*Driver program to test above function*/

int main()
{

/*Key to be searched in BST*/

int key = 65;

/* Let us create following BST
                 50
                /  \
               /    \
              30     70
             / \     / \
            /   \   /   \
           20   40 60   80
*/

    Node* root = NULL;
    root = insert(root, 50);
    insert(root, 30);
    insert(root, 20);
    insert(root, 40);
    insert(root, 70);
    insert(root, 60);
    insert(root, 80);
    Node *pre = NULL, *suc = NULL;
    findPreSuc(root, pre, suc, key);
    if (pre != NULL)
        cout << "Predecessor is " << pre->key << endl;
    else
        cout << "-1";
    if (suc != NULL)
        cout << "Successor is " << suc->key;
    else
        cout << "-1";
    return 0;
}

/*A C++ program to check if there
is a triplet with sum equal to 0 in
a given BST*/

#include <bits/stdc++.h>
using namespace std;

/*A BST node has key, and left and right pointers*/

class node
{
    public:
    int key;
    node *left;
    node *right;
};

/*A function to convert given BST to Doubly
Linked List. left pointer is used
as previous pointer and right pointer
is used as next pointer. The function
sets *head to point to first and *tail
to point to last node of converted DLL*/

void convertBSTtoDLL(node* root, node** head, node** tail)
{

/*    Base case*/

    if (root == NULL)
        return;

/*    First convert the left subtree*/

    if (root->left)
        convertBSTtoDLL(root->left, head, tail);

/*    Then change left of current root
    as last node of left subtree*/

    root->left = *tail;

/*    If tail is not NULL, then set right
    of tail as root, else current
    node is head*/

    if (*tail)
        (*tail)->right = root;
    else
        *head = root;

/*    Update tail*/

    *tail = root;

/*    Finally, convert right subtree*/

    if (root->right)
        convertBSTtoDLL(root->right, head, tail);
}

/*This function returns true if there
is pair in DLL with sum equal to given
sum. The algorithm is similar to hasArrayTwoCandidates()
tinyurl.com/dy6palr
in method 1 of http:*/

bool isPresentInDLL(node* head, node* tail, int sum)
{
    while (head != tail)
    {
        int curr = head->key + tail->key;
        if (curr == sum)
            return true;
        else if (curr > sum)
            tail = tail->left;
        else
            head = head->right;
    }
    return false;
}

/*The main function that returns
true if there is a 0 sum triplet in
BST otherwise returns false*/

bool isTripletPresent(node *root)
{

/*    Check if the given BST is empty*/

    if (root == NULL)
    return false;

/*    Convert given BST to doubly linked list. head and tail store the
    pointers to first and last nodes in DLLL*/

    node* head = NULL;
    node* tail = NULL;
    convertBSTtoDLL(root, &head, &tail);

/*    Now iterate through every node and
    find if there is a pair with sum
    equal to -1 * heaf->key where head is current node*/

    while ((head->right != tail) && (head->key < 0))
    {

/*        If there is a pair with sum
        equal to -1*head->key, then return
        true else move forward*/

        if (isPresentInDLL(head->right, tail, -1*head->key))
            return true;
        else
            head = head->right;
    }

/*    If we reach here, then
    there was no 0 sum triplet*/

    return false;
}

/*A utility function to create
a new BST node with key as given num*/

node* newNode(int num)
{
    node* temp = new node();
    temp->key = num;
    temp->left = temp->right = NULL;
    return temp;
}

/*A utility function to insert a given key to BST*/

node* insert(node* root, int key)
{
    if (root == NULL)
    return newNode(key);
    if (root->key > key)
        root->left = insert(root->left, key);
    else
        root->right = insert(root->right, key);
    return root;
}

/*Driver code*/

int main()
{
    node* root = NULL;
    root = insert(root, 6);
    root = insert(root, -13);
    root = insert(root, 14);
    root = insert(root, -8);
    root = insert(root, 15);
    root = insert(root, 13);
    root = insert(root, 7);
    if (isTripletPresent(root))
        cout << "Present";
    else
        cout << "Not Present";
    return 0;
}

/* In a balanced binary search tree
isPairPresent two element which sums to
a given value time O(n) space O(logn) */

#include <bits/stdc++.h>
using namespace std;
#define MAX_SIZE 100

/*A BST node*/

class node {
public:
    int val;
    node *left, *right;
};

/*Stack type*/

class Stack {
public:
    int size;
    int top;
    node** array;
};

/*A utility function to create a stack of given size*/

Stack* createStack(int size)
{
    Stack* stack = new Stack();
    stack->size = size;
    stack->top = -1;
    stack->array = new node*[(stack->size * sizeof(node*))];
    return stack;
}

/*BASIC OPERATIONS OF STACK*/

int isFull(Stack* stack)
{
    return stack->top - 1 == stack->size;
}
int isEmpty(Stack* stack)
{
    return stack->top == -1;
}
void push(Stack* stack, node* node)
{
    if (isFull(stack))
        return;
    stack->array[++stack->top] = node;
}
node* pop(Stack* stack)
{
    if (isEmpty(stack))
        return NULL;
    return stack->array[stack->top--];
}

/*Returns true if a pair with target
sum exists in BST, otherwise false*/

bool isPairPresent(node* root, int target)
{

/*    Create two stacks. s1 is used for
    normal inorder traversal and s2 is
    used for reverse inorder traversal*/

    Stack* s1 = createStack(MAX_SIZE);
    Stack* s2 = createStack(MAX_SIZE);

/*    Note the sizes of stacks is MAX_SIZE,
    we can find the tree size and fix stack size
    as O(Logn) for balanced trees like AVL and Red Black
    tree. We have used MAX_SIZE to keep the code simple
    done1, val1 and curr1 are used for
    normal inorder traversal using s1
    done2, val2 and curr2 are used for
    reverse inorder traversal using s2*/

    bool done1 = false, done2 = false;
    int val1 = 0, val2 = 0;
    node *curr1 = root, *curr2 = root;

/*    The loop will break when we either find a pair or one of the two
    traversals is complete*/

    while (1) {

/*        Find next node in normal Inorder
        traversal. See following post
www.geeksforgeeks.org/inorder-tree-traversal-without-recursion/
https:*/

        while (done1 == false) {
            if (curr1 != NULL) {
                push(s1, curr1);
                curr1 = curr1->left;
            }
            else {
                if (isEmpty(s1))
                    done1 = 1;
                else {
                    curr1 = pop(s1);
                    val1 = curr1->val;
                    curr1 = curr1->right;
                    done1 = 1;
                }
            }
        }

/*        Find next node in REVERSE Inorder traversal. The only
        difference between above and below loop is, in below loop
        right subtree is traversed before left subtree*/

        while (done2 == false) {
            if (curr2 != NULL) {
                push(s2, curr2);
                curr2 = curr2->right;
            }
            else {
                if (isEmpty(s2))
                    done2 = 1;
                else {
                    curr2 = pop(s2);
                    val2 = curr2->val;
                    curr2 = curr2->left;
                    done2 = 1;
                }
            }
        }

/*        If we find a pair, then print the pair and return. The first
        condition makes sure that two same values are not added*/

        if ((val1 != val2) && (val1 + val2) == target) {
            cout << "Pair Found: " << val1 << "+ " << val2 << " = " << target << endl;
            return true;
        }

/*        If sum of current values is smaller,
        then move to next node in
        normal inorder traversal*/

        else if ((val1 + val2) < target)
            done1 = false;

/*        If sum of current values is greater,
        then move to next node in
        reverse inorder traversal*/

        else if ((val1 + val2) > target)
            done2 = false;

/*        If any of the inorder traversals is
        over, then there is no pair
        so return false*/

        if (val1 >= val2)
            return false;
    }
}

/*A utility function to create BST node*/

node* NewNode(int val)
{
    node* tmp = new node();
    tmp->val = val;
    tmp->right = tmp->left = NULL;
    return tmp;
}

/*Driver program to test above functions*/

int main()
{

/*
                15
                / \
