/*C++ program to find maximum element in the path
between two Nodes of Binary Search Tree.*/

#include <bits/stdc++.h>
using namespace std;
struct Node
{
    struct Node *left, *right;
    int data;
};

/*Create and return a pointer of new Node.*/

Node *createNode(int x)
{
    Node *p = new Node;
    p -> data = x;
    p -> left = p -> right = NULL;
    return p;
}

/*Insert a new Node in Binary Search Tree.*/

void insertNode(struct Node *root, int x)
{
    Node *p = root, *q = NULL;
    while (p != NULL)
    {
        q = p;
        if (p -> data < x)
            p = p -> right;
        else
            p = p -> left;
    }
    if (q == NULL)
        p = createNode(x);
    else
    {
        if (q -> data < x)
            q -> right = createNode(x);
        else
            q -> left = createNode(x);
    }
}

/*Return the maximum element between a Node
and its given ancestor.*/

int maxelpath(Node *q, int x)
{
    Node *p = q;
    int mx = INT_MIN;

/*    Traversing the path between ansector and
    Node and finding maximum element.*/

    while (p -> data != x)
    {
        if (p -> data > x)
        {
            mx = max(mx, p -> data);
            p = p -> left;
        }
        else
        {
            mx = max(mx, p -> data);
            p = p -> right;
        }
    }
    return max(mx, x);
}

/*Return maximum element in the path between
two given Node of BST.*/

int maximumElement(struct Node *root, int x, int y)
{
    Node *p = root;

/*    Finding the LCA of Node x and Node y*/

    while ((x < p -> data && y < p -> data) ||
        (x > p -> data && y > p -> data))
    {

/*        Checking if both the Node lie on the
        left side of the parent p.*/

        if (x < p -> data && y < p -> data)
            p = p -> left;

/*        Checking if both the Node lie on the
        right side of the parent p.*/

        else if (x > p -> data && y > p -> data)
            p = p -> right;
    }

/*    Return the maximum of maximum elements occur
    in path from ancestor to both Node.*/

    return max(maxelpath(p, x), maxelpath(p, y));
}

/*Driver Code*/

int main()
{
    int arr[] = { 18, 36, 9, 6, 12, 10, 1, 8 };
    int a = 1, b = 10;
    int n = sizeof(arr) / sizeof(arr[0]);

/*    Creating the root of Binary Search Tree*/

    struct Node *root = createNode(arr[0]);

/*    Inserting Nodes in Binary Search Tree*/

    for (int i = 1; i < n; i++)
        insertNode(root, arr[i]);
    cout << maximumElement(root, a, b) << endl;
    return 0;
}

/*C++ program to find pairs with given sum such
that one element of pair exists in one BST and
other in other BST.*/

#include<bits/stdc++.h>
using namespace std;

/*A binary Tree node*/

struct Node
{
    int data;
    struct Node *left, *right;
};

/*A utility function to create a new BST node
with key as given num*/

struct Node* newNode(int num)
{
    struct Node* temp = new Node;
    temp->data = num;
    temp->left = temp->right = NULL;
    return temp;
}

/*A utility function to insert a given key to BST*/

Node* insert(Node* root, int key)
{
    if (root == NULL)
        return newNode(key);
    if (root->data > key)
        root->left = insert(root->left, key);
    else
        root->right = insert(root->right, key);
    return root;
}

/*store storeInorder traversal in auxiliary array*/

void storeInorder(Node *ptr, vector<int> &vect)
{
    if (ptr==NULL)
        return;
    storeInorder(ptr->left, vect);
    vect.push_back(ptr->data);
    storeInorder(ptr->right, vect);
}

/*Function to find pair for given sum in different bst
vect1[]  --> stores storeInorder traversal of first bst
vect2[]  --> stores storeInorder traversal of second bst*/

void pairSumUtil(vector<int> &vect1, vector<int> &vect2,
                                                int sum)
{

/*    Initialize two indexes to two different corners
    of two vectors.*/

    int left = 0;
    int right = vect2.size() - 1;

/*    find pair by moving two corners.*/

    while (left < vect1.size() && right >= 0)
    {

/*        If we found a pair*/

        if (vect1[left] + vect2[right] == sum)
        {
            cout << "(" << vect1[left] << ", "
                 << vect2[right] << "), ";
            left++;
            right--;
        }

/*        If sum is more, move to higher value in
        first vector.*/

        else if (vect1[left] + vect2[right] < sum)
            left++;

/*        If sum is less, move to lower value in
        second vector.*/

        else
            right--;
    }
}

/*Prints all pairs with given "sum" such that one
element of pair is in tree with root1 and other
node is in tree with root2.*/

void pairSum(Node *root1, Node *root2, int sum)
{

/*    Store inorder traversals of two BSTs in two
    vectors.*/

    vector<int> vect1, vect2;
    storeInorder(root1, vect1);
    storeInorder(root2, vect2);

/*    Now the problem reduces to finding a pair
    with given sum such that one element is in
    vect1 and other is in vect2.*/

    pairSumUtil(vect1, vect2, sum);
}

/*Driver program to run the case*/

int main()
{

/*    first BST*/

    struct Node* root1 = NULL;
    root1 = insert(root1, 8);
    root1 = insert(root1, 10);
    root1 = insert(root1, 3);
    root1 = insert(root1, 6);
    root1 = insert(root1, 1);
    root1 = insert(root1, 5);
    root1 = insert(root1, 7);
    root1 = insert(root1, 14);
    root1 = insert(root1, 13);

/*    second BST*/

    struct Node* root2 = NULL;
    root2 = insert(root2, 5);
    root2 = insert(root2, 18);
    root2 = insert(root2, 2);
    root2 = insert(root2, 1);
    root2 = insert(root2, 3);
    root2 = insert(root2, 4);
    int sum = 10;
    pairSum(root1, root2, sum);
    return 0;
}

/*Recursive C++ program to find key closest to k
in given Binary Search Tree.*/

#include<bits/stdc++.h>
using namespace std;

/* A binary tree node has key, pointer to left child
and a pointer to right child */

struct Node
{
    int key;
    struct Node* left, *right;
};

/* Utility that allocates a new node with the
  given key and NULL left and right pointers. */

struct Node* newnode(int key)
{
    struct Node* node = new (struct Node);
    node->key = key;
    node->left = node->right  = NULL;
    return (node);
}

/*Function to find node with minimum absolute
difference with given K
min_diff   --> minimum difference till now
min_diff_key  --> node having minimum absolute
                   difference with K*/

void maxDiffUtil(struct Node *ptr, int k, int &min_diff,
                                      int &min_diff_key)
{
    if (ptr == NULL)
        return ;

/*    If k itself is present*/

    if (ptr->key == k)
    {
        min_diff_key = k;
        return;
    }

/*    update min_diff and min_diff_key by checking
    current node value*/

    if (min_diff > abs(ptr->key - k))
    {
        min_diff = abs(ptr->key - k);
        min_diff_key = ptr->key;
    }

/*    if k is less than ptr->key then move in
    left subtree else in right subtree*/

    if (k < ptr->key)
        maxDiffUtil(ptr->left, k, min_diff, min_diff_key);
    else
        maxDiffUtil(ptr->right, k, min_diff, min_diff_key);
}

/*Wrapper over maxDiffUtil()*/

int maxDiff(Node *root, int k)
{

/*    Initialize minimum difference*/

    int min_diff = INT_MAX, min_diff_key = -1;

/*    Find value of min_diff_key (Closest key
    in tree with k)*/

    maxDiffUtil(root, k, min_diff, min_diff_key);
    return min_diff_key;
}

/*Driver program to run the case*/

int main()
{
    struct Node *root = newnode(9);
    root->left    = newnode(4);
    root->right   = newnode(17);
    root->left->left = newnode(3);
    root->left->right = newnode(6);
    root->left->right->left = newnode(5);
    root->left->right->right = newnode(7);
    root->right->right = newnode(22);
    root->right->right->left = newnode(20);
    int k = 18;
    cout << maxDiff(root, k);
    return 0;
}

/*Insertion in Threaded Binary Search Tree.*/

#include<bits/stdc++.h>
using namespace std;
struct Node
{
    struct Node *left, *right;
    int info;

/*    True if left pointer points to predecessor
    in Inorder Traversal*/

    bool lthread;

/*    True if right pointer points to successor
    in Inorder Traversal*/

    bool rthread;
};

/*Insert a Node in Binary Threaded Tree*/

struct Node *insert(struct Node *root, int ikey)
{

/*    Searching for a Node with given value*/

    Node *ptr = root;

/*Parent of key to be inserted*/

Node *par = NULL; 
    while (ptr != NULL)
    {

/*        If key already exists, return*/

        if (ikey == (ptr->info))
        {
            printf("Duplicate Key !\n");
            return root;
        }

/*Update parent pointer*/

par = ptr;

/*        Moving on left subtree.*/

        if (ikey < ptr->info)
        {
            if (ptr -> lthread == false)
                ptr = ptr -> left;
            else
                break;
        }

/*        Moving on right subtree.*/

        else
        {
            if (ptr->rthread == false)
                ptr = ptr -> right;
            else
                break;
        }
    }

/*    Create a new node*/

    Node *tmp = new Node;
    tmp -> info = ikey;
    tmp -> lthread = true;
    tmp -> rthread = true;
    if (par == NULL)
    {
        root = tmp;
        tmp -> left = NULL;
        tmp -> right = NULL;
    }
    else if (ikey < (par -> info))
    {
        tmp -> left = par -> left;
        tmp -> right = par;
        par -> lthread = false;
        par -> left = tmp;
    }
    else
    {
        tmp -> left = par;
        tmp -> right = par -> right;
        par -> rthread = false;
        par -> right = tmp;
    }
    return root;
}

/*Returns inorder successor using rthread*/

struct Node *inorderSuccessor(struct Node *ptr)
{

/*    If rthread is set, we can quickly find*/

    if (ptr -> rthread == true)
        return ptr->right;

/*    Else return leftmost child of right subtree*/

    ptr = ptr -> right;
    while (ptr -> lthread == false)
        ptr = ptr -> left;
    return ptr;
}

/*Printing the threaded tree*/

void inorder(struct Node *root)
{
    if (root == NULL)
        printf("Tree is empty");

/*    Reach leftmost node*/

    struct Node *ptr = root;
    while (ptr -> lthread == false)
        ptr = ptr -> left;

/*    One by one print successors*/

    while (ptr != NULL)
    {
        printf("%d ",ptr -> info);
        ptr = inorderSuccessor(ptr);
    }
}

/*Driver Program*/

int main()
{
    struct Node *root = NULL;
    root = insert(root, 20);
    root = insert(root, 10);
    root = insert(root, 30);
    root = insert(root, 5);
    root = insert(root, 16);
    root = insert(root, 14);
    root = insert(root, 17);
    root = insert(root, 13);
    inorder(root);
    return 0;
}

