{
    int mat[][C] = {{1, 1, 2}, {3, 4, 6}, {5, 3, 2}};
    struct Cell arr[] = {{0, 0}, {1, 1}, {0, 1}};
    int n = sizeof(arr)/sizeof(arr[0]);
    printSums(mat, arr, n);
    return 0;
}

/*CPP program to implement Queue using
two stacks with costly enQueue()*/

#include <bits/stdc++.h>
using namespace std;
struct Queue {
    stack<int> s1, s2;
    void enQueue(int x)
    {

/*        Move all elements from s1 to s2*/

        while (!s1.empty()) {
            s2.push(s1.top());
            s1.pop();
        }

/*        Push item into s1*/

        s1.push(x);

/*        Push everything back to s1*/

        while (!s2.empty()) {
            s1.push(s2.top());
            s2.pop();
        }
    }

/*    Dequeue an item from the queue*/

    int deQueue()
    {

/*        if first stack is empty*/

        if (s1.empty()) {
            cout << "Q is Empty";
            exit(0);
        }

/*        Return top of s1*/

        int x = s1.top();
        s1.pop();
        return x;
    }
};

/*Driver code*/

int main()
{
    Queue q;
    q.enQueue(1);
    q.enQueue(2);
    q.enQueue(3);
    cout << q.deQueue() << '\n';
    cout << q.deQueue() << '\n';
    cout << q.deQueue() << '\n';
    return 0;
}

/*C Program for Iterative Tower of Hanoi*/

#include <stdio.h>
#include <math.h>
#include <stdlib.h>
#include <limits.h>

/*A structure to represent a stack*/

struct Stack
{
unsigned capacity;
int top;
int *array;
};

/*function to create a stack of given capacity.*/

struct Stack* createStack(unsigned capacity)
{
    struct Stack* stack =
        (struct Stack*) malloc(sizeof(struct Stack));
    stack -> capacity = capacity;
    stack -> top = -1;
    stack -> array =
        (int*) malloc(stack -> capacity * sizeof(int));
    return stack;
}

/*Stack is full when top is equal to the last index*/

int isFull(struct Stack* stack)
{
return (stack->top == stack->capacity - 1);
}

/*Stack is empty when top is equal to -1*/

int isEmpty(struct Stack* stack)
{
return (stack->top == -1);
}

/*Function to add an item to stack. It increases
top by 1*/

void push(struct Stack *stack, int item)
{
    if (isFull(stack))
        return;
    stack -> array[++stack -> top] = item;
}

/*Function to remove an item from stack. It
decreases top by 1*/

int pop(struct Stack* stack)
{
    if (isEmpty(stack))
        return INT_MIN;
    return stack -> array[stack -> top--];
}

/*Function to show the movement of disks*/

void moveDisk(char fromPeg, char toPeg, int disk)
{
    printf("Move the disk %d from \'%c\' to \'%c\'\n",
        disk, fromPeg, toPeg);
}

/*Function to implement legal movement between
two poles*/

void moveDisksBetweenTwoPoles(struct Stack *src,
            struct Stack *dest, char s, char d)
{
    int pole1TopDisk = pop(src);
    int pole2TopDisk = pop(dest);

/*    When pole 1 is empty*/

    if (pole1TopDisk == INT_MIN)
    {
        push(src, pole2TopDisk);
        moveDisk(d, s, pole2TopDisk);
    }

/*    When pole2 pole is empty*/

    else if (pole2TopDisk == INT_MIN)
    {
        push(dest, pole1TopDisk);
        moveDisk(s, d, pole1TopDisk);
    }

/*    When top disk of pole1 > top disk of pole2*/

    else if (pole1TopDisk > pole2TopDisk)
    {
        push(src, pole1TopDisk);
        push(src, pole2TopDisk);
        moveDisk(d, s, pole2TopDisk);
    }

/*    When top disk of pole1 < top disk of pole2*/

    else
    {
        push(dest, pole2TopDisk);
        push(dest, pole1TopDisk);
        moveDisk(s, d, pole1TopDisk);
    }
}

/*Function to implement TOH puzzle*/

void tohIterative(int num_of_disks, struct Stack
            *src, struct Stack *aux,
            struct Stack *dest)
{
    int i, total_num_of_moves;
    char s = 'S', d = 'D', a = 'A';

/*    If number of disks is even, then interchange
    destination pole and auxiliary pole*/

    if (num_of_disks % 2 == 0)
    {
        char temp = d;
        d = a;
        a = temp;
    }
    total_num_of_moves = pow(2, num_of_disks) - 1;

/*    Larger disks will be pushed first*/

    for (i = num_of_disks; i >= 1; i--)
        push(src, i);
    for (i = 1; i <= total_num_of_moves; i++)
    {
        if (i % 3 == 1)
        moveDisksBetweenTwoPoles(src, dest, s, d);
        else if (i % 3 == 2)
        moveDisksBetweenTwoPoles(src, aux, s, a);
        else if (i % 3 == 0)
        moveDisksBetweenTwoPoles(aux, dest, a, d);
    }
}

/*Driver Program*/

int main()
{

/*    Input: number of disks*/

    unsigned num_of_disks = 3;
    struct Stack *src, *dest, *aux;

/*    Create three stacks of size 'num_of_disks'
    to hold the disks*/

    src = createStack(num_of_disks);
    aux = createStack(num_of_disks);
    dest = createStack(num_of_disks);
    tohIterative(num_of_disks, src, aux, dest);
    return 0;
}

/*C++ program to print all ancestors of a given key*/

#include <bits/stdc++.h>
using namespace std;

/*Structure for a tree node*/

struct Node {
    int data;
    struct Node* left, *right;
};

/*A utility function to create a new tree node*/

struct Node* newNode(int data)
{
    struct Node* node = (struct Node*)malloc(sizeof(struct Node));
    node->data = data;
    node->left = node->right = NULL;
    return node;
}

/*Iterative Function to print all ancestors of a
given key*/

void printAncestors(struct Node* root, int key)
{
    if (root == NULL)
        return;

/*    Create a stack to hold ancestors*/

    stack<struct Node*> st;

/*    Traverse the complete tree in postorder way till
    we find the key*/

    while (1) {

/*        Traverse the left side. While traversing, push
        the nodes into  the stack so that their right
        subtrees can be traversed later*/

        while (root && root->data != key) {

/*push current node*/

st.push(root);

/*move to next node*/

root = root->left; 
        }

/*        If the node whose ancestors are to be printed
        is found, then break the while loop.*/

        if (root && root->data == key)
            break;

/*        Check if right sub-tree exists for the node at top
        If not then pop that node because we don't need
        this node any more.*/

        if (st.top()->right == NULL) {
            root = st.top();
            st.pop();

/*            If the popped node is right child of top,
            then remove the top as well. Left child of
            the top must have processed before.*/

            while (!st.empty() && st.top()->right == root) {
                root = st.top();
                st.pop();
            }
        }

/*        if stack is not empty then simply set the root
        as right child of top and start traversing right
        sub-tree.*/

        root = st.empty() ? NULL : st.top()->right;
    }

/*    If stack is not empty, print contents of stack
    Here assumption is that the key is there in tree*/

    while (!st.empty()) {
        cout << st.top()->data << " ";
        st.pop();
    }
}

/*Driver program to test above functions*/

int main()
{

/*    Let us construct a binary tree*/

    struct Node* root = newNode(1);
    root->left = newNode(2);
    root->right = newNode(7);
    root->left->left = newNode(3);
    root->left->right = newNode(5);
    root->right->left = newNode(8);
    root->right->right = newNode(9);
    root->left->left->left = newNode(4);
    root->left->right->right = newNode(6);
    root->right->right->left = newNode(10);
    int key = 6;
    printAncestors(root, key);
    return 0;
}

/*C++ program to keep track of maximum
element in a stack*/

#include <bits/stdc++.h>
using namespace std;
class StackWithMax
{

/*    main stack*/

    stack<int> mainStack;

/*    stack to keep track of max element*/

    stack<int> trackStack;
public:
    void push(int x)
    {
        mainStack.push(x);
        if (mainStack.size() == 1)
        {
            trackStack.push(x);
            return;
        }

/*        If current element is greater than
        the top element of track stack, push
        the current element to track stack
        otherwise push the element at top of
        track stack again into it.*/

        if (x > trackStack.top())
            trackStack.push(x);
        else
            trackStack.push(trackStack.top());
    }
    int getMax()
    {
        return trackStack.top();
    }
    int pop()
    {
        mainStack.pop();
        trackStack.pop();
    }
};

/*Driver program to test above functions*/

int main()
{
    StackWithMax s;
    s.push(20);
    cout << s.getMax() << endl;
    s.push(10);
    cout << s.getMax() << endl;
    s.push(50);
    cout << s.getMax() << endl;
    return 0;
}

/*C++ program to checks if a
binary tree is max heap or not*/

#include <bits/stdc++.h>
using namespace std;

/*Tree node structure*/

struct Node {
    int data;
    struct Node* left;
    struct Node* right;
};

/*To add a new node*/

struct Node* newNode(int k)
{
    struct Node* node = new Node;
    node->data = k;
    node->right = node->left = NULL;
    return node;
}
bool isHeap(Node* root)
{
    queue<Node*> q;
    q.push(root);
    bool nullish = false;
    while (!q.empty())
    {
        Node* temp = q.front();
        q.pop();
        if (temp->left)
        {
            if (nullish
                || temp->left->data
                >= temp->data)
            {
                return false;
            }
            q.push(temp->left);
        }
        else {
            nullish = true;
        }
        if (temp->right)
        {
            if (nullish
                || temp->right->data
                >= temp->data)
            {
                return false;
            }
            q.push(temp->right);
        }
        else
        {
            nullish = true;
        }
    }
    return true;
}

/*Driver code*/

int main()
{
    struct Node* root = NULL;
    root = newNode(10);
    root->left = newNode(9);
    root->right = newNode(8);
    root->left->left = newNode(7);
    root->left->right = newNode(6);
    root->right->left = newNode(5);
    root->right->right = newNode(4);
    root->left->left->left = newNode(3);
    root->left->left->right = newNode(2);
    root->left->right->left = newNode(1);

/*    Function call*/

    if (isHeap(root))
        cout << "Given binary tree is a Heap\n";
    else
        cout << "Given binary tree is not a Heap\n";
    return 0;
}

/*C++ program to rearrange characters in a string
so that no two adjacent characters are same.*/

#include <bits/stdc++.h>
using namespace std;
const int MAX_CHAR = 26;
struct Key {

/*store frequency of character*/

int freq; 
    char ch;

/*    function for priority_queue to store Key
    according to freq*/

    bool operator<(const Key& k) const
    {
        return freq < k.freq;
    }
};

/*Function to rearrange character of a string
so that no char repeat twice*/

void rearrangeString(string str)
{
    int n = str.length();

/*    Store frequencies of all characters in string*/

    int count[MAX_CHAR] = { 0 };
    for (int i = 0; i < n; i++)
        count[str[i] - 'a']++;

/*    Insert all characters with their frequencies
    into a priority_queue*/

    priority_queue<Key> pq;
   for (char c = 'a'; c <= 'z'; c++) {
          int val = c - 'a';
        if (count[val]) {
            pq.push(Key{ count[val], c });
        }
    }

/*    'str' that will store resultant value*/

    str = "";

/*    work as the previous visited element
    initial previous element be. ( '#' and
    it's frequency '-1' )*/

    Key prev{ -1, '#' };

/*    traverse queue*/

    while (!pq.empty()) {

/*        pop top element from queue and add it
        to string.*/

        Key k = pq.top();
        pq.pop();
        str = str + k.ch;

/*        IF frequency of previous character is less
        than zero that means it is useless, we
        need not to push it*/

        if (prev.freq > 0)
            pq.push(prev);

/*        make current character as the previous 'char'
        decrease frequency by 'one'*/

        (k.freq)--;
        prev = k;
    }

/*    If length of the resultant string and original
    string is not same then string is not valid*/

    if (n != str.length())
        cout << " Not valid String " << endl;

/*valid string*/

else 
        cout << str << endl;
}

/*Driver program to test above function*/

int main()
{
    string str = "bbbaa";
    rearrangeString(str);
    return 0;
}

/*C++ implementation of Deque using
doubly linked list*/

#include <bits/stdc++.h>
using namespace std;

/*Node of a doubly linked list*/

struct Node
{
    int data;
    Node *prev, *next;

/*    Function to get a new node*/

    static Node* getnode(int data)
    {
        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->data = data;
        newNode->prev = newNode->next = NULL;
        return newNode;
    }
};

/*A structure to represent a deque*/

class Deque
{
    Node* front;
    Node* rear;
    int Size;
public:
    Deque()
    {
        front = rear = NULL;
        Size = 0;
    }

/*    Operations on Deque*/

    void insertFront(int data);
    void insertRear(int data);
    void deleteFront();
    void deleteRear();
    int getFront();
    int getRear();
    int size();
    bool isEmpty();
    void erase();
};

/*Function to check whether deque
is empty or not*/

bool Deque::isEmpty()
{
    return (front == NULL);
}

/*Function to return the number of
elements in the deque*/

int Deque::size()
{
    return Size;
}

/*Function to insert an element
at the front end*/

void Deque::insertFront(int data)
{
    Node* newNode = Node::getnode(data);

/*    If true then new element cannot be added
    and it is an 'Overflow' condition*/

    if (newNode == NULL)
        cout << "OverFlow\n";
    else
    {

/*        If deque is empty*/

        if (front == NULL)
            rear = front = newNode;

/*        Inserts node at the front end*/

        else
        {
            newNode->next = front;
            front->prev = newNode;
            front = newNode;
        }

/*        Increments count of elements by 1*/

        Size++;
    }
}

/*Function to insert an element
at the rear end*/

void Deque::insertRear(int data)
{
    Node* newNode = Node::getnode(data);

/*    If true then new element cannot be added
    and it is an 'Overflow' condition*/

    if (newNode == NULL)
        cout << "OverFlow\n";
    else
    {

/*        If deque is empty*/

        if (rear == NULL)
            front = rear = newNode;

/*        Inserts node at the rear end*/

        else
        {
            newNode->prev = rear;
            rear->next = newNode;
            rear = newNode;
        }
        Size++;
    }
}

/*Function to delete the element
from the front end*/

void Deque::deleteFront()
{

/*    If deque is empty then
    'Underflow' condition*/

    if (isEmpty())
        cout << "UnderFlow\n";

/*    Deletes the node from the front end and makes
    the adjustment in the links*/

    else
    {
        Node* temp = front;
        front = front->next;

/*        If only one element was present*/

        if (front == NULL)
            rear = NULL;
        else
            front->prev = NULL;
        free(temp);

/*        Decrements count of elements by 1*/

        Size--;
    }
}

/*Function to delete the element
from the rear end*/

void Deque::deleteRear()
{

/*    If deque is empty then
    'Underflow' condition*/

    if (isEmpty())
        cout << "UnderFlow\n";

/*    Deletes the node from the rear end and makes
    the adjustment in the links*/

    else
    {
        Node* temp = rear;
        rear = rear->prev;

/*        If only one element was present*/

        if (rear == NULL)
            front = NULL;
        else
            rear->next = NULL;
        free(temp);

/*        Decrements count of elements by 1*/

        Size--;
    }
}

/*Function to return the element
at the front end*/

int Deque::getFront()
{

/*    If deque is empty, then returns
    garbage value*/

    if (isEmpty())
        return -1;
    return front->data;
}

/*Function to return the element
at the rear end*/

int Deque::getRear()
{

/*    If deque is empty, then returns
    garbage value*/

    if (isEmpty())
        return -1;
    return rear->data;
}

/*Function to delete all the elements
from Deque*/

void Deque::erase()
{
    rear = NULL;
    while (front != NULL)
    {
        Node* temp = front;
        front = front->next;
        free(temp);
    }
    Size = 0;
}

/*Driver program to test above*/

int main()
{
    Deque dq;
    cout << "Insert element '5' at rear end\n";
    dq.insertRear(5);
    cout << "Insert element '10' at rear end\n";
    dq.insertRear(10);
    cout << "Rear end element: "
        << dq.getRear() << endl;
    dq.deleteRear();
    cout << "After deleting rear element new rear"
        << " is: " << dq.getRear() << endl;
    cout << "Inserting element '15' at front end \n";
    dq.insertFront(15);
    cout << "Front end element: "
        << dq.getFront() << endl;
    cout << "Number of elements in Deque: "
        << dq.size() << endl;
    dq.deleteFront();
    cout << "After deleting front element new "
        << "front is: " << dq.getFront() << endl;
    return 0;
}

/*C++ program to find number
of siblings of a given node*/

#include <bits/stdc++.h>
using namespace std;

/*Represents a node of an n-ary tree*/

class Node {
public:
    int key;
    vector<Node*> child;
    Node(int data)
    {
        key = data;
    }
};

/*Function to calculate number
of siblings of a given node*/

int numberOfSiblings(Node* root, int x)
{
    if (root == NULL)
        return 0;

/*    Creating a queue and
    pushing the root*/

    queue<Node*> q;
    q.push(root);
    while (!q.empty()) {

/*        Dequeue an item from queue and
        check if it is equal to x If YES,
        then return number of children*/

        Node* p = q.front();
        q.pop();

/*        Enqueue all children of
        the dequeued item*/

        for (int i = 0; i < p->child.size(); i++) {

/*            If the value of children
            is equal to x, then return
            the number of siblings*/

            if (p->child[i]->key == x)
                return p->child.size() - 1;
            q.push(p->child[i]);
        }
    }
}

