/*C++ implementation to count
items common to both the lists
but with different prices*/

#include <bits/stdc++.h>
using namespace std;

/*Details of an item*/

struct item
{
  string name;
  int price;
};

/*comparator function
used for sorting*/

bool compare(struct item a,
             struct item b)
{
  return (a.name.compare
         (b.name) <= 0);       
}

/*Function to search 'str'
in 'list2[]'. If it exists then
price associated with 'str'
in 'list2[]' is being returned
else -1 is returned. Here binary
serach technique is being applied
for searching*/

int binary_search(item list2[], int low,
                  int high, string str)
{
  while (low <= high)
  {
    int mid = (low + high) / 2;

/*    if true the item 'str'
    is in 'list2'        */

    if (list2[mid].name.compare(str) == 0)
      return list2[mid].price;
    else if (list2[mid].name.compare(str) < 0)   
      low = mid + 1;
    else
      high = mid - 1;   
  }

/*  item 'str' is not in 'list2'        */

  return -1;
}

/*Function to count items common to both
the lists but with different prices*/

int countItems(item list1[], int m,
               item list2[], int n)
{

/*  sort 'list2' in alphabetcal
  order of items name*/

  sort(list2, list2 + n,
       compare);

/*  initial count*/

  int count = 0;
  for (int i = 0; i < m; i++)
  {

/*    get the price of item 'list1[i]'
    from 'list2' if item in not
    present in second list then
    -1 is being obtained*/

    int r = binary_search(list2, 0, n - 1,
                          list1[i].name);

/*    if item is present in list2
    with a different price*/

    if ((r != -1) &&
        (r != list1[i].price))
      count++;
  }

/*  Required count of items*/

  return count;
}

/*Driver code*/

int main()
{
  item list1[] = {{"apple", 60},
                  {"bread", 20},
                  {"wheat", 50},
                  {"oil", 30}};
  item list2[] = {{"milk", 20},
                  {"bread", 15},
                  {"wheat", 40},
                  {"apple", 60}};
  int m = sizeof(list1) /
          sizeof(list1[0]);
  int n = sizeof(list2) /
          sizeof(list2[0]);   
  cout << "Count = " <<
           countItems(list1, m,
                      list2, n);
  return 0;    
}

/*C++ implementation to count items common to both
the lists but with different prices*/

#include <bits/stdc++.h>
using namespace std;

/*details of an item*/

struct item
{
    string name;
    int price;
};

/*function to count items common to both
the lists but with different prices*/

int countItems(item list1[], int m,
               item list2[], int n)
{

/*    'um' implemented as hash table that contains
    item name as the key and price as the value
    associated with the key*/

    unordered_map<string, int> um;
    int count = 0;

/*    insert elements of 'list1' in 'um'*/

    for (int i = 0; i < m; i++)
        um[list1[i].name] = list1[i].price;

/*    for each element of 'list2' check if it is
    present in 'um' with a different price
    value*/

    for (int i = 0; i < n; i++)   
        if ((um.find(list2[i].name) != um.end()) &&
            (um[list2[i].name] != list2[i].price))
            count++;

/*    required count of items       */

    return count;       
}

/*Driver program to test above*/

int main()
{
    item list1[] = {{"apple", 60}, {"bread", 20},
                    {"wheat", 50}, {"oil", 30}};
    item list2[] = {{"milk", 20}, {"bread", 15},
                    {"wheat", 40}, {"apple", 60}};
    int m = sizeof(list1) / sizeof(list1[0]);
    int n = sizeof(list2) / sizeof(list2[0]);   
    cout << "Count = "   
         << countItems(list1, m, list2, n);
    return 0;    
}

/* C++ program to design a DS that supports following operations
in Theta(n) time
a) Insert
b) Delete
c) Search
d) getRandom */

#include<bits/stdc++.h>
using namespace std;

/*class to represent the required data structure*/

class myStructure
{

/*    A resizable array*/

    vector <int> arr;

/*    A hash where keys are array elements and values are
    indexes in arr[]*/

    map <int, int> Map;
    public:

/*    A Theta(1) function to add an element to MyDS
    data structure*/

    void add(int x)
    {

/*        If element is already present, then nothing to do*/

        if(Map.find(x) != Map.end())
            return;

/*        Else put element at the end of arr[]*/

        int index = arr.size();
        arr.push_back(x);

/*        and hashmap also*/

        Map.insert(std::pair<int,int>(x, index));
    }

/*    function to remove a number to DS in O(1)*/

    void remove(int x)
    {

/*        element not found then return*/

        if(Map.find(x) == Map.end())
            return;

/*        remove element from map*/

        int index = Map.at(x);
        Map.erase(x);

/*        swap with last element in arr*/

        int last = arr.size() - 1;
        swap(arr[index], arr[last]);

/*then remove element at back*/
        arr.pop_back();

/*        Update hash table for new index of last element*/

        Map.at(arr[index]) = index;
    }

/*    Returns a random element from myStructure*/

    int getRandom()
    {

/*        Find a random index from 0 to size - 1*/

        srand (time(NULL));
        int random_index = rand() % arr.size();

/*        Return element at randomly picked index*/

        return arr.at(random_index);
    }

/*    Returns index of element if element is present, otherwise null*/

    int search(int x)
    {
        if(Map.find(x) != Map.end())
        return Map.at(x);
        return -1;
    }
};

/*Driver main*/

int main()
{
    myStructure ds;
    ds.add(10);
    ds.add(20);
    ds.add(30);
    ds.add(40);
    cout << ds.search(30) << endl;
    ds.remove(20);
    ds.add(50);
    cout << ds.search(50) << endl;
    cout << ds.getRandom() << endl;
}

/* A C++ program to answer queries to check whether 
the substrings are palindrome or not efficiently */

#include <bits/stdc++.h>
using namespace std;
#define p 101
#define MOD 1000000007

/*Structure to represent a query. A query consists
of (L, R) and we have to answer whether the substring
from index-L to R is a palindrome or not*/

struct Query {
    int L, R;
};

/*A function to check if a string str is palindrome
in the ranfe L to R*/

bool isPalindrome(string str, int L, int R)
{

/*    Keep comparing characters while they are same*/

    while (R > L)
        if (str[L++] != str[R--])
            return (false);
    return (true);
}

/*A Function to find pow (base, exponent) % MOD
in log (exponent) time*/

unsigned long long int modPow(
    unsigned long long int base,
    unsigned long long int exponent)
{
    if (exponent == 0)
        return 1;
    if (exponent == 1)
        return base;
    unsigned long long int temp = modPow(base, exponent / 2);
    if (exponent % 2 == 0)
        return (temp % MOD * temp % MOD) % MOD;
    else
        return (((temp % MOD * temp % MOD) % MOD)
                * base % MOD)
               % MOD;
}

/*A Function to calculate Modulo Multiplicative Inverse of 'n'*/

unsigned long long int findMMI(unsigned long long int n)
{
    return modPow(n, MOD - 2);
}

/*A Function to calculate the prefix hash*/

void computePrefixHash(
    string str, int n,
    unsigned long long int prefix[],
    unsigned long long int power[])
{
    prefix[0] = 0;
    prefix[1] = str[0];
    for (int i = 2; i <= n; i++)
        prefix[i] = (prefix[i - 1] % MOD
                     + (str[i - 1] % MOD
                        * power[i - 1] % MOD)
                           % MOD)
                    % MOD;
    return;
}

/*A Function to calculate the suffix hash
Suffix hash is nothing but the prefix hash of
the reversed string*/

void computeSuffixHash(
    string str, int n,
    unsigned long long int suffix[],
    unsigned long long int power[])
{
    suffix[0] = 0;
    suffix[1] = str[n - 1];
    for (int i = n - 2, j = 2; i >= 0 && j <= n; i--, j++)
        suffix[j] = (suffix[j - 1] % MOD
                     + (str[i] % MOD
                        * power[j - 1] % MOD)
                           % MOD)
                    % MOD;
    return;
}

/*A Function to answer the Queries*/

void queryResults(string str, Query q[], int m, int n,
                  unsigned long long int prefix[],
                  unsigned long long int suffix[],
                  unsigned long long int power[])
{
    for (int i = 0; i <= m - 1; i++) {
        int L = q[i].L;
        int R = q[i].R;

/*        Hash Value of Substring [L, R]*/

        unsigned long long hash_LR
            = ((prefix[R + 1] - prefix[L] + MOD) % MOD
               * findMMI(power[L]) % MOD)
              % MOD;

/*        Reverse Hash Value of Substring [L, R]*/

        unsigned long long reverse_hash_LR
            = ((suffix[n - L] - suffix[n - R - 1] + MOD) % MOD
               * findMMI(power[n - R - 1]) % MOD)
              % MOD;

/*        If both are equal then
        the substring is a palindrome*/

        if (hash_LR == reverse_hash_LR) {
            if (isPalindrome(str, L, R) == true)
                printf("The Substring [%d %d] is a "
                       "palindrome\n",
                       L, R);
            else
                printf("The Substring [%d %d] is not a "
                       "palindrome\n",
                       L, R);
        }
        else
            printf("The Substring [%d %d] is not a "
                   "palindrome\n",
                   L, R);
    }
    return;
}

/*A Dynamic Programming Based Approach to compute the
powers of 101*/

void computePowers(unsigned long long int power[], int n)
{

/*    101^0 = 1*/

    power[0] = 1;
    for (int i = 1; i <= n; i++)
        power[i] = (power[i - 1] % MOD * p % MOD) % MOD;
    return;
}

/* Driver program to test above function */

int main()
{
    string str = "abaaabaaaba";
    int n = str.length();

/*    A Table to store the powers of 101*/

    unsigned long long int power[n + 1];
    computePowers(power, n);

/*    Arrays to hold prefix and suffix hash values*/

    unsigned long long int prefix[n + 1], suffix[n + 1];

/*    Compute Prefix Hash and Suffix Hash Arrays*/

    computePrefixHash(str, n, prefix, power);
    computeSuffixHash(str, n, suffix, power);
    Query q[] = { { 0, 10 }, { 5, 8 }, { 2, 5 }, { 5, 9 } };
    int m = sizeof(q) / sizeof(q[0]);
    queryResults(str, q, m, n, prefix, suffix, power);
    return (0);
}

/*kth largest element in a 2d array sorted row-wise and
column-wise*/

#include <bits/stdc++.h>
using namespace std;

/*A structure to store entry of heap. The entry contains
value from 2D array, row and column numbers of the value*/

struct HeapNode {

/*value to be stored*/

int val;

/*Row number of value in 2D array*/

int r;

/*Column number of value in 2D array*/

int c; 
};

/*A utility function to swap two HeapNode items.*/

void swap(HeapNode* x, HeapNode* y)
{
    HeapNode z = *x;
    *x = *y;
    *y = z;
}

/*A utility function to minheapify the node harr[i] of a
heap stored in harr[]*/

void minHeapify(HeapNode harr[], int i, int heap_size)
{
    int l = i * 2 + 1;
    int r = i * 2 + 2;
    if(l < heap_size&& r<heap_size && harr[l].val < harr[i].val && harr[r].val < harr[i].val){
            HeapNode temp=harr[r];
            harr[r]=harr[i];
            harr[i]=harr[l];
            harr[l]=temp;
            minHeapify(harr ,l,heap_size);
            minHeapify(harr ,r,heap_size);
        }
        if (l < heap_size && harr[l].val < harr[i].val){
            HeapNode temp=harr[i];      
            harr[i]=harr[l];
            harr[l]=temp;
            minHeapify(harr ,l,heap_size);
        }
}

/*This function returns kth
smallest element in a 2D array
mat[][]*/

int kthSmallest(int mat[4][4], int n, int k)
{

/*    k must be greater than 0 and smaller than n*n*/

    if (k < 0 && k >= n * n)
        return INT_MAX;

/*    Create a min heap of elements from first row of 2D
    array*/

    HeapNode harr[n];
    for (int i = 0; i < n; i++)
        harr[i] = { mat[0][i], 0, i };

    HeapNode hr;
    for (int i = 0; i < k; i++) {

/*        Get current heap root*/

        hr = harr[0];

/*        Get next value from column of root's value. If
        the value stored at root was last value in its
        column, then assign INFINITE as next value*/

        int nextval = (hr.r < (n - 1)) ? mat[hr.r + 1][hr.c]: INT_MAX;

/*        Update heap root with next value*/

        harr[0] = { nextval, (hr.r) + 1, hr.c };

/*        Heapify root*/

        minHeapify(harr, 0, n);
    }

/*    Return the value at last extracted root*/

    return hr.val;
}

/*driver program to test above function*/

int main()
{
    int mat[4][4] = {
        { 10, 20, 30, 40 },
        { 15, 25, 35, 45 },
        { 25, 29, 37, 48 },
        { 32, 33, 39, 50 },
    };
    cout << "7th smallest element is "
         << kthSmallest(mat, 4, 7);
    return 0;
}

/*C++ program of above implementation*/

#include<iostream>
using namespace std;

/*Pair struct is used to return
two values from getMinMax()*/

struct Pair
{
    int min;
    int max;
};
struct Pair getMinMax(int arr[], int n)
{
    struct Pair minmax;    
    int i;

/*    If there is only one element
    then return it as min and max both*/

    if (n == 1)
    {
        minmax.max = arr[0];
        minmax.min = arr[0];    
        return minmax;
    }

/*    If there are more than one elements,
    then initialize min and max*/

    if (arr[0] > arr[1])
    {
        minmax.max = arr[0];
        minmax.min = arr[1];
    }
    else
    {
        minmax.max = arr[1];
        minmax.min = arr[0];
    }
    for(i = 2; i < n; i++)
    {
        if (arr[i] > minmax.max)    
            minmax.max = arr[i];
        else if (arr[i] < minmax.min)    
            minmax.min = arr[i];
    }
    return minmax;
}

/*Driver code*/

int main()
{
    int arr[] = { 1000, 11, 445,
                  1, 330, 3000 };
    int arr_size = 6;
    struct Pair minmax = getMinMax(arr, arr_size);
    cout << "Minimum element is "
         << minmax.min << endl;
    cout << "Maximum element is "
         << minmax.max;
    return 0;
}

/*C++ program of above implementation*/

#include<iostream>
using namespace std;

/*Structure is used to return
two values from minMax()*/

struct Pair
{
    int min;
    int max;
};
struct Pair getMinMax(int arr[], int n)
{
    struct Pair minmax;    
    int i;

/*    If array has even number of elements
    then initialize the first two elements
    as minimum and maximum*/

    if (n % 2 == 0)
    {
        if (arr[0] > arr[1])    
        {
            minmax.max = arr[0];
            minmax.min = arr[1];
        }
        else
        {
            minmax.min = arr[0];
            minmax.max = arr[1];
        }

/*        Set the starting index for loop*/

        i = 2;
    }

/*    If array has odd number of elements
    then initialize the first element as
    minimum and maximum*/

    else
    {
        minmax.min = arr[0];
        minmax.max = arr[0];

/*        Set the starting index for loop*/

        i = 1;
    }

/*    In the while loop, pick elements in
    pair and compare the pair with max
    and min so far*/

    while (i < n - 1)
    {        
        if (arr[i] > arr[i + 1])        
        {
            if(arr[i] > minmax.max)    
                minmax.max = arr[i];
            if(arr[i + 1] < minmax.min)        
                minmax.min = arr[i + 1];    
        }
        else       
        {
            if (arr[i + 1] > minmax.max)    
                minmax.max = arr[i + 1];
            if (arr[i] < minmax.min)        
                minmax.min = arr[i];    
        }

/*        Increment the index by 2 as
        two elements are processed in loop*/

        i += 2;
    }        
    return minmax;
}

/*Driver code*/

int main()
{
    int arr[] = { 1000, 11, 445,
                1, 330, 3000 };
    int arr_size = 6;
    Pair minmax = getMinMax(arr, arr_size);
    cout << "nMinimum element is "
        << minmax.min << endl;
    cout << "nMaximum element is "
        << minmax.max;
    return 0;
}

/*Program to compute sum of ranges for different range
queries.*/

#include <bits/stdc++.h>
using namespace std;

/*Structure to represent a query range*/

struct Query
{
    int L, R;
};

/*Prints sum of all query ranges. m is number of queries
n is the size of the array.*/

void printQuerySums(int a[], int n, Query q[], int m)
{

/*    One by one compute sum of all queries*/

    for (int i=0; i<m; i++)
    {

/*        Left and right boundaries of current range*/

        int L = q[i].L, R = q[i].R;

/*        Compute sum of current query range*/

        int sum = 0;
        for (int j=L; j<=R; j++)
            sum += a[j];

/*        Print sum of current query range*/

        cout << "Sum of [" << L << ", "
            << R << "] is "  << sum << endl;
    }
}

/*Driver program*/

int main()
{
    int a[] = {1, 1, 2, 1, 3, 4, 5, 2, 8};
    int n = sizeof(a)/sizeof(a[0]);
    Query q[] = {{0, 4}, {1, 3}, {2, 4}};
    int m = sizeof(q)/sizeof(q[0]);
    printQuerySums(a, n, q, m);
    return 0;
}

/*C++ program to do range
minimum query in O(1) time with
O(n*n) extra space and O(n*n)
preprocessing time.*/

#include <bits/stdc++.h>
using namespace std;
#define MAX 500

/*lookup[i][j] is going to store
index of minimum value in
arr[i..j]*/

int lookup[MAX][MAX];

/*Structure to represent a query range*/

struct Query {
    int L, R;
};

/*Fills lookup array lookup[n][n]
for all possible values
of query ranges*/

void preprocess(int arr[], int n)
{

/*    Initialize lookup[][] for the
    intervals with length 1*/

    for (int i = 0; i < n; i++)
        lookup[i][i] = i;

/*    Fill rest of the entries in bottom up manner*/

    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++)

/*            To find minimum of [0,4],
            we compare minimum
            of arr[lookup[0][3]] with arr[4].*/

            if (arr[lookup[i][j - 1]] < arr[j])
                lookup[i][j] = lookup[i][j - 1];
            else
                lookup[i][j] = j;
    }
}

/*Prints minimum of given m
query ranges in arr[0..n-1]*/

void RMQ(int arr[], int n, Query q[], int m)
{

/*    Fill lookup table for
    all possible input queries*/

    preprocess(arr, n);

/*    One by one compute sum of all queries*/

    for (int i = 0; i < m; i++)
    {

/*        Left and right boundaries
        of current range*/

        int L = q[i].L, R = q[i].R;

/*        Print sum of current query range*/

        cout << "Minimum of [" << L
             << ", " << R << "] is "
             << arr[lookup[L][R]] << endl;
    }
}

/*Driver code*/

int main()
{
    int a[] = { 7, 2, 3, 0, 5, 10, 3, 12, 18 };
    int n = sizeof(a) / sizeof(a[0]);
    Query q[] = { { 0, 4 }, { 4, 7 }, { 7, 8 } };
    int m = sizeof(q) / sizeof(q[0]);
    RMQ(a, n, q, m);
    return 0;
}

/*C++ program to do range minimum
query in O(1) time with
O(n Log n) extra space and
O(n Log n) preprocessing time*/

#include <bits/stdc++.h>
using namespace std;
#define MAX 500

/*lookup[i][j] is going to
store index of minimum value in
arr[i..j]. Ideally lookup
table size should not be fixed
and should be determined using
n Log n. It is kept
constant to keep code simple.*/

int lookup[MAX][MAX];

/*Structure to represent a query range*/

struct Query {
    int L, R;
};

/*Fills lookup array
lookup[][] in bottom up manner.*/

void preprocess(int arr[], int n)
{

/*    Initialize M for the
    intervals with length 1*/

    for (int i = 0; i < n; i++)
        lookup[i][0] = i;

/*    Compute values from smaller
    to bigger intervals*/

    for (int j = 1; (1 << j) <= n; j++)
    {

/*        Compute minimum value for
        all intervals with size
        2^j*/

        for (int i = 0; (i + (1 << j) - 1) < n; i++)
        {

/*            For arr[2][10], we
            compare arr[lookup[0][3]]
            and arr[lookup[3][3]]*/

            if (arr[lookup[i][j - 1]]
                < arr[lookup[i + (1 << (j - 1))][j - 1]])
                lookup[i][j] = lookup[i][j - 1];
            else
                lookup[i][j]
                    = lookup[i + (1 << (j - 1))][j - 1];
        }
    }
}

/*Returns minimum of arr[L..R]*/

int query(int arr[], int L, int R)
{

/*    For [2,10], j = 3*/

    int j = (int)log2(R - L + 1);

/*    For [2,10], we compare arr[lookup[0][3]] and
    arr[lookup[3][3]],*/

    if (arr[lookup[L][j]]
        <= arr[lookup[R - (1 << j) + 1][j]])
        return arr[lookup[L][j]];
    else
        return arr[lookup[R - (1 << j) + 1][j]];
}

/*Prints minimum of given
m query ranges in arr[0..n-1]*/

void RMQ(int arr[], int n, Query q[], int m)
{

/*    Fills table lookup[n][Log n]*/

    preprocess(arr, n);

/*    One by one compute sum of all queries*/

    for (int i = 0; i < m; i++)
    {

/*        Left and right boundaries
        of current range*/

        int L = q[i].L, R = q[i].R;

/*        Print sum of current query range*/

        cout << "Minimum of [" << L << ", "
             << R << "] is "
             << query(arr, L, R) << endl;
    }
}

/*Driver code*/

int main()
{
    int a[] = { 7, 2, 3, 0, 5, 10, 3, 12, 18 };
    int n = sizeof(a) / sizeof(a[0]);
    Query q[] = { { 0, 4 }, { 4, 7 }, { 7, 8 } };
    int m = sizeof(q) / sizeof(q[0]);
    RMQ(a, n, q, m);
    return 0;
}

/*Program to determine if the element
exists for different range queries*/

#include <bits/stdc++.h>
using namespace std;

/*Structure to represent a query range*/

struct Query
{
    int L, R, X;
};
const int maxn = 100;
int root[maxn];

/*Find the root of the group containing
the element at index x*/

int find(int x)
{
    return x == root[x] ? x : root[x] =
                find(root[x]);
}

/*merge the two groups containing elements
at indices x and y into one group*/

int uni(int x, int y)
{
    int p = find(x), q = find(y);
    if (p != q) {
        root[p] = root[q];
    }
}
void initialize(int a[], int n, Query q[], int m)
{

/*    make n subsets with every
    element as its root*/

    for (int i = 0; i < n; i++)
        root[i] = i;

/*    consecutive elements equal in value are
    merged into one single group*/

    for (int i = 1; i < n; i++)
        if (a[i] == a[i - 1])
            uni(i, i - 1);
}

/*Driver code*/

int main()
{
    int a[] = { 1, 1, 5, 4, 5 };
    int n = sizeof(a) / sizeof(a[0]);
    Query q[] = { { 0, 2, 2 }, { 1, 4, 1 },
                  { 2, 4, 5 } };
    int m = sizeof(q) / sizeof(q[0]);
    initialize(a, n, q, m);
    for (int i = 0; i < m; i++)
    {
        int flag = 0;
        int l = q[i].L, r = q[i].R, x = q[i].X;
        int p = r;
        while (p >= l)
        {

/*            check if the current element in
            consideration is equal to x or not
            if it is equal, then x exists in the range*/

            if (a[p] == x)
            {
                flag = 1;
                break;
            }
            p = find(p) - 1;
        }

/*        Print if x exists or not*/

        if (flag != 0)
            cout << x << " exists between [" << l 
                 << ", " << r << "] " << endl;
        else
            cout << x << " does not exist between [" 
                << l << ", " << r  << "] " << endl;
    }
}

/*C++ program to demonstrate insert operation in binary
search tree.*/

#include <bits/stdc++.h>
using namespace std;
struct node {
    int key;
    int c = 0;
    struct node *left, *right;
};

/*A utility function to create a new BST node*/

struct node* newNode(int item)
{
    struct node* temp
        = (struct node*)malloc(sizeof(struct node));
    temp->key = item;
    temp->c = 1;
    temp->left = temp->right = NULL;
    return temp;
}

/*A utility function to insert a new node with given key in
BST*/

struct node* insert(struct node* node, int key, int& ma)
{

/*    If the tree is empty, return a new node*/

    if (node == NULL) {
        if (ma == 0)
            ma = 1;
        return newNode(key);
    }

/*    Otherwise, recur down the tree*/

    if (key < node->key)
        node->left = insert(node->left, key, ma);
    else if (key > node->key)
        node->right = insert(node->right, key, ma);
    else
        node->c++;

/*    find the max count*/

    ma = max(ma, node->c);

/*    return the (unchanged) node pointer*/

    return node;
}

/*A utility function to do inorder traversal of BST*/

void inorder(struct node* root, int s)
{
    if (root != NULL) {
        inorder(root->left, s);
        if (root->c > (s / 2))
            printf("%d \n", root->key);
        inorder(root->right, s);
    }
}

/*Driver Code*/

int main()
{
    int a[] = { 1, 3, 3, 3, 2 };
    int size = (sizeof(a)) / sizeof(a[0]);
    struct node* root = NULL;
    int ma = 0;
    for (int i = 0; i < size; i++) {
        root = insert(root, a[i], ma);
    }

/*    Function call*/

    if (ma > (size / 2))
        inorder(root, size);
    else
        cout << "No majority element\n";
    return 0;
}

/*C++ program for activity selection problem
when input activities may not be sorted.*/

#include <bits/stdc++.h>
using namespace std;

/*A job has a start time, finish time and profit.*/

struct Activitiy
{
    int start, finish;
};

/*A utility function that is used for sorting
activities according to finish time*/

bool activityCompare(Activitiy s1, Activitiy s2)
{
    return (s1.finish < s2.finish);
}

/*Returns count of the maximum set of activities that can
be done by a single person, one at a time.*/

void printMaxActivities(Activitiy arr[], int n)
{

/*    Sort jobs according to finish time*/

    sort(arr, arr+n, activityCompare);
    cout << "Following activities are selected n";

/*    The first activity always gets selected*/

    int i = 0;
    cout << "(" << arr[i].start << ", " << arr[i].finish << "), ";

/*    Consider rest of the activities*/

    for (int j = 1; j < n; j++)
    {

/*      If this activity has start time greater than or
      equal to the finish time of previously selected
      activity, then select it*/

      if (arr[j].start >= arr[i].finish)
      {
          cout << "(" << arr[j].start << ", "
              << arr[j].finish << "), ";
          i = j;
      }
    }
}

/*Driver program*/

int main()
{
    Activitiy arr[] = {{5, 9}, {1, 2}, {3, 4}, {0, 6},
                                       {5, 7}, {8, 9}};
    int n = sizeof(arr)/sizeof(arr[0]);
    printMaxActivities(arr, n);
    return 0;
}

/*C++ Program for Efficient Huffman Coding for Sorted input*/

#include <bits/stdc++.h>
using namespace std;

/*This constant can be avoided by explicitly
calculating height of Huffman Tree*/

#define MAX_TREE_HT 100

/*A node of huffman tree*/

class QueueNode {
public:
    char data;
    unsigned freq;
    QueueNode *left, *right;
};

/*Structure for Queue: collection
of Huffman Tree nodes (or QueueNodes)*/

class Queue {
public:
    int front, rear;
    int capacity;
    QueueNode** array;
};

/*A utility function to create a new Queuenode*/

QueueNode* newNode(char data, unsigned freq)
{
    QueueNode* temp = new QueueNode[(sizeof(QueueNode))];
    temp->left = temp->right = NULL;
    temp->data = data;
    temp->freq = freq;
    return temp;
}

/*A utility function to create a Queue of given capacity*/

Queue* createQueue(int capacity)
{
    Queue* queue = new Queue[(sizeof(Queue))];
    queue->front = queue->rear = -1;
    queue->capacity = capacity;
    queue->array = new QueueNode*[(queue->capacity
                                   * sizeof(QueueNode*))];
    return queue;
}

/*A utility function to check if size of given queue is 1*/

int isSizeOne(Queue* queue)
{
    return queue->front == queue->rear
           && queue->front != -1;
}

/*A utility function to check if given queue is empty*/

int isEmpty(Queue* queue) { return queue->front == -1; }

/*A utility function to check if given queue is full*/

int isFull(Queue* queue)
{
    return queue->rear == queue->capacity - 1;
}

/*A utility function to add an item to queue*/

void enQueue(Queue* queue, QueueNode* item)
{
    if (isFull(queue))
        return;
    queue->array[++queue->rear] = item;
    if (queue->front == -1)
        ++queue->front;
}

/*A utility function to remove an item from queue*/

QueueNode* deQueue(Queue* queue)
{
    if (isEmpty(queue))
        return NULL;
    QueueNode* temp = queue->array[queue->front];
    if (queue->front
        == queue

/*If there is only one item in queue*/

->rear) 
        queue->front = queue->rear = -1;
    else
        ++queue->front;
    return temp;
}

/*A utility function to get from of queue*/

QueueNode* getFront(Queue* queue)
{
    if (isEmpty(queue))
        return NULL;
    return queue->array[queue->front];
}

/* A function to get minimum item from two queues */

QueueNode* findMin(Queue* firstQueue, Queue* secondQueue)
{

/*    Step 3.a: If first queue is empty, dequeue from
    second queue*/

    if (isEmpty(firstQueue))
        return deQueue(secondQueue);

/*    Step 3.b: If second queue is empty, dequeue from
    first queue*/

    if (isEmpty(secondQueue))
        return deQueue(firstQueue);

/*    Step 3.c: Else, compare the front of two queues and
    dequeue minimum*/

    if (getFront(firstQueue)->freq
        < getFront(secondQueue)->freq)
        return deQueue(firstQueue);
    return deQueue(secondQueue);
}

/*Utility function to check if this node is leaf*/

int isLeaf(QueueNode* root)
{
    return !(root->left) && !(root->right);
}

/*A utility function to print an array of size n*/

void printArr(int arr[], int n)
{
    int i;
    for (i = 0; i < n; ++i)
        cout << arr[i];
    cout << endl;
}

/*The main function that builds Huffman tree*/

QueueNode* buildHuffmanTree(char data[], int freq[],
                            int size)
{
    QueueNode *left, *right, *top;

/*    Step 1: Create two empty queues*/

    Queue* firstQueue = createQueue(size);
    Queue* secondQueue = createQueue(size);

/*    Step 2:Create a leaf node for each unique character
    and Enqueue it to the first queue in non-decreasing
    order of frequency. Initially second queue is empty*/

    for (int i = 0; i < size; ++i)
        enQueue(firstQueue, newNode(data[i], freq[i]));

/*    Run while Queues contain more than one node. Finally,
    first queue will be empty and second queue will
    contain only one node*/

    while (
        !(isEmpty(firstQueue) && isSizeOne(secondQueue))) {

/*        Step 3: Dequeue two nodes with the minimum
        frequency by examining the front of both queues*/

        left = findMin(firstQueue, secondQueue);
        right = findMin(firstQueue, secondQueue);

/*        Step 4: Create a new internal node with frequency
        equal to the sum of the two nodes frequencies.
        Enqueue this node to second queue.*/

        top = newNode('$', left->freq + right->freq);
        top->left = left;
        top->right = right;
        enQueue(secondQueue, top);
    }
    return deQueue(secondQueue);
}

/*Prints huffman codes from the root of Huffman Tree. It
uses arr[] to store codes*/

void printCodes(QueueNode* root, int arr[], int top)
{

/*    Assign 0 to left edge and recur*/

    if (root->left) {
        arr[top] = 0;
        printCodes(root->left, arr, top + 1);
    }

/*    Assign 1 to right edge and recur*/

    if (root->right) {
        arr[top] = 1;
        printCodes(root->right, arr, top + 1);
    }

/*    If this is a leaf node, then it contains one of the
    input characters, print the character and its code
    from arr[]*/

    if (isLeaf(root)) {
        cout << root->data << ": ";
        printArr(arr, top);
    }
}

/*The main function that builds a Huffman Tree and print
codes by traversing the built Huffman Tree*/

void HuffmanCodes(char data[], int freq[], int size)
{

/*    Construct Huffman Tree*/

    QueueNode* root = buildHuffmanTree(data, freq, size);

/*    Print Huffman codes using the Huffman tree built
    above*/

    int arr[MAX_TREE_HT], top = 0;
    printCodes(root, arr, top);
}

/*Driver code*/

int main()
{
    char arr[] = { 'a', 'b', 'c', 'd', 'e', 'f' };
    int freq[] = { 5, 9, 12, 13, 16, 45 };
    int size = sizeof(arr) / sizeof(arr[0]);
    HuffmanCodes(arr, freq, size);
    return 0;
}

/*A naive recursive implementation of
Largest Independent Set problem*/

#include <bits/stdc++.h>
using namespace std;

/*A utility function to find
max of two integers*/

int max(int x, int y)
{
    return (x > y) ? x : y;
}

/* A binary tree node has data,
pointer to left child and a
pointer to right child */

class node
{
    public:
    int data;
    node *left, *right;
};

/*The function returns size of the
largest independent set in a given
binary tree*/

int LISS(node *root)
{
    if (root == NULL)
    return 0;

/*    Calculate size excluding the current node*/

    int size_excl = LISS(root->left) +
                    LISS(root->right);

/*    Calculate size including the current node*/

    int size_incl = 1;
    if (root->left)
        size_incl += LISS(root->left->left) +
                     LISS(root->left->right);
    if (root->right)
        size_incl += LISS(root->right->left) +
                     LISS(root->right->right);

/*    Return the maximum of two sizes*/

    return max(size_incl, size_excl);
}

/*A utility function to create a node*/

node* newNode( int data )
{
    node* temp = new node();
    temp->data = data;
    temp->left = temp->right = NULL;
    return temp;
}

/*Driver Code*/

int main()
{

/*    Let us construct the tree
    given in the above diagram*/

    node *root = newNode(20);
    root->left = newNode(8);
    root->left->left = newNode(4);
    root->left->right = newNode(12);
    root->left->right->left = newNode(10);
    root->left->right->right = newNode(14);
    root->right = newNode(22);
    root->right->right = newNode(25);
    cout << "Size of the Largest"
         << " Independent Set is "
         << LISS(root);
    return 0;
}

/*C++ program to calculate pow(x,n)*/

#include<iostream>
using namespace std;
class gfg
{

/* Function to calculate x raised to the power y */

public:
int power(int x, unsigned int y)
{
    if (y == 0)
        return 1;
    else if (y % 2 == 0)
        return power(x, y / 2) * power(x, y / 2);
    else
        return x * power(x, y / 2) * power(x, y / 2);
}
};

/* Driver code */

int main()
{
    gfg g;
    int x = 2;
    unsigned int y = 3;
    cout << g.power(x, y);
    return 0;
}

/*A divide and conquer program in C++
to find the smallest distance from a
given set of points.*/

#include <bits/stdc++.h>
using namespace std;

/*A structure to represent a Point in 2D plane*/

class Point
{
    public:
    int x, y;
};

/*Needed to sort array of points
according to X coordinate*/

int compareX(const void* a, const void* b)
{
    Point *p1 = (Point *)a, *p2 = (Point *)b;
    return (p1->x - p2->x);
}

/*Needed to sort array of points according to Y coordinate*/

int compareY(const void* a, const void* b)
{
    Point *p1 = (Point *)a, *p2 = (Point *)b;
    return (p1->y - p2->y);
}

/*A utility function to find the
distance between two points*/

float dist(Point p1, Point p2)
{
    return sqrt( (p1.x - p2.x)*(p1.x - p2.x) +
                (p1.y - p2.y)*(p1.y - p2.y)
            );
}

/*A Brute Force method to return the
smallest distance between two points
in P[] of size n*/

float bruteForce(Point P[], int n)
{
    float min = FLT_MAX;
    for (int i = 0; i < n; ++i)
        for (int j = i+1; j < n; ++j)
            if (dist(P[i], P[j]) < min)
                min = dist(P[i], P[j]);
    return min;
}

/*A utility function to find
minimum of two float values*/

float min(float x, float y)
{
    return (x < y)? x : y;
}

/*A utility function to find the
distance beween the closest points of
strip of given size. All points in
strip[] are sorted accordint to
y coordinate. They all have an upper
bound on minimum distance as d.
Note that this method seems to be
a O(n^2) method, but it's a O(n)
method as the inner loop runs at most 6 times*/

float stripClosest(Point strip[], int size, float d)
{

/*Initialize the minimum distance as d*/

float min = d; 
    qsort(strip, size, sizeof(Point), compareY);

/*    Pick all points one by one and try the next points till the difference
    between y coordinates is smaller than d.
    This is a proven fact that this loop runs at most 6 times*/

    for (int i = 0; i < size; ++i)
        for (int j = i+1; j < size && (strip[j].y - strip[i].y) < min; ++j)
            if (dist(strip[i],strip[j]) < min)
                min = dist(strip[i], strip[j]);
    return min;
}

/*A recursive function to find the
smallest distance. The array P contains
all points sorted according to x coordinate*/

float closestUtil(Point P[], int n)
{

/*    If there are 2 or 3 points, then use brute force*/

    if (n <= 3)
        return bruteForce(P, n);

/*    Find the middle point*/

    int mid = n/2;
    Point midPoint = P[mid];

/*    Consider the vertical line passing
    through the middle point calculate
    the smallest distance dl on left
    of middle point and dr on right side*/

    float dl = closestUtil(P, mid);
    float dr = closestUtil(P + mid, n - mid);

/*    Find the smaller of two distances*/

    float d = min(dl, dr);

/*    Build an array strip[] that contains
    points close (closer than d)
    to the line passing through the middle point*/

    Point strip[n];
    int j = 0;
    for (int i = 0; i < n; i++)
        if (abs(P[i].x - midPoint.x) < d)
            strip[j] = P[i], j++;

/*    Find the closest points in strip.
    Return the minimum of d and closest
    distance is strip[]*/

    return min(d, stripClosest(strip, j, d) );
}

/*The main function that finds the smallest distance
This method mainly uses closestUtil()*/

float closest(Point P[], int n)
{
    qsort(P, n, sizeof(Point), compareX);

/*    Use recursive function closestUtil()
    to find the smallest distance*/

    return closestUtil(P, n);
}

/*Driver code*/

int main()
{
    Point P[] = {{2, 3}, {12, 30}, {40, 50}, {5, 1}, {12, 10}, {3, 4}};
    int n = sizeof(P) / sizeof(P[0]);
    cout << "The smallest distance is " << closest(P, n);
    return 0;
}

/*A C++ program to check if two given line segments intersect*/

#include <iostream>
using namespace std;
struct Point
{
    int x;
    int y;
};

/*Given three colinear points p, q, r, the function checks if
point q lies on line segment 'pr'*/

bool onSegment(Point p, Point q, Point r)
{
    if (q.x <= max(p.x, r.x) && q.x >= min(p.x, r.x) &&
        q.y <= max(p.y, r.y) && q.y >= min(p.y, r.y))
       return true;
    return false;
}

/*To find orientation of ordered triplet (p, q, r).
The function returns following values
0 --> p, q and r are colinear
1 --> Clockwise
2 --> Counterclockwise*/

int orientation(Point p, Point q, Point r)
{

/*www.geeksforgeeks.org/orientation-3-ordered-points/
See https:
    for details of below formula.*/

    int val = (q.y - p.y) * (r.x - q.x) -
              (q.x - p.x) * (r.y - q.y);

/*colinear*/

if (val == 0) return 0;

/*clock or counterclock wise*/

return (val > 0)? 1: 2; 
}

/*The main function that returns true if line segment 'p1q1'
and 'p2q2' intersect.*/

bool doIntersect(Point p1, Point q1, Point p2, Point q2)
{

/*    Find the four orientations needed for general and
    special cases*/

    int o1 = orientation(p1, q1, p2);
    int o2 = orientation(p1, q1, q2);
    int o3 = orientation(p2, q2, p1);
    int o4 = orientation(p2, q2, q1);

/*    General case*/

    if (o1 != o2 && o3 != o4)
        return true;

/*    Special Cases
    p1, q1 and p2 are colinear and p2 lies on segment p1q1*/

    if (o1 == 0 && onSegment(p1, p2, q1)) return true;

/*    p1, q1 and q2 are colinear and q2 lies on segment p1q1*/

    if (o2 == 0 && onSegment(p1, q2, q1)) return true;

/*    p2, q2 and p1 are colinear and p1 lies on segment p2q2*/

    if (o3 == 0 && onSegment(p2, p1, q2)) return true;

/*     p2, q2 and q1 are colinear and q1 lies on segment p2q2*/

    if (o4 == 0 && onSegment(p2, q1, q2)) return true;

/*Doesn't fall in any of the above cases*/

return false; 
}

/*Driver program to test above functions*/

int main()
{
    struct Point p1 = {1, 1}, q1 = {10, 1};
    struct Point p2 = {1, 2}, q2 = {10, 2};
    doIntersect(p1, q1, p2, q2)? cout << "Yes\n": cout << "No\n";
    p1 = {10, 0}, q1 = {0, 10};
    p2 = {0, 0}, q2 = {10, 10};
    doIntersect(p1, q1, p2, q2)? cout << "Yes\n": cout << "No\n";
    p1 = {-5, -5}, q1 = {0, 0};
    p2 = {1, 1}, q2 = {10, 10};
    doIntersect(p1, q1, p2, q2)? cout << "Yes\n": cout << "No\n";
    return 0;
}

#include <iostream>
using namespace std;
class gfg {

/*Returns the square root of n. Note that the function */

public:
    float squareRoot(float n)
    {

/*We are using n itself as initial approximation
          This can definitely be improved */

        float x = n;
        float y = 1;
        float e = 0.000001;

/* e decides the accuracy level*/

        while (x - y > e) {
            x = (x + y) / 2;
            y = n / x;
        }
        return x;
    }
};

/* Driver program to test above function*/

int main()
{
    gfg g;
    int n = 50;
    cout << "Square root of " << n << " is " << g.squareRoot(n);
    getchar();
}

/*C++ program to Multiply two integers without
using multiplication, division and bitwise
  operators, and no loops*/

#include<iostream>
using namespace std;
class GFG
{

/* function to multiply two numbers x and y*/

public : int multiply(int x, int y)
{

/* 0 multiplied with anything gives 0 */

    if(y == 0)
    return 0;

/* Add x one by one */

    if(y > 0 )
    return (x + multiply(x, y-1));

/* the case where y is negative */

    if(y < 0 )
    return -multiply(x, -y);
}
};

/*Driver code*/

int main()
{
    GFG g;
    cout << endl << g.multiply(5, -11);
    getchar();
    return 0;
}

/* Sample run of the Algo for V1 with capacity 3 and V2 with capacity 7
1. Fill V1:                               V1 = 3, V2 = 0
2. Transfer from V1 to V2, and fill V1:   V1 = 3, V2 = 3
2. Transfer from V1 to V2, and fill V1:   V1 = 3, V2 = 6
3. Transfer from V1 to V2, and empty V2:  V1 = 2, V2 = 0
4. Transfer from V1 to V2, and fill V1:   V1 = 3, V2 = 2
5. Transfer from V1 to V2, and fill V1:   V1 = 3, V2 = 5
6. Transfer from V1 to V2, and empty V2:  V1 = 1, V2 = 0
7. Stop as V1 now contains 1 litre.
Note that V2 was made empty in steps 3 and 6 because it became full */

#include <iostream>
using namespace std;

/*A utility function to get GCD of two numbers*/

int gcd(int a, int b) { return b? gcd(b, a % b) : a; }

/*Class to represent a Vessel*/

class Vessel
{

/*    A vessel has capacity, and current amount of water in it*/

    int capacity, current;
public:

/*    Constructor: initializes capacity as given, and current as 0*/

    Vessel(int capacity) { this->capacity = capacity; current = 0; }

/*    The main function to fill one litre in this vessel. Capacity of V2
    must be greater than this vessel and two capacities must be co-prime*/

    void makeOneLitre(Vessel &V2);

/*    Fills vessel with given amount and returns the amount of water 
    transferred to it. If the vessel becomes full, then the vessel 
    is made empty.*/

    int transfer(int amount);
};

/*The main function to fill one litre in this vessel. Capacity 
of V2 must be greater than this vessel and two capacities 
must be coprime*/

void Vessel:: makeOneLitre(Vessel &V2)
{

/*    solution exists iff a and b are co-prime*/

    if (gcd(capacity, V2.capacity) != 1)
        return;
    while (current != 1)
    {

/*        fill A (smaller vessel)*/

        if (current == 0)
            current = capacity;
        cout << "Vessel 1: " << current << "   Vessel 2: " 
             << V2.current << endl;

/*        Transfer water from V1 to V2 and reduce current of V1 by
          the amount equal to transferred water*/

        current = current - V2.transfer(current);
    }

/*    Finally, there will be 1 litre in vessel 1*/

    cout << "Vessel 1: " << current << "   Vessel 2: " 
         << V2.current << endl;
}

/*Fills vessel with given amount and returns the amount of water 
transferred to it. If the vessel becomes full, then the vessel 
is made empty*/

int Vessel::transfer(int amount)
{

/*    If the vessel can accommodate the given amount*/

    if (current + amount < capacity)
    {
        current += amount;
        return amount;
    }

/*    If the vessel cannot accommodate the given amount, then
    store the amount of water transferred*/

    int transferred = capacity - current;

/*    Since the vessel becomes full, make the vessel
    empty so that it can be filled again*/

    current = 0;
    return transferred;
}

/*Driver program to test above function*/

int main()
{

/*a must be smaller than b*/

int a = 3, b = 7;

/*    Create two vessels of capacities a and b*/

    Vessel V1(a), V2(b);

/*    Get 1 litre in first vessel*/

    V1.makeOneLitre(V2);
    return 0;
}

/*C++ program to find whether a given
number is a power of 4 or not*/

#include<iostream>
using namespace std;
#define bool int
class GFG
{

/* Function to check if x is power of 4*/

public : bool isPowerOfFour(int n)
{
    if(n == 0)
        return 0;
    while(n != 1)
    {
        if(n % 4 != 0)
            return 0;
        n = n / 4;
    }
    return 1;
}
};

/*Driver code*/

int main()
{
    GFG g;
    int test_no = 64;
    if(g.isPowerOfFour(test_no))
        cout << test_no << " is a power of 4";
    else
        cout << test_no << "is not a power of 4";
    getchar();
}

/*C++ program to Compute the minimum
or maximum of two integers without
branching*/

#include<iostream>
using namespace std;
class gfg
{

/*Function to find minimum of x and y*/

    public:
    int min(int x, int y)
    {
        return y ^ ((x ^ y) & -(x < y));
    }

/*Function to find maximum of x and y*/

    int max(int x, int y)
    {
        return x ^ ((x ^ y) & -(x < y));
    }
    };

