/*C++ program for Position
of rightmost set bit*/

#include <iostream>
#include <math.h>
using namespace std;
class gfg
{
public:
unsigned int getFirstSetBitPos(int n)
{
    return log2(n & -n) + 1;
}
};

/*Driver code*/

int main()
{
    gfg g;
    int n = 12;
    cout << g.getFirstSetBitPos(n);
    return 0;
}

#include <iostream>
using namespace std;

#include<stdio.h>
#include<stdlib.h>

/*An AVL tree node*/

struct node
{
    int key;
    struct node *left;
    struct node *right;
    int height;

/*    size of the tree rooted
    with this node*/

    int size;
};

/*A utility function to get
maximum of two integers*/

int max(int a, int b);

/*A utility function to get
height of the tree rooted with N*/

int height(struct node *N)
{
    if (N == NULL)
        return 0;

    return N->height;
}

/*A utility function to size
of the tree of rooted with N*/

int size(struct node *N)
{
    if (N == NULL)
        return 0;

    return N->size;
}

/*A utility function to
get maximum of two integers*/

int max(int a, int b)
{
    return (a > b)? a : b;
}

/*Helper function that allocates a
new node with the given key and
NULL left and right pointers.*/

struct node* newNode(int key)
{
    struct node* node = (struct node*)
                        malloc(sizeof(struct node));
    node->key   = key;
    node->left   = NULL;
    node->right  = NULL;

/*    New node is initially added at leaf*/

    node->height = 1; 
    node->size = 1;
    return(node);
}

/*A utility function to right rotate
subtree rooted with y*/

struct node *rightRotate(struct node *y)
{
    struct node *x = y->left;
    struct node *T2 = x->right;

/*    Perform rotation*/

    x->right = y;
    y->left = T2;

/*    Update heights*/

    y->height = max(height(y->left),
                    height(y->right)) + 1;
    x->height = max(height(x->left),
                    height(x->right)) + 1;

/*    Update sizes*/

    y->size = size(y->left) + size(y->right) + 1;
    x->size = size(x->left) + size(x->right) + 1;

/*    Return new root*/

    return x;
}

/*A utility function to left rotate
subtree rooted with x*/

struct node *leftRotate(struct node *x)
{
    struct node *y = x->right;
    struct node *T2 = y->left;

/*    Perform rotation*/

    y->left = x;
    x->right = T2;

/*      Update heights*/

    x->height = max(height(x->left),
                    height(x->right)) + 1;
    y->height = max(height(y->left),
                    height(y->right)) + 1;

/*    Update sizes*/

    x->size = size(x->left) + size(x->right) + 1;
    y->size = size(y->left) + size(y->right) + 1;

/*    Return new root*/

    return y;
}

/*Get Balance factor of node N*/

int getBalance(struct node *N)
{
    if (N == NULL)
        return 0;

    return height(N->left) - height(N->right);
}

/*Inserts a new key to the tree rotted with
node. Also, updates *count to contain count
of smaller elements for the new key*/

struct node* insert(struct node* node, int key,
                    int *count)
{

/*    1. Perform the normal BST rotation*/

    if (node == NULL)
        return(newNode(key));

    if (key < node->key)
        node->left  = insert(node->left, key, count);
    else
    {
        node->right = insert(node->right, key, count);

/*        UPDATE COUNT OF SMALLER ELEMENTS FOR KEY*/

        *count = *count + size(node->left) + 1;
    }

/*    2.Update height and size of this ancestor node*/

    node->height = max(height(node->left),
                       height(node->right)) + 1;
    node->size   = size(node->left) +
                   size(node->right) + 1;

/*    3. Get the balance factor of this
    ancestor node to check whether this
    node became unbalanced*/

    int balance = getBalance(node);

/*    If this node becomes unbalanced,
    then there are 4 cases*/

/*    Left Left Case*/

    if (balance > 1 && key < node->left->key)
        return rightRotate(node);

/*    Right Right Case*/

    if (balance < -1 && key > node->right->key)
        return leftRotate(node);

/*    Left Right Case*/

    if (balance > 1 && key > node->left->key)
    {
        node->left =  leftRotate(node->left);
        return rightRotate(node);
    }

/*    Right Left Case*/

    if (balance < -1 && key < node->right->key)
    {
        node->right = rightRotate(node->right);
        return leftRotate(node);
    }

/*    Return the (unchanged) node pointer*/

    return node;
}

/*The following function updates the
countSmaller array to contain count of
smaller elements on right side.*/

void constructLowerArray(int arr[], int countSmaller[],
                         int n)
{
    int i, j;
    struct node *root = NULL;

/*    Initialize all the counts in
    countSmaller array as 0*/

    for(i = 0; i < n; i++)
        countSmaller[i] = 0;

/*    Starting from rightmost element,
    insert all elements one by one in
    an AVL tree and get the count of
    smaller elements*/

    for(i = n - 1; i >= 0; i--)
    {
        root = insert(root, arr[i], &countSmaller[i]);
    }
}

/*Utility function that prints out an
array on a line*/

void printArray(int arr[], int size)
{
    int i;
    cout << "\n";

    for(i = 0; i < size; i++)
        cout << arr[i] <<" ";
}

/*Driver code*/

int main()
{
    int arr[] = {10, 6, 15, 20, 30, 5, 7};
    int n = sizeof(arr)/sizeof(arr[0]);

    int *low = (int *)malloc(sizeof(int)*n);

    constructLowerArray(arr, low, n);

    cout <<"Following is the constructed smaller count array";
    printArray(low, n);

    return 0;
}

/*A C++ program to check if any two intervals overlap*/

#include <algorithm>
#include <iostream>
using namespace std;

/*An interval has start time and end time*/

struct Interval {
    int start;
    int end;
};

/*Compares two intervals according to their staring time.
This is needed for sorting the intervals using library
goo.gl/iGspV
function std::sort(). See http:*/

bool compareInterval(Interval i1, Interval i2)
{
    return (i1.start < i2.start) ? true : false;
}

/*Function to check if any two intervals overlap*/

bool isIntersect(Interval arr[], int n)
{

/*    Sort intervals in increasing order of start time*/

    sort(arr, arr + n , compareInterval);

/*    In the sorted array, if start time of an interval
    is less than end of previous interval, then there
    is an overlap*/

    for (int i = 1; i < n; i++)
        if (arr[i - 1].end > arr[i].start)
            return true;

/*    If we reach here, then no overlap*/

    return false;
}

/*Driver program*/

int main()
{
    Interval arr1[] = { { 1, 3 }, { 7, 9 }, { 4, 6 }, { 10, 13 } };
    int n1 = sizeof(arr1) / sizeof(arr1[0]);
    isIntersect(arr1, n1) ? cout << "Yes\n" : cout << "No\n";

    Interval arr2[] = { { 6, 8 }, { 1, 3 }, { 2, 4 }, { 4, 7 } };
    int n2 = sizeof(arr2) / sizeof(arr2[0]);
    isIntersect(arr2, n2) ? cout << "Yes\n" : cout << "No\n";

    return 0;
}

/*A C++ program to check if any two intervals overlap*/

#include <algorithm>
#include <iostream>
using namespace std;

/*An interval has start time and end time*/

struct Interval {
    int start;
    int end;
};

/*Function to check if any two intervals overlap*/

bool isIntersect(Interval arr[], int n)
{

    int max_ele = 0;

/*    Find the overall maximum element*/

    for (int i = 0; i < n; i++) {
        if (max_ele < arr[i].end)
            max_ele = arr[i].end;
    }

/*    Initialize an array of size max_ele*/

    int aux[max_ele + 1] = { 0 };
    for (int i = 0; i < n; i++) {

/*        starting point of the interval*/

        int x = arr[i].start;

/*        end point of the interval*/

        int y = arr[i].end;
        aux[x]++, aux[y + 1]--;
    }
    for (int i = 1; i <= max_ele; i++) {

/*        Calculating the prefix Sum*/

        aux[i] += aux[i - 1];

/*        Overlap*/

        if (aux[i] > 1)
            return true;
    }

/*    If we reach here, then no Overlap*/

    return false;
}

/*Driver program*/

int main()
{
    Interval arr1[] = { { 1, 3 }, { 7, 9 }, { 4, 6 }, { 10, 13 } };
    int n1 = sizeof(arr1) / sizeof(arr1[0]);

    isIntersect(arr1, n1) ? cout << "Yes\n" : cout << "No\n";

    Interval arr2[] = { { 6, 8 }, { 1, 3 }, { 2, 4 }, { 4, 7 } };
    int n2 = sizeof(arr2) / sizeof(arr2[0]);
    isIntersect(arr2, n2) ? cout << "Yes\n" : cout << "No\n";

    return 0;
}

/*C++ implementation to increment values in the
given range by a value d for multiple queries*/

#include <bits/stdc++.h>

using namespace std;

/*structure to store the (start, end) index pair for
each query*/

struct query {
    int start, end;
};

/*function to increment values in the given range
by a value d for multiple queries*/

void incrementByD(int arr[], struct query q_arr[],
                  int n, int m, int d)
{
    int sum[n];
    memset(sum, 0, sizeof(sum));

/*    for each (start, end) index pair perform the
    following operations on 'sum[]'*/

    for (int i = 0; i < m; i++) {

/*        increment the value at index 'start' by
        the given value 'd' in 'sum[]'*/

        sum[q_arr[i].start] += d;

/*        if the index '(end+1)' exists then decrement
        the value at index '(end+1)' by the given
        value 'd' in 'sum[]'*/

        if ((q_arr[i].end + 1) < n)
            sum[q_arr[i].end + 1] -= d;
    }

/*    Now, perform the following operations:
    accumulate values in the 'sum[]' array and
    then add them to the corresponding indexes
    in 'arr[]'*/

    arr[0] += sum[0];
    for (int i = 1; i < n; i++) {
        sum[i] += sum[i - 1];
        arr[i] += sum[i];
    }
}

/*function to print the elements of the given array*/

void printArray(int arr[], int n)
{
    for (int i = 0; i < n; i++)
        cout << arr[i] << " ";
}

/*Driver program to test above*/

int main()
{
    int arr[] = { 3, 5, 4, 8, 6, 1 };
    struct query q_arr[] = { { 0, 3 }, { 4, 5 }, { 1, 4 },
                                       { 0, 1 }, { 2, 5 } };
    int n = sizeof(arr) / sizeof(arr[0]);
    int m = sizeof(q_arr) / sizeof(q_arr[0]);
    int d = 2;

    cout << "Original Array:\n";
    printArray(arr, n);

/*    modifying the array for multiple queries*/

    incrementByD(arr, q_arr, n, m, d);

    cout << "\nModified Array:\n";
    printArray(arr, n);

    return 0;
}

/*C++ code to find number of distinct numbers
in a subarray*/

#include<bits/stdc++.h>
using namespace std;

const int MAX = 1000001;

/*structure to store queries*/

struct Query
{
    int l, r, idx;
};

/*cmp function to sort queries according to r*/

bool cmp(Query x, Query y)
{
    return x.r < y.r;
}

/*updating the bit array*/

void update(int idx, int val, int bit[], int n)
{
    for (; idx <= n; idx += idx&-idx)
        bit[idx] += val;
}

/*querying the bit array*/

int query(int idx, int bit[], int n)
{
    int sum = 0;
    for (; idx>0; idx-=idx&-idx)
        sum += bit[idx];
    return sum;
}

void answeringQueries(int arr[], int n, Query queries[], int q)
{

/*    initialising bit array*/

    int bit[n+1];
    memset(bit, 0, sizeof(bit));

/*    holds the rightmost index of any number
    as numbers of a[i] are less than or equal to 10^6*/

    int last_visit[MAX];
    memset(last_visit, -1, sizeof(last_visit));

/*    answer for each query*/

    int ans[q];
    int query_counter = 0;
    for (int i=0; i<n; i++)
    {

/*        If last visit is not -1 update -1 at the
        idx equal to last_visit[arr[i]]*/

        if (last_visit[arr[i]] !=-1)
            update (last_visit[arr[i]] + 1, -1, bit, n);

/*        Setting last_visit[arr[i]] as i and updating
        the bit array accordingly*/

        last_visit[arr[i]] = i;
        update(i + 1, 1, bit, n);

/*        If i is equal to r of any query  store answer
        for that query in ans[]*/

        while (query_counter < q && queries[query_counter].r == i)
        {
            ans[queries[query_counter].idx] =
                     query(queries[query_counter].r + 1, bit, n)-
                     query(queries[query_counter].l, bit, n);
            query_counter++;
        }
    }

/*    print answer for each query*/

    for (int i=0; i<q; i++)
        cout << ans[i] << endl;
}

/*driver code*/

int main()
{
    int a[] = {1, 1, 2, 1, 3};
    int n = sizeof(a)/sizeof(a[0]);
    Query queries[3];
    queries[0].l = 0;
    queries[0].r = 4;
    queries[0].idx = 0;
    queries[1].l = 1;
    queries[1].r = 3;
    queries[1].idx = 1;
    queries[2].l = 2;
    queries[2].r = 4;
    queries[2].idx = 2;
    int q = sizeof(queries)/sizeof(queries[0]);
    sort(queries, queries+q, cmp);
    answeringQueries(a, n, queries, q);
    return 0;
}

/*Efficient CPP program to sort given list in order
elements are appearing in an array*/

#include <bits/stdc++.h>
using namespace std;

/*Linked list node*/

struct Node {
    int data;
    struct Node* next;
};

/*function prototype for printing the list*/

void printList(struct Node*);

/*Function to insert a node at the
beginning of the linked list*/

void push(struct Node** head_ref, int new_data)
{
    struct Node* new_node = new Node;
    new_node -> data = new_data;
    new_node -> next = *head_ref;
    *head_ref = new_node;
}

/*function to print the linked list*/

void printList(struct Node* head)
{
    while (head != NULL) {
        cout << head -> data << " -> ";
        head = head -> next;
    }
}

/*Function that sort list in order of apperaing
elements in an array*/

void sortlist(int arr[], int N, struct Node* head)
{

/*    Store frequencies of elements in a
    hash table.*/

    unordered_map<int, int> hash;
    struct Node* temp = head;
    while (temp) {       
        hash[temp -> data]++;
        temp = temp -> next;
    }

    temp = head;

/*    One by one put elements in lis according
    to their appearance in array*/

    for (int i = 0; i < N; i++) {

/*        Update 'frequency' nodes with value
        equal to arr[i]*/

        int frequency = hash[arr[i]];
        while (frequency--) {

/*            Modify list data as element
            appear in an array*/

            temp -> data = arr[i];
            temp = temp -> next;
        }
    }
}

/*Driver Code*/

int main()
{
    struct Node* head = NULL;
    int arr[] = { 5, 1, 3, 2, 8 };
    int N = sizeof(arr) / sizeof(arr[0]);

/*    creating the linked list*/

    push(&head, 3);
    push(&head, 2);
    push(&head, 5);
    push(&head, 8);
    push(&head, 5);
    push(&head, 2);
    push(&head, 1);

/*    Function call to sort the list in order
    elements are apperaing in an array*/

    sortlist(arr, N, head);

/*    print the modified linked list*/

    cout << "Sorted List:" << endl;
    printList(head);
    return 0;
}

/*C++ program to find 4 elements
with given sum*/

#include <bits/stdc++.h>
using namespace std;

/*The following structure is needed
to store pair sums in aux[]*/

class pairSum {
public:

/*    index (int A[]) of first element in pair*/

    int first;

/*    index of second element in pair*/

    int sec;

/*    sum of the pair*/

    int sum;
};

/*Following function is needed
for library function qsort()*/

int compare(const void* a, const void* b)
{
    return ((*(pairSum*)a).sum - (*(pairSum*)b).sum);
}

/*Function to check if two given pairs
have any common element or not*/

bool noCommon(pairSum a, pairSum b)
{
    if (a.first == b.first || a.first == b.sec
        || a.sec == b.first || a.sec == b.sec)
        return false;
    return true;
}

/*The function finds four
elements with given sum X*/

void findFourElements(int arr[], int n, int X)
{
    int i, j;

/*    Create an auxiliary array
    to store all pair sums*/

    int size = (n * (n - 1)) / 2;
    pairSum aux[size];

/*    Generate all possible pairs
    from A[] and store sums
    of all possible pairs in aux[]*/

    int k = 0;
    for (i = 0; i < n - 1; i++) {
        for (j = i + 1; j < n; j++) {
            aux[k].sum = arr[i] + arr[j];
            aux[k].first = i;
            aux[k].sec = j;
            k++;
        }
    }

/*    Sort the aux[] array using
    library function for sorting*/

    qsort(aux, size, sizeof(aux[0]), compare);

/*    Now start two index variables
    from two corners of array
    and move them toward each other.*/

    i = 0;
    j = size - 1;
    while (i < size && j >= 0) {
        if ((aux[i].sum + aux[j].sum == X)
            && noCommon(aux[i], aux[j])) {
            cout << arr[aux[i].first] << ", "
                 << arr[aux[i].sec] << ", "
                 << arr[aux[j].first] << ", "
                 << arr[aux[j].sec] << endl;
            return;
        }
        else if (aux[i].sum + aux[j].sum < X)
            i++;
        else
            j--;
    }
}

/*Driver code*/

int main()
{
    int arr[] = { 10, 20, 30, 40, 1, 2 };
    int n = sizeof(arr) / sizeof(arr[0]);
    int X = 91;

/*    Function Call*/

    findFourElements(arr, n, X);
    return 0;
}

/*Recursive C++ program to search
an element in linked list*/

#include <bits/stdc++.h>
using namespace std;

/* Link list node */

struct Node
{
    int key;
    struct Node* next;
};

/* Given a reference (pointer to pointer) to the head
of a list and an int, push a new node on the front
of the list. */

void push(struct Node** head_ref, int new_key)
{

/* allocate node */

    struct Node* new_node =
            (struct Node*) malloc(sizeof(struct Node));
    new_node->key = new_key;

/* link the old list off the new node */

    new_node->next = (*head_ref);

/* move the head to point to the new node */

    (*head_ref) = new_node;
}

/* Checks whether the value x is present in linked list */

bool search(struct Node* head, int x)
{

/*    Base case*/

    if (head == NULL)
        return false;

/*    If key is present in current node, return true*/

    if (head->key == x)
        return true;

/*    Recur for remaining list*/

    return search(head->next, x);
}

/* Driver code*/

int main()
{

/* Start with the empty list */

    struct Node* head = NULL;
    int x = 21;

/* Use push() to construct below list
    14->21->11->30->10 */

    push(&head, 10);
    push(&head, 30);
    push(&head, 11);
    push(&head, 21);
    push(&head, 14);

    search(head, 21)? cout << "Yes" : cout << "No";
    return 0;
}

/*C++ program to reverse a linked list using two pointers.*/

#include <bits/stdc++.h>
using namespace std;
typedef uintptr_t ut;

/* Link list node */

struct Node {
    int data;
    struct Node* next;
};

/* Function to reverse the linked list using 2 pointers */

void reverse(struct Node** head_ref)
{
    struct Node* prev = NULL;
    struct Node* current = *head_ref;

/*    at last prev points to new head*/

    while (current != NULL) {

/*        This expression evaluates from left to right
        current->next = prev, changes the link fron
        next to prev node
        prev = current, moves prev to current node for
        next reversal of node
        This example of list will clear it more 1->2->3->4
        initially prev = 1, current = 2
        Final expression will be current = 1^2^3^2^1,
        as we know that bitwise XOR of two same
        numbers will always be 0 i.e; 1^1 = 2^2 = 0
        After the evaluation of expression current = 3 that
        means it has been moved by one node from its
        previous position*/

        current = (struct Node*)((ut)prev ^ (ut)current ^ (ut)(current->next) ^ (ut)(current->next = prev) ^ (ut)(prev = current));
    }

    *head_ref = prev;
}

/* Function to push a node */

void push(struct Node** head_ref, int new_data)
{

/* allocate node */

    struct Node* new_node = (struct Node*)malloc(sizeof(struct Node));

/* put in the data  */

    new_node->data = new_data;

/* link the old list off the new node */

    new_node->next = (*head_ref);

/* move the head to point to the new node */

    (*head_ref) = new_node;
}

/* Function to print linked list */

void printList(struct Node* head)
{
    struct Node* temp = head;
    while (temp != NULL) {
        printf("%d  ", temp->data);
        temp = temp->next;
    }
}

/* Driver program to test above function*/

int main()
{

/* Start with the empty list */

    struct Node* head = NULL;

    push(&head, 20);
    push(&head, 4);
    push(&head, 15);
    push(&head, 85);

    printf("Given linked list\n");
    printList(head);
    reverse(&head);
    printf("\nReversed Linked list \n");
    printList(head);
    return 0;
}

/*C++ program to reverse a linked list using two pointers.*/

#include <bits/stdc++.h>
using namespace std;
typedef uintptr_t ut;

/* Link list node */

struct Node {
    int data;
    struct Node* next;
};

/* Function to reverse the linked list using 2 pointers */

void reverse(struct Node** head_ref)
{
    struct Node* current = *head_ref;
    struct Node* next;
    while (current->next != NULL) {
        next = current->next;
        current->next = next->next;
        next->next = (*head_ref);
        *head_ref = next;
    }
}

/* Function to push a node */

void push(struct Node** head_ref, int new_data)
{
    struct Node* new_node = new Node;
    new_node->data = new_data;
    new_node->next = (*head_ref);
    (*head_ref) = new_node;
}

/* Function to print linked list */

void printList(struct Node* head)
{
    struct Node* temp = head;
    while (temp != NULL) {
        printf("%d  ", temp->data);
        temp = temp->next;
    }
}

