int main()
{

/* Start with the empty list */

    struct Node* head = NULL;

    push(&head, 20);
    push(&head, 4);
    push(&head, 15);
    push(&head, 85);

    printf("Given linked list\n");
    printList(head);
    reverse(&head);
    printf("\nReversed Linked list \n");
    printList(head);
    return 0;
}

/*CPP program to rearrange nodes
as alternate odd even nodes in
a Singly Linked List*/

#include <bits/stdc++.h>
using namespace std;

/*Structure node*/

struct Node {
    int data;
    struct Node* next;
};

/*A utility function to print
linked list*/

void printList(struct Node* node)
{
    while (node != NULL) {
        cout << node->data << " ";
        node = node->next;
    }
    cout << endl;
}

/*Function to create newNode
in a linkedlist*/

Node* newNode(int key)
{
    Node* temp = new Node;
    temp->data = key;
    temp->next = NULL;
    return temp;
}

/*Function to insert at beginning*/

Node* insertBeg(Node* head, int val)
{
    Node* temp = newNode(val);
    temp->next = head;
    head = temp;
    return head;
}

/*Function to rearrange the
odd and even nodes*/

void rearrangeOddEven(Node* head)
{
    stack<Node*> odd;
    stack<Node*> even;
    int i = 1;

    while (head != nullptr) {

        if (head->data % 2 != 0 && i % 2 == 0) {

/*            Odd Value in Even Position
            Add pointer to current node
            in odd stack*/

            odd.push(head);
        }

        else if (head->data % 2 == 0 && i % 2 != 0) {

/*            Even Value in Odd Position
            Add pointer to current node
            in even stack*/

            even.push(head);
        }

        head = head->next;
        i++;
    }

    while (!odd.empty() && !even.empty()) {

/*        Swap Data at the top of two stacks*/

        swap(odd.top()->data, even.top()->data);
        odd.pop();
        even.pop();
    }
}

/*Driver code*/

int main()
{
    Node* head = newNode(8);
    head = insertBeg(head, 7);
    head = insertBeg(head, 6);
    head = insertBeg(head, 5);
    head = insertBeg(head, 3);
    head = insertBeg(head, 2);
    head = insertBeg(head, 1);

    cout << "Linked List:" << endl;
    printList(head);
    rearrangeOddEven(head);

    cout << "Linked List after "
         << "Rearranging:" << endl;
    printList(head);

    return 0;
}

/*Cpp program to rearrange nodes
as alternate odd even nodes in
a Singly Linked List*/

#include <bits/stdc++.h>
using namespace std;

/*Structure node*/

struct Node {
    int data;
    struct Node* next;
};

/*A utility function to print
linked list*/

void printList(struct Node* node)
{
    while (node != NULL) {
        cout << node->data << " ";
        node = node->next;
    }
    cout << endl;
}

/*Function to create newNode
in a linkedlist*/

Node* newNode(int key)
{
    Node* temp = new Node;
    temp->data = key;
    temp->next = NULL;
    return temp;
}

/*Function to insert at beginning*/

Node* insertBeg(Node* head, int val)
{
    Node* temp = newNode(val);
    temp->next = head;
    head = temp;
    return head;
}

/*Function to rearrange the
odd and even nodes*/

void rearrange(Node** head)
{

/*    Step 1: Segregate even and odd nodes
    Step 2: Split odd and even lists
    Step 3: Merge even list into odd list*/

    Node* even;
    Node *temp, *prev_temp;
    Node *i, *j, *k, *l, *ptr;

/*    Step 1: Segregate Odd and Even Nodes*/

    temp = (*head)->next;
    prev_temp = *head;

    while (temp != nullptr) {

/*        Backup next pointer of temp*/

        Node* x = temp->next;

/*        If temp is odd move the node
        to beginning of list*/

        if (temp->data % 2 != 0) {
            prev_temp->next = x;
            temp->next = (*head);
            (*head) = temp;
        }
        else {
            prev_temp = temp;
        }

/*        Advance Temp Pointer*/

        temp = x;
    }

/*    Step 2
    Split the List into Odd and even*/

    temp = (*head)->next;
    prev_temp = (*head);

    while (temp != nullptr && temp->data % 2 != 0) {
        prev_temp = temp;
        temp = temp->next;
    }

    even = temp;

/*    End the odd List (Make last node null)*/

    prev_temp->next = nullptr;

/*    Step 3:
    Merge Even List into odd*/

    i = *head;
    j = even;

    while (j != nullptr && i != nullptr) {

/*        While both lists are not
        exhausted Backup next
        pointers of i and j*/

        k = i->next;
        l = j->next;

        i->next = j;
        j->next = k;

/*        ptr points to the latest node added*/

        ptr = j;

/*        Advance i and j pointers*/

        i = k;
        j = l;
    }

    if (i == nullptr) {

/*        Odd list exhausts before even,
        append remainder of even list to odd.*/

        ptr->next = j;
    }

/*    The case where even list exhausts before
    odd list is automatically handled since we
    merge the even list into the odd list*/

}

/*Driver Code*/

int main()
{
    Node* head = newNode(8);
    head = insertBeg(head, 7);
    head = insertBeg(head, 6);
    head = insertBeg(head, 3);
    head = insertBeg(head, 5);
    head = insertBeg(head, 1);
    head = insertBeg(head, 2);
    head = insertBeg(head, 10);

    cout << "Linked List:" << endl;
    printList(head);
    cout << "Rearranged List" << endl;
    rearrange(&head);
    printList(head);
}

/*An iterative C++ program to check if
two linked lists are identical or not*/

#include<bits/stdc++.h>
using namespace std;

/* Structure for a linked list node */

struct Node
{
    int data;
    struct Node *next;
};

/* Returns true if linked lists a and b
are identical, otherwise false */

bool areIdentical(struct Node *a,
                  struct Node *b)
{
    while (a != NULL && b != NULL)
    {
        if (a->data != b->data)
            return false;

/* If we reach here, then a and b are
        not NULL and their data is same, so
        move to next nodes in both lists */

        a = a->next;
        b = b->next;
    }

/*    If linked lists are identical, then
    'a' and 'b' must be NULL at this point.*/

    return (a == NULL && b == NULL);
}

/* UTILITY FUNCTIONS TO TEST fun1() and fun2() */

/* Given a reference (pointer to pointer) to the
head of a list and an int, push a new node on the
front of the list. */

void push(struct Node** head_ref, int new_data)
{

/* allocate node  put in the data */

    struct Node* new_node =
        (struct Node*) malloc(sizeof(struct Node));
    new_node->data = new_data;

/* link the old list off the new node */

    new_node->next = (*head_ref);

/* move the head to point to the new node */

    (*head_ref) = new_node;
}

/*Driver Code*/

int main()
{

/* The constructed linked lists are :
    a: 3->2->1
    b: 3->2->1 */

    struct Node *a = NULL;
    struct Node *b = NULL;
    push(&a, 1);
    push(&a, 2);
    push(&a, 3);
    push(&b, 1);
    push(&b, 2);
    push(&b, 3);

    if(areIdentical(a, b))
        cout << "Identical";
    else
        cout << "Not identical";

    return 0;
}

/*C++ program to rotate
a linked list counter clock wise*/


#include <bits/stdc++.h>
using namespace std;

/* Link list node */

class Node {
public:
    int data;
    Node* next;
};

/*This function rotates a linked list
counter-clockwise and updates the
head. The function assumes that k is
smaller than size of linked list.*/

void rotate(Node** head_ref, int k)
{
    if (k == 0)
        return;

/*    Let us understand the below
    code for example k = 4 and
    list = 10->20->30->40->50->60.*/

    Node* current = *head_ref;

/*    Traverse till the end.*/

    while (current->next != NULL)
        current = current->next;

    current->next = *head_ref;
    current = *head_ref;

/*    traverse the linked list to k-1 position which
    will be last element for rotated array.*/

    for (int i = 0; i < k - 1; i++)
        current = current->next;

/*    update the head_ref and last element pointer to NULL*/

    *head_ref = current->next;
    current->next = NULL;
}

/* UTILITY FUNCTIONS */

/* Function to push a node */

void push(Node** head_ref, int new_data)
{

/* allocate node */

    Node* new_node = new Node();

/* put in the data */

    new_node->data = new_data;

/* link the old list off the new node */

    new_node->next = (*head_ref);

/* move the head to point to the new node */

    (*head_ref) = new_node;
}

/* Function to print linked list */

void printList(Node* node)
{
    while (node != NULL) {
        cout << node->data << " ";
        node = node->next;
    }
}

/* Driver code*/

int main(void)
{

/* Start with the empty list */

    Node* head = NULL;

/*    create a list 10->20->30->40->50->60*/

    for (int i = 60; i > 0; i -= 10)
        push(&head, i);

    cout << "Given linked list \n";
    printList(head);
    rotate(&head, 4);

    cout << "\nRotated Linked list \n";
    printList(head);

    return (0);
}

/*C++ Program to sort a linked list 0s, 1s or 2s*/

#include <bits/stdc++.h>
using namespace std;

/* Link list node */

class Node
{
    public:
    int data;
    Node* next;
};

/*Function to sort a linked list of 0s, 1s and 2s*/

void sortList(Node *head)
{

/*Initialize count of '0', '1' and '2' as 0*/

int count[3] = {0, 0, 0}; 
    Node *ptr = head;

/* count total number of '0', '1' and '2'
    * count[0] will store total number of '0's
    * count[1] will store total number of '1's
    * count[2] will store total number of '2's */

    while (ptr != NULL)
    {
        count[ptr->data] += 1;
        ptr = ptr->next;
    }

    int i = 0;
    ptr = head;

/* Let say count[0] = n1, count[1] = n2 and count[2] = n3
    * now start traversing list from head node,
    * 1) fill the list with 0, till n1 > 0
    * 2) fill the list with 1, till n2 > 0
    * 3) fill the list with 2, till n3 > 0 */

    while (ptr != NULL)
    {
        if (count[i] == 0)
            ++i;
        else
        {
            ptr->data = i;
            --count[i];
            ptr = ptr->next;
        }
    }
}

/* Function to push a node */

void push (Node** head_ref, int new_data)
{

/* allocate node put in the data */

    Node* new_node = new Node();
    new_node->data = new_data;

/* link the old list off the new node */

    new_node->next = (*head_ref);

/* move the head to point to the new node */

    (*head_ref) = new_node;
}

/* Function to print linked list */

void printList(Node *node)
{
    while (node != NULL)
    {
        cout << node->data << " ";
        node = node->next;
    }
    cout << endl;
}

/* Driver code*/

int main(void)
{

/* Constructed Linked List is 1->2->3->4->5->6->7->
           8->8->9->null */

    Node *head = NULL;
    push(&head, 0);
    push(&head, 1);
    push(&head, 0);
    push(&head, 2);
    push(&head, 1);
    push(&head, 1);
    push(&head, 2);
    push(&head, 1);
    push(&head, 2);

    cout << "Linked List Before Sorting\n";
    printList(head);

    sortList(head);

    cout << "Linked List After Sorting\n";
    printList(head);

    return 0;
}

/*C++ code to rearrange linked list in place*/

#include <bits/stdc++.h>

using namespace std;

struct node {
    int data;
    struct node* next;
};
typedef struct node Node;

/*function for rearranging a linked list with high and low
value.*/

void rearrange(Node* head)
{

/*Base case.*/

if (head == NULL) 
        return;

/*    two pointer variable.*/

    Node *prev = head, *curr = head->next;

    while (curr) {

/*        swap function for swapping data.*/

        if (prev->data > curr->data)
            swap(prev->data, curr->data);

/*        swap function for swapping data.*/

        if (curr->next && curr->next->data > curr->data)
            swap(curr->next->data, curr->data);

        prev = curr->next;

        if (!curr->next)
            break;
        curr = curr->next->next;
    }
}

/*function to insert a node in the linked list at the
beginning.*/

void push(Node** head, int k)
{
    Node* tem = (Node*)malloc(sizeof(Node));
    tem->data = k;
    tem->next = *head;
    *head = tem;
}

/*function to display node of linked list.*/

void display(Node* head)
{
    Node* curr = head;
    while (curr != NULL) {
        printf("%d ", curr->data);
        curr = curr->next;
    }
}

