int main()
{

    Node* head = NULL;

/*    let create a linked list.
    9 -> 6 -> 8 -> 3 -> 7*/

    push(&head, 7);
    push(&head, 3);
    push(&head, 8);
    push(&head, 6);
    push(&head, 9);

    rearrange(head);

    display(head);

    return 0;
}

/*C++ program to rearrange a linked list in such a
way that all odd positioned node are stored before
all even positioned nodes*/

#include<bits/stdc++.h>
using namespace std;

/*Linked List Node*/

class Node
{
    public:
    int data;
    Node* next;
};

/*A utility function to create a new node*/

Node* newNode(int key)
{
    Node *temp = new Node;
    temp->data = key;
    temp->next = NULL;
    return temp;
}

/*Rearranges given linked list such that all even
positioned nodes are before odd positioned.
Returns new head of linked List.*/

Node *rearrangeEvenOdd(Node *head)
{

/*    Corner case*/

    if (head == NULL)
        return NULL;

/*    Initialize first nodes of even and
    odd lists*/

    Node *odd = head;
    Node *even = head->next;

/*    Remember the first node of even list so
    that we can connect the even list at the
    end of odd list.*/

    Node *evenFirst = even;

    while (1)
    {

/*        If there are no more nodes, then connect
        first node of even list to the last node
        of odd list*/

        if (!odd || !even || !(even->next))
        {
            odd->next = evenFirst;
            break;
        }

/*        Connecting odd nodes*/

        odd->next = even->next;
        odd = even->next;

/*        If there are NO more even nodes after
        current odd.*/

        if (odd->next == NULL)
        {
            even->next = NULL;
            odd->next = evenFirst;
            break;
        }

/*        Connecting even nodes*/

        even->next = odd->next;
        even = odd->next;
    }

    return head;
}

/*A utility function to print a linked list*/

void printlist(Node * node)
{
    while (node != NULL)
    {
        cout << node->data << "->";
        node = node->next;
    }
    cout << "NULL" << endl;
}

/*Driver code*/

int main(void)
{
    Node *head = newNode(1);
    head->next = newNode(2);
    head->next->next = newNode(3);
    head->next->next->next = newNode(4);
    head->next->next->next->next = newNode(5);

    cout << "Given Linked List\n";
    printlist(head);

    head = rearrangeEvenOdd(head);

    cout << "Modified Linked List\n";
    printlist(head);

    return 0;
}

/*Recursive C++ program to add 1 to a linked list*/

#include <bits/stdc++.h>

/* Linked list node */

struct Node {
    int data;
    Node* next;
};

/* Function to create a new node with given data */

Node* newNode(int data)
{
    Node* new_node = new Node;
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

/*Recursively add 1 from end to beginning and returns
carry after all nodes are processed.*/

int addWithCarry(Node* head)
{

/*    If linked list is empty, then
    return carry*/

    if (head == NULL)
        return 1;

/*    Add carry returned be next node call*/

    int res = head->data + addWithCarry(head->next);

/*    Update data and return new carry*/

    head->data = (res) % 10;
    return (res) / 10;
}

/*This function mainly uses addWithCarry().*/

Node* addOne(Node* head)
{

/*    Add 1 to linked list from end to beginning*/

    int carry = addWithCarry(head);

/*    If there is carry after processing all nodes,
    then we need to add a new node to linked list*/

    if (carry) {
        Node* newNode = new Node;
        newNode->data = carry;
        newNode->next = head;

/*New node becomes head now*/

return newNode; 
    }

    return head;
}

/*A utility function to print a linked list*/

void printList(Node* node)
{
    while (node != NULL) {
        printf("%d", node->data);
        node = node->next;
    }
    printf("\n");
}

/* Driver code */

int main(void)
{
    Node* head = newNode(1);
    head->next = newNode(9);
    head->next->next = newNode(9);
    head->next->next->next = newNode(9);

    printf("List is ");
    printList(head);

    head = addOne(head);

    printf("\nResultant list is ");
    printList(head);

    return 0;
}

/*C++ program to point arbit pointers to highest
value on its right*/

#include<bits/stdc++.h>
using namespace std;

/* Link list node */

struct Node
{
    int data;
    Node* next, *arbit;
};

/* Function to reverse the linked list */

Node* reverse(Node *head)
{
    Node *prev = NULL, *current = head, *next;
    while (current != NULL)
    {
        next  = current->next;
        current->next = prev;
        prev = current;
        current = next;
    }
    return prev;
}

/*This function populates arbit pointer in every
node to the greatest value to its right.*/

Node* populateArbit(Node *head)
{

/*    Reverse given linked list*/

    head = reverse(head);

/*    Initialize pointer to maximum value node*/

    Node *max = head;

/*    Traverse the reversed list*/

    Node *temp = head->next;
    while (temp != NULL)
    {

/*        Connect max through arbit pointer*/

        temp->arbit = max;

/*        Update max if required*/

        if (max->data < temp->data)
            max = temp;

/*        Move ahead in reversed list*/

        temp = temp->next;
    }

/*    Reverse modified linked list and return
    head.*/

    return reverse(head);
}

/*Utility function to print result linked list*/

void printNextArbitPointers(Node *node)
{
    printf("Node\tNext Pointer\tArbit Pointer\n");
    while (node!=NULL)
    {
        cout << node->data << "\t\t";

        if (node->next)
            cout << node->next->data << "\t\t";
        else cout << "NULL" << "\t\t";

        if (node->arbit)
            cout << node->arbit->data;
        else cout << "NULL";

        cout << endl;
        node = node->next;
    }
}

/* Function to create a new node with given data */

Node *newNode(int data)
{
    Node *new_node = new Node;
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

/* Driver program to test above functions*/

