}

/*C++ Program to merge two sorted linked lists without
using any extra space and without changing links
of first list*/

#include <bits/stdc++.h>
using namespace std;

/* Structure for a linked list node */

struct Node
{
    int data;
    struct Node *next;
};

/* Given a reference (pointer to pointer) to the head
  of a list and an int, push a new node on the front
  of the list. */

void push(struct Node** head_ref, int new_data)
{

/* allocate node */

    struct Node* new_node =
        (struct Node*) malloc(sizeof(struct Node));

/* put in the data  */

    new_node->data  = new_data;

/* link the old list off the new node */

    new_node->next = (*head_ref);

/* move the head to point to the new node */

    (*head_ref)    = new_node;
}

/*Function to merge two sorted linked lists
LL1 and LL2 without using any extra space.*/

void mergeLists(struct Node *a, struct Node * &b)
{

/*    run till either one of a or b runs out*/

    while (a && b)
    {

/*        for each element of LL1,
        compare it with first element of LL2.*/

        if (a->data > b->data)
        {

/*            swap the two elements involved
            if LL1 has a greater element*/

            swap(a->data, b->data);

            struct Node *temp = b;

/*            To keep LL2 sorted, place first
            element of LL2 at its correct place*/

            if (b->next && b->data > b->next->data)
            {
                b = b->next;
                struct Node *ptr= b, *prev = NULL;

/*                find mismatch by traversing the
                second linked list once*/

                while (ptr && ptr->data < temp->data)
                {
                    prev = ptr;
                    ptr = ptr -> next;
                }

/*                correct the pointers*/

                prev->next = temp;
                temp->next = ptr;
            }
        }

/*        move LL1 pointer to next element*/

        a = a->next;
    }
}

/*Code to print the linked link*/

void printList(struct Node *head)
{
    while (head)
    {
        cout << head->data << "->" ;
        head = head->next;
    }
    cout << "NULL" << endl;
}

/*Driver code*/

int main()
{
    struct Node *a = NULL;
    push(&a, 10);
    push(&a, 8);
    push(&a, 7);
    push(&a, 4);
    push(&a, 2);

    struct Node *b = NULL;
    push(&b, 12);
    push(&b, 3);
    push(&b, 1);

    mergeLists(a, b);

    cout << "First List: ";
    printList(a);

    cout << "Second List: ";
    printList(b);

    return 0;
}

/*C++ program to delete middle
of a linked list*/

#include <bits/stdc++.h>
using namespace std;

/* Link list Node */

struct Node {
    int data;
    struct Node* next;
};

/*count of nodes*/

int countOfNodes(struct Node* head)
{
    int count = 0;
    while (head != NULL) {
        head = head->next;
        count++;
    }
    return count;
}

/*Deletes middle node and returns
head of the modified list*/

struct Node* deleteMid(struct Node* head)
{

/*    Base cases*/

    if (head == NULL)
        return NULL;
    if (head->next == NULL) {
        delete head;
        return NULL;
    }
    struct Node* copyHead = head;

/*    Find the count of nodes*/

    int count = countOfNodes(head);

/*    Find the middle node*/

    int mid = count / 2;

/*    Delete the middle node*/

    while (mid-- > 1) {
        head = head->next;
    }

/*    Delete the middle node*/

    head->next = head->next->next;

    return copyHead;
}

/*A utility function to print
a given linked list*/

void printList(struct Node* ptr)
{
    while (ptr != NULL) {
        cout << ptr->data << "->";
        ptr = ptr->next;
    }
    cout << "NULL\n";
}

/*Utility function to create a new node.*/

Node* newNode(int data)
{
    struct Node* temp = new Node;
    temp->data = data;
    temp->next = NULL;
    return temp;
}

