    head->next->next = newNode(3);
    head->next->next->next = newNode(4);

    cout << "Given Linked List\n";
    printList(head);

    head = deleteMid(head);

    cout << "Linked List after deletion of middle\n";
    printList(head);

    return 0;
}

/*C++ program to merge k sorted
arrays of size n each*/

#include <bits/stdc++.h>
using namespace std;

/*A Linked List node*/

struct Node {
    int data;
    Node* next;
};

/* Function to print nodes in
   a given linked list */

void printList(Node* node)
{
    while (node != NULL) {
        printf("%d ", node->data);
        node = node->next;
    }
}

/*The main function that
takes an array of lists
arr[0..last] and generates
the sorted output*/

Node* mergeKLists(Node* arr[], int last)
{

/*    Traverse form second list to last*/

    for (int i = 1; i <= last; i++) {
        while (true) {

/*            head of both the lists,
            0 and ith list.*/

            Node *head_0 = arr[0], *head_i = arr[i];

/*            Break if list ended*/

            if (head_i == NULL)
                break;

/*            Smaller than first element*/

            if (head_0->data >= head_i->data) {
                arr[i] = head_i->next;
                head_i->next = head_0;
                arr[0] = head_i;
            }
            else

/*                Traverse the first list*/

                while (head_0->next != NULL) {

/*                    Smaller than next element*/

                    if (head_0->next->data
                        >= head_i->data) {
                        arr[i] = head_i->next;
                        head_i->next = head_0->next;
                        head_0->next = head_i;
                        break;
                    }

/*                    go to next node*/

                    head_0 = head_0->next;

/*                    if last node*/

                    if (head_0->next == NULL) {
                        arr[i] = head_i->next;
                        head_i->next = NULL;
                        head_0->next = head_i;
                        head_0->next->next = NULL;
                        break;
                    }
                }
        }
    }

    return arr[0];
}

/*Utility function to create a new node.*/

Node* newNode(int data)
{
    struct Node* temp = new Node;
    temp->data = data;
    temp->next = NULL;
    return temp;
}

