{
    struct Node* head = NULL;

/*    create linked list 10->12->8->4->6*/

    push(&head, 6);
    push(&head, 4);
    push(&head, 8);
    push(&head, 12);
    push(&head, 10);

    cout << "Linked list before sorting:n";
    printList(head);

/*    sort the linked list*/

    sort(&head);

    cout << "\nLinked list after sorting:n";
    printList(head);

    return 0;
}

/*C++ implementation to insert node at the middle
of the linked list*/

#include <bits/stdc++.h>

using namespace std;

/*structure of a node*/

struct Node {
    int data;
    Node* next;
};

/*function to create and return a node*/

Node* getNode(int data)
{
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

/*function to insert node at the middle
of the linked list*/

void insertAtMid(Node** head_ref, int x)
{

/*    if list is empty*/

    if (*head_ref == NULL)
        *head_ref = getNode(x);
    else {

/*        get a new node*/

        Node* newNode = getNode(x);

        Node* ptr = *head_ref;
        int len = 0;

/*        calculate length of the linked list
        , i.e, the number of nodes*/

        while (ptr != NULL) {
            len++;
            ptr = ptr->next;
        }

/*        'count' the number of nodes after which
          the new node is to be inserted*/

        int count = ((len % 2) == 0) ? (len / 2) :
                                    (len + 1) / 2;
        ptr = *head_ref;

/*        'ptr' points to the node after which
        the new node is to be inserted*/

        while (count-- > 1)
            ptr = ptr->next;

/*        insert the 'newNode' and adjust the
        required links*/

        newNode->next = ptr->next;
        ptr->next = newNode;
    }
}

/*function to display the linked list*/

void display(Node* head)
{
    while (head != NULL) {
        cout << head->data << " ";
        head = head->next;
    }
}

