    push(&head, 11);
    push(&head, 8);
    push(&head, 5);
    push(&head, 18);
    push(&head, 15);

    printList(head);
    cout << endl;
    cout << "Linked list rotated elements: ";

/*    Function call countRotation()*/

    cout << countRotation(head) << endl;

    return 0;
}

/*C++ program to make middle node as head of
linked list.*/

#include <bits/stdc++.h>
using namespace std;

/* Link list node */

class Node
{
    public:
    int data;
    Node* next;
};

/* Function to get the middle and set at
beginning of the linked list*/

void setMiddleHead(Node** head)
{
    if (*head == NULL)
        return;

/*    To traverse list nodes one by one*/

    Node* one_node = (*head);

/*    To traverse list nodes by skipping
    one.*/

    Node* two_node = (*head);

/*    To keep track of previous of middle*/

    Node* prev = NULL;
    while (two_node != NULL && two_node->next != NULL)
    {

/* for previous node of middle node */

        prev = one_node;

/* move one node each time*/

        two_node = two_node->next->next;

/* move two node each time*/

        one_node = one_node->next;
    }

/* set middle node at head */

    prev->next = prev->next->next;
    one_node->next = (*head);
    (*head) = one_node;
}

/*To insert a node at the beginning of linked
list.*/

void push(Node** head_ref, int new_data)
{

/* allocate node */

    Node* new_node = new Node();

    new_node->data = new_data;

/* link the old list off the new node */

    new_node->next = (*head_ref);

/* move the head to point to the new node */

    (*head_ref) = new_node;
}

/*A function to print a given linked list*/

void printList(Node* ptr)
{
    while (ptr != NULL)
    {
        cout << ptr->data << " ";
        ptr = ptr->next;
    }
    cout<<endl;
}

/* Driver code*/

int main()
{

/*    Create a list of 5 nodes*/

    Node* head = NULL;
    int i;
    for (i = 5; i > 0; i--)
        push(&head, i);

    cout << " list before: ";
    printList(head);

    setMiddleHead(&head);

    cout << " list After: ";
    printList(head);

    return 0;
}

/*C++ implementation for Sorted merge of two
sorted doubly circular linked list*/

#include <bits/stdc++.h>
using namespace std;

struct Node {
    int data;
    Node *next, *prev;
};

/*A utility function to insert a new node at the
beginning of doubly circular linked list*/

void insert(Node** head_ref, int data)
{

/*    allocate space*/

    Node* new_node = new Node;

/*    put in the data*/

    new_node->data = data;

/*    if list is empty*/

    if (*head_ref == NULL) {
        new_node->next = new_node;
        new_node->prev = new_node;
    }

    else {

/*        pointer points to last Node*/

        Node* last = (*head_ref)->prev;

/*        setting up previous and next of new node*/

        new_node->next = *head_ref;
        new_node->prev = last;

/*        update next and previous pointers of head_ref
        and last.*/

        last->next = (*head_ref)->prev = new_node;
    }

/*    update head_ref pointer*/

    *head_ref = new_node;
}

/*function for Sorted merge of two
sorted doubly linked list*/

Node* merge(Node* first, Node* second)
{

/*    If first list is empty*/

    if (!first)
        return second;

/*    If second list is empty*/

    if (!second)
        return first;

/*    Pick the smaller value and adjust
    the links*/

    if (first->data < second->data) {
        first->next = merge(first->next, second);
        first->next->prev = first;
        first->prev = NULL;
        return first;
    }
    else {
        second->next = merge(first, second->next);
        second->next->prev = second;
        second->prev = NULL;
        return second;
    }
}

/*function for Sorted merge of two sorted
doubly circular linked list*/

Node* mergeUtil(Node* head1, Node* head2)
{

/*    if 1st list is empty*/

    if (!head1)
        return head2;

/*    if 2nd list is empty*/

    if (!head2)
        return head1;

/*    get pointer to the node which will be the
    last node of the final list*/

    Node* last_node;
    if (head1->prev->data < head2->prev->data)
        last_node = head2->prev;
    else
        last_node = head1->prev;

/*    store NULL to the 'next' link of the last nodes
    of the two lists*/

    head1->prev->next = head2->prev->next = NULL;

/*    sorted merge of head1 and head2*/

    Node* finalHead = merge(head1, head2);

/*    'prev' of 1st node pointing the last node
    'next' of last node pointing to 1st node*/

    finalHead->prev = last_node;
    last_node->next = finalHead;

    return finalHead;
}

/*function to print the list*/

void printList(Node* head)
{
    Node* temp = head;

    while (temp->next != head) {
        cout << temp->data << " ";
        temp = temp->next;
    }
    cout << temp->data << " ";
}

/*Driver program to test above*/

int main()
{
    Node *head1 = NULL, *head2 = NULL;

/*    list 1:*/

    insert(&head1, 8);
    insert(&head1, 5);
    insert(&head1, 3);
    insert(&head1, 1);

/*    list 2:*/

    insert(&head2, 11);
    insert(&head2, 9);
    insert(&head2, 7);
    insert(&head2, 2);

    Node* newHead = mergeUtil(head1, head2);

    cout << "Final Sorted List: ";
    printList(newHead);

    return 0;
}

/*Cpp Program to Reverse a List using Data Swapping*/


#include <bits/stdc++.h>
using namespace std;

struct Node {
    int data;
    struct Node *prev, *next;
};

Node* newNode(int val)
{
    Node* temp = new Node;
    temp->data = val;
    temp->prev = temp->next = nullptr;
    return temp;
}

void printList(Node* head)
{
    while (head->next != nullptr) {
        cout << head->data << " <--> ";
        head = head->next;
    }
    cout << head->data << endl;
}

/*Insert a new node at the head of the list*/

void insert(Node** head, int val)
{
    Node* temp = newNode(val);
    temp->next = *head;
    (*head)->prev = temp;
    (*head) = temp;
}

/*Function to reverse the list*/

void reverseList(Node** head)
{
    Node* left = *head, * right = *head;

/*    Traverse the list and set right pointer to
    end of list*/

    while (right->next != nullptr)
        right = right->next;

/*    Swap data of left and right pointer and move
    them towards each other until they meet or
    cross each other*/

    while (left != right && left->prev != right) {

/*        Swap data of left and right pointer*/

        swap(left->data, right->data);

/*        Advance left pointer*/

        left = left->next;

/*        Advance right pointer*/

        right = right->prev;
    }
}

/*Driver code*/

int main()
{
    Node* head = newNode(5);
    insert(&head, 4);
    insert(&head, 3);
    insert(&head, 2);
    insert(&head, 1);

    printList(head);
    cout << "List After Reversing" << endl;
    reverseList(&head);
    printList(head);

    return 0;
}

/*C++ implementation for insertion Sort
on a doubly linked list*/

#include <bits/stdc++.h>

using namespace std;

/*Node of a doubly linked list*/

struct Node {
    int data;
    struct Node* prev, *next;
};

/*function to create and return a new node
of a doubly linked list*/

struct Node* getNode(int data)
{

/*    allocate node*/

    struct Node* newNode =
          (struct Node*)malloc(sizeof(struct Node));

/*    put in the data*/

    newNode->data = data;
    newNode->prev = newNode->next = NULL;
    return newNode;
}

/*function to insert a new node in sorted way in
a sorted doubly linked list*/

void sortedInsert(struct Node** head_ref, struct Node* newNode)
{
    struct Node* current;

/*    if list is empty*/

    if (*head_ref == NULL)
        *head_ref = newNode;

/*    if the node is to be inserted at the beginning
    of the doubly linked list*/

    else if ((*head_ref)->data >= newNode->data) {
        newNode->next = *head_ref;
        newNode->next->prev = newNode;
        *head_ref = newNode;
    }

    else {
        current = *head_ref;

/*        locate the node after which the new node
        is to be inserted*/

        while (current->next != NULL &&
               current->next->data < newNode->data)
            current = current->next;

/*Make the appropriate links */


        newNode->next = current->next;

/*        if the new node is not inserted
        at the end of the list*/

        if (current->next != NULL)
            newNode->next->prev = newNode;

        current->next = newNode;
        newNode->prev = current;
    }
}

/*function to sort a doubly linked list using insertion sort*/

void insertionSort(struct Node** head_ref)
{

/*    Initialize 'sorted' - a sorted doubly linked list*/

    struct Node* sorted = NULL;

/*    Traverse the given doubly linked list and
    insert every node to 'sorted'*/

    struct Node* current = *head_ref;
    while (current != NULL) {

/*        Store next for next iteration*/

        struct Node* next = current->next;

/*        removing all the links so as to create 'current'
        as a new node for insertion*/

        current->prev = current->next = NULL;

/*        insert current in 'sorted' doubly linked list*/

        sortedInsert(&sorted, current);

/*        Update current*/

        current = next;
    }

/*    Update head_ref to point to sorted doubly linked list*/

    *head_ref = sorted;
}

/*function to print the doubly linked list*/

void printList(struct Node* head)
{
    while (head != NULL) {
        cout << head->data << " ";
        head = head->next;
    }
}

/*function to insert a node at the beginning of
the doubly linked list*/

void push(struct Node** head_ref, int new_data)
{

/* allocate node */

    struct Node* new_node =
         (struct Node*)malloc(sizeof(struct Node));

/* put in the data  */

    new_node->data = new_data;

/* Make next of new node as head and previous as NULL */

    new_node->next = (*head_ref);
    new_node->prev = NULL;

/* change prev of head node to new node */

    if ((*head_ref) != NULL)
        (*head_ref)->prev = new_node;

/* move the head to point to the new node */

    (*head_ref) = new_node;
}

/*Driver program to test above*/

int main()
{

/* start with the empty doubly linked list */

    struct Node* head = NULL;

/*    insert the following data*/

    push(&head, 9);
    push(&head, 3);
    push(&head, 5);
    push(&head, 10);
    push(&head, 12);
    push(&head, 8);

    cout << "Doubly Linked List Before Sortingn";
    printList(head);

    insertionSort(&head);

    cout << "nDoubly Linked List After Sortingn";
    printList(head);

    return 0;
}

/*C++ program to check if doubly
linked list is palindrome or not*/

#include<bits/stdc++.h>
using namespace std;

/*Structure of node*/

struct Node
{
    char data;
    struct Node *next;
    struct Node *prev;
};

/* Given a reference (pointer to pointer) to
   the head of a list and an int, inserts a
   new node on the front of the list. */

void push(struct Node** head_ref, char new_data)
{
    struct Node* new_node = new Node;
    new_node->data  = new_data;
    new_node->next = (*head_ref);
    new_node->prev = NULL;
    if ((*head_ref) !=  NULL)
      (*head_ref)->prev = new_node ;
    (*head_ref)    = new_node;
}

/*Function to check if list is palindrome or not*/

bool isPalindrome(struct Node *left)
{
    if (left == NULL)
       return true;

/*    Find rightmost node*/

    struct Node *right = left;
    while (right->next != NULL)
        right = right->next;

    while (left != right)
    {
        if (left->data != right->data)
            return false;

        left = left->next;
        right = right->prev;
    }

    return true;
}

/*Driver program*/

int main()
{
    struct Node* head = NULL;
    push(&head, 'l');
    push(&head, 'e');
    push(&head, 'v');
    push(&head, 'e');
    push(&head, 'l');

    if (isPalindrome(head))
        printf("It is Palindrome");
    else
        printf("Not Palindrome");

    return 0;
}

/* C++ Implementation of Memory
efficient Doubly Linked List */

#include <bits/stdc++.h>
#include <cinttypes>
using namespace std;

/*Node structure of a memory
efficient doubly linked list*/

class Node
{
    public:
    int data;
    Node* npx;

/* XOR of next and previous node */

};

/* returns XORed value of the node addresses */

Node* XOR (Node *a, Node *b)
{
    return reinterpret_cast<Node *>(
      reinterpret_cast<uintptr_t>(a) ^
      reinterpret_cast<uintptr_t>(b));
}

/* Insert a node at the beginning of the
XORed linked list and makes the newly
inserted node as head */

void insert(Node **head_ref, int data)
{

/*    Allocate memory for new node*/

    Node *new_node = new Node();
    new_node->data = data;

/* Since new node is being inserted at the
    beginning, npx of new node will always be
    XOR of current head and NULL */

    new_node->npx = *head_ref;

/* If linked list is not empty, then npx of
    current head node will be XOR of new node
    and node next to current head */

    if (*head_ref != NULL)
    {

/*        *(head_ref)->npx is XOR of NULL and next.
        So if we do XOR of it with NULL, we get next*/

        (*head_ref)->npx = XOR(new_node, (*head_ref)->npx);
    }

/*    Change head*/

    *head_ref = new_node;
}

/*prints contents of doubly linked
list in forward direction*/

void printList (Node *head)
{
    Node *curr = head;
    Node *prev = NULL;
    Node *next;

    cout << "Following are the nodes of Linked List: \n";

    while (curr != NULL)
    {

/*        print current node*/

        cout<<curr->data<<" ";

/*        get address of next node: curr->npx is
        next^prev, so curr->npx^prev will be
        next^prev^prev which is next*/

        next = XOR (prev, curr->npx);

/*        update prev and curr for next iteration*/

        prev = curr;
        curr = next;
    }
}

/*Driver code*/

int main ()
{

/* Create following Doubly Linked List
    head-->40<-->30<-->20<-->10 */

    Node *head = NULL;
    insert(&head, 10);
    insert(&head, 20);
    insert(&head, 30);
    insert(&head, 40);

/*    print the created list*/

    printList (head);

    return (0);
}

/*A C++ program to print Nodes level by level berween given two levels.*/

#include <bits/stdc++.h>
using namespace std;

/* A binary tree Node has key, pointer to left and right children */

struct Node
{
    int key;
    struct Node* left, *right;
};

/* Given a binary tree, print nodes from level number 'low' to level
   number 'high'*/

void printLevels(Node* root, int low, int high)
{
    queue <Node *> Q;

/*Marker node to indicate end of level*/

Node *marker = new Node;

/*Initialize level number*/

int level = 1;

/*    Enqueue the only first level node and marker node for end of level*/

    Q.push(root);
    Q.push(marker);

/*    Simple level order traversal loop*/

    while (Q.empty() == false)
    {

/*        Remove the front item from queue*/

        Node *n = Q.front();
        Q.pop();

/*        Check if end of level is reached*/

        if (n == marker)
        {

/*            print a new line and increment level number*/

            cout << endl;
            level++;

/*            Check if marker node was last node in queue or
            level number is beyond the given upper limit*/

            if (Q.empty() == true || level > high) break;

/*            Enqueue the marker for end of next level*/

            Q.push(marker);

/*            If this is marker, then we don't need print it
            and enqueue its children*/

            continue;
        }

/*        If level is equal to or greater than given lower level,
        print it*/

        if (level >= low)
            cout << n->key << " ";

/*        Enqueue children of non-marker node*/

        if (n->left != NULL)  Q.push(n->left);
        if (n->right != NULL) Q.push(n->right);
    }
}

/* Helper function that allocates a new Node with the
   given key and NULL left and right pointers. */

Node* newNode(int key)
{
    Node* temp = new Node;
    temp->key = key;
    temp->left = temp->right = NULL;
    return (temp);
}

/* Driver program to test above functions*/

int main()
{
    struct Node *root        = newNode(20);
    root->left               = newNode(8);
    root->right              = newNode(22);
    root->left->left         = newNode(4);
    root->left->right        = newNode(12);
    root->left->right->left  = newNode(10);
    root->left->right->right = newNode(14);

    cout << "Level Order traversal between given two levels is";
    printLevels(root, 2, 3);

    return 0;
}

#include<bits/stdc++.h>

using namespace std;

/* A binary tree node has data,
pointer to left child and
a pointer to right child */

class node
{
    public:
    int data;
    node* left;
    node* right;
    node(int data)
    {
        this->data = data;
        this->left = NULL;
        this->right = NULL;
    }
};

void printKDistant(node *root , int k)
{
    if(root == NULL|| k < 0 )
        return;
    if( k == 0 )
    {
        cout << root->data << " ";
         return;
    }

        printKDistant( root->left, k - 1 ) ;
        printKDistant( root->right, k - 1 ) ;

}

/* Driver code*/

