/*CPP program to print all nodes of level k
iterative approach*/
#include <bits/stdc++.h>
using namespace std;

/*Node of binary tree*/

struct Node {
    int data;
    Node* left, * right;
};

/*Function to add a new node*/

Node* newNode(int data)
{
    Node* newnode = new Node();
    newnode->data = data;
    newnode->left = newnode->right = NULL;
}

/*Function to print nodes of given level*/

bool printKDistant(Node* root, int klevel)
{
    queue<Node*> q;
    int level = 1;
    bool flag = false;
    q.push(root);

/*    extra NULL is pushed to keep track
    of all the nodes to be pushed before
    level is incremented by 1*/

    q.push(NULL);
    while (!q.empty()) {
        Node* temp = q.front();

/*        print when level is equal to k*/

        if (level == klevel && temp != NULL) {
            flag = true;
            cout << temp->data << " ";
        }
        q.pop();
        if (temp == NULL) {
            if (q.front())
                q.push(NULL);
            level += 1;

/*            break the loop if level exceeds
            the given level number*/

            if (level > klevel)
                break;
        } else {
            if (temp->left)
                q.push(temp->left);

            if (temp->right)
                q.push(temp->right);
        }
    }
    cout << endl;

    return flag;
}

/*Driver code*/

int main()
{

/*    create a binary tree*/

    Node* root = newNode(20);
    root->left = newNode(10);
    root->right = newNode(30);
    root->left->left = newNode(5);
    root->left->right = newNode(15);
    root->left->right->left = newNode(12);
    root->right->left = newNode(25);
    root->right->right = newNode(40);

    cout << "data at level 1 : ";
    int ret = printKDistant(root, 1);
    if (ret == false)
        cout << "Number exceeds total number of levels\n";

    cout << "data at level 2 : ";
    ret = printKDistant(root, 2);
    if (ret == false)
        cout << "Number exceeds total number of levels\n";

    cout << "data at level 3 : ";
    ret = printKDistant(root, 3);
    if (ret == false)
        cout << "Number exceeds total number of levels\n";

    cout << "data at level 6 : ";
    ret = printKDistant(root, 6);
    if (ret == false)
        cout << "Number exceeds total number of levels\n";

    return 0;
}

/* C++ program to print leaf nodes from left
   to right */

#include <iostream>
using namespace std;

/*A Binary Tree Node*/

struct Node
{
    int data;
    struct Node *left, *right;
};

/*function to print leaf
nodes from left to right*/

void printLeafNodes(Node *root)
{

/*    if node is null, return*/

    if (!root)
        return;

/*    if node is leaf node, print its data   */

    if (!root->left && !root->right)
    {
        cout << root->data << " ";
        return;
    }

/*    if left child exists, check for leaf
    recursively*/

    if (root->left)
       printLeafNodes(root->left);

/*    if right child exists, check for leaf
    recursively*/

    if (root->right)
       printLeafNodes(root->right);
}

/*Utility function to create a new tree node*/

Node* newNode(int data)
{
    Node *temp = new Node;
    temp->data = data;
    temp->left = temp->right = NULL;
    return temp;
}

/*Driver program to test above functions*/

int main()
{

/*    Let us create binary tree shown in
    above diagram*/

    Node *root = newNode(1);
    root->left = newNode(2);
    root->right = newNode(3);
    root->left->left = newNode(4);
    root->right->left = newNode(5);
    root->right->right = newNode(8);
    root->right->left->left = newNode(6);
    root->right->left->right = newNode(7);
    root->right->right->left = newNode(9);
    root->right->right->right = newNode(10);

/*    print leaf nodes of the given tree*/

    printLeafNodes(root);

    return 0;
}

#include <iostream>
using namespace std;

/*A binary Tree node*/

struct node
{
    int data;
    struct node *left, *right;
};

/* Recursive function to print all the nodes at distance k in the
   tree (or subtree) rooted with given root. See  */

void printkdistanceNodeDown(node *root, int k)
{

/*    Base Case*/

    if (root == NULL || k < 0)  return;

/*    If we reach a k distant node, print it*/

    if (k==0)
    {
        cout << root->data << endl;
        return;
    }

/*    Recur for left and right subtrees*/

    printkdistanceNodeDown(root->left, k-1);
    printkdistanceNodeDown(root->right, k-1);
}

/*Prints all nodes at distance k from a given target node.
The k distant nodes may be upward or downward.  This function
Returns distance of root from target node, it returns -1 if target
node is not present in tree rooted with root.*/

int printkdistanceNode(node* root, node* target , int k)
{

/*    Base Case 1: If tree is empty, return -1*/

    if (root == NULL) return -1;

/*    If target is same as root.  Use the downward function
    to print all nodes at distance k in subtree rooted with
    target or root*/

    if (root == target)
    {
        printkdistanceNodeDown(root, k);
        return 0;
    }

/*    Recur for left subtree*/

    int dl = printkdistanceNode(root->left, target, k);

/*    Check if target node was found in left subtree*/

    if (dl != -1)
    {

/*         If root is at distance k from target, print root
         Note that dl is Distance of root's left child from target*/

         if (dl + 1 == k)
            cout << root->data << endl;

/*         Else go to right subtree and print all k-dl-2 distant nodes
         Note that the right child is 2 edges away from left child*/

         else
            printkdistanceNodeDown(root->right, k-dl-2);

/*         Add 1 to the distance and return value for parent calls*/

         return 1 + dl;
    }

/*    MIRROR OF ABOVE CODE FOR RIGHT SUBTREE
    Note that we reach here only when node was not found in left subtree*/

    int dr = printkdistanceNode(root->right, target, k);
    if (dr != -1)
    {
         if (dr + 1 == k)
            cout << root->data << endl;
         else
            printkdistanceNodeDown(root->left, k-dr-2);
         return 1 + dr;
    }

/*    If target was neither present in left nor in right subtree*/

    return -1;
}

/*A utility function to create a new binary tree node*/

node *newnode(int data)
{
    node *temp = new node;
    temp->data = data;
    temp->left = temp->right = NULL;
    return temp;
}

