}

/* Program to find singles in a given binary tree */

#include <bits/stdc++.h>
using namespace std;

/*A Binary Tree Node*/

struct node
{
    struct node *left, *right;
    int key;
};

node* newNode(int key)
{
    node *temp = new node;
    temp->key = key;
    temp->left = temp->right = NULL;
    return temp;
}

/*Function to print all non-root nodes
that don't have a sibling*/

void printSingles(struct node *root)
{

/*    Base case*/

    if (root == NULL)
      return;

/*    If this is an internal node, recur for left
    and right subtrees*/

    if (root->left != NULL && root->right != NULL)
    {
        printSingles(root->left);
        printSingles(root->right);
    }

/*    If left child is NULL and right is not,
    print right child
    and recur for right child*/

    else if (root->right != NULL)
    {
        cout << root->right->key << " ";
        printSingles(root->right);
    }

/*    If right child is NULL and left is
    not, print left child
    and recur for left child*/

    else if (root->left != NULL)
    {
        cout << root->left->key << " ";
        printSingles(root->left);
    }
}

/*Driver program to test above functions*/

int main()
{

/*    Let us create binary tree
    given in the above example*/

    node *root = newNode(1);
    root->left = newNode(2);
    root->right = newNode(3);
    root->left->right = newNode(4);
    root->right->left = newNode(5);
    root->right->left->left = newNode(6);
    printSingles(root);
    return 0;
}

/* Program to print all nodes
which are at distance k from a leaf */

#include <iostream>
using namespace std;
#define MAX_HEIGHT 10000

/* utility that allocates a new Node with the given key  */

struct Node {
    int key;
    Node *left, *right;
};
Node* newNode(int key)
{
    Node* node = new Node;
    node->key = key;
    node->left = node->right = NULL;
    return (node);
}

/* This function prints all nodes that are distance k from a leaf node
   path[] --> Store ancestors of a node
   visited[] --> Stores true if a node is printed as output.  A node may be k
                 distance away from many leaves, we want to print it once */

void kDistantFromLeafUtil(Node* node, int path[], bool visited[],
                          int pathLen, int k)
{

/*    Base case*/

    if (node == NULL)
        return;

/* append this Node to the path array */

    path[pathLen] = node->key;
    visited[pathLen] = false;
    pathLen++;

/* it's a leaf, so print the ancestor at distance k only
       if the ancestor is not already printed  */

    if (node->left == NULL &&
        node->right == NULL &&
        pathLen - k - 1 >= 0 &&
        visited[pathLen - k - 1] == false)
    {
        cout << path[pathLen - k - 1] << " ";
        visited[pathLen - k - 1] = true;
        return;
    }

/* If not leaf node, recur for left and right subtrees */

    kDistantFromLeafUtil(node->left, path, visited, pathLen, k);
    kDistantFromLeafUtil(node->right, path, visited, pathLen, k);
}

/* Given a binary tree and a number k, print all nodes that are k
   distant from a leaf*/

void printKDistantfromLeaf(Node* node, int k)
{
    int path[MAX_HEIGHT];
    bool visited[MAX_HEIGHT] = { false };
    kDistantFromLeafUtil(node, path, visited, 0, k);
}

/* Driver code*/

int main()
{

/*    Let us create binary tree
  given in the above example*/

    Node* root = newNode(1);
    root->left = newNode(2);
    root->right = newNode(3);
    root->left->left = newNode(4);
    root->left->right = newNode(5);
    root->right->left = newNode(6);
    root->right->right = newNode(7);
    root->right->left->right = newNode(8);

    cout << "Nodes at distance 2 are: ";
    printKDistantfromLeaf(root, 2);

    return 0;
}

/*C++  program to print all nodes at a distance k from leaf*/


#include <bits/stdc++.h>
using namespace std;

/*A binary tree node*/

struct Node
{
  int data;
  Node *left, *right;
};
Node* newNode(int key)  
{  
  Node *temp = new Node;  
  temp->data= key;  
  temp->left = temp->right = NULL;  
  return temp;  
}

/* Given a binary tree and a number k,
print all nodes that are k
distant from a leaf*/

int printKDistantfromLeaf(struct Node *node, int k)
{
  if (node == NULL)
    return -1;
  int lk = printKDistantfromLeaf(node->left, k);
  int rk = printKDistantfromLeaf(node->right, k);
  bool isLeaf = lk == -1 && lk == rk;
  if (lk == 0 || rk == 0 || (isLeaf && k == 0))
    cout<<(" " )<<( node->data);
  if (isLeaf && k > 0)

/*leaf node*/

return k - 1; 
  if (lk > 0 && lk < k)

/*parent of left leaf*/

return lk - 1; 
  if (rk > 0 && rk < k)

/*parent of right leaf*/

return rk - 1; 
  return -2;
}

