/*C/C++ program to print corner node at each level
of binary tree*/

#include <bits/stdc++.h>
using namespace std;

/* A binary tree node has key, pointer to left
   child and a pointer to right child */

struct Node
{
    int key;
    struct Node* left, *right;
};
struct Node* newNode(int key)
{
    Node* temp = new Node;
    temp->key = key;
    temp->left = temp->right = NULL;
    return (temp);
}

/* Function to print corner node at each level */

void printCorner(Node *root)
{

/*    If the root is null then simply return*/

    if(root == NULL)
        return;

/*        star node is for keeping track of levels*/


    queue<Node*> q;

/*        pushing root node and star node*/


    q.push(root);

/*    Do level order traversal using a single queue*/


    while(!q.empty())
    {

/*        n denotes the size of the current level in the queue*/

        int n = q.size();

        for(int i =0;i<n;i++)
        {
            Node *temp = q.front();
            q.pop();

/*            If it is leftmost corner value or rightmost corner value then print it*/

            if(i==0 || i==n-1)
               cout<<temp->key<<" ";

/*            push the left and right children of the temp node*/

            if(temp->left)
                q.push(temp->left);
            if(temp->right)
                q.push(temp->right);
        }
    }
}

/*Driver program to test above function*/

int main ()
{
    Node *root =  newNode(15);
    root->left = newNode(10);
    root->right = newNode(20);
    root->left->left = newNode(8);
    root->left->right = newNode(12);
    root->right->left = newNode(16);
    root->right->right = newNode(25);
    printCorner(root);
    return 0; 
}

/*C++ Program to print binary tree in 2D*/

#include<bits/stdc++.h>

using namespace std;
#define COUNT 10

/*A binary tree node*/

class Node
{
    public:
    int data;
    Node* left, *right;

/* Constructor that allocates a new node with the
    given data and NULL left and right pointers. */

    Node(int data){
        this->data = data;
        this->left = NULL;
        this->right = NULL;
    }
};

/*Function to print binary tree in 2D
It does reverse inorder traversal*/

void print2DUtil(Node *root, int space)
{

/*    Base case*/

    if (root == NULL)
        return;

/*    Increase distance between levels*/

    space += COUNT;

/*    Process right child first*/

    print2DUtil(root->right, space);

/*    Print current node after space
    count*/

    cout<<endl;
    for (int i = COUNT; i < space; i++)
        cout<<" ";
    cout<<root->data<<"\n";

/*    Process left child*/

    print2DUtil(root->left, space);
}

/*Wrapper over print2DUtil()*/

void print2D(Node *root)
{

/*    Pass initial space count as 0*/

    print2DUtil(root, 0);
}

/*Driver code*/

int main()
{
    Node *root = new Node(1);
    root->left = new Node(2);
    root->right = new Node(3);

    root->left->left = new Node(4);
    root->left->right = new Node(5);
    root->right->left = new Node(6);
    root->right->right = new Node(7);

    root->left->left->left = new Node(8);
    root->left->left->right = new Node(9);
    root->left->right->left = new Node(10);
    root->left->right->right = new Node(11);
    root->right->left->left = new Node(12);
    root->right->left->right = new Node(13);
    root->right->right->left = new Node(14);
    root->right->right->right = new Node(15);

    print2D(root);

    return 0;
}

/*C++ program to print left view of Binary Tree*/

#include <bits/stdc++.h>
using namespace std;

/*A utility function to
create a new Binary Tree Node*/

struct Node
{
    int data;
    struct Node *left, *right;
};
struct Node *newNode(int item)
{
    struct Node *temp = (struct Node *)malloc(
                        sizeof(struct Node));
    temp->data = item;
    temp->left = temp->right = NULL;
    return temp;
}

/*Recursive function to print
left view of a binary tree.*/

void leftViewUtil(struct Node *root,
                int level, int *max_level)
{

/*    Base Case*/

    if (root == NULL) return;

/*    If this is the first Node of its level*/

    if (*max_level < level)
    {
        cout << root->data << " ";
        *max_level = level;
    }

/*    Recur for left subtree first,
    then right subtree*/

      leftViewUtil(root->left, level + 1, max_level);
    leftViewUtil(root->right, level + 1, max_level);

}

/*A wrapper over leftViewUtil()*/

void leftView(struct Node *root)
{
    int max_level = 0;
    leftViewUtil(root, 1, &max_level);
}

/*Driver Code*/

int main()
{
    Node* root = newNode(10);
    root->left = newNode(2);
    root->right = newNode(3);
    root->left->left = newNode(7);
    root->left->right = newNode(8);
    root->right->right = newNode(15);
    root->right->left = newNode(12);
    root->right->right->left = newNode(14);

    leftView(root);

    return 0;
}

/*C++ program to print left view of
Binary Tree*/


#include<bits/stdc++.h>
using namespace std;

/*A Binary Tree Node*/

struct Node
{
    int data;
    struct Node *left, *right;
};

/*Utility function to create a new tree node*/

Node* newNode(int data)
{
    Node *temp = new Node;
    temp->data = data;
    temp->left = temp->right = NULL;
    return temp;
}

/*function to print left view of
binary tree*/

void printLeftView(Node* root)
{
    if (!root)
        return;

    queue<Node*> q;
    q.push(root);

    while (!q.empty())
    {

/*        number of nodes at current level*/

        int n = q.size();

/*        Traverse all nodes of current level*/

        for(int i = 1; i <= n; i++)
        {
            Node* temp = q.front();
            q.pop();

/*            Print the left most element
            at the level*/

            if (i == 1)
                cout<<temp->data<<" ";

/*            Add left node to queue*/

            if (temp->left != NULL)
                q.push(temp->left);

/*            Add right node to queue*/

            if (temp->right != NULL)
                q.push(temp->right);
        }
    }
}

/*Driver code*/

int main()
{

/*    Let's construct the tree as
    shown in example*/


    Node* root = newNode(10);
    root->left = newNode(2);
    root->right = newNode(3);
    root->left->left = newNode(7);
    root->left->right = newNode(8);
    root->right->right = newNode(15);
    root->right->left = newNode(12);
    root->right->right->left = newNode(14);

    printLeftView(root);
}

/*C++ Program to implement
the above appraoch*/

#include <bits/stdc++.h>
using namespace std;

/*Structure of an AVL Tree Node*/

struct node {
    int key;
    struct node* left;
    struct node* right;
    int height;

/*    Size of the tree rooted
    with this node*/

    int size;
};

/*Utility function to get maximum
of two integers*/

int max(int a, int b);

/*Utility function to get height
of the tree rooted with N*/

int height(struct node* N)
{
    if (N == NULL)
        return 0;
    return N->height;
}

/*Utility function to find size of
the tree rooted with N*/

int size(struct node* N)
{
    if (N == NULL)
        return 0;
    return N->size;
}

/*Utility function to get maximum
of two integers*/

int max(int a, int b)
{
    return (a > b) ? a : b;
}

/*Helper function to allocates a
new node with the given key*/

struct node* newNode(int key)
{
    struct node* node
        = (struct node*)
            malloc(sizeof(struct node));
    node->key = key;
    node->left = NULL;
    node->right = NULL;
    node->height = 1;
    node->size = 1;
    return (node);
}

/*Utility function to right rotate
subtree rooted with y*/

struct node* rightRotate(struct node* y)
{
    struct node* x = y->left;
    struct node* T2 = x->right;

/*    Perform rotation*/

    x->right = y;
    y->left = T2;

/*    Update heights*/

    y->height = max(height(y->left),
                    height(y->right))
                + 1;
    x->height = max(height(x->left),
                    height(x->right))
                + 1;

/*    Update sizes*/

    y->size = size(y->left)
              + size(y->right) + 1;
    x->size = size(x->left)
              + size(x->right) + 1;

/*    Return new root*/

    return x;
}

/*Utility function to left rotate
subtree rooted with x*/

struct node* leftRotate(struct node* x)
{
    struct node* y = x->right;
    struct node* T2 = y->left;

/*    Perform rotation*/

    y->left = x;
    x->right = T2;

/*    Update heights*/

    x->height = max(height(x->left),
                    height(x->right))
                + 1;
    y->height = max(height(y->left),
                    height(y->right))
                + 1;

/*    Update sizes*/

    x->size = size(x->left)
              + size(x->right) + 1;
    y->size = size(y->left)
              + size(y->right) + 1;

/*    Return new root*/

    return y;
}

/*Function to obtain Balance factor
of node N*/

int getBalance(struct node* N)
{
    if (N == NULL)
        return 0;

    return height(N->left)
           - height(N->right);
}

/*Function to insert a new key to the
tree rooted with node*/

struct node* insert(struct node* node, int key,
                    int* count)
{

/*    Perform the normal BST rotation*/

    if (node == NULL)
        return (newNode(key));

    if (key < node->key)
        node->left
            = insert(node->left, key, count);
    else {
        node->right
            = insert(node->right, key, count);

/*        Update count of smaller elements*/

        *count = *count + size(node->left) + 1;
    }

/*    Update height and size of the ancestor*/

    node->height = max(height(node->left),
                       height(node->right))
                   + 1;
    node->size = size(node->left)
                 + size(node->right) + 1;

/*    Get the balance factor of the ancestor*/

    int balance = getBalance(node);

/*    Left Left Case*/

    if (balance > 1 && key < node->left->key)
        return rightRotate(node);

/*    Right Right Case*/

    if (balance < -1 && key > node->right->key)
        return leftRotate(node);

/*    Left Right Case*/

    if (balance > 1 && key > node->left->key) {
        node->left = leftRotate(node->left);
        return rightRotate(node);
    }

/*    Right Left Case*/

    if (balance < -1 && key < node->right->key) {
        node->right = rightRotate(node->right);
        return leftRotate(node);
    }

    return node;
}

/*Function to generate an array which contains
count of smaller elements on the right*/

void constructLowerArray(int arr[],
                         int countSmaller[],
                         int n)
{
    int i, j;
    struct node* root = NULL;

    for (i = 0; i < n; i++)
        countSmaller[i] = 0;

/*    Insert all elements in the AVL Tree
    and get the count of smaller elements*/

    for (i = n - 1; i >= 0; i--) {
        root = insert(root, arr[i],
                      &countSmaller[i]);
    }
}

/*Function to find the number
of elements which are greater
than all elements on its left
and K elements on its right*/

int countElements(int A[], int n, int K)
{

    int count = 0;

/*    Stores the count of smaller
    elements on its right*/

    int* countSmaller
        = (int*)malloc(sizeof(int) * n);
    constructLowerArray(A, countSmaller, n);

    int maxi = INT_MIN;
    for (int i = 0; i <= (n - K - 1); i++) {
        if (A[i] > maxi && countSmaller[i] >= K) {
            count++;
            maxi = A[i];
        }
    }

    return count;
}

/*Driver Code*/

int main()
{

    int A[] = { 2, 5, 1, 7, 3, 4, 0 };
    int n = sizeof(A) / sizeof(int);
    int K = 3;

    cout << countElements(A, n, K);

    return 0;
}

