using namespace std;

/* Link list node */

class Node {
public:
    int data;
    Node* next;
};

/* A utility function to push a node */

void push(Node** head_ref, int new_data)
{

/* allocate node */

    Node* new_node = new Node();

/* put in the data */

    new_node->data = new_data;

/* link the old list off the new node */

    new_node->next = (*head_ref);

/* move the head to point to the new node */

    (*head_ref) = new_node;
}

/* A utility function to print linked list */

void printList(Node* node)
{
    while (node != NULL) {
        cout << node->data << " -> ";
        node = node->next;
    }
    cout << "NULL";
}

/*Function that rotates the given linked list
clockwise by k and returns the updated
head pointer*/

Node* rightRotate(Node* head, int k)
{

/*    If the linked list is empty*/

    if (!head)
        return head;

/*    len is used to store length of the linked list
    tmp will point to the last node after this loop*/

    Node* tmp = head;
    int len = 1;
    while (tmp->next != NULL) {
        tmp = tmp->next;
        len++;
    }

/*    If k is greater than the size
    of the linked list*/

    if (k > len)
        k = k % len;

/*    Subtract from length to convert
    it into left rotation*/

    k = len - k;

/*    If no rotation needed then
    return the head node*/

    if (k == 0 || k == len)
        return head;

/*    current will either point to
    kth or NULL after this loop*/

    Node* current = head;
    int cnt = 1;
    while (cnt < k && current != NULL) {
        current = current->next;
        cnt++;
    }

/*    If current is NULL then k is equal to the
    count of nodes in the list
    Don't change the list in this case*/

    if (current == NULL)
        return head;

/*    current points to the kth node*/

    Node* kthnode = current;

/*    Change next of last node to previous head*/

    tmp->next = head;

/*    Change head to (k+1)th node*/

    head = kthnode->next;

/*    Change next of kth node to NULL*/

    kthnode->next = NULL;

/*    Return the updated head pointer*/

    return head;
}

/*Driver code*/

int main()
{

/* The constructed linked list is:
    1->2->3->4->5 */

    Node* head = NULL;
    push(&head, 5);
    push(&head, 4);
    push(&head, 3);
    push(&head, 2);
    push(&head, 1);

    int k = 2;

/*    Rotate the linked list*/

    Node* updated_head = rightRotate(head, k);

/*    Print the rotated linked list*/

    printList(updated_head);

    return 0;
}

/*C++ implementation of the above approach*/

#include <bits/stdc++.h>
using namespace std;

/*Definition of node of linkedlist*/

struct ListNode {
    int data;
    struct ListNode* next;
};

/*This function take head pointer of list, start and
end points of sublist that is to be rotated and the
number k and rotate the sublist to right by k places.*/

void rotateSubList(ListNode* A, int m, int n, int k)
{
    int size = n - m + 1;

/*    If k is greater than size of sublist then
    we will take its modulo with size of sublist*/

    if (k > size) {
        k = k % size;
    }

/*    If k is zero or k is equal to size or k is
    a multiple of size of sublist then list
    remains intact*/

    if (k == 0 || k == size) {
        ListNode* head = A;
        while (head != NULL) {
            cout << head->data;
            head = head->next;
        }
        return;
    }

/*m-th node*/

ListNode* link = NULL;  
    if (m == 1) {
        link = A;
    }

/*    This loop will traverse all node till
    end node of sublist.   
Current traversed node*/

ListNode* c = A;

/*Count of traversed nodes*/

int count = 0;  
    ListNode* end = NULL;

/*Previous of m-th node*/

ListNode* pre = NULL; 
    while (c != NULL) {
        count++;

/*        We will save (m-1)th node and later
        make it point to (n-k+1)th node*/

        if (count == m - 1) {
            pre = c;
            link = c->next;
        }
        if (count == n - k) {
            if (m == 1) {
                end = c;
                A = c->next;
            }
            else {
                end = c;

/*                That is how we bring (n-k+1)th
                node to front of sublist.*/

                pre->next = c->next;
            }
        }

/*        This keeps rest part of list intact.*/

        if (count == n) {
            ListNode* d = c->next;
            c->next = link;
            end->next = d;
            ListNode* head = A;
            while (head != NULL) {
                cout << head->data << " ";
                head = head->next;
            }
            return;
        }
        c = c->next;
    }
}

/*Function for creating and linking new nodes*/

void push(struct ListNode** head, int val)
{
    struct ListNode* new_node = new ListNode;
    new_node->data = val;
    new_node->next = (*head);
    (*head) = new_node;
}

