    push(&head, 40);
    push(&head, 30);
    push(&head, 20);
    push(&head, 10);
    ListNode* tmp = head;
    cout << "Given List: ";
    while (tmp != NULL) {
        cout << tmp->data << " ";
        tmp = tmp->next;
    }
    cout << endl;

    int m = 3, n = 6, k = 2;
    cout << "After rotation of sublist: ";
    rotateSubList(head, m, n, k);

    return 0;
}

/*Program for count number of rotations in
sorted linked list.*/

#include <bits/stdc++.h>
using namespace std;

/* Linked list node */

struct Node {
    int data;
    struct Node* next;
};

/*Function that count number of
rotation in singly linked list.*/

int countRotation(struct Node* head)
{

/*    declare count variable and assign it 1.*/

    int count = 0;

/*    declare a min variable and assign to
    data of head node.*/

    int min = head->data;

/*    check that while head not equal to NULL.*/

    while (head != NULL) {

/*        if min value is greater then head->data
        then it breaks the while loop and
        return the value of count.*/

        if (min > head->data)
            break;

        count++;

/*        head assign the next value of head.*/

        head = head->next;
    }
    return count;
}

/*Function to push element in linked list.*/

void push(struct Node** head, int data)
{

/*    Allocate dynamic memory for newNode.*/

    struct Node* newNode = new Node;

/*    Assign the data into newNode.*/

    newNode->data = data;

/*    newNode->next assign the address of
    head node.*/

    newNode->next = (*head);

/*    newNode become the headNode.*/

    (*head) = newNode;
}

