/*C++ program to rotate a linked list block wise*/

#include<bits/stdc++.h>
using namespace std;

/* Link list node */

class Node
{
    public:
    int data;
    Node* next;
};

/*Recursive function to rotate one block*/

Node* rotateHelper(Node* blockHead,
                        Node* blockTail,
                        int d, Node** tail,
                        int k)
{
    if (d == 0)
        return blockHead;

/*    Rotate Clockwise*/

    if (d > 0)
    {
        Node* temp = blockHead;
        for (int i = 1; temp->next->next &&
                        i < k - 1; i++)
            temp = temp->next;
        blockTail->next = blockHead;
        *tail = temp;
        return rotateHelper(blockTail, temp,
                            d - 1, tail, k);
    }

/*    Rotate anti-Clockwise*/

    if (d < 0)
    {
        blockTail->next = blockHead;
        *tail = blockHead;
        return rotateHelper(blockHead->next,
                blockHead, d + 1, tail, k);
    }
}

/*Function to rotate the linked list block wise*/

Node* rotateByBlocks(Node* head,
                                int k, int d)
{

/*    If length is 0 or 1 return head*/

    if (!head || !head->next)
        return head;

/*    if degree of rotation is 0, return head*/

    if (d == 0)
        return head;

    Node* temp = head, *tail = NULL;

/*    Traverse upto last element of this block*/

    int i;
    for (i = 1; temp->next && i < k; i++)
        temp = temp->next;

/*    storing the first node of next block*/

    Node* nextBlock = temp->next;

/*    If nodes of this block are less than k.
    Rotate this block also*/

    if (i < k)
        head = rotateHelper(head, temp, d % k,
                                    &tail, i);
    else
        head = rotateHelper(head, temp, d % k,
                                    &tail, k);

/*    Append the new head of next block to
    the tail of this block*/

    tail->next = rotateByBlocks(nextBlock, k,
                                    d % k);

/*    return head of updated Linked List*/

    return head;
}

/* UTILITY FUNCTIONS */

/* Function to push a node */

void push(Node** head_ref, int new_data)
{
    Node* new_node = new Node;
    new_node->data = new_data;
    new_node->next = (*head_ref);
    (*head_ref) = new_node;
}

/* Function to print linked list */

void printList(Node* node)
{
    while (node != NULL)
    {
        cout << node->data << " ";
        node = node->next;
    }
}

/* Driver code*/

int main()
{

/* Start with the empty list */

    Node* head = NULL;

/*    create a list 1->2->3->4->5->
    6->7->8->9->NULL*/

    for (int i = 9; i > 0; i -= 1)
        push(&head, i);

    cout<<"Given linked list \n";
    printList(head);

/*    k is block size and d is number of
    rotations in every block.*/

    int k = 3, d = 2;
    head = rotateByBlocks(head, k, d);

    cout << "\nRotated by blocks Linked list \n";
    printList(head);

    return (0);
}

/*C++ program to rotate
a linked list counter clock wise*/


#include <bits/stdc++.h>
using namespace std;

/* Link list node */

class Node {
public:
    int data;
    Node* next;
};

/*This function rotates a linked list
counter-clockwise and updates the
head. The function assumes that k is
smaller than size of linked list.*/

void rotate(Node** head_ref, int k)
{
    if (k == 0)
        return;

/*    Let us understand the below
    code for example k = 4 and
    list = 10->20->30->40->50->60.*/

    Node* current = *head_ref;

/*    Traverse till the end.*/

    while (current->next != NULL)
        current = current->next;

    current->next = *head_ref;
    current = *head_ref;

/*    traverse the linked list to k-1 position which
    will be last element for rotated array.*/

    for (int i = 0; i < k - 1; i++)
        current = current->next;

/*    update the head_ref and last element pointer to NULL*/

    *head_ref = current->next;
    current->next = NULL;
}

/* UTILITY FUNCTIONS */

/* Function to push a node */

void push(Node** head_ref, int new_data)
{

/* allocate node */

    Node* new_node = new Node();

/* put in the data */

    new_node->data = new_data;

/* link the old list off the new node */

    new_node->next = (*head_ref);

/* move the head to point to the new node */

    (*head_ref) = new_node;
}

/* Function to print linked list */

void printList(Node* node)
{
    while (node != NULL) {
        cout << node->data << " ";
        node = node->next;
    }
}

/* Driver code*/

int main(void)
{

/* Start with the empty list */

    Node* head = NULL;

/*    create a list 10->20->30->40->50->60*/

    for (int i = 60; i > 0; i -= 10)
        push(&head, i);

    cout << "Given linked list \n";
    printList(head);
    rotate(&head, 4);

    cout << "\nRotated Linked list \n";
    printList(head);

    return (0);
}

