/*Function to find the next
greater element for each node*/

void NextGreaterElement(Node *head)
{

/*    Stores the head of circular
    Linked list*/

    Node *H = head;

/*    Stores the head of the
    resulting linked list*/

    Node *res = NULL;

/*    Stores the temporary head of
    the resulting Linked list*/

    Node *tempList = NULL;

/*    Iterate until head
    is not equal to H*/

    do
    {

/*        Used to iterate over the
        circular Linked List*/

        Node *curr = head;

/*        Stores if there exist
        any next Greater element*/

        int Val = -1;

/*        Iterate until head is
        not equal to curr*/

        do
        {

/*            If the current node
            is smaller*/

            if (head->data < curr->data)
            {

/*                Update the value
                of Val*/

                Val = curr->data;
                break;
            }

/*            Update curr*/

            curr = curr->next;

        } while (curr != head);

/*        If res is Null*/

        if (res == NULL)
        {

/*            Create new Node with
            value curr->data*/

            res = new Node(Val);

/*            Assign address of
            res to tempList*/

            tempList = res;
        }
        else
        {

/*            Update tempList*/

            tempList->next = new Node(Val);

/*            Assign address of the
            next node to tempList*/

            tempList = tempList->next;
        }

/*        Update the value of
        head node*/

        head = head->next;
    } while (head != H);

/*    Print the resulting
    Linked list*/

    print(res);
}

/*Driver code*/

int main()
{
    Node *head = new Node(1);
    head->next = new Node(5);
    head->next->next = new Node(12);
    head->next->next->next = new Node(10);

    head->next->next->next->next = new Node(0);
    head->next->next->next->next->next = head;

    NextGreaterElement(head);

    return 0;
}

