}

/*C++ program to remove all
the Even Parity Nodes from a
circular singly linked list*/


#include <bits/stdc++.h>
using namespace std;

/*Structure for a node*/

struct Node {
    int data;
    struct Node* next;
};

/*Function to insert a node at the beginning
of a Circular linked list*/

void push(struct Node** head_ref, int data)
{

/*    Create a new node
    and make head as next
    of it.*/

    struct Node* ptr1
        = (struct Node*)malloc(
            sizeof(struct Node));

    struct Node* temp = *head_ref;
    ptr1->data = data;
    ptr1->next = *head_ref;

/*    If linked list is not NULL then
    set the next of last node*/

    if (*head_ref != NULL) {

/*        Find the node before head
        and update next of it.*/

        while (temp->next != *head_ref)
            temp = temp->next;

        temp->next = ptr1;
    }
    else

/*        Point for the first node*/

        ptr1->next = ptr1;

    *head_ref = ptr1;
}

/*Function to delete the node from a
Circular Linked list*/

void deleteNode(
    Node*& head_ref, Node* del)
{

/*    If node to be deleted is head node*/

    if (head_ref == del)
        head_ref = del->next;

    struct Node* temp = head_ref;

/*    Traverse list till not found
    delete node*/

    while (temp->next != del) {
        temp = temp->next;
    }

/*    Copy the address of the node*/

    temp->next = del->next;

/*    Finally, free the memory
    occupied by del*/

    free(del);

    return;
}

/*Function that returns true if count
of set bits in x is even*/

bool isEvenParity(int x)
{

/*    parity will store the
    count of set bits*/

    int parity = 0;
    while (x != 0) {
        if (x & 1)
            parity++;
        x = x >> 1;
    }

    if (parity % 2 == 0)
        return true;
    else
        return false;
}

/*Function to delete all
the Even Parity Nodes
from the singly circular linked list*/

void deleteEvenParityNodes(Node*& head)
{
    if (head == NULL)
        return;

    if (head == head->next) {
        if (isEvenParity(head->data))
            head = NULL;
        return;
    }

    struct Node* ptr = head;

    struct Node* next;

/*    Traverse the list till the end*/

    do {
        next = ptr->next;

/*        If the node's data has even parity,
        delete node 'ptr'*/

        if (isEvenParity(ptr->data))
            deleteNode(head, ptr);

/*        Point to the next node*/

        ptr = next;

    } while (ptr != head);

    if (head == head->next) {
        if (isEvenParity(head->data))
            head = NULL;
        return;
    }
}

/*Function to print nodes in a
given Circular linked list*/

void printList(struct Node* head)
{
    if (head == NULL) {
        cout << "Empty List\n";
        return;
    }

    struct Node* temp = head;
    if (head != NULL) {
        do {
            printf("%d ", temp->data);
            temp = temp->next;
        } while (temp != head);
    }
}

/*Driver code*/

int main()
{

/*    Initialize lists as empty*/

    struct Node* head = NULL;

/*    Created linked list will be
    11->9->34->6->13->21*/

    push(&head, 21);
    push(&head, 13);
    push(&head, 6);
    push(&head, 34);
    push(&head, 9);
    push(&head, 11);

    deleteEvenParityNodes(head);

    printList(head);

    return 0;
}

/*C++ program to remove all
the Even Digit Sum Nodes from a
circular singly linked list*/


#include <bits/stdc++.h>
using namespace std;

/*Structure for a node*/

struct Node {
    int data;
    struct Node* next;
};

/*Function to insert a node at the beginning
of a Circular linked list*/

void push(struct Node** head_ref, int data)
{

/*    Create a new node and make head as next
    of it.*/

    struct Node* ptr1
        = (struct Node*)malloc(
            sizeof(struct Node));

    struct Node* temp = *head_ref;
    ptr1->data = data;
    ptr1->next = *head_ref;

/*    If linked list is not NULL then
    set the next of last node*/

    if (*head_ref != NULL) {

/*        Find the node before head
        and update next of it.*/

        while (temp->next != *head_ref)
            temp = temp->next;

        temp->next = ptr1;
    }
    else

/*        Point for the first node*/

        ptr1->next = ptr1;

    *head_ref = ptr1;
}

/*Function to delete the node from a
Circular Linked list*/

void deleteNode(Node* head_ref, Node* del)
{
    struct Node* temp = head_ref;

/*    If node to be deleted is head node*/

    if (head_ref == del)
        head_ref = del->next;

/*    Traverse list till not found
    delete node*/

    while (temp->next != del) {
        temp = temp->next;
    }

/*    Copy the address of the node*/

    temp->next = del->next;

/*    Finally, free the memory
    occupied by del*/

    free(del);

    return;
}

/*Function to find the digit sum
for a number*/

int digitSum(int num)
{
    int sum = 0;
    while (num) {
        sum += (num % 10);
        num /= 10;
    }

    return sum;
}

/*Function to delete all the Even Digit Sum Nodes
from the singly circular linked list*/

void deleteEvenDigitSumNodes(Node* head)
{
    struct Node* ptr = head;

    struct Node* next;

/*    Traverse the list till the end*/

    do {

/*        If the node's data is Fibonacci,
        delete node 'ptr'*/

        if (!(digitSum(ptr->data) & 1))
            deleteNode(head, ptr);

/*        Point to the next node*/

        next = ptr->next;
        ptr = next;

    } while (ptr != head);
}

