/*C++ implementation of the approach*/

#include <bits/stdc++.h>
using namespace std;

/*Node structure*/

struct Node {
    Node* next;
    int data;
};

/*Function to create a node*/

Node* create()
{
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->next = NULL;

    return new_node;
}

/*Function to find and return the head*/

Node* find_head(Node* random)
{

/*    If the list is empty*/

    if (random == NULL)
        return NULL;

    Node *head, *var = random;

/*    Finding the last node of the linked list
    the last node must have the highest value
    if no such element is present then all the nodes
    of the linked list must be same*/

    while (!(var->data > var->next->data || var->next == random)) {
        var = var->next;
    }

/*    Return the head*/

    return var->next;
}

/*Function to insert a new_node in the list in sorted fashion
Note that this function expects a pointer to head node
as this can modify the head of the input linked list*/

Node* sortedInsert(Node* head_ref, Node* new_node)
{
    Node* current = head_ref;

/*    If the list is empty*/

    if (current == NULL) {
        new_node->next = new_node;
        head_ref = new_node;
    }

/*    If the node to be inserted is the smallest
    then it has to be the new head*/

    else if (current->data >= new_node->data) {

/*        Find the last node of the list as it
        will be pointing to the head*/

        while (current->next != head_ref)
            current = current->next;
        current->next = new_node;
        new_node->next = head_ref;
        head_ref = new_node;
    }

    else {

/*        Locate the node before the point of insertion*/

        while (current->next != head_ref
               && current->next->data < new_node->data) {
            current = current->next;
        }

        new_node->next = current->next;
        current->next = new_node;
    }

/*    Return the new head*/

    return head_ref;
}

/*Function to print the nodes of the linked list*/

void printList(Node* start)
{
    Node* temp;

    if (start != NULL) {
        temp = start;
        do {
            cout << temp->data << " ";
            temp = temp->next;
        } while (temp != start);
    }
}

/*Driver code*/

int main()
{

    int arr[] = { 12, 56, 2, 11, 1, 90 };
    int list_size, i;

/*    Start with an empty linked list*/

    Node* start = NULL;
    Node* temp;

/*    Create linked list from the given array*/

    for (i = 0; i < 6; i++) {

/*        Move to a random node if it exists*/

        if (start != NULL)
            for (int j = 0; j < (rand() % 10); j++)
                start = start->next;

        temp = create();
        temp->data = arr[i];
        start = sortedInsert(find_head(start), temp);
    }

/*    Print the contents of the created list*/

    printList(find_head(start));

    return 0;
}

/*C++ implementation of the approach*/

#include<bits/stdc++.h>
using namespace std;

class CircularLinkedList
{
    public:
    struct Node
    {
        int data;
        Node* next;
    };

    Node* last;

/*    Function to add a node to the empty list*/

    Node* addToEmpty(int data)
    {

/*        If not empty*/

        if (last != NULL)
            return last;

/*        Creating a node dynamically*/

        Node *temp = new Node();

/*        Assigning the data*/

        temp->data = data;
        last = temp;

/*        Creating the link*/

        last->next = last;

        return last;
    }

/*    Function to add a node to the
    beginning of the list*/

    Node* addBegin(int data)
    {

/*        If list is empty*/

        if (last == NULL)
            return addToEmpty(data);

/*        Create node*/

        Node *temp = new Node();

/*        Assign data*/

        temp->data = data;
        temp->next = last->next;
        last->next = temp;

        return last;
    }

/*    Function to traverse and print the list*/

    void traverse()
    {
        Node* p;

/*        If list is empty*/

        if (last == NULL)
        {
            cout<<("List is empty.");
            return;
        }

/*        Pointing to the first Node of the list*/

        p = last->next;

/*        Traversing the list*/

        do
        {
            cout << p->data << " ";
            p = p->next;
        } while (p != last->next);
        cout << endl;
    }

/*    Function to find the length of the CircularLinkedList*/

    int length()
    {

/*        Stores the length*/

        int x = 0;

/*        List is empty*/

        if (last == NULL)
            return x;

/*        Iterator Node to traverse the List*/

        Node* itr = last->next;
        while (itr->next != last->next)
        {
            x++;
            itr = itr->next;
        }

/*        Return the length of the list*/

        return (x + 1);
    }

/*    Function to split the first k nodes into
    a new CircularLinkedList and the remaining
    nodes stay in the original CircularLinkedList*/

    Node* split(int k)
    {

/*        Empty Node for reference*/

        Node* pass = new Node();

/*        Check if the list is empty
        If yes, then return NULL*/

        if (last == NULL)
            return last;

/*        NewLast will contain the last node of
        the new split list
        itr to iterate the node till
        the required node*/

        Node* newLast, *itr = last;
        for (int i = 0; i < k; i++)
        {
            itr = itr->next;
        }

/*        Update NewLast to the required node and
        link the last to the start of rest of the list*/

        newLast = itr;
        pass->next = itr->next;
        newLast->next = last->next;
        last->next = pass->next;

/*        Return the last node of the required list*/

        return newLast;
    }
};

/*    Driver code*/

int main()
{
    CircularLinkedList* clist = new CircularLinkedList();
    clist->last = NULL;

    clist->addToEmpty(12);
    clist->addBegin(10);
    clist->addBegin(8);
    clist->addBegin(6);
    clist->addBegin(4);
    clist->addBegin(2);
    cout<<("Original list:");
    clist->traverse();

    int k = 4;

/*    Create a new list for the starting k nodes*/

    CircularLinkedList* clist2 = new CircularLinkedList();

/*    Append the new last node into the new list*/

    clist2->last = clist->split(k);

/*    Print the new lists*/

    cout<<("The new lists are:");
    clist2->traverse();
    clist->traverse();
}

/*A C++ program for conversion
of Binary Tree to CDLL*/


#include <bits/stdc++.h>
using namespace std;

/*A binary tree node has data,
and left and right pointers*/

struct Node {
    int data;
    struct Node* left;
    struct Node* right;

    Node(int x)
    {
        data = x;
        left = right = NULL;
    }
};

/*Function to perform In-Order traversal of the
tree and store the nodes in a vector*/

void inorder(Node* root, vector<int>& v)
{
    if (!root)
        return;

/* first recur on left child */

    inorder(root->left, v);

/* append the data of node in vector */

    v.push_back(root->data);

/* now recur on right child */

    inorder(root->right, v);
}

/*Function to convert Binary Tree to Circular
Doubly Linked list using the vector which stores
In-Order traversal of the Binary Tree*/

Node* bTreeToCList(Node* root)
{

/*    Base cases*/

    if (root == NULL)
        return NULL;

/*    Vector to be used for storing the nodes
    of tree in In-order form*/

    vector<int> v;

/*    Calling the In-Order traversal function*/

    inorder(root, v);

/*    Create the head of the linked list pointing
    to the root of the tree*/

    Node* head_ref = new Node(v[0]);

/*    Create a current pointer to be used in traversal*/

    Node* curr = head_ref;

/*    Traversing the nodes of the tree starting
    from the second elements*/

    for (int i = 1; i < v.size(); i++) {

/*        Create a temporary pointer
        pointing to current*/

        Node* temp = curr;

/*        Current's right points to the current
        node in traversal*/

        curr->right = new Node(v[i]);

/*        Current points to its right*/

        curr = curr->right;

/*        Current's left points to temp*/

        curr->left = temp;
    }

/*    Current's right points to head of the list*/

    curr->right = head_ref;

/*    Head's left points to current*/

    head_ref->left = curr;

/*    Return head of the list*/

    return head_ref;
}

/*Display Circular Link List*/

void displayCList(Node* head)
{
    cout << "Circular Doubly Linked List is :\n";

    Node* itr = head;
    do {
        cout << itr->data << " ";
        itr = itr->right;
    } while (head != itr);

    cout << "\n";
}

/*Driver Code*/

int main()
{
    Node* root = new Node(10);
    root->left = new Node(12);
    root->right = new Node(15);
    root->left->left = new Node(25);
    root->left->right = new Node(30);
    root->right->left = new Node(36);

    Node* head = bTreeToCList(root);
    displayCList(head);

    return 0;
}

/*C++ program to delete all even and odd position
nodes from Singly Circular Linked list*/


#include <bits/stdc++.h>

/*structure for a node*/

struct Node {
    int data;
    struct Node* next;
};

/*Function return number of nodes present in list*/

int Length(struct Node* head)
{
    struct Node* current = head;
    int count = 0;

/*    if list is empty simply return length zero*/

    if (head == NULL) {
        return 0;
    }

/*    traverse forst to last node*/

    else {
        do {
            current = current->next;
            count++;
        } while (current != head);
    }
    return count;
}

/*Function print data of list*/

void Display(struct Node* head)
{
    struct Node* current = head;

/*    if list is empty simply show message*/

    if (head == NULL) {
        printf("\nDisplay List is empty\n");
        return;
    }

/*    traverse forst to last node*/

    else {
        do {
            printf("%d ", current->data);
            current = current->next;
        } while (current != head);
    }
}

/* Function to insert a node at the end of
a Circular linked list */

void Insert(struct Node** head, int data)
{
    struct Node* current = *head;

/*    Create a new node*/

    struct Node* newNode = new Node;

/*    check node is created or not*/

    if (!newNode) {
        printf("\nMemory Error\n");
        return;
    }

/*    insert data into newly created node*/

    newNode->data = data;

/*    check list is empty
    if not have any node then
    make first node it*/

    if (*head == NULL) {
        newNode->next = newNode;
        *head = newNode;
        return;

/*if list have already some node*/

} 
    else {

/*        move firt node to last node*/

        while (current->next != *head) {
            current = current->next;
        }

/*        put first or head node address in new node link*/

        newNode->next = *head;

/*        put new node address into last node link(next)*/

        current->next = newNode;
    }
}

/*Utitlity function to delete a Node*/

void deleteNode(struct Node* head_ref, struct Node* del)
{
    struct Node* temp = head_ref;

/*    If node to be deleted is head node*/


    if (head_ref == del) {
        head_ref = del->next;
    }

/*    traverse list till not found
    delete node*/

    while (temp->next != del) {
        temp = temp->next;
    }

/*    copy address of node*/

    temp->next = del->next;

/*    Finally, free the memory
    occupied by del*/

    free(del);

    return;
}

/*Function to delete First node of
Circular Linked List*/

void DeleteFirst(struct Node** head)
{
    struct Node *previous = *head, *next = *head;

/*    check list have any node
    if not then return*/

    if (*head == NULL) {
        printf("\nList is empty\n");
        return;
    }

/*    check list have single node
    if yes then delete it and return*/

    if (previous->next == previous) {
        *head = NULL;
        return;
    }

/*    traverse second to first*/

    while (previous->next != *head) {

        previous = previous->next;
        next = previous->next;
    }

/*    now previous is last node and
    next is first node of list
    first node(next) link address
    put in last node(previous) link*/

    previous->next = next->next;

/*    make second node as head node*/

    *head = previous->next;
    free(next);
    return;
}

/*Function to delete odd position nodes*/

void DeleteAllOddNode(struct Node** head)
{
    int len = Length(*head);
    int count = 0;
    struct Node *previous = *head, *next = *head;

/*    check list have any node
    if not then return*/

    if (*head == NULL) {
        printf("\nDelete Last List is empty\n");
        return;
    }

/*    if list have single node means
    odd position then delete it*/

    if (len == 1) {
        DeleteFirst(head);
        return;
    }

/*    traverse first to last if
    list have more than one node*/

    while (len > 0) {

/*        delete first position node
        which is odd position*/

        if (count == 0) {

/*            Function to delete first node*/

            DeleteFirst(head);
        }

/*        check position is odd or not
        if yes then delete node
        Note: Considered 1 based indexing*/

        if (count % 2 == 0 && count != 0) {
            deleteNode(*head, previous);
        }

        previous = previous->next;
        next = previous->next;

        len--;
        count++;
    }

    return;
}

/*Function to delete all even position nodes*/

void DeleteAllEvenNode(struct Node** head)
{

/*    Take size of list*/

    int len = Length(*head);

    int count = 1;
    struct Node *previous = *head, *next = *head;

/*    Check list is empty
    if empty simply return*/

    if (*head == NULL) {
        printf("\nList is empty\n");
        return;
    }

/*    if list have single node
    then return*/

    if (len < 2) {
        return;
    }

/*    make first node is previous*/

    previous = *head;

/*    make second node is current*/

    next = previous->next;

    while (len > 0) {

/*        check node number is even
        if node is even then
        delete that node*/

        if (count % 2 == 0) {
            previous->next = next->next;
            free(next);
            previous = next->next;
            next = previous->next;
        }

        len--;
        count++;
    }

    return;
}

/*Driver Code*/

int main()
{
    struct Node* head = NULL;
    Insert(&head, 99);
    Insert(&head, 11);
    Insert(&head, 22);
    Insert(&head, 33);
    Insert(&head, 44);
    Insert(&head, 55);
    Insert(&head, 66);

/*    Deleting Odd positioned nodes*/

    printf("Initial List: ");
    Display(head);

    printf("\nAfter deleting Odd position nodes: ");
    DeleteAllOddNode(&head);
    Display(head);

/*    Deleting Even positioned nodes*/

    printf("\n\nInitial List: ");
    Display(head);

    printf("\nAfter deleting even position nodes: ");
    DeleteAllEvenNode(&head);
    Display(head);

    return 0;
}

