    else {

/*        move first node to last node*/

        while (current->next != *head) {
            current = current->next;
        }

/*        put first or head node address
        in new node link*/

        newNode->next = *head;

/*        put new node address into last
        node link(next)*/

        current->next = newNode;
    }
}

/*Function print data of list*/

void Display(struct Node* head)
{
    struct Node* current = head;

/*    if list is empty, simply show message*/

    if (head == NULL) {
        printf("\nDisplay List is empty\n");
        return;
    }

/*    traverse first to last node*/

    else {
        do {
            printf("%d ", current->data);
            current = current->next;
        } while (current != head);
    }
}

/*Function return number of nodes present in list*/

int Length(struct Node* head)
{
    struct Node* current = head;
    int count = 0;

/*    if list is empty simply return length zero*/

    if (head == NULL) {
        return 0;
    }

/*    traverse forst to last node*/

    else {
        do {
            current = current->next;
            count++;
        } while (current != head);
    }
    return count;
}

/*Function delete First node of Circular Linked List*/

void DeleteFirst(struct Node** head)
{
    struct Node *previous = *head, *next = *head;

/*    check list have any node
    if not then return*/

    if (*head == NULL) {
        printf("\nList is empty\n");
        return;
    }

/*    check list have single node
    if yes then delete it and return*/

    if (previous->next == previous) {
        *head = NULL;
        return;
    }

/*    traverse second to first*/

    while (previous->next != *head) {

        previous = previous->next;
        next = previous->next;
    }

/*    now previous is last node and
    next is first node of list
    first node(next) link address
    put in last node(previous) link*/

    previous->next = next->next;

/*    make second node as head node*/

    *head = previous->next;
    free(next);

    return;
}

/*Function to delete last node of
Circular Linked List*/

void DeleteLast(struct Node** head)
{
    struct Node *current = *head, *temp = *head, *previous;

/*    check if list doesn't have any node
    if not then return*/

    if (*head == NULL) {
        printf("\nList is empty\n");
        return;
    }

/*    check if list have single node
    if yes then delete it and return*/

    if (current->next == current) {
        *head = NULL;
        return;
    }

/*    move first node to last
    previous*/

    while (current->next != *head) {
        previous = current;
        current = current->next;
    }

    previous->next = current->next;
    *head = previous->next;
    free(current);

    return;
}

/*Function delete node at a given poisition
of Circular Linked List*/

void DeleteAtPosition(struct Node** head, int index)
{

/*    Find length of list*/

    int len = Length(*head);
    int count = 1;
    struct Node *previous = *head, *next = *head;

/*    check list have any node
    if not then return*/

    if (*head == NULL) {
        printf("\nDelete Last List is empty\n");
        return;
    }

/*    given index is in list or not*/

    if (index >= len || index < 0) {
        printf("\nIndex is not Found\n");
        return;
    }

/*    delete first node*/

    if (index == 0) {
        DeleteFirst(head);
        return;
    }

/*    traverse first to last node*/

    while (len > 0) {

/*        if index found delete that node*/

        if (index == count) {
            previous->next = next->next;
            free(next);
            return;
        }
        previous = previous->next;
        next = previous->next;
        len--;
        count++;
    }
    return;
}

/*Driver Code*/

int main()
{
    struct Node* head = NULL;
    Insert(&head, 99);
    Insert(&head, 11);
    Insert(&head, 22);
    Insert(&head, 33);
    Insert(&head, 44);
    Insert(&head, 55);
    Insert(&head, 66);

/*    Deleting Node at position*/

    printf("Initial List: ");
    Display(head);
    printf("\nAfter Deleting node at index 4: ");
    DeleteAtPosition(&head, 4);
    Display(head);

/*    Deleting first Node*/

    printf("\n\nInitial List: ");
    Display(head);
    printf("\nAfter Deleting first node: ");
    DeleteFirst(&head);
    Display(head);

/*    Deleting last Node*/

    printf("\n\nInitial List: ");
    Display(head);
    printf("\nAfter Deleting last node: ");
    DeleteLast(&head);
    Display(head);

    return 0;
}

/*C++ program to find minimum and maximum
value from singly circular linked list*/

#include <bits/stdc++.h>
using namespace std;

/*structure for a node*/

struct Node {
    int data;
    struct Node* next;
};

/*Function to print minimum and maximum
nodes of the circular linked list*/

void printMinMax(struct Node** head)
{

/*    check list is empty*/

    if (*head == NULL) {
        return;
    }

/*    pointer for traversing*/

    struct Node* current;

/*    initialize head to current pointer*/

    current = *head;

/*    initialize max int value to min
    initialize min int value to max*/

    int min = INT_MAX, max = INT_MIN;

/*    While last node is not reached*/

    do {

/*        If current node data is lesser for min
        then replace it*/

        if (current->data < min) {
            min = current->data;
        }

/*        If current node data is greater for max
        then replace it*/

        if (current->data > max) {
            max = current->data;
        }

        current = current->next;
    }while(current != head);

    cout << "\nMinimum = " << min << ", Maximum = " << max;
}

/*Function to insert a node at the end of
a Circular linked list*/

void insertNode(struct Node** head, int data)
{
    struct Node* current = *head;

/*    Create a new node*/

    struct Node* newNode = new Node;

/*    check node is created or not*/

    if (!newNode) {
        printf("\nMemory Error\n");
        return;
    }

/*    insert data into newly created node*/

    newNode->data = data;

/*    check list is empty
    if not have any node then
    make first node it*/

    if (*head == NULL) {
        newNode->next = newNode;
        *head = newNode;
        return;
    }

/*    if list have already some node*/

    else {

/*        move firt node to last node*/

        while (current->next != *head) {
            current = current->next;
        }

/*        put first or head node address
        in new node link*/

        newNode->next = *head;

/*        put new node address into
        last node link(next)*/

        current->next = newNode;
    }
}

/*Function to print the Circular linked list*/

void displayList(struct Node* head)
{

    struct Node* current = head;

/*    if list is empty simply show message*/

    if (head == NULL) {
        printf("\nDisplay List is empty\n");
        return;
    }

/*    traverse first to last node*/

    else {
        do {
            printf("%d ", current->data);
            current = current->next;
        } while (current != head);
    }
}

/*Driver Code*/

int main()
{
    struct Node* Head = NULL;

    insertNode(&Head, 99);
    insertNode(&Head, 11);
    insertNode(&Head, 22);
    insertNode(&Head, 33);
    insertNode(&Head, 44);
    insertNode(&Head, 55);
    insertNode(&Head, 66);

    cout << "Initial List: ";

    displayList(Head);

    printMinMax(&Head);

    return 0;
}

/*CPP program to delete all even
node from a Circular singly linked list*/


#include <bits/stdc++.h>
using namespace std;

/*Structure for a node*/

struct Node {
    int data;
    struct Node* next;
};

/*Function to insert a node at the beginning
of a Circular linked list*/

void push(struct Node** head_ref, int data)
{
    struct Node* ptr1 = (struct Node*)malloc(sizeof(struct Node));
    struct Node* temp = *head_ref;
    ptr1->data = data;
    ptr1->next = *head_ref;

/*    If linked list is not NULL then
    set the next of last node*/

    if (*head_ref != NULL) {
        while (temp->next != *head_ref)
            temp = temp->next;
        temp->next = ptr1;
    }
    else

/*For the first node*/

ptr1->next = ptr1; 

    *head_ref = ptr1;
}

/*Delete the node if it is even*/

void deleteNode(Node* head_ref, Node* del)
{
    struct Node* temp = head_ref;

/*    If node to be deleted is head node*/


    if (head_ref == del)
        head_ref = del->next;

/*    traverse list till not found
    delete node*/

    while (temp->next != del) {
        temp = temp->next;
    }

/*    copy address of node*/

    temp->next = del->next;

/*    Finally, free the memory occupied by del*/

    free(del);
    return;
}

/*Function to delete all even nodes
from the singly circular  linked list*/

void deleteEvenNodes(Node* head)
{
    struct Node* ptr = head;

    struct Node* next;

/*    traverse list till the end
    if the node is even then delete it*/

    do {

/*        if node is even*/

        if (ptr->data % 2 == 0)
            deleteNode(head, ptr);

/*        point to next node*/

        next = ptr->next;
        ptr = next;
    } while (ptr != head);
}

/*Function to print nodes*/

void printList(struct Node* head)
{
    struct Node* temp = head;
    if (head != NULL) {
        do {
            printf("%d ", temp->data);
            temp = temp->next;
        } while (temp != head);
    }
}

/*Driver code*/

int main()
{

/*    Initialize lists as empty*/

    struct Node* head = NULL;

/*    Created linked list will be 57->11->2->56->12->61*/

    push(&head, 61);
    push(&head, 12);
    push(&head, 56);
    push(&head, 2);
    push(&head, 11);
    push(&head, 57);

    cout << "\nList after deletion : ";
    deleteEvenNodes(head);
    printList(head);

    return 0;
}

/*CPP program to find the sum of all nodes
of a Circular linked list*/


#include <bits/stdc++.h>
using namespace std;

/*Structure for a node*/

struct Node {
    int data;
    struct Node* next;
};

/*Function to insert a node at the beginning
of a Circular linked list*/

void push(struct Node** head_ref, int data)
{
    struct Node* ptr1 = (struct Node*)malloc(sizeof(struct Node));
    struct Node* temp = *head_ref;
    ptr1->data = data;
    ptr1->next = *head_ref;

/*    If linked list is not NULL then
    set the next of last node*/

    if (*head_ref != NULL) {
        while (temp->next != *head_ref)
            temp = temp->next;
        temp->next = ptr1;
    }
    else

/*For the first node*/

ptr1->next = ptr1; 

    *head_ref = ptr1;
}

/*Function to find sum of the given
Circular linked list*/

int sumOfList(struct Node* head)
{
    struct Node* temp = head;
    int sum = 0;
    if (head != NULL) {
        do {
            temp = temp->next;
            sum += temp->data;
        } while (temp != head);
    }

    return sum;
}

