/*C++ program to delete every kth Node from
circular linked list.*/

#include <bits/stdc++.h>
using namespace std;

/* structure for a Node */

struct Node {
    int data;
    Node* next;
    Node(int x)
    {
        data = x;
        next = NULL;
    }
};

/*Utility function to print the circular linked list*/

void printList(Node* head)
{
    if (head == NULL)
        return;
    Node* temp = head;
    do {
        cout << temp->data << "->";
        temp = temp->next;
    } while (temp != head);
    cout << head->data << endl;
}

/*Function to delete every kth Node*/

void deleteK(Node** head_ref, int k)
{
    Node* head = *head_ref;

/*    If list is empty, simply return.*/

    if (head == NULL)
        return;

/*    take two pointers - current and previous*/

    Node *curr = head, *prev;
    while (true) {

/*        Check if Node is the only Node\
        If yes, we reached the goal, therefore
        return.*/

        if (curr->next == head && curr == head)
            break;

/*        Print intermediate list.*/

        printList(head);

/*        If more than one Node present in the list,
        Make previous pointer point to current
        Iterate current pointer k times,
        i.e. current Node is to be deleted.*/

        for (int i = 0; i < k; i++) {
            prev = curr;
            curr = curr->next;
        }

/*        If Node to be deleted is head*/

        if (curr == head) {
            prev = head;
            while (prev->next != head)
                prev = prev->next;
            head = curr->next;
            prev->next = head;
            *head_ref = head;
            free(curr);
        }

/*        If Node to be deleted is last Node.*/

        else if (curr->next == head) {
            prev->next = head;
            free(curr);
        }
        else {
            prev->next = curr->next;
            free(curr);
        }
    }
}

/* Function to insert a Node at the end of
a Circular linked list */

void insertNode(Node** head_ref, int x)
{

/*    Create a new Node*/

    Node* head = *head_ref;
    Node* temp = new Node(x);

/*    if the list is empty, make the new Node head
    Also, it will point to itself.*/

    if (head == NULL) {
        temp->next = temp;
        *head_ref = temp;
    }

/*    traverse the list to reach the last Node
    and insert the Node*/

    else {
        Node* temp1 = head;
        while (temp1->next != head)
            temp1 = temp1->next;
        temp1->next = temp;
        temp->next = head;
    }
}

/* Driver program to test above functions */

int main()
{

/*    insert Nodes in the circular linked list*/

    struct Node* head = NULL;
    insertNode(&head, 1);
    insertNode(&head, 2);
    insertNode(&head, 3);
    insertNode(&head, 4);
    insertNode(&head, 5);
    insertNode(&head, 6);
    insertNode(&head, 7);
    insertNode(&head, 8);
    insertNode(&head, 9);

    int k = 4;

/*    Delete every kth Node from the
    circular linked list.*/

    deleteK(&head, k);

    return 0;
}

/*C++ program to illustrate inserting a Node in
a Cicular Doubly Linked list in begging, end
and middle*/

#include <bits/stdc++.h>
using namespace std;

/*Structure of a Node*/

struct Node
{
    int data;
    struct Node *next;
    struct Node *prev;
};

/*Function to insert a node at the end*/

void insertNode(struct Node** start, int value)
{

/*    If the list is empty, create a single node
    circular and doubly list*/

    if (*start == NULL)
    {
        struct Node* new_node = new Node;
        new_node->data = value;
        new_node->next = new_node->prev = new_node;
        *start = new_node;
        return;
    }

/*    If list is not empty*/

/* Find last node */

    Node *last = (*start)->prev;

/*    Create Node dynamically*/

    struct Node* new_node = new Node;
    new_node->data = value;

/*    Start is going to be next of new_node*/

    new_node->next = *start;

/*    Make new node previous of start*/

    (*start)->prev = new_node;

/*    Make last preivous of new node*/

    new_node->prev = last;

/*    Make new node next of old last*/

    last->next = new_node;
}

/*Function to display the
circular doubly linked list*/

void displayList(struct Node* start)
{
    struct Node *temp = start;

    while (temp->next != start)
    {
        printf("%d ", temp->data);
        temp = temp->next;
    }
    printf("%d ", temp->data);
}

/*Function to search the particular element
from the list*/

int searchList(struct Node* start, int search)
{

/*    Declare the temp variable*/

    struct Node *temp = start;

/*    Declare other control
    variable for the searching*/

    int count=0,flag=0,value;

/*    If start is NULL return -1*/

    if(temp == NULL)
        return -1;
    else
    {

/*        Move the temp pointer until,
        temp->next doesn't move
        start address (Circular Fashion)*/

        while(temp->next != start)
        {

/*            Increment count for location*/

            count++;

/*            If it is found raise the
            flag and break the loop*/

            if(temp->data == search)
            {
                flag = 1;
                count--;
                break;
            }

/*            Increment temp pointer*/

            temp = temp->next;  
        }

/*        Check whether last element in the
        list content the value if contain,
        raise a flag and increment count*/

        if(temp->data == search)
        {
            count++;
            flag = 1;
        }

/*        If flag is true, then element
        found, else not*/

        if(flag == 1)
            cout<<"\n"<<search <<" found at location "<<
                                            count<<endl;
        else
            cout<<"\n"<<search <<" not found"<<endl;
    }
}

/*Driver code*/

int main()
{

/* Start with the empty list */

    struct Node* start = NULL;

/*    Insert 4. So linked list becomes 4->NULL*/

    insertNode(&start, 4);

/*    Insert 5. So linked list becomes 4->5*/

    insertNode(&start, 5);

/*    Insert 7. So linked list
    becomes 4->5->7*/

    insertNode(&start, 7);

/*    Insert 8. So linked list
    becomes 4->5->7->8*/

    insertNode(&start, 8);

/*    Insert 6. So linked list
    becomes 4->5->7->8->6*/

    insertNode(&start, 6);

    printf("Created circular doubly linked list is: ");
    displayList(start);

    searchList(start, 5);

    return 0;
}

/*CPP program to convert insert an element at a specific
position in a circular doubly linked list*/


#include <bits/stdc++.h>
using namespace std;

/*Doubly linked list node*/

struct node {
    int data;
    struct node* next;
    struct node* prev;
};

/*Utility function to create a node in memory*/

struct node* getNode()
{
    return ((struct node*)malloc(sizeof(struct node)));
}

/*Function to display the list*/

int displayList(struct node* temp)
{
    struct node* t = temp;
    if (temp == NULL)
        return 0;
    else {
        cout << "The list is: ";

        while (temp->next != t) {
            cout << temp->data << " ";
            temp = temp->next;
        }

        cout << temp->data << endl;

        return 1;
    }
}

/*Function to count nunmber of
elements in the list*/

int countList(struct node* start)
{

/*    Declare temp pointer to
    traverse the list*/

    struct node* temp = start;

/*    Variable to store the count*/

    int count = 0;

/*    Iterate the list and increment the count*/

    while (temp->next != start) {
        temp = temp->next;
        count++;
    }

/*    As the list is circular, increment the
    counter at last*/

    count++;

    return count;
}

/*Function to insert a node at a given position
in the circular doubly linked list*/

bool insertAtLocation(struct node* start, int data, int loc)
{

/*    Declare two pointers*/

    struct node *temp, *newNode;
    int i, count;

/*    Create a new node in memory*/

    newNode = getNode();

/*    Point temp to start*/

    temp = start;

/*    count of total elements in the list*/

    count = countList(start);

/*    If list is empty or the position is
    not valid, return false*/

    if (temp == NULL || count < loc)
        return false;

    else {

/*        Assign the data*/

        newNode->data = data;

/*        Iterate till the loc*/

        for (i = 1; i < loc - 1; i++) {
            temp = temp->next;
        }

/*        See in Image, circle 1*/

        newNode->next = temp->next;

/*        See in Image, Circle 2*/

        (temp->next)->prev = newNode;

/*        See in Image, Circle 3*/

        temp->next = newNode;

/*        See in Image, Circle 4*/

        newNode->prev = temp;

        return true;
    }

    return false;
}

/*Function to create circular doubly linked list
from array elements*/

void createList(int arr[], int n, struct node** start)
{

/*    Declare newNode and temporary pointer*/

    struct node *newNode, *temp;
    int i;

/*    Iterate the loop until array length*/

    for (i = 0; i < n; i++) {

/*        Create new node*/

        newNode = getNode();

/*        Assign the array data*/

        newNode->data = arr[i];

/*        If it is first element
        Put that node prev and next as start
        as it is circular*/

        if (i == 0) {
            *start = newNode;
            newNode->prev = *start;
            newNode->next = *start;
        }

        else {

/*            Find the last node*/

            temp = (*start)->prev;

/*            Add the last node to make them
            in circular fashion*/

            temp->next = newNode;
            newNode->next = *start;
            newNode->prev = temp;
            temp = *start;
            temp->prev = newNode;
        }
    }
}

/*Driver Code*/

int main()
{

/*    Array elements to create
    circular doubly linked list*/

    int arr[] = { 1, 2, 3, 4, 5, 6 };
    int n = sizeof(arr) / sizeof(arr[0]);

/*    Start Pointer*/

    struct node* start = NULL;

/*    Create the List*/

    createList(arr, n, &start);

/*    Display the list before insertion*/

    displayList(start);

/*    Inserting 8 at 3rd position*/

    insertAtLocation(start, 8, 3);

/*    Display the list after insertion*/

    displayList(start);

    return 0;
}

/*C++ implementation to revesre a
doubly circular linked list*/

#include <bits/stdc++.h>

using namespace std;

/*structure of a node of linked list*/

struct Node {
    int data;
    Node *next, *prev;
};

/*function to create and return a new node*/

Node* getNode(int data)
{
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    return newNode;
}

/*Function to insert at the end*/

void insertEnd(Node** head, Node* new_node)
{

/*    If the list is empty, create a single node
    circular and doubly list*/

    if (*head == NULL) {
        new_node->next = new_node->prev = new_node;
        *head = new_node;
        return;
    }

/*    If list is not empty*/

/* Find last node */

    Node* last = (*head)->prev;

/*    Start is going to be next of new_node*/

    new_node->next = *head;

/*    Make new node previous of start*/

    (*head)->prev = new_node;

/*    Make last preivous of new node*/

    new_node->prev = last;

/*    Make new node next of old last*/

    last->next = new_node;
}

/*Uitlity function to revesre a
doubly circular linked list*/

Node* reverse(Node* head)
{
    if (!head)
        return NULL;

/*    Initialize a new head pointer*/

    Node* new_head = NULL;

/*    get pointer to the the last node*/

    Node* last = head->prev;

/*    set 'curr' to last node*/

    Node *curr = last, *prev;

/*    traverse list in backward direction*/

    while (curr->prev != last) {
        prev = curr->prev;

/*        insert 'curr' at the end of the list
        starting with the 'new_head' pointer*/

        insertEnd(&new_head, curr);
        curr = prev;
    }
    insertEnd(&new_head, curr);

/*    head pointer of the reversed list*/

    return new_head;
}

/*function to display a doubly circular list in
forward and backward direction*/

void display(Node* head)
{
    if (!head)
        return;

    Node* temp = head;

    cout << "Forward direction: ";
    while (temp->next != head) {
        cout << temp->data << " ";
        temp = temp->next;
    }
    cout << temp->data;

    Node* last = head->prev;
    temp = last;

    cout << "\nBackward direction: ";
    while (temp->prev != last) {
        cout << temp->data << " ";
        temp = temp->prev;
    }
    cout << temp->data;
}

/*Driver program to test above*/

int main()
{
    Node* head = NULL;

    insertEnd(&head, getNode(1));
    insertEnd(&head, getNode(2));
    insertEnd(&head, getNode(3));
    insertEnd(&head, getNode(4));
    insertEnd(&head, getNode(5));

    cout << "Current list:\n";
    display(head);

    head = reverse(head);

    cout << "\n\nReversed list:\n";
    display(head);

    return 0;
}

/*CPP program to convert array to
circular doubly linked list*/


