        while(temp->next != t)
        {
            cout<<temp->data<<" ";
            temp = temp->next;
        }

        cout<<temp->data;

        return 1;
    }
}

/*Function to convert array into list*/

void createList(int arr[], int n, struct node **start)
{

/*    Declare newNode and temporary pointer*/

    struct node *newNode,*temp;
    int i;

/*    Iterate the loop until array length*/

    for(i=0;i<n;i++)
    {

/*        Create new node*/

        newNode = getNode();

/*        Assign the array data*/

        newNode->data = arr[i];

/*        If it is first element
        Put that node prev and next as start
        as it is circular*/

        if(i==0)
        {
            *start = newNode;
            newNode->prev = *start;
            newNode->next = *start;
        }
        else
        {

/*            Find the last node*/

            temp = (*start)->prev;

/*            Add the last node to make them
            in circular fashion*/

            temp->next = newNode;
            newNode->next = *start;
            newNode->prev = temp;
            temp = *start;
            temp->prev = newNode;
        }
    }
}

/*Driver Code*/

int main()
{

/*    Array to be converted*/

    int arr[] = {1,2,3,4,5};
    int n = sizeof(arr) / sizeof(arr[0]);

/*    Start Pointer*/

    struct node *start = NULL;

/*    Create the List*/

    createList(arr, n, &start);

/*    Display the list*/

    displayList(start);

    return 0;
}

/*C++ code to find the luckiest person*/

#include <bits/stdc++.h>
using namespace std;

/*Node structure*/

struct Node {
    int data;
    struct Node* next;
};

Node *newNode(int data)
{
   Node *node = new Node;
   node->data = data;
   node->next = NULL;
   return node;
}

/*Function to find the luckiest person*/

int alivesol(int Num)
{
    if (Num == 1)
        return 1;

/*    Create a single node circular
    linked list.*/

    Node *last = newNode(1);
    last->next = last;

    for (int i = 2; i <= Num; i++) {
        Node *temp = newNode(i);
        temp->next = last->next;       
        last->next = temp;
        last = temp;    
    }

/*    Starting from first soldier.*/

    Node *curr = last->next;

/*    condition for evaluating the existence
    of single soldier who is not killed.*/

    Node *temp;
    while (curr->next != curr) {
        temp = curr;
        curr = curr->next;
        temp->next = curr->next;

/*        deleting soldier from the circular
        list who is killed in the fight.*/

        delete curr;
        temp = temp->next;
        curr = temp;
    }

/*    Returning the Luckiest soldier who
    remains alive.*/

    int res = temp->data;
    delete temp;

    return res;
}

/*Driver code*/

int main()
{
    int N = 100;
    cout << alivesol(N) << endl;
    return 0;
}

/*C++ program for the above approach*/


#include <bits/stdc++.h>
using namespace std;

/*Node of a Binary Tree*/

struct Node {
    struct Node* left;
    struct Node* right;
    int data;
};

/*Function to create
a new tree Node*/

Node* newNode(int key)
{
    Node* temp = new Node;
    temp->data = key;
    temp->left = temp->right = NULL;
    return temp;
}

/*Function to find the depth
of the Binary Tree*/

int finddepth(Node* root)
{

/*    If root is not null*/

    if (!root)
        return 0;

/*    Left recursive subtree*/

    int left = finddepth(root->left);

/*    Right recursive subtree*/

    int right = finddepth(root->right);

/*    Returns the maximum depth*/

    return 1 + max(left, right);
}

/*Function to perform the depth
first search on the binary tree*/

Node* dfs(Node* root, int curr,
          int depth)
{

/*    If root is null*/

    if (!root)
        return NULL;

/*    If curr is equal to depth*/

    if (curr == depth)
        return root;

/*    Left recursive subtree*/

    Node* left = dfs(root->left,
                     curr + 1, depth);

/*    Right recursive subtree*/

    Node* right = dfs(root->right,
                      curr + 1, depth);

/*    If left and right are not null*/

    if (left != NULL && right != NULL)
        return root;

/*    Return left, if left is not null
    Otherwise return right*/

    return left ? left : right;
}

/*Function to find the LCA of the
deepest nodes of the binary tree*/

Node* lcaOfDeepestLeaves(Node* root)
{

/*    If root is null*/

    if (!root)
        return NULL;

/*    Stores the deepest depth
    of the binary tree*/

    int depth = finddepth(root) - 1;

/*    Return the LCA of the
    nodes at level depth*/

    return dfs(root, 0, depth);
}

