}

/*C++ program to find sum of all odd nodes
in the path connecting two given nodes*/


#include<bits/stdc++.h>
using namespace std;

/*Binary Tree node*/

struct Node
{
    int data;
    struct Node* left;
    struct Node* right;
};

/*Utitlity function to create a
new Binary Tree node*/

struct Node* newNode(int data)
{
    struct Node* node = new Node;
    node->data = data;
    node->left = NULL;
    node->right = NULL;

    return node;
}

/*Function to check if there is a path from root
to the given node. It also populates
'arr' with the given path*/

bool getPath(Node* root, vector<int>& arr, int x)
{

/*    if root is NULL
    there is no path*/

    if (!root)
        return false;

/*    push the node's value in 'arr'*/

    arr.push_back(root->data);

/*    if it is the required node
    return true*/

    if (root->data == x)
        return true;

/*    else check whether the required node lies
    in the left subtree or right subtree of
    the current node*/

    if (getPath(root->left, arr, x) || getPath(root->right, arr, x))
        return true;

/*    required node does not lie either in the
    left or right subtree of the current node
    Thus, remove current node's value from
    'arr'and then return false*/

    arr.pop_back();
    return false;
}

/*Function to get the sum of odd nodes in the
path between any two nodes in a binary tree*/

int sumOddNodes(Node* root, int n1, int n2)
{

/*    vector to store the path of
    first node n1 from root*/

    vector<int> path1;

/*    vector to store the path of
    second node n2 from root*/

    vector<int> path2;

    getPath(root, path1, n1);
    getPath(root, path2, n2);

    int intersection = -1;

/*    Get intersection point*/

    int i = 0, j = 0;
    while (i != path1.size() || j != path2.size()) {

/*        Keep moving forward until no intersection
        is found*/

        if (i == j && path1[i] == path2[j]) {
            i++;
            j++;
        }
        else {
            intersection = j - 1;
            break;
        }
    }

    int sum = 0;

/*    calculate sum of ODD nodes from the path*/

    for (int i = path1.size() - 1; i > intersection; i--)
        if(path1[i]%2)
            sum += path1[i];

    for (int i = intersection; i < path2.size(); i++)
        if(path2[i]%2)
            sum += path2[i];

    return sum;       
}

/*Driver Code*/

int main()
{
    struct Node* root = newNode(1);

    root->left = newNode(2);
    root->right = newNode(3);
    root->left->left = newNode(4);
    root->left->right = newNode(5);
    root->right->right = newNode(6);

    int node1 = 5;
    int node2 = 6;

    cout<<sumOddNodes(root, node1, node2);

    return 0;
}

/*C++ program to find distance between
two nodes for multiple queries*/

#include <bits/stdc++.h>
#define MAX 100001
using namespace std;

/* A tree node structure */

struct Node {
    int data;
    struct Node* left;
    struct Node* right;
};

/* Utility function to create a new Binary Tree node */

struct Node* newNode(int data)
{
    struct Node* temp = new struct Node;
    temp->data = data;
    temp->left = temp->right = NULL;
    return temp;
}

/*Array to store level of each node*/

int level[MAX];

/*Utility Function to store level of all nodes*/

void FindLevels(struct Node* root)
{
    if (!root)
        return;

/*    queue to hold tree node with level*/

    queue<pair<struct Node*, int> > q;

/*    let root node be at level 0*/

    q.push({ root, 0 });

    pair<struct Node*, int> p;

/*    Do level Order Traversal of tree*/

    while (!q.empty()) {
        p = q.front();
        q.pop();

/*        Node p.first is on level p.second*/

        level[p.first->data] = p.second;

/*        If left child exits, put it in queue
        with current_level +1*/

        if (p.first->left)
            q.push({ p.first->left, p.second + 1 });

/*        If right child exists, put it in queue
        with current_level +1*/

        if (p.first->right)
            q.push({ p.first->right, p.second + 1 });
    }
}

/*Stores Euler Tour*/

int Euler[MAX];

/*index in Euler array*/

int idx = 0;

/*Find Euler Tour*/

void eulerTree(struct Node* root)
{

/*    store current node's data*/

    Euler[++idx] = root->data;

/*    If left node exists*/

    if (root->left) {

/*        traverse left subtree*/

        eulerTree(root->left);

/*        store parent node's data*/

        Euler[++idx] = root->data;
    }

/*    If right node exists*/

    if (root->right) {

/*        traverse right subtree*/

        eulerTree(root->right);

/*        store parent node's data*/

        Euler[++idx] = root->data;
    }
}

/*checks for visited nodes*/

int vis[MAX];

/*Stores level of Euler Tour*/

int L[MAX];

/*Stores indices of first occurrence
of nodes in Euler tour*/

int H[MAX];

/*Preprocessing Euler Tour for finding LCA*/

void preprocessEuler(int size)
{
    for (int i = 1; i <= size; i++) {
        L[i] = level[Euler[i]];

/*        If node is not visited before*/

        if (vis[Euler[i]] == 0) {

/*            Add to first occurrence*/

            H[Euler[i]] = i;

/*            Mark it visited*/

            vis[Euler[i]] = 1;
        }
    }
}

/*Stores values and positions*/

pair<int, int> seg[4 * MAX];

/*Utility function to find minimum of
pair type values*/

pair<int, int> min(pair<int, int> a,
                   pair<int, int> b)
{
    if (a.first <= b.first)
        return a;
    else
        return b;
}

/*Utility function to build segment tree*/

pair<int, int> buildSegTree(int low, int high, int pos)
{
    if (low == high) {
        seg[pos].first = L[low];
        seg[pos].second = low;
        return seg[pos];
    }
    int mid = low + (high - low) / 2;
    buildSegTree(low, mid, 2 * pos);
    buildSegTree(mid + 1, high, 2 * pos + 1);

    seg[pos] = min(seg[2 * pos], seg[2 * pos + 1]);
}

/*Utility function to find LCA*/

pair<int, int> LCA(int qlow, int qhigh, int low,
                   int high, int pos)
{
    if (qlow <= low && qhigh >= high)
        return seg[pos];

    if (qlow > high || qhigh < low)
        return { INT_MAX, 0 };

    int mid = low + (high - low) / 2;

    return min(LCA(qlow, qhigh, low, mid, 2 * pos),
               LCA(qlow, qhigh, mid + 1, high, 2 * pos + 1));
}

/*Function to return distance between
two nodes n1 and n2*/

int findDistance(int n1, int n2, int size)
{

/*    Maintain original Values*/

    int prevn1 = n1, prevn2 = n2;

/*    Get First Occurrence of n1*/

    n1 = H[n1];

/*    Get First Occurrence of n2*/

    n2 = H[n2];

/*    Swap if low > high*/

    if (n2 < n1)
        swap(n1, n2);

/*    Get position of minimum value*/

    int lca = LCA(n1, n2, 1, size, 1).second;

/*    Extract value out of Euler tour*/

    lca = Euler[lca];

/*    return calculated distance*/

    return level[prevn1] + level[prevn2] - 2 * level[lca];
}

void preProcessing(Node* root, int N)
{

/*    Build Tree*/

    eulerTree(root);

/*    Store Levels*/

    FindLevels(root);

/*    Find L and H array*/

    preprocessEuler(2 * N - 1);

/*    Build segment Tree*/

    buildSegTree(1, 2 * N - 1, 1);
}

/* Driver function to test above functions */

int main()
{

/*Number of nodes*/

int N = 8;

/* Constructing tree given in the above figure */

    Node* root = newNode(1);
    root->left = newNode(2);
    root->right = newNode(3);
    root->left->left = newNode(4);
    root->left->right = newNode(5);
    root->right->left = newNode(6);
    root->right->right = newNode(7);
    root->right->left->right = newNode(8);

/*    Function to do all preprocessing*/

    preProcessing(root, N);

    cout << "Dist(4, 5) = " <<
      findDistance(4, 5, 2 * N - 1) << "\n";
    cout << "Dist(4, 6) = " <<
      findDistance(4, 6, 2 * N - 1) << "\n";
    cout << "Dist(3, 4) = " <<
      findDistance(3, 4, 2 * N - 1) << "\n";
    cout << "Dist(2, 4) = " <<
      findDistance(2, 4, 2 * N - 1) << "\n";
    cout << "Dist(8, 5) = " <<
      findDistance(8, 5, 2 * N - 1) << "\n";

    return 0;
}

/*CPP program to find distance between
two nodes in BST*/

#include <bits/stdc++.h>
using namespace std;

struct Node {
    struct Node* left, *right;
    int key;
};

struct Node* newNode(int key)
{
    struct Node* ptr = new Node;
    ptr->key = key;
    ptr->left = ptr->right = NULL;
    return ptr;
}

/*Standard BST insert function*/

struct Node* insert(struct Node* root, int key)
{
    if (!root)
        root = newNode(key);
    else if (root->key > key)
        root->left = insert(root->left, key);
    else if (root->key < key)
        root->right = insert(root->right, key);
    return root;
}

/*This function returns distance of x from
root. This function assumes that x exists
in BST and BST is not NULL.*/

int distanceFromRoot(struct Node* root, int x)
{
    if (root->key == x)
        return 0;
    else if (root->key > x)
        return 1 + distanceFromRoot(root->left, x);
    return 1 + distanceFromRoot(root->right, x);
}

/*Returns minimum distance between a and b.
This function assumes that a and b exist
in BST.*/

int distanceBetween2(struct Node* root, int a, int b)
{
    if (!root)
        return 0;

/*    Both keys lie in left*/

    if (root->key > a && root->key > b)
        return distanceBetween2(root->left, a, b);

/*    Both keys lie in right
same path*/

if (root->key < a && root->key < b) 
        return distanceBetween2(root->right, a, b);

/*    Lie in opposite directions (Root is
    LCA of two nodes)*/

    if (root->key >= a && root->key <= b)
        return distanceFromRoot(root, a) +
               distanceFromRoot(root, b);
}

/*This function make sure that a is smaller
than b before making a call to findDistWrapper()*/

int findDistWrapper(Node *root, int a, int b)
{
   if (a > b)
     swap(a, b);
   return distanceBetween2(root, a, b);  
}

/*Driver code*/

int main()
{
    struct Node* root = NULL;
    root = insert(root, 20);
    insert(root, 10);
    insert(root, 5);
    insert(root, 15);
    insert(root, 30);
    insert(root, 25);
    insert(root, 35);
    int a = 5, b = 55;
    cout << findDistWrapper(root, 5, 35);
    return 0;
}

/*A C++ Program to find the length of longest
common extension using Naive Method*/

#include<bits/stdc++.h>
using namespace std;

/*Structure to represent a query of form (L,R)*/

struct Query
{
    int L, R;
};

/*A utility function to find longest common
extension from index - L and index - R*/

int LCE(string str, int n, int L, int R)
{
    int length = 0;

    while (str[L+length] == str[R+length] &&
            R+length < n)
        length++;

    return(length);
}

/*A function to answer queries of longest
common extension*/

void LCEQueries(string str, int n, Query q[],
                                       int m)
{
    for (int i=0; i<m; i++)
    {
        int L = q[i].L;
        int R = q[i].R;

        printf("LCE (%d, %d) = %d\n", L, R,
                         LCE(str, n, L, R));
    }
    return;
}

